    const msgs = db.prepare("SELECT role, content FROM messages WHERE thread_id=? ORDER BY created_at ASC").all(threadId) as any[];
    const wordCount = msgs.reduce((acc: number, m: any) => acc + (m.content || '').split(/\s+/).length, 0);
