// citation_trackers table
db.exec(`CREATE TABLE IF NOT EXISTS citation_trackers (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  title TEXT NOT NULL,
  authors TEXT,
  publication TEXT,
  year INTEGER,
  url TEXT,
  doi TEXT,
  citation_type TEXT DEFAULT 'article',
  abstract TEXT,
  notes TEXT,
  tags TEXT DEFAULT '[]',
  cite_count INTEGER DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
)`);
app.get('/api/citations', requireAuth, (req: any, res: any) => {
  const { search, type } = req.query as any;
  let q = `SELECT id,title,authors,publication,year,citation_type,cite_count,created_at FROM citation_trackers WHERE user_id=?`;
  const params: any[] = [req.user.id];
  if (type) { q += ` AND citation_type=?`; params.push(type); }
  if (search) { q += ` AND (title LIKE ? OR authors LIKE ?)`; params.push(`%${search}%`,`%${search}%`); }
  q += ` ORDER BY created_at DESC LIMIT 200`;
  const rows = db.prepare(q).all(...params);
  res.json({ rows, total: rows.length });
});
app.post('/api/citations', requireAuth, (req: any, res: any) => {
  const { title, authors, publication, year, url, doi, citation_type, abstract, notes, tags } = req.body;
  if (!title) return res.status(400).json({ error: 'title required' });
  const r = db.prepare(`INSERT INTO citation_trackers (user_id,title,authors,publication,year,url,doi,citation_type,abstract,notes,tags) VALUES (?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id,title,authors||null,publication||null,year||null,url||null,doi||null,citation_type||'article',abstract||null,notes||null,JSON.stringify(tags||[]));
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/citations/:id/cite', requireAuth, (req: any, res: any) => {
  const row = db.prepare(`SELECT * FROM citation_trackers WHERE id=? AND user_id=?`).get(req.params.id, req.user.id) as any;
  if (!row) return res.status(404).json({ error: 'not found' });
  db.prepare(`UPDATE citation_trackers SET cite_count=cite_count+1 WHERE id=?`).run(req.params.id);
  // Format APA
  const apa = `${row.authors||'Unknown'} (${row.year||'n.d.'}). ${row.title}. ${row.publication||''}${row.doi?`. https://doi.org/${row.doi}`:''}`;
  res.json({ success: true, apa_format: apa });
});
app.delete('/api/citations/:id', requireAuth, (req: any, res: any) => {
  db.prepare(`DELETE FROM citation_trackers WHERE id=? AND user_id=?`).run(req.params.id, req.user.id);
  res.json({ success: true });
});

