// ab_tests table
db.exec(`CREATE TABLE IF NOT EXISTS ab_tests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  name TEXT NOT NULL,
  test_type TEXT DEFAULT 'headline',
  variant_a TEXT NOT NULL,
  variant_b TEXT NOT NULL,
  metric TEXT DEFAULT 'ctr',
  impressions_a INTEGER DEFAULT 0,
  impressions_b INTEGER DEFAULT 0,
  conversions_a INTEGER DEFAULT 0,
  conversions_b INTEGER DEFAULT 0,
  winner TEXT,
  confidence REAL DEFAULT 0,
  status TEXT DEFAULT 'running',
  started_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  ended_at DATETIME
)`);
app.get('/api/ab-tests', requireAuth, (req: any, res: any) => {
  const rows = db.prepare(`SELECT id,name,test_type,variant_a,variant_b,winner,status,confidence,started_at FROM ab_tests WHERE user_id=? ORDER BY started_at DESC LIMIT 50`).all(req.user.id);
  res.json({ rows, total: rows.length });
});
app.post('/api/ab-tests', requireAuth, (req: any, res: any) => {
  const { name, test_type, variant_a, variant_b, metric } = req.body;
  if (!name || !variant_a || !variant_b) return res.status(400).json({ error: 'name, variant_a, variant_b required' });
  const r = db.prepare(`INSERT INTO ab_tests (user_id,name,test_type,variant_a,variant_b,metric) VALUES (?,?,?,?,?,?)`).run(req.user.id,name,test_type||'headline',variant_a,variant_b,metric||'ctr');
  res.json({ id: r.lastInsertRowid });
});
app.put('/api/ab-tests/:id/record', requireAuth, (req: any, res: any) => {
  const { variant, type } = req.body; // variant: 'a'|'b', type: 'impression'|'conversion'
  if (!variant || !type) return res.status(400).json({ error: 'variant and type required' });
  const col = type === 'conversion' ? `conversions_${variant}` : `impressions_${variant}`;
  db.prepare(`UPDATE ab_tests SET ${col}=${col}+1 WHERE id=? AND user_id=?`).run(req.params.id, req.user.id);
  const test = db.prepare(`SELECT * FROM ab_tests WHERE id=?`).get(req.params.id) as any;
  const ctrA = test.impressions_a > 0 ? test.conversions_a/test.impressions_a : 0;
  const ctrB = test.impressions_b > 0 ? test.conversions_b/test.impressions_b : 0;
  const winner = ctrA > ctrB ? 'a' : ctrB > ctrA ? 'b' : null;
  res.json({ success: true, ctr_a: ctrA, ctr_b: ctrB, leading: winner });
});
app.put('/api/ab-tests/:id/conclude', requireAuth, (req: any, res: any) => {
  const { winner, confidence } = req.body;
  db.prepare(`UPDATE ab_tests SET winner=?,confidence=?,status='concluded',ended_at=CURRENT_TIMESTAMP WHERE id=? AND user_id=?`).run(winner||null,confidence||0,req.params.id,req.user.id);
  res.json({ success: true });
});

