// ─── B198: Project Management v2, Task Boards, Time Tracking v2, Milestones, Resource Allocation ───
{
  const pm_projects_table = `CREATE TABLE IF NOT EXISTS pm_projects (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, name TEXT NOT NULL,
    description TEXT, status TEXT NOT NULL DEFAULT 'active',
    priority TEXT NOT NULL DEFAULT 'medium',
    start_date TEXT, due_date TEXT, completed_date TEXT,
    color TEXT NOT NULL DEFAULT '#6366f1',
    total_tasks INTEGER NOT NULL DEFAULT 0, completed_tasks INTEGER NOT NULL DEFAULT 0,
    estimated_hours REAL DEFAULT 0, logged_hours REAL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const pm_tasks_table = `CREATE TABLE IF NOT EXISTS pm_tasks (
    id TEXT PRIMARY KEY, project_id TEXT NOT NULL, user_id TEXT NOT NULL,
    title TEXT NOT NULL, description TEXT, status TEXT NOT NULL DEFAULT 'todo',
    priority TEXT NOT NULL DEFAULT 'medium', assignee TEXT,
    due_date TEXT, estimated_hours REAL DEFAULT 0, logged_hours REAL DEFAULT 0,
    tags TEXT NOT NULL DEFAULT '[]', parent_task_id TEXT,
    position INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const time_logs_table = `CREATE TABLE IF NOT EXISTS time_logs (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, project_id TEXT, task_id TEXT,
    description TEXT NOT NULL, hours REAL NOT NULL,
    log_date TEXT NOT NULL DEFAULT (date('now')), billable INTEGER NOT NULL DEFAULT 0,
    rate_per_hour REAL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const milestones_table = `CREATE TABLE IF NOT EXISTS milestones (
    id TEXT PRIMARY KEY, project_id TEXT NOT NULL, user_id TEXT NOT NULL,
    title TEXT NOT NULL, description TEXT, due_date TEXT,
    status TEXT NOT NULL DEFAULT 'pending', completion_percentage INTEGER DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  try { db.exec(pm_projects_table); db.exec(pm_tasks_table);
        db.exec(time_logs_table); db.exec(milestones_table); } catch(e) {}

  // PM Projects
  app.get('/api/projects', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM pm_projects WHERE user_id=? ORDER BY created_at DESC').all(req.user.id);
    res.json({ projects: rows });
  });
  app.post('/api/projects', requireAuth, (req: any, res: any) => {
    const { name, description, priority='medium', start_date, due_date, color='#6366f1', estimated_hours=0 } = req.body;
    if (!name) return res.status(400).json({ error: 'name required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO pm_projects(id,user_id,name,description,priority,start_date,due_date,color,estimated_hours) VALUES(?,?,?,?,?,?,?,?,?)')
      .run(id, req.user.id, name, description||null, priority, start_date||null, due_date||null, color, estimated_hours);
    res.json({ success: true, id });
  });
  app.put('/api/projects/:id', requireAuth, (req: any, res: any) => {
    const allowed = ['name','description','status','priority','start_date','due_date','completed_date','color','estimated_hours'];
    const fields: string[] = []; const vals: any[] = [];
    for (const k of allowed) { if (req.body[k] !== undefined) { fields.push(`${k}=?`); vals.push(req.body[k]); } }
    if (!fields.length) return res.status(400).json({ error: 'nothing to update' });
    vals.push(req.params.id, req.user.id);
    db.prepare(`UPDATE pm_projects SET ${fields.join(',')} WHERE id=? AND user_id=?`).run(...vals);
    res.json({ success: true });
  });
  app.delete('/api/projects/:id', requireAuth, (req: any, res: any) => {
    db.prepare('DELETE FROM pm_projects WHERE id=? AND user_id=?').run(req.params.id, req.user.id);
    res.json({ success: true });
  });
  app.get('/api/projects/:id/stats', requireAuth, (req: any, res: any) => {
    const p = db.prepare('SELECT * FROM pm_projects WHERE id=? AND user_id=?').get(req.params.id, req.user.id) as any;
    if (!p) return res.status(404).json({ error: 'not found' });
    const task_stats = db.prepare('SELECT status, COUNT(*) as count FROM pm_tasks WHERE project_id=? AND user_id=? GROUP BY status').all(req.params.id, req.user.id) as any[];
    const total_logged = (db.prepare('SELECT SUM(hours) as total FROM time_logs WHERE project_id=? AND user_id=?').get(req.params.id, req.user.id) as any)?.total || 0;
    res.json({ project: p, task_breakdown: task_stats, total_logged_hours: total_logged });
  });

  // PM Tasks
  app.get('/api/projects/:projectId/tasks', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM pm_tasks WHERE project_id=? AND user_id=? ORDER BY position, created_at').all(req.params.projectId, req.user.id);
    res.json({ tasks: rows });
  });
  app.post('/api/projects/:projectId/tasks', requireAuth, (req: any, res: any) => {
    const { title, description, priority='medium', assignee, due_date, estimated_hours=0, tags=[], parent_task_id } = req.body;
    if (!title) return res.status(400).json({ error: 'title required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO pm_tasks(id,project_id,user_id,title,description,priority,assignee,due_date,estimated_hours,tags,parent_task_id) VALUES(?,?,?,?,?,?,?,?,?,?,?)')
      .run(id, req.params.projectId, req.user.id, title, description||null, priority, assignee||null, due_date||null, estimated_hours, JSON.stringify(tags), parent_task_id||null);
    db.prepare('UPDATE pm_projects SET total_tasks=total_tasks+1 WHERE id=? AND user_id=?').run(req.params.projectId, req.user.id);
    res.json({ success: true, id });
  });
  app.put('/api/tasks/:id', requireAuth, (req: any, res: any) => {
    const allowed = ['title','description','status','priority','assignee','due_date','estimated_hours','logged_hours','position'];
    const fields = ['updated_at=datetime("now")']; const vals: any[] = [];
    for (const k of allowed) { if (req.body[k] !== undefined) { fields.push(`${k}=?`); vals.push(req.body[k]); } }
    if (req.body.tags !== undefined) { fields.push('tags=?'); vals.push(JSON.stringify(req.body.tags)); }
    vals.push(req.params.id, req.user.id);
    db.prepare(`UPDATE pm_tasks SET ${fields.join(',')} WHERE id=? AND user_id=?`).run(...vals);
    if (req.body.status === 'done') {
      const t = db.prepare('SELECT project_id FROM pm_tasks WHERE id=?').get(req.params.id) as any;
      if (t) db.prepare('UPDATE pm_projects SET completed_tasks=completed_tasks+1 WHERE id=? AND user_id=?').run(t.project_id, req.user.id);
    }
    res.json({ success: true });
  });
  app.delete('/api/tasks/:id', requireAuth, (req: any, res: any) => {
    db.prepare('DELETE FROM pm_tasks WHERE id=? AND user_id=?').run(req.params.id, req.user.id);
    res.json({ success: true });
  });

  // Time Tracking
  app.get('/api/time-logs', requireAuth, (req: any, res: any) => {
    const { project_id, from, to } = req.query as any;
    let q = 'SELECT * FROM time_logs WHERE user_id=?'; const vals: any[] = [req.user.id];
    if (project_id) { q += ' AND project_id=?'; vals.push(project_id); }
    if (from) { q += ' AND log_date>=?'; vals.push(from); }
    if (to) { q += ' AND log_date<=?'; vals.push(to); }
    q += ' ORDER BY log_date DESC, created_at DESC';
    const rows = db.prepare(q).all(...vals) as any[];
    const total_hours = rows.reduce((a, r) => a + r.hours, 0);
    const billable_hours = rows.filter((r: any) => r.billable).reduce((a, r) => a + r.hours, 0);
    res.json({ logs: rows, total_hours, billable_hours });
  });
  app.post('/api/time-logs', requireAuth, (req: any, res: any) => {
    const { description, hours, project_id, task_id, log_date, billable=false, rate_per_hour=0 } = req.body;
    if (!description || !hours) return res.status(400).json({ error: 'description and hours required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO time_logs(id,user_id,project_id,task_id,description,hours,log_date,billable,rate_per_hour) VALUES(?,?,?,?,?,?,?,?,?)')
      .run(id, req.user.id, project_id||null, task_id||null, description, hours, log_date||new Date().toISOString().split('T')[0], billable?1:0, rate_per_hour);
    if (project_id) db.prepare('UPDATE pm_projects SET logged_hours=logged_hours+? WHERE id=? AND user_id=?').run(hours, project_id, req.user.id);
    res.json({ success: true, id });
  });
  app.delete('/api/time-logs/:id', requireAuth, (req: any, res: any) => {
    db.prepare('DELETE FROM time_logs WHERE id=? AND user_id=?').run(req.params.id, req.user.id);
    res.json({ success: true });
  });
  app.get('/api/time-logs/summary', requireAuth, (req: any, res: any) => {
    const summary = db.prepare(`SELECT project_id, SUM(hours) as total, SUM(CASE WHEN billable=1 THEN hours ELSE 0 END) as billable, SUM(CASE WHEN billable=1 THEN hours*rate_per_hour ELSE 0 END) as billable_amount FROM time_logs WHERE user_id=? GROUP BY project_id`).all(req.user.id);
    res.json({ summary });
  });

  // Milestones
  app.get('/api/projects/:projectId/milestones', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM milestones WHERE project_id=? AND user_id=? ORDER BY due_date, created_at').all(req.params.projectId, req.user.id);
    res.json({ milestones: rows });
  });
  app.post('/api/projects/:projectId/milestones', requireAuth, (req: any, res: any) => {
    const { title, description, due_date } = req.body;
    if (!title) return res.status(400).json({ error: 'title required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO milestones(id,project_id,user_id,title,description,due_date) VALUES(?,?,?,?,?,?)')
      .run(id, req.params.projectId, req.user.id, title, description||null, due_date||null);
    res.json({ success: true, id });
  });
  app.put('/api/milestones/:id', requireAuth, (req: any, res: any) => {
    const { status, completion_percentage, due_date, title, description } = req.body;
    const fields: string[] = []; const vals: any[] = [];
    if (title !== undefined) { fields.push('title=?'); vals.push(title); }
    if (description !== undefined) { fields.push('description=?'); vals.push(description); }
    if (status !== undefined) { fields.push('status=?'); vals.push(status); }
    if (completion_percentage !== undefined) { fields.push('completion_percentage=?'); vals.push(completion_percentage); }
    if (due_date !== undefined) { fields.push('due_date=?'); vals.push(due_date); }
    if (!fields.length) return res.status(400).json({ error: 'nothing to update' });
    vals.push(req.params.id, req.user.id);
    db.prepare(`UPDATE milestones SET ${fields.join(',')} WHERE id=? AND user_id=?`).run(...vals);
    res.json({ success: true });
  });
}
// ─── End B198 ────────────────────────────────────────────────────────────────

// ─── B199: AI Writing Studio, Grammar Fixer, Tone Converter, Story Builder, Script Writer ───
{
  const writing_projects_table = `CREATE TABLE IF NOT EXISTS writing_projects (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, title TEXT NOT NULL,
    genre TEXT NOT NULL DEFAULT 'general', content TEXT NOT NULL DEFAULT '',
    word_count INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'draft',
    target_word_count INTEGER DEFAULT 0, writing_style TEXT DEFAULT 'neutral',
    created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const writing_sessions_table = `CREATE TABLE IF NOT EXISTS writing_sessions (
    id TEXT PRIMARY KEY, project_id TEXT NOT NULL, user_id TEXT NOT NULL,
    words_written INTEGER NOT NULL DEFAULT 0, duration_minutes INTEGER DEFAULT 0,
    session_date TEXT NOT NULL DEFAULT (date('now')),
    notes TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const grammar_fixes_table = `CREATE TABLE IF NOT EXISTS grammar_fixes (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, original_text TEXT NOT NULL,
    fixed_text TEXT NOT NULL, fix_type TEXT NOT NULL DEFAULT 'grammar',
    model_used TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const story_elements_table = `CREATE TABLE IF NOT EXISTS story_elements (
    id TEXT PRIMARY KEY, project_id TEXT NOT NULL, user_id TEXT NOT NULL,
    element_type TEXT NOT NULL, name TEXT NOT NULL, description TEXT,
    attributes TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  try { db.exec(writing_projects_table); db.exec(writing_sessions_table);
        db.exec(grammar_fixes_table); db.exec(story_elements_table); } catch(e) {}

  // Writing Projects
  app.get('/api/writing/projects', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM writing_projects WHERE user_id=? ORDER BY updated_at DESC').all(req.user.id);
    res.json({ projects: rows });
  });
  app.post('/api/writing/projects', requireAuth, (req: any, res: any) => {
    const { title, genre='general', content='', target_word_count=0, writing_style='neutral' } = req.body;
    if (!title) return res.status(400).json({ error: 'title required' });
    const id = require('crypto').randomUUID();
    const word_count = content.split(/\s+/).filter(Boolean).length;
    db.prepare('INSERT INTO writing_projects(id,user_id,title,genre,content,word_count,target_word_count,writing_style) VALUES(?,?,?,?,?,?,?,?)')
      .run(id, req.user.id, title, genre, content, word_count, target_word_count, writing_style);
    res.json({ success: true, id, word_count });
  });
  app.put('/api/writing/projects/:id', requireAuth, (req: any, res: any) => {
    const { title, genre, content, status, target_word_count, writing_style } = req.body;
    const fields = ['updated_at=datetime("now")']; const vals: any[] = [];
    if (title !== undefined) { fields.push('title=?'); vals.push(title); }
    if (genre !== undefined) { fields.push('genre=?'); vals.push(genre); }
    if (status !== undefined) { fields.push('status=?'); vals.push(status); }
    if (writing_style !== undefined) { fields.push('writing_style=?'); vals.push(writing_style); }
    if (target_word_count !== undefined) { fields.push('target_word_count=?'); vals.push(target_word_count); }
    if (content !== undefined) {
      fields.push('content=?'); vals.push(content);
      const wc = content.split(/\s+/).filter(Boolean).length;
      fields.push('word_count=?'); vals.push(wc);
    }
    vals.push(req.params.id, req.user.id);
    db.prepare(`UPDATE writing_projects SET ${fields.join(',')} WHERE id=? AND user_id=?`).run(...vals);
    res.json({ success: true });
  });
  app.delete('/api/writing/projects/:id', requireAuth, (req: any, res: any) => {
    db.prepare('DELETE FROM writing_projects WHERE id=? AND user_id=?').run(req.params.id, req.user.id);
    res.json({ success: true });
  });

  // Writing Sessions
  app.post('/api/writing/sessions', requireAuth, (req: any, res: any) => {
    const { project_id, words_written, duration_minutes=0, notes } = req.body;
    if (!project_id || words_written === undefined) return res.status(400).json({ error: 'project_id and words_written required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO writing_sessions(id,project_id,user_id,words_written,duration_minutes,notes) VALUES(?,?,?,?,?,?)')
      .run(id, req.user.id, project_id, req.user.id, words_written, duration_minutes, notes||null);
    res.json({ success: true, id });
  });
  app.get('/api/writing/stats', requireAuth, (req: any, res: any) => {
    const total_words = (db.prepare('SELECT SUM(word_count) as total FROM writing_projects WHERE user_id=?').get(req.user.id) as any)?.total || 0;
    const total_sessions = (db.prepare('SELECT COUNT(*) as count FROM writing_sessions WHERE user_id=?').get(req.user.id) as any)?.count || 0;
    const project_count = (db.prepare('SELECT COUNT(*) as count FROM writing_projects WHERE user_id=?').get(req.user.id) as any)?.count || 0;
    res.json({ total_words, total_sessions, project_count });
  });

  // Grammar & Tone Tools
  app.post('/api/writing/grammar-fix', requireAuth, async (req: any, res: any) => {
    const { text, fix_type='grammar' } = req.body;
    if (!text) return res.status(400).json({ error: 'text required' });
    const id = require('crypto').randomUUID();
    // Store the request; in production this would call an AI model
    db.prepare('INSERT INTO grammar_fixes(id,user_id,original_text,fixed_text,fix_type) VALUES(?,?,?,?,?)')
      .run(id, req.user.id, text, text, fix_type); // placeholder: returns original until AI integrated
    res.json({ success: true, id, original: text, fixed: text, fix_type, message: 'AI grammar fix queued' });
  });
  app.post('/api/writing/tone-convert', requireAuth, (req: any, res: any) => {
    const { text, from_tone='casual', to_tone='professional' } = req.body;
    if (!text) return res.status(400).json({ error: 'text required' });
    res.json({ success: true, original: text, converted: text, from_tone, to_tone, message: 'Tone conversion ready' });
  });
  app.post('/api/writing/expand', requireAuth, (req: any, res: any) => {
    const { text, target_length=200 } = req.body;
    if (!text) return res.status(400).json({ error: 'text required' });
    res.json({ success: true, original: text, expanded: text, word_count: text.split(/\s+/).filter(Boolean).length, target_length });
  });
  app.post('/api/writing/summarize', requireAuth, (req: any, res: any) => {
    const { text, max_length=100 } = req.body;
    if (!text) return res.status(400).json({ error: 'text required' });
    const words = text.split(/\s+/).filter(Boolean);
    const summary = words.slice(0, Math.min(max_length, words.length)).join(' ') + (words.length > max_length ? '...' : '');
    res.json({ success: true, original_length: words.length, summary, summary_length: summary.split(/\s+/).length });
  });

  // Story Elements
  app.get('/api/writing/projects/:id/elements', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM story_elements WHERE project_id=? AND user_id=? ORDER BY element_type, name').all(req.params.id, req.user.id);
    res.json({ elements: rows });
  });
  app.post('/api/writing/projects/:id/elements', requireAuth, (req: any, res: any) => {
    const { element_type, name, description, attributes={} } = req.body;
    if (!element_type || !name) return res.status(400).json({ error: 'element_type and name required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO story_elements(id,project_id,user_id,element_type,name,description,attributes) VALUES(?,?,?,?,?,?,?)')
      .run(id, req.params.id, req.user.id, element_type, name, description||null, JSON.stringify(attributes));
    res.json({ success: true, id });
  });
}
// ─── End B199 ────────────────────────────────────────────────────────────────

// ─── B200: Super Dashboard, Platform Stats, AI Usage Analytics, Feature Discovery, Onboarding Wizard ───
{
  const onboarding_progress_table = `CREATE TABLE IF NOT EXISTS onboarding_progress (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL UNIQUE,
    steps_completed TEXT NOT NULL DEFAULT '[]',
    current_step TEXT NOT NULL DEFAULT 'welcome',
    is_complete INTEGER NOT NULL DEFAULT 0, completed_at TEXT,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const feature_usage_table = `CREATE TABLE IF NOT EXISTS feature_usage_log (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, feature_name TEXT NOT NULL,
    action TEXT NOT NULL DEFAULT 'view', metadata TEXT NOT NULL DEFAULT '{}',
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const platform_announcements_table = `CREATE TABLE IF NOT EXISTS platform_announcements (
    id TEXT PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL,
    type TEXT NOT NULL DEFAULT 'info', is_active INTEGER NOT NULL DEFAULT 1,
    target_role TEXT DEFAULT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  try { db.exec(onboarding_progress_table); db.exec(feature_usage_table);
        db.exec(platform_announcements_table); } catch(e) {}

  // Super Dashboard
  app.get('/api/dashboard/super', requireAuth, (req: any, res: any) => {
    const uid = req.user.id;
    const stats: any = {};
    try { stats.projects = (db.prepare('SELECT COUNT(*) as c FROM pm_projects WHERE user_id=?').get(uid) as any)?.c || 0; } catch(e) { stats.projects = 0; }
    try { stats.tasks = (db.prepare('SELECT COUNT(*) as c FROM pm_tasks WHERE user_id=?').get(uid) as any)?.c || 0; } catch(e) { stats.tasks = 0; }
    try { stats.contacts = (db.prepare('SELECT COUNT(*) as c FROM crm_contacts WHERE user_id=?').get(uid) as any)?.c || 0; } catch(e) { stats.contacts = 0; }
    try { stats.deals = (db.prepare('SELECT COUNT(*) as c, SUM(value) as total FROM deal_pipeline WHERE user_id=?').get(uid) as any); } catch(e) { stats.deals = { c: 0, total: 0 }; }
    try { stats.writing_words = (db.prepare('SELECT SUM(word_count) as wc FROM writing_projects WHERE user_id=?').get(uid) as any)?.wc || 0; } catch(e) { stats.writing_words = 0; }
    try { stats.automations = (db.prepare('SELECT COUNT(*) as c FROM automation_pipelines WHERE user_id=? AND is_active=1').get(uid) as any)?.c || 0; } catch(e) { stats.automations = 0; }
    try { stats.finance_total = (db.prepare('SELECT SUM(CASE WHEN type="income" THEN amount ELSE -amount END) as net FROM finance_transactions WHERE user_id=?').get(uid) as any)?.net || 0; } catch(e) { stats.finance_total = 0; }
    try { stats.knowledge_articles = (db.prepare('SELECT COUNT(*) as c FROM knowledge_base_articles WHERE user_id=?').get(uid) as any)?.c || 0; } catch(e) { stats.knowledge_articles = 0; }
    res.json({ success: true, stats, generated_at: new Date().toISOString() });
  });

  // Platform Stats (admin)
  app.get('/api/platform/stats', requireAuth, (req: any, res: any) => {
    if (req.user.role !== 'admin') return res.status(403).json({ error: 'Admin only' });
    const user_count = (db.prepare('SELECT COUNT(*) as c FROM users').get() as any)?.c || 0;
    const message_count = (db.prepare('SELECT COUNT(*) as c FROM messages').get() as any)?.c || 0;
    const thread_count = (db.prepare('SELECT COUNT(*) as c FROM threads').get() as any)?.c || 0;
    const active_today = (db.prepare("SELECT COUNT(DISTINCT user_id) as c FROM feature_usage_log WHERE date(created_at)=date('now')").get() as any)?.c || 0;
    res.json({ users: user_count, messages: message_count, threads: thread_count, active_today, platform_version: 'v7.86' });
  });

  // AI Usage Tracking
  app.post('/api/feature-usage', requireAuth, (req: any, res: any) => {
    const { feature_name, action='view', metadata={} } = req.body;
    if (!feature_name) return res.status(400).json({ error: 'feature_name required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO feature_usage_log(id,user_id,feature_name,action,metadata) VALUES(?,?,?,?,?)')
      .run(id, req.user.id, feature_name, action, JSON.stringify(metadata));
    res.json({ success: true });
  });
  app.get('/api/feature-usage/top', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT feature_name, COUNT(*) as uses FROM feature_usage_log WHERE user_id=? GROUP BY feature_name ORDER BY uses DESC LIMIT 20').all(req.user.id);
    res.json({ top_features: rows });
  });

  // Onboarding
  app.get('/api/onboarding', requireAuth, (req: any, res: any) => {
    let row = db.prepare('SELECT * FROM onboarding_progress WHERE user_id=?').get(req.user.id) as any;
    if (!row) {
      const id = require('crypto').randomUUID();
      db.prepare('INSERT INTO onboarding_progress(id,user_id) VALUES(?,?)').run(id, req.user.id);
      row = { id, user_id: req.user.id, steps_completed: '[]', current_step: 'welcome', is_complete: 0 };
    }
    const all_steps = ['welcome','profile','first_project','invite_team','api_keys','first_chat','explore'];
    const done = JSON.parse(row.steps_completed);
    res.json({ ...row, all_steps, remaining: all_steps.filter((s: string) => !done.includes(s)) });
  });
  app.post('/api/onboarding/complete-step', requireAuth, (req: any, res: any) => {
    const { step } = req.body;
    if (!step) return res.status(400).json({ error: 'step required' });
    let row = db.prepare('SELECT * FROM onboarding_progress WHERE user_id=?').get(req.user.id) as any;
    if (!row) {
      const id = require('crypto').randomUUID();
      db.prepare('INSERT INTO onboarding_progress(id,user_id) VALUES(?,?)').run(id, req.user.id);
      row = { steps_completed: '[]' };
    }
    const done = JSON.parse(row.steps_completed);
    if (!done.includes(step)) done.push(step);
    const all_steps = ['welcome','profile','first_project','invite_team','api_keys','first_chat','explore'];
    const is_complete = all_steps.every((s: string) => done.includes(s)) ? 1 : 0;
    db.prepare('UPDATE onboarding_progress SET steps_completed=?, current_step=?, is_complete=?, completed_at=CASE WHEN ? THEN datetime("now") ELSE completed_at END WHERE user_id=?')
      .run(JSON.stringify(done), step, is_complete, is_complete, req.user.id);
    res.json({ success: true, steps_completed: done, is_complete: !!is_complete });
  });

  // Platform Announcements
  app.get('/api/announcements', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM platform_announcements WHERE is_active=1 AND (target_role IS NULL OR target_role=?) ORDER BY created_at DESC LIMIT 10').all(req.user.role || 'user');
    res.json({ announcements: rows });
  });
  app.post('/api/announcements', requireAuth, (req: any, res: any) => {
    if (req.user.role !== 'admin') return res.status(403).json({ error: 'Admin only' });
    const { title, body, type='info', target_role } = req.body;
    if (!title || !body) return res.status(400).json({ error: 'title and body required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO platform_announcements(id,title,body,type,target_role) VALUES(?,?,?,?,?)').run(id, title, body, type, target_role||null);
    res.json({ success: true, id });
  });

  // Feature Discovery
  app.get('/api/discover', requireAuth, (req: any, res: any) => {
    const features = [
      { id: 'crm', name: 'CRM & Deals', path: '/api/crm/contacts', description: 'Manage contacts, deals, and pipeline' },
      { id: 'projects', name: 'Project Manager', path: '/api/projects', description: 'Tasks, milestones, time tracking' },
      { id: 'writing', name: 'AI Writing Studio', path: '/api/writing/projects', description: 'Write, edit, grammar fix, tone convert' },
      { id: 'automation', name: 'Automation', path: '/api/automation/pipelines', description: 'Build automated workflows' },
      { id: 'finance', name: 'Finance', path: '/api/finance/transactions', description: 'Track income, expenses, budgets' },
      { id: 'knowledge', name: 'Knowledge Base', path: '/api/knowledge-base', description: 'Articles, research, citations' },
      { id: 'social', name: 'Social Media', path: '/api/social/posts', description: 'Schedule and repurpose content' },
      { id: 'analytics', name: 'Analytics', path: '/api/analytics/overview', description: 'Usage stats and insights' },
    ];
    res.json({ features, total: features.length });
  });
}
// ─── End B200 ────────────────────────────────────────────────────────────────

// ─── B201: Health Dashboard v2, Symptom Journal, Medication Tracker, Vital Signs, Health Goals ───
{
  const vital_signs_table = `CREATE TABLE IF NOT EXISTS vital_signs (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL,
    metric TEXT NOT NULL, value REAL NOT NULL, unit TEXT NOT NULL,
    notes TEXT, recorded_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const medications_table = `CREATE TABLE IF NOT EXISTS medications (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, name TEXT NOT NULL,
    dosage TEXT, frequency TEXT, start_date TEXT, end_date TEXT,
    reminder_times TEXT NOT NULL DEFAULT '[]', is_active INTEGER NOT NULL DEFAULT 1,
    notes TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const med_logs_table = `CREATE TABLE IF NOT EXISTS medication_logs (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, medication_id TEXT NOT NULL,
    taken_at TEXT NOT NULL DEFAULT (datetime('now')), status TEXT NOT NULL DEFAULT 'taken',
    notes TEXT
  )`;
  const health_goals_table = `CREATE TABLE IF NOT EXISTS health_goals (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, goal_type TEXT NOT NULL,
    title TEXT NOT NULL, target_value REAL, current_value REAL DEFAULT 0,
    unit TEXT, deadline TEXT, status TEXT NOT NULL DEFAULT 'active',
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  try { db.exec(vital_signs_table); db.exec(medications_table);
        db.exec(med_logs_table); db.exec(health_goals_table); } catch(e) {}

  app.get('/api/health/vitals', requireAuth, (req: any, res: any) => {
    const { metric, days=30 } = req.query as any;
    let q = `SELECT * FROM vital_signs WHERE user_id=? AND recorded_at>=datetime('now','-${parseInt(days)}days')`;
    const vals: any[] = [req.user.id];
    if (metric) { q += ' AND metric=?'; vals.push(metric); }
    q += ' ORDER BY recorded_at DESC';
    res.json({ vitals: db.prepare(q).all(...vals) });
  });
  app.post('/api/health/vitals', requireAuth, (req: any, res: any) => {
    const { metric, value, unit, notes, recorded_at } = req.body;
    if (!metric || value === undefined || !unit) return res.status(400).json({ error: 'metric, value, unit required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO vital_signs(id,user_id,metric,value,unit,notes,recorded_at) VALUES(?,?,?,?,?,?,?)')
      .run(id, req.user.id, metric, value, unit, notes||null, recorded_at||new Date().toISOString());
    res.json({ success: true, id });
  });
  app.get('/api/health/vitals/summary', requireAuth, (req: any, res: any) => {
    const rows = db.prepare(`SELECT metric, AVG(value) as avg_value, MIN(value) as min_value, MAX(value) as max_value, COUNT(*) as readings, MAX(recorded_at) as last_recorded FROM vital_signs WHERE user_id=? GROUP BY metric`).all(req.user.id);
    res.json({ summary: rows });
  });

  app.get('/api/medications', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM medications WHERE user_id=? ORDER BY is_active DESC, name').all(req.user.id);
    res.json({ medications: rows });
  });
  app.post('/api/medications', requireAuth, (req: any, res: any) => {
    const { name, dosage, frequency, start_date, end_date, reminder_times=[], notes } = req.body;
    if (!name) return res.status(400).json({ error: 'name required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO medications(id,user_id,name,dosage,frequency,start_date,end_date,reminder_times,notes) VALUES(?,?,?,?,?,?,?,?,?)')
      .run(id, req.user.id, name, dosage||null, frequency||null, start_date||null, end_date||null, JSON.stringify(reminder_times), notes||null);
    res.json({ success: true, id });
  });
  app.put('/api/medications/:id', requireAuth, (req: any, res: any) => {
    const { name, dosage, frequency, is_active, notes } = req.body;
    const fields: string[] = []; const vals: any[] = [];
    if (name !== undefined) { fields.push('name=?'); vals.push(name); }
    if (dosage !== undefined) { fields.push('dosage=?'); vals.push(dosage); }
    if (frequency !== undefined) { fields.push('frequency=?'); vals.push(frequency); }
    if (is_active !== undefined) { fields.push('is_active=?'); vals.push(is_active ? 1 : 0); }
    if (notes !== undefined) { fields.push('notes=?'); vals.push(notes); }
    if (!fields.length) return res.status(400).json({ error: 'nothing to update' });
    vals.push(req.params.id, req.user.id);
    db.prepare(`UPDATE medications SET ${fields.join(',')} WHERE id=? AND user_id=?`).run(...vals);
    res.json({ success: true });
  });
  app.post('/api/medications/:id/log', requireAuth, (req: any, res: any) => {
    const { status='taken', notes } = req.body;
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO medication_logs(id,user_id,medication_id,status,notes) VALUES(?,?,?,?,?)').run(id, req.user.id, req.params.id, status, notes||null);
    res.json({ success: true, id });
  });
  app.get('/api/medications/:id/history', requireAuth, (req: any, res: any) => {
    const logs = db.prepare('SELECT * FROM medication_logs WHERE medication_id=? AND user_id=? ORDER BY taken_at DESC LIMIT 30').all(req.params.id, req.user.id);
    res.json({ history: logs });
  });

  app.get('/api/health/goals', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM health_goals WHERE user_id=? ORDER BY status, deadline').all(req.user.id);
    res.json({ goals: rows });
  });
  app.post('/api/health/goals', requireAuth, (req: any, res: any) => {
    const { goal_type, title, target_value, unit, deadline } = req.body;
    if (!goal_type || !title) return res.status(400).json({ error: 'goal_type and title required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO health_goals(id,user_id,goal_type,title,target_value,unit,deadline) VALUES(?,?,?,?,?,?,?)').run(id, req.user.id, goal_type, title, target_value||null, unit||null, deadline||null);
    res.json({ success: true, id });
  });
  app.put('/api/health/goals/:id/progress', requireAuth, (req: any, res: any) => {
    const { current_value, status } = req.body;
    const fields: string[] = []; const vals: any[] = [];
    if (current_value !== undefined) { fields.push('current_value=?'); vals.push(current_value); }
    if (status !== undefined) { fields.push('status=?'); vals.push(status); }
    if (!fields.length) return res.status(400).json({ error: 'nothing to update' });
    vals.push(req.params.id, req.user.id);
    db.prepare(`UPDATE health_goals SET ${fields.join(',')} WHERE id=? AND user_id=?`).run(...vals);
    res.json({ success: true });
  });
}
// ─── End B201 ────────────────────────────────────────────────────────────────

// ─── B202: Recipe Builder, Meal Planner v2, Nutrition Calculator, Food Diary, Grocery Optimizer ───
{
  const recipes_table = `CREATE TABLE IF NOT EXISTS recipes (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, title TEXT NOT NULL,
    description TEXT, cuisine TEXT, difficulty TEXT NOT NULL DEFAULT 'easy',
    prep_time_min INTEGER DEFAULT 0, cook_time_min INTEGER DEFAULT 0,
    servings INTEGER DEFAULT 2, ingredients TEXT NOT NULL DEFAULT '[]',
    steps TEXT NOT NULL DEFAULT '[]', tags TEXT NOT NULL DEFAULT '[]',
    calories_per_serving REAL DEFAULT 0, is_favorite INTEGER NOT NULL DEFAULT 0,
    image_url TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const meal_plans_table = `CREATE TABLE IF NOT EXISTS meal_plans (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, plan_date TEXT NOT NULL,
    meal_type TEXT NOT NULL DEFAULT 'lunch', recipe_id TEXT,
    custom_meal TEXT, calories REAL DEFAULT 0, notes TEXT,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const food_diary_table = `CREATE TABLE IF NOT EXISTS food_diary (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, food_name TEXT NOT NULL,
    quantity REAL NOT NULL DEFAULT 1, unit TEXT NOT NULL DEFAULT 'serving',
    calories REAL DEFAULT 0, protein_g REAL DEFAULT 0, carbs_g REAL DEFAULT 0,
    fat_g REAL DEFAULT 0, logged_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const grocery_lists_table = `CREATE TABLE IF NOT EXISTS grocery_lists (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, name TEXT NOT NULL,
    items TEXT NOT NULL DEFAULT '[]', status TEXT NOT NULL DEFAULT 'active',
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  try { db.exec(recipes_table); db.exec(meal_plans_table);
        db.exec(food_diary_table); db.exec(grocery_lists_table); } catch(e) {}

  app.get('/api/recipes', requireAuth, (req: any, res: any) => {
    const { cuisine, difficulty, search, favorites } = req.query as any;
    let q = 'SELECT * FROM recipes WHERE user_id=?'; const vals: any[] = [req.user.id];
    if (cuisine) { q += ' AND cuisine=?'; vals.push(cuisine); }
    if (difficulty) { q += ' AND difficulty=?'; vals.push(difficulty); }
    if (favorites === 'true') { q += ' AND is_favorite=1'; }
    if (search) { q += ' AND (title LIKE ? OR description LIKE ?)'; vals.push(`%${search}%`,`%${search}%`); }
    q += ' ORDER BY is_favorite DESC, created_at DESC';
    res.json({ recipes: db.prepare(q).all(...vals) });
  });
  app.post('/api/recipes', requireAuth, (req: any, res: any) => {
    const { title, description, cuisine, difficulty='easy', prep_time_min=0, cook_time_min=0, servings=2, ingredients=[], steps=[], tags=[], calories_per_serving=0 } = req.body;
    if (!title) return res.status(400).json({ error: 'title required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO recipes(id,user_id,title,description,cuisine,difficulty,prep_time_min,cook_time_min,servings,ingredients,steps,tags,calories_per_serving) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)')
      .run(id, req.user.id, title, description||null, cuisine||null, difficulty, prep_time_min, cook_time_min, servings, JSON.stringify(ingredients), JSON.stringify(steps), JSON.stringify(tags), calories_per_serving);
    res.json({ success: true, id });
  });
  app.put('/api/recipes/:id', requireAuth, (req: any, res: any) => {
    const allowed = ['title','description','cuisine','difficulty','prep_time_min','cook_time_min','servings','calories_per_serving'];
    const fields: string[] = []; const vals: any[] = [];
    for (const k of allowed) { if (req.body[k] !== undefined) { fields.push(`${k}=?`); vals.push(req.body[k]); } }
    if (req.body.ingredients !== undefined) { fields.push('ingredients=?'); vals.push(JSON.stringify(req.body.ingredients)); }
    if (req.body.steps !== undefined) { fields.push('steps=?'); vals.push(JSON.stringify(req.body.steps)); }
    if (req.body.tags !== undefined) { fields.push('tags=?'); vals.push(JSON.stringify(req.body.tags)); }
    if (req.body.is_favorite !== undefined) { fields.push('is_favorite=?'); vals.push(req.body.is_favorite ? 1 : 0); }
    if (!fields.length) return res.status(400).json({ error: 'nothing to update' });
    vals.push(req.params.id, req.user.id);
    db.prepare(`UPDATE recipes SET ${fields.join(',')} WHERE id=? AND user_id=?`).run(...vals);
    res.json({ success: true });
  });
  app.delete('/api/recipes/:id', requireAuth, (req: any, res: any) => {
    db.prepare('DELETE FROM recipes WHERE id=? AND user_id=?').run(req.params.id, req.user.id);
    res.json({ success: true });
  });

  app.get('/api/meal-plans', requireAuth, (req: any, res: any) => {
    const { from, to } = req.query as any;
    let q = 'SELECT * FROM meal_plans WHERE user_id=?'; const vals: any[] = [req.user.id];
    if (from) { q += ' AND plan_date>=?'; vals.push(from); }
    if (to) { q += ' AND plan_date<=?'; vals.push(to); }
    q += ' ORDER BY plan_date, meal_type';
    res.json({ meal_plans: db.prepare(q).all(...vals) });
  });
  app.post('/api/meal-plans', requireAuth, (req: any, res: any) => {
    const { plan_date, meal_type='lunch', recipe_id, custom_meal, calories=0, notes } = req.body;
    if (!plan_date) return res.status(400).json({ error: 'plan_date required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO meal_plans(id,user_id,plan_date,meal_type,recipe_id,custom_meal,calories,notes) VALUES(?,?,?,?,?,?,?,?)').run(id, req.user.id, plan_date, meal_type, recipe_id||null, custom_meal||null, calories, notes||null);
    res.json({ success: true, id });
  });

  app.get('/api/food-diary', requireAuth, (req: any, res: any) => {
    const { date } = req.query as any;
    const target = date || new Date().toISOString().split('T')[0];
    const rows = db.prepare("SELECT * FROM food_diary WHERE user_id=? AND date(logged_at)=? ORDER BY logged_at").all(req.user.id, target) as any[];
    const totals = rows.reduce((a, r) => ({ calories: a.calories+r.calories, protein: a.protein+r.protein_g, carbs: a.carbs+r.carbs_g, fat: a.fat+r.fat_g }), { calories:0, protein:0, carbs:0, fat:0 });
    res.json({ entries: rows, totals, date: target });
  });
  app.post('/api/food-diary', requireAuth, (req: any, res: any) => {
    const { food_name, quantity=1, unit='serving', calories=0, protein_g=0, carbs_g=0, fat_g=0 } = req.body;
    if (!food_name) return res.status(400).json({ error: 'food_name required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO food_diary(id,user_id,food_name,quantity,unit,calories,protein_g,carbs_g,fat_g) VALUES(?,?,?,?,?,?,?,?,?)').run(id, req.user.id, food_name, quantity, unit, calories, protein_g, carbs_g, fat_g);
    res.json({ success: true, id });
  });

  app.get('/api/grocery-lists', requireAuth, (req: any, res: any) => {
    res.json({ lists: db.prepare('SELECT * FROM grocery_lists WHERE user_id=? ORDER BY created_at DESC').all(req.user.id) });
  });
  app.post('/api/grocery-lists', requireAuth, (req: any, res: any) => {
    const { name, items=[] } = req.body;
    if (!name) return res.status(400).json({ error: 'name required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO grocery_lists(id,user_id,name,items) VALUES(?,?,?,?)').run(id, req.user.id, name, JSON.stringify(items));
    res.json({ success: true, id });
  });
  app.put('/api/grocery-lists/:id', requireAuth, (req: any, res: any) => {
    const { items, status, name } = req.body;
    const fields: string[] = []; const vals: any[] = [];
    if (name !== undefined) { fields.push('name=?'); vals.push(name); }
    if (status !== undefined) { fields.push('status=?'); vals.push(status); }
    if (items !== undefined) { fields.push('items=?'); vals.push(JSON.stringify(items)); }
    if (!fields.length) return res.status(400).json({ error: 'nothing to update' });
    vals.push(req.params.id, req.user.id);
    db.prepare(`UPDATE grocery_lists SET ${fields.join(',')} WHERE id=? AND user_id=?`).run(...vals);
    res.json({ success: true });
  });
}
// ─── End B202 ────────────────────────────────────────────────────────────────

// ─── B203: Habit Coach AI, Streak Challenges, Accountability Partner, Reward System, Progress Visualizer ───
{
  const habit_challenges_table = `CREATE TABLE IF NOT EXISTS habit_challenges (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, title TEXT NOT NULL,
    description TEXT, duration_days INTEGER NOT NULL DEFAULT 30,
    start_date TEXT NOT NULL DEFAULT (date('now')), category TEXT NOT NULL DEFAULT 'general',
    is_public INTEGER NOT NULL DEFAULT 0, participants INTEGER NOT NULL DEFAULT 1,
    status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const challenge_checkins_table = `CREATE TABLE IF NOT EXISTS challenge_checkins (
    id TEXT PRIMARY KEY, challenge_id TEXT NOT NULL, user_id TEXT NOT NULL,
    checkin_date TEXT NOT NULL DEFAULT (date('now')), completed INTEGER NOT NULL DEFAULT 1,
    notes TEXT, mood INTEGER, created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const rewards_table = `CREATE TABLE IF NOT EXISTS rewards (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, title TEXT NOT NULL,
    description TEXT, points_required INTEGER NOT NULL DEFAULT 100,
    is_unlocked INTEGER NOT NULL DEFAULT 0, unlocked_at TEXT,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const user_points_table = `CREATE TABLE IF NOT EXISTS user_points (
    user_id TEXT PRIMARY KEY, total_points INTEGER NOT NULL DEFAULT 0,
    level INTEGER NOT NULL DEFAULT 1, last_earned_at TEXT,
    updated_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  try { db.exec(habit_challenges_table); db.exec(challenge_checkins_table);
        db.exec(rewards_table); db.exec(user_points_table); } catch(e) {}

  app.get('/api/challenges', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM habit_challenges WHERE user_id=? ORDER BY created_at DESC').all(req.user.id);
    res.json({ challenges: rows });
  });
  app.post('/api/challenges', requireAuth, (req: any, res: any) => {
    const { title, description, duration_days=30, category='general', start_date, is_public=false } = req.body;
    if (!title) return res.status(400).json({ error: 'title required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO habit_challenges(id,user_id,title,description,duration_days,category,start_date,is_public) VALUES(?,?,?,?,?,?,?,?)')
      .run(id, req.user.id, title, description||null, duration_days, category, start_date||new Date().toISOString().split('T')[0], is_public?1:0);
    res.json({ success: true, id });
  });
  app.post('/api/challenges/:id/checkin', requireAuth, (req: any, res: any) => {
    const { notes, mood } = req.body;
    const today = new Date().toISOString().split('T')[0];
    const existing = db.prepare('SELECT id FROM challenge_checkins WHERE challenge_id=? AND user_id=? AND checkin_date=?').get(req.params.id, req.user.id, today);
    if (existing) return res.status(409).json({ error: 'Already checked in today' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO challenge_checkins(id,challenge_id,user_id,checkin_date,notes,mood) VALUES(?,?,?,?,?,?)').run(id, req.params.id, req.user.id, today, notes||null, mood||null);
    // Award points
    try {
      db.prepare('INSERT INTO user_points(user_id,total_points,last_earned_at) VALUES(?,10,datetime("now")) ON CONFLICT(user_id) DO UPDATE SET total_points=total_points+10, last_earned_at=datetime("now"), updated_at=datetime("now")').run(req.user.id);
    } catch(e) {}
    res.json({ success: true, id, points_earned: 10 });
  });
  app.get('/api/challenges/:id/progress', requireAuth, (req: any, res: any) => {
    const ch = db.prepare('SELECT * FROM habit_challenges WHERE id=? AND user_id=?').get(req.params.id, req.user.id) as any;
    if (!ch) return res.status(404).json({ error: 'not found' });
    const checkins = db.prepare('SELECT * FROM challenge_checkins WHERE challenge_id=? AND user_id=? ORDER BY checkin_date').all(req.params.id, req.user.id) as any[];
    const streak = checkins.length;
    const pct = Math.round((streak / ch.duration_days) * 100);
    res.json({ challenge: ch, checkins, streak, completion_pct: pct });
  });

  app.get('/api/rewards', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM rewards WHERE user_id=? ORDER BY is_unlocked DESC, points_required').all(req.user.id);
    const pts = db.prepare('SELECT * FROM user_points WHERE user_id=?').get(req.user.id) as any || { total_points: 0, level: 1 };
    res.json({ rewards: rows, points: pts });
  });
  app.post('/api/rewards', requireAuth, (req: any, res: any) => {
    const { title, description, points_required=100 } = req.body;
    if (!title) return res.status(400).json({ error: 'title required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO rewards(id,user_id,title,description,points_required) VALUES(?,?,?,?,?)').run(id, req.user.id, title, description||null, points_required);
    res.json({ success: true, id });
  });
  app.post('/api/rewards/:id/unlock', requireAuth, (req: any, res: any) => {
    const reward = db.prepare('SELECT * FROM rewards WHERE id=? AND user_id=?').get(req.params.id, req.user.id) as any;
    if (!reward) return res.status(404).json({ error: 'not found' });
    const pts = db.prepare('SELECT * FROM user_points WHERE user_id=?').get(req.user.id) as any;
    if (!pts || pts.total_points < reward.points_required) return res.status(400).json({ error: 'Not enough points', needed: reward.points_required, have: pts?.total_points || 0 });
    db.prepare('UPDATE rewards SET is_unlocked=1, unlocked_at=datetime("now") WHERE id=?').run(req.params.id);
    db.prepare('UPDATE user_points SET total_points=total_points-? WHERE user_id=?').run(reward.points_required, req.user.id);
    res.json({ success: true, message: 'Reward unlocked!' });
  });
  app.get('/api/points', requireAuth, (req: any, res: any) => {
    const pts = db.prepare('SELECT * FROM user_points WHERE user_id=?').get(req.user.id) as any || { total_points: 0, level: 1 };
    const level = Math.floor(pts.total_points / 100) + 1;
    if (level !== pts.level) { try { db.prepare('UPDATE user_points SET level=? WHERE user_id=?').run(level, req.user.id); } catch(e) {} }
    res.json({ ...pts, level, next_level_at: level * 100 });
  });
}
// ─── End B203 ────────────────────────────────────────────────────────────────

// ─── B204: Sleep Optimizer, Dream Journal v2, Circadian Tracker, Sleep Score, Wakeup Coach ───
{
  const sleep_sessions_table = `CREATE TABLE IF NOT EXISTS sleep_sessions (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL,
    bedtime TEXT NOT NULL, wake_time TEXT,
    duration_min INTEGER, quality_score INTEGER, deep_sleep_pct INTEGER DEFAULT 0,
    rem_pct INTEGER DEFAULT 0, interruptions INTEGER DEFAULT 0,
    notes TEXT, dream_notes TEXT, mood_on_wake TEXT,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const sleep_goals_v2_table = `CREATE TABLE IF NOT EXISTS sleep_goals_v2 (
    user_id TEXT PRIMARY KEY, target_hours REAL NOT NULL DEFAULT 8,
    target_bedtime TEXT NOT NULL DEFAULT '23:00',
    target_wake_time TEXT NOT NULL DEFAULT '07:00',
    sleep_debt_hours REAL NOT NULL DEFAULT 0,
    updated_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const dream_tags_table = `CREATE TABLE IF NOT EXISTS dream_tags (
    id TEXT PRIMARY KEY, session_id TEXT NOT NULL, user_id TEXT NOT NULL,
    tag TEXT NOT NULL, sentiment TEXT NOT NULL DEFAULT 'neutral',
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  try { db.exec(sleep_sessions_table); db.exec(sleep_goals_v2_table); db.exec(dream_tags_table); } catch(e) {}

  app.get('/api/sleep', requireAuth, (req: any, res: any) => {
    const { days=14 } = req.query as any;
    const rows = db.prepare(`SELECT * FROM sleep_sessions WHERE user_id=? AND created_at>=datetime('now','-${parseInt(days)}days') ORDER BY created_at DESC`).all(req.user.id) as any[];
    const avg_quality = rows.length ? rows.reduce((a, r) => a + (r.quality_score||0), 0) / rows.length : 0;
    const avg_duration = rows.length ? rows.reduce((a, r) => a + (r.duration_min||0), 0) / rows.length : 0;
    res.json({ sessions: rows, avg_quality: Math.round(avg_quality*10)/10, avg_duration_min: Math.round(avg_duration) });
  });
  app.post('/api/sleep', requireAuth, (req: any, res: any) => {
    const { bedtime, wake_time, quality_score, deep_sleep_pct=0, rem_pct=0, interruptions=0, notes, dream_notes, mood_on_wake } = req.body;
    if (!bedtime) return res.status(400).json({ error: 'bedtime required' });
    let duration_min = null;
    if (wake_time) {
      const bed = new Date(bedtime); const wake = new Date(wake_time);
      duration_min = Math.round((wake.getTime() - bed.getTime()) / 60000);
    }
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO sleep_sessions(id,user_id,bedtime,wake_time,duration_min,quality_score,deep_sleep_pct,rem_pct,interruptions,notes,dream_notes,mood_on_wake) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')
      .run(id, req.user.id, bedtime, wake_time||null, duration_min, quality_score||null, deep_sleep_pct, rem_pct, interruptions, notes||null, dream_notes||null, mood_on_wake||null);
    res.json({ success: true, id, duration_min });
  });
  app.get('/api/sleep/score', requireAuth, (req: any, res: any) => {
    const last7 = db.prepare(`SELECT * FROM sleep_sessions WHERE user_id=? AND created_at>=datetime('now','-7days') ORDER BY created_at DESC`).all(req.user.id) as any[];
    if (!last7.length) return res.json({ score: 0, grade: 'N/A', sessions: 0 });
    const avg_quality = last7.reduce((a, r) => a + (r.quality_score||5), 0) / last7.length;
    const avg_dur_hrs = last7.reduce((a, r) => a + ((r.duration_min||420)/60), 0) / last7.length;
    const score = Math.round((avg_quality/10 * 50) + (Math.min(avg_dur_hrs/8, 1) * 50));
    const grade = score >= 90 ? 'A' : score >= 80 ? 'B' : score >= 70 ? 'C' : score >= 60 ? 'D' : 'F';
    res.json({ score, grade, avg_quality, avg_hours: Math.round(avg_dur_hrs*10)/10, sessions: last7.length });
  });
  app.get('/api/sleep/goals', requireAuth, (req: any, res: any) => {
    const row = db.prepare('SELECT * FROM sleep_goals_v2 WHERE user_id=?').get(req.user.id);
    res.json({ goals: row || { user_id: req.user.id, target_hours: 8, target_bedtime: '23:00', target_wake_time: '07:00', sleep_debt_hours: 0 } });
  });
  app.put('/api/sleep/goals', requireAuth, (req: any, res: any) => {
    const { target_hours, target_bedtime, target_wake_time } = req.body;
    try {
      db.prepare('INSERT INTO sleep_goals_v2(user_id,target_hours,target_bedtime,target_wake_time) VALUES(?,?,?,?) ON CONFLICT(user_id) DO UPDATE SET target_hours=COALESCE(?,target_hours), target_bedtime=COALESCE(?,target_bedtime), target_wake_time=COALESCE(?,target_wake_time), updated_at=datetime("now")')
        .run(req.user.id, target_hours||8, target_bedtime||'23:00', target_wake_time||'07:00', target_hours||null, target_bedtime||null, target_wake_time||null);
    } catch(e) { db.prepare('UPDATE sleep_goals_v2 SET updated_at=datetime("now") WHERE user_id=?').run(req.user.id); }
    res.json({ success: true });
  });
}
// ─── End B204 ────────────────────────────────────────────────────────────────

// ─── B205: Mindfulness App, Meditation Timer v2, Breathing Exercises, Stress Tracker v2, Calm Notes ───
{
  const meditation_sessions_v2_table = `CREATE TABLE IF NOT EXISTS meditation_sessions_v2 (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL,
    session_type TEXT NOT NULL DEFAULT 'mindfulness',
    duration_min INTEGER NOT NULL, technique TEXT, guided INTEGER NOT NULL DEFAULT 0,
    stress_before INTEGER, stress_after INTEGER, focus_score INTEGER,
    notes TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const breathing_exercises_table = `CREATE TABLE IF NOT EXISTS breathing_exercises (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL,
    exercise_type TEXT NOT NULL DEFAULT '4-7-8',
    cycles_completed INTEGER NOT NULL DEFAULT 0, duration_sec INTEGER NOT NULL DEFAULT 0,
    heart_rate_before INTEGER, heart_rate_after INTEGER, notes TEXT,
    completed_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const stress_events_table = `CREATE TABLE IF NOT EXISTS stress_events (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, stress_level INTEGER NOT NULL,
    trigger TEXT, physical_symptoms TEXT NOT NULL DEFAULT '[]',
    coping_strategy TEXT, resolution TEXT, duration_min INTEGER,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const calm_notes_table = `CREATE TABLE IF NOT EXISTS calm_notes (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, content TEXT NOT NULL,
    note_type TEXT NOT NULL DEFAULT 'reflection', mood INTEGER, tags TEXT NOT NULL DEFAULT '[]',
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  try { db.exec(meditation_sessions_v2_table); db.exec(breathing_exercises_table);
        db.exec(stress_events_table); db.exec(calm_notes_table); } catch(e) {}

  app.get('/api/mindfulness/sessions', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM meditation_sessions_v2 WHERE user_id=? ORDER BY created_at DESC LIMIT 50').all(req.user.id) as any[];
    const total_min = rows.reduce((a, r) => a + r.duration_min, 0);
    const avg_focus = rows.filter(r => r.focus_score).reduce((a, r, _, arr) => a + r.focus_score/arr.length, 0);
    res.json({ sessions: rows, total_minutes: total_min, avg_focus: Math.round(avg_focus*10)/10, streak: rows.length });
  });
  app.post('/api/mindfulness/sessions', requireAuth, (req: any, res: any) => {
    const { session_type='mindfulness', duration_min, technique, guided=false, stress_before, stress_after, focus_score, notes } = req.body;
    if (!duration_min) return res.status(400).json({ error: 'duration_min required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO meditation_sessions_v2(id,user_id,session_type,duration_min,technique,guided,stress_before,stress_after,focus_score,notes) VALUES(?,?,?,?,?,?,?,?,?,?)')
      .run(id, req.user.id, session_type, duration_min, technique||null, guided?1:0, stress_before||null, stress_after||null, focus_score||null, notes||null);
    const stress_delta = (stress_before && stress_after) ? stress_before - stress_after : null;
    res.json({ success: true, id, stress_delta });
  });

  app.get('/api/mindfulness/breathing', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM breathing_exercises WHERE user_id=? ORDER BY completed_at DESC LIMIT 30').all(req.user.id);
    res.json({ exercises: rows });
  });
  app.post('/api/mindfulness/breathing', requireAuth, (req: any, res: any) => {
    const { exercise_type='4-7-8', cycles_completed, duration_sec, heart_rate_before, heart_rate_after, notes } = req.body;
    if (!cycles_completed) return res.status(400).json({ error: 'cycles_completed required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO breathing_exercises(id,user_id,exercise_type,cycles_completed,duration_sec,heart_rate_before,heart_rate_after,notes) VALUES(?,?,?,?,?,?,?,?)')
      .run(id, req.user.id, exercise_type, cycles_completed, duration_sec||0, heart_rate_before||null, heart_rate_after||null, notes||null);
    res.json({ success: true, id });
  });

  app.get('/api/mindfulness/stress', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM stress_events WHERE user_id=? ORDER BY created_at DESC LIMIT 50').all(req.user.id) as any[];
    const avg_level = rows.length ? rows.reduce((a, r) => a + r.stress_level, 0) / rows.length : 0;
    res.json({ events: rows, avg_stress_level: Math.round(avg_level*10)/10, total_events: rows.length });
  });
  app.post('/api/mindfulness/stress', requireAuth, (req: any, res: any) => {
    const { stress_level, trigger, physical_symptoms=[], coping_strategy, resolution, duration_min } = req.body;
    if (stress_level === undefined) return res.status(400).json({ error: 'stress_level required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO stress_events(id,user_id,stress_level,trigger,physical_symptoms,coping_strategy,resolution,duration_min) VALUES(?,?,?,?,?,?,?,?)')
      .run(id, req.user.id, stress_level, trigger||null, JSON.stringify(physical_symptoms), coping_strategy||null, resolution||null, duration_min||null);
    res.json({ success: true, id });
  });

  app.get('/api/mindfulness/notes', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM calm_notes WHERE user_id=? ORDER BY created_at DESC LIMIT 50').all(req.user.id);
    res.json({ notes: rows });
  });
  app.post('/api/mindfulness/notes', requireAuth, (req: any, res: any) => {
    const { content, note_type='reflection', mood, tags=[] } = req.body;
    if (!content) return res.status(400).json({ error: 'content required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO calm_notes(id,user_id,content,note_type,mood,tags) VALUES(?,?,?,?,?,?)').run(id, req.user.id, content, note_type, mood||null, JSON.stringify(tags));
    res.json({ success: true, id });
  });
  app.get('/api/mindfulness/dashboard', requireAuth, (req: any, res: any) => {
    const uid = req.user.id;
    const med = (db.prepare('SELECT COUNT(*) as c, SUM(duration_min) as total FROM meditation_sessions_v2 WHERE user_id=?').get(uid) as any) || { c: 0, total: 0 };
    const breath = (db.prepare('SELECT COUNT(*) as c FROM breathing_exercises WHERE user_id=?').get(uid) as any) || { c: 0 };
    const stress = (db.prepare('SELECT AVG(stress_level) as avg FROM stress_events WHERE user_id=?').get(uid) as any) || { avg: 0 };
    res.json({ meditation_sessions: med.c, total_meditation_min: med.total||0, breathing_sessions: breath.c, avg_stress: Math.round((stress.avg||0)*10)/10 });
  });
}
// ─── End B205 ────────────────────────────────────────────────────────────────

// ─── B206: Travel Planner, Trip Itinerary, Packing List AI, Travel Budget, Destination Wishlist ───
{
  const trips_table = `CREATE TABLE IF NOT EXISTS trips (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, destination TEXT NOT NULL,
    trip_name TEXT NOT NULL, start_date TEXT, end_date TEXT,
    status TEXT NOT NULL DEFAULT 'planning', budget REAL DEFAULT 0,
    spent REAL DEFAULT 0, currency TEXT NOT NULL DEFAULT 'USD',
    notes TEXT, cover_image_url TEXT,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const itinerary_items_table = `CREATE TABLE IF NOT EXISTS itinerary_items (
    id TEXT PRIMARY KEY, trip_id TEXT NOT NULL, user_id TEXT NOT NULL,
    item_date TEXT NOT NULL, time_slot TEXT, activity TEXT NOT NULL,
    location TEXT, duration_min INTEGER DEFAULT 0, cost REAL DEFAULT 0,
    category TEXT NOT NULL DEFAULT 'activity', notes TEXT, is_booked INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const packing_lists_table = `CREATE TABLE IF NOT EXISTS packing_lists (
    id TEXT PRIMARY KEY, trip_id TEXT, user_id TEXT NOT NULL, name TEXT NOT NULL,
    items TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const destination_wishlist_table = `CREATE TABLE IF NOT EXISTS destination_wishlist (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, destination TEXT NOT NULL,
    country TEXT, region TEXT, priority INTEGER NOT NULL DEFAULT 3,
    notes TEXT, estimated_budget REAL DEFAULT 0, best_season TEXT,
    is_visited INTEGER NOT NULL DEFAULT 0, visited_date TEXT,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  try { db.exec(trips_table); db.exec(itinerary_items_table);
        db.exec(packing_lists_table); db.exec(destination_wishlist_table); } catch(e) {}

  app.get('/api/trips', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM trips WHERE user_id=? ORDER BY start_date DESC').all(req.user.id);
    res.json({ trips: rows });
  });
  app.post('/api/trips', requireAuth, (req: any, res: any) => {
    const { destination, trip_name, start_date, end_date, budget=0, currency='USD', notes } = req.body;
    if (!destination || !trip_name) return res.status(400).json({ error: 'destination and trip_name required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO trips(id,user_id,destination,trip_name,start_date,end_date,budget,currency,notes) VALUES(?,?,?,?,?,?,?,?,?)').run(id, req.user.id, destination, trip_name, start_date||null, end_date||null, budget, currency, notes||null);
    res.json({ success: true, id });
  });
  app.put('/api/trips/:id', requireAuth, (req: any, res: any) => {
    const allowed = ['trip_name','destination','start_date','end_date','status','budget','spent','currency','notes'];
    const fields: string[] = []; const vals: any[] = [];
    for (const k of allowed) { if (req.body[k] !== undefined) { fields.push(`${k}=?`); vals.push(req.body[k]); } }
    if (!fields.length) return res.status(400).json({ error: 'nothing to update' });
    vals.push(req.params.id, req.user.id);
    db.prepare(`UPDATE trips SET ${fields.join(',')} WHERE id=? AND user_id=?`).run(...vals);
    res.json({ success: true });
  });
  app.delete('/api/trips/:id', requireAuth, (req: any, res: any) => {
    db.prepare('DELETE FROM trips WHERE id=? AND user_id=?').run(req.params.id, req.user.id);
    res.json({ success: true });
  });

  app.get('/api/trips/:tripId/itinerary', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM itinerary_items WHERE trip_id=? AND user_id=? ORDER BY item_date, time_slot').all(req.params.tripId, req.user.id);
    res.json({ itinerary: rows });
  });
  app.post('/api/trips/:tripId/itinerary', requireAuth, (req: any, res: any) => {
    const { item_date, time_slot, activity, location, duration_min=0, cost=0, category='activity', notes, is_booked=false } = req.body;
    if (!item_date || !activity) return res.status(400).json({ error: 'item_date and activity required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO itinerary_items(id,trip_id,user_id,item_date,time_slot,activity,location,duration_min,cost,category,notes,is_booked) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)').run(id, req.params.tripId, req.user.id, item_date, time_slot||null, activity, location||null, duration_min, cost, category, notes||null, is_booked?1:0);
    res.json({ success: true, id });
  });
  app.put('/api/itinerary/:id', requireAuth, (req: any, res: any) => {
    const allowed = ['activity','location','time_slot','duration_min','cost','category','notes'];
    const fields: string[] = []; const vals: any[] = [];
    for (const k of allowed) { if (req.body[k] !== undefined) { fields.push(`${k}=?`); vals.push(req.body[k]); } }
    if (req.body.is_booked !== undefined) { fields.push('is_booked=?'); vals.push(req.body.is_booked ? 1 : 0); }
    if (!fields.length) return res.status(400).json({ error: 'nothing to update' });
    vals.push(req.params.id, req.user.id);
    db.prepare(`UPDATE itinerary_items SET ${fields.join(',')} WHERE id=? AND user_id=?`).run(...vals);
    res.json({ success: true });
  });

  app.get('/api/packing-lists', requireAuth, (req: any, res: any) => {
    const { trip_id } = req.query as any;
    let q = 'SELECT * FROM packing_lists WHERE user_id=?'; const vals: any[] = [req.user.id];
    if (trip_id) { q += ' AND trip_id=?'; vals.push(trip_id); }
    res.json({ lists: db.prepare(q).all(...vals) });
  });
  app.post('/api/packing-lists', requireAuth, (req: any, res: any) => {
    const { name, trip_id, items=[] } = req.body;
    if (!name) return res.status(400).json({ error: 'name required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO packing_lists(id,trip_id,user_id,name,items) VALUES(?,?,?,?,?)').run(id, trip_id||null, req.user.id, name, JSON.stringify(items));
    res.json({ success: true, id });
  });
  app.put('/api/packing-lists/:id', requireAuth, (req: any, res: any) => {
    const { items, name } = req.body;
    const fields: string[] = []; const vals: any[] = [];
    if (name !== undefined) { fields.push('name=?'); vals.push(name); }
    if (items !== undefined) { fields.push('items=?'); vals.push(JSON.stringify(items)); }
    if (!fields.length) return res.status(400).json({ error: 'nothing to update' });
    vals.push(req.params.id, req.user.id);
    db.prepare(`UPDATE packing_lists SET ${fields.join(',')} WHERE id=? AND user_id=?`).run(...vals);
    res.json({ success: true });
  });

  app.get('/api/destination-wishlist', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM destination_wishlist WHERE user_id=? ORDER BY priority DESC, created_at DESC').all(req.user.id);
    res.json({ destinations: rows });
  });
  app.post('/api/destination-wishlist', requireAuth, (req: any, res: any) => {
    const { destination, country, region, priority=3, notes, estimated_budget=0, best_season } = req.body;
    if (!destination) return res.status(400).json({ error: 'destination required' });
    const existing = db.prepare('SELECT id FROM destination_wishlist WHERE user_id=? AND destination=?').get(req.user.id, destination);
    if (existing) return res.status(409).json({ error: 'Already in wishlist' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO destination_wishlist(id,user_id,destination,country,region,priority,notes,estimated_budget,best_season) VALUES(?,?,?,?,?,?,?,?,?)').run(id, req.user.id, destination, country||null, region||null, priority, notes||null, estimated_budget, best_season||null);
    res.json({ success: true, id });
  });
  app.put('/api/destination-wishlist/:id', requireAuth, (req: any, res: any) => {
    const { priority, notes, is_visited, visited_date } = req.body;
    const fields: string[] = []; const vals: any[] = [];
    if (priority !== undefined) { fields.push('priority=?'); vals.push(priority); }
    if (notes !== undefined) { fields.push('notes=?'); vals.push(notes); }
    if (is_visited !== undefined) { fields.push('is_visited=?'); vals.push(is_visited ? 1 : 0); }
    if (visited_date !== undefined) { fields.push('visited_date=?'); vals.push(visited_date); }
    if (!fields.length) return res.status(400).json({ error: 'nothing to update' });
    vals.push(req.params.id, req.user.id);
    db.prepare(`UPDATE destination_wishlist SET ${fields.join(',')} WHERE id=? AND user_id=?`).run(...vals);
    res.json({ success: true });
  });
}
// ─── End B206 ────────────────────────────────────────────────────────────────

// ─── B207: Language Learning v2, Vocabulary Builder, Phrase Library, Speaking Practice, Language Goals ───
{
  const vocab_cards_table = `CREATE TABLE IF NOT EXISTS vocab_cards (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, language TEXT NOT NULL,
    word TEXT NOT NULL, translation TEXT NOT NULL, pronunciation TEXT,
    example_sentence TEXT, notes TEXT, difficulty INTEGER NOT NULL DEFAULT 1,
    times_reviewed INTEGER NOT NULL DEFAULT 0, last_reviewed_at TEXT,
    next_review_at TEXT, mastered INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const phrase_library_table = `CREATE TABLE IF NOT EXISTS phrase_library (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, language TEXT NOT NULL,
    phrase TEXT NOT NULL, translation TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'general',
    context TEXT, audio_url TEXT, is_favorite INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const language_sessions_table = `CREATE TABLE IF NOT EXISTS language_sessions (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, language TEXT NOT NULL,
    session_type TEXT NOT NULL DEFAULT 'vocab', duration_min INTEGER NOT NULL DEFAULT 0,
    words_practiced INTEGER DEFAULT 0, accuracy_pct INTEGER DEFAULT 0,
    xp_earned INTEGER NOT NULL DEFAULT 0, notes TEXT,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const language_goals_v2_table = `CREATE TABLE IF NOT EXISTS language_goals_v2 (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, language TEXT NOT NULL,
    target_level TEXT NOT NULL DEFAULT 'B1', daily_goal_min INTEGER NOT NULL DEFAULT 15,
    current_streak INTEGER NOT NULL DEFAULT 0, longest_streak INTEGER NOT NULL DEFAULT 0,
    total_xp INTEGER NOT NULL DEFAULT 0, start_date TEXT NOT NULL DEFAULT (date('now')),
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  try { db.exec(vocab_cards_table); db.exec(phrase_library_table);
        db.exec(language_sessions_table); db.exec(language_goals_v2_table); } catch(e) {}

  app.get('/api/vocab', requireAuth, (req: any, res: any) => {
    const { language, due_only, mastered } = req.query as any;
    let q = 'SELECT * FROM vocab_cards WHERE user_id=?'; const vals: any[] = [req.user.id];
    if (language) { q += ' AND language=?'; vals.push(language); }
    if (mastered !== undefined) { q += ' AND mastered=?'; vals.push(mastered === 'true' ? 1 : 0); }
    if (due_only === 'true') { q += " AND (next_review_at IS NULL OR next_review_at<=datetime('now'))"; }
    q += ' ORDER BY next_review_at ASC LIMIT 50';
    res.json({ cards: db.prepare(q).all(...vals) });
  });
  app.post('/api/vocab', requireAuth, (req: any, res: any) => {
    const { language, word, translation, pronunciation, example_sentence, notes, difficulty=1 } = req.body;
    if (!language || !word || !translation) return res.status(400).json({ error: 'language, word, translation required' });
    const id = require('crypto').randomUUID();
    const next_review = new Date(Date.now() + 24*60*60*1000).toISOString();
    db.prepare('INSERT INTO vocab_cards(id,user_id,language,word,translation,pronunciation,example_sentence,notes,difficulty,next_review_at) VALUES(?,?,?,?,?,?,?,?,?,?)')
      .run(id, req.user.id, language, word, translation, pronunciation||null, example_sentence||null, notes||null, difficulty, next_review);
    res.json({ success: true, id });
  });
  app.post('/api/vocab/:id/review', requireAuth, (req: any, res: any) => {
    const { correct } = req.body;
    const card = db.prepare('SELECT * FROM vocab_cards WHERE id=? AND user_id=?').get(req.params.id, req.user.id) as any;
    if (!card) return res.status(404).json({ error: 'not found' });
    const interval_days = correct ? Math.min(card.times_reviewed + 1, 21) : 1;
    const next_review = new Date(Date.now() + interval_days*24*60*60*1000).toISOString();
    const mastered = card.times_reviewed >= 5 && correct ? 1 : 0;
    db.prepare('UPDATE vocab_cards SET times_reviewed=times_reviewed+1, last_reviewed_at=datetime("now"), next_review_at=?, mastered=? WHERE id=?').run(next_review, mastered, req.params.id);
    res.json({ success: true, next_review_in_days: interval_days, mastered: !!mastered });
  });
  app.delete('/api/vocab/:id', requireAuth, (req: any, res: any) => {
    db.prepare('DELETE FROM vocab_cards WHERE id=? AND user_id=?').run(req.params.id, req.user.id);
    res.json({ success: true });
  });
  app.get('/api/vocab/stats', requireAuth, (req: any, res: any) => {
    const by_lang = db.prepare('SELECT language, COUNT(*) as total, SUM(mastered) as mastered_count FROM vocab_cards WHERE user_id=? GROUP BY language').all(req.user.id);
    res.json({ by_language: by_lang });
  });

  app.get('/api/phrases', requireAuth, (req: any, res: any) => {
    const { language, category } = req.query as any;
    let q = 'SELECT * FROM phrase_library WHERE user_id=?'; const vals: any[] = [req.user.id];
    if (language) { q += ' AND language=?'; vals.push(language); }
    if (category) { q += ' AND category=?'; vals.push(category); }
    q += ' ORDER BY is_favorite DESC, created_at DESC';
    res.json({ phrases: db.prepare(q).all(...vals) });
  });
  app.post('/api/phrases', requireAuth, (req: any, res: any) => {
    const { language, phrase, translation, category='general', context } = req.body;
    if (!language || !phrase || !translation) return res.status(400).json({ error: 'language, phrase, translation required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO phrase_library(id,user_id,language,phrase,translation,category,context) VALUES(?,?,?,?,?,?,?)').run(id, req.user.id, language, phrase, translation, category, context||null);
    res.json({ success: true, id });
  });

  app.post('/api/language/sessions', requireAuth, (req: any, res: any) => {
    const { language, session_type='vocab', duration_min, words_practiced=0, accuracy_pct=0 } = req.body;
    if (!language || !duration_min) return res.status(400).json({ error: 'language and duration_min required' });
    const id = require('crypto').randomUUID();
    const xp = Math.round(duration_min * (accuracy_pct/100 + 0.5));
    db.prepare('INSERT INTO language_sessions(id,user_id,language,session_type,duration_min,words_practiced,accuracy_pct,xp_earned) VALUES(?,?,?,?,?,?,?,?)').run(id, req.user.id, language, session_type, duration_min, words_practiced, accuracy_pct, xp);
    // Update language goal XP
    try { db.prepare('UPDATE language_goals_v2 SET total_xp=total_xp+?, current_streak=current_streak+1 WHERE user_id=? AND language=?').run(xp, req.user.id, language); } catch(e) {}
    res.json({ success: true, id, xp_earned: xp });
  });
  app.get('/api/language/goals', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM language_goals_v2 WHERE user_id=? ORDER BY total_xp DESC').all(req.user.id);
    res.json({ goals: rows });
  });
  app.post('/api/language/goals', requireAuth, (req: any, res: any) => {
    const { language, target_level='B1', daily_goal_min=15 } = req.body;
    if (!language) return res.status(400).json({ error: 'language required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT OR IGNORE INTO language_goals_v2(id,user_id,language,target_level,daily_goal_min) VALUES(?,?,?,?,?)').run(id, req.user.id, language, target_level, daily_goal_min);
    res.json({ success: true });
  });
}
// ─── End B207 ────────────────────────────────────────────────────────────────

// ─── B208: Career Coach AI, Interview Prep v2, Salary Negotiator, Skills Gap Analyzer, Job Tracker ───
{
  const job_applications_table = `CREATE TABLE IF NOT EXISTS job_applications (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, company TEXT NOT NULL,
    role TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'applied',
    applied_date TEXT NOT NULL DEFAULT (date('now')), salary_min REAL, salary_max REAL,
    location TEXT, remote INTEGER NOT NULL DEFAULT 0,
    job_url TEXT, notes TEXT, contacts TEXT NOT NULL DEFAULT '[]',
    next_action TEXT, next_action_date TEXT,
    created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const interview_preps_table = `CREATE TABLE IF NOT EXISTS interview_preps (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, job_application_id TEXT,
    company TEXT NOT NULL, role TEXT NOT NULL, interview_type TEXT NOT NULL DEFAULT 'behavioral',
    interview_date TEXT, questions TEXT NOT NULL DEFAULT '[]',
    notes TEXT, outcome TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const skills_inventory_table = `CREATE TABLE IF NOT EXISTS skills_inventory (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, skill_name TEXT NOT NULL,
    category TEXT NOT NULL DEFAULT 'technical', proficiency INTEGER NOT NULL DEFAULT 3,
    years_experience REAL DEFAULT 0, is_target INTEGER NOT NULL DEFAULT 0,
    target_proficiency INTEGER DEFAULT 5, evidence TEXT,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const career_goals_table = `CREATE TABLE IF NOT EXISTS career_goals (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, title TEXT NOT NULL,
    goal_type TEXT NOT NULL DEFAULT 'promotion', target_role TEXT,
    target_company TEXT, target_salary REAL, timeline_months INTEGER DEFAULT 12,
    status TEXT NOT NULL DEFAULT 'active', milestones TEXT NOT NULL DEFAULT '[]',
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  try { db.exec(job_applications_table); db.exec(interview_preps_table);
        db.exec(skills_inventory_table); db.exec(career_goals_table); } catch(e) {}

  app.get('/api/career/jobs', requireAuth, (req: any, res: any) => {
    const { status } = req.query as any;
    let q = 'SELECT * FROM job_applications WHERE user_id=?'; const vals: any[] = [req.user.id];
    if (status) { q += ' AND status=?'; vals.push(status); }
    q += ' ORDER BY updated_at DESC';
    const rows = db.prepare(q).all(...vals);
    res.json({ applications: rows, total: rows.length });
  });
  app.get('/api/career/jobs/funnel', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT status, COUNT(*) as count FROM job_applications WHERE user_id=? GROUP BY status').all(req.user.id);
    res.json({ funnel: rows });
  });
  app.post('/api/career/jobs', requireAuth, (req: any, res: any) => {
    const { company, role, status='applied', salary_min, salary_max, location, remote=false, job_url, notes, next_action } = req.body;
    if (!company || !role) return res.status(400).json({ error: 'company and role required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO job_applications(id,user_id,company,role,status,salary_min,salary_max,location,remote,job_url,notes,next_action) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)').run(id, req.user.id, company, role, status, salary_min||null, salary_max||null, location||null, remote?1:0, job_url||null, notes||null, next_action||null);
    res.json({ success: true, id });
  });
  app.put('/api/career/jobs/:id', requireAuth, (req: any, res: any) => {
    const allowed = ['company','role','status','salary_min','salary_max','location','job_url','notes','next_action','next_action_date'];
    const fields = ['updated_at=datetime("now")']; const vals: any[] = [];
    for (const k of allowed) { if (req.body[k] !== undefined) { fields.push(`${k}=?`); vals.push(req.body[k]); } }
    if (req.body.remote !== undefined) { fields.push('remote=?'); vals.push(req.body.remote ? 1 : 0); }
    if (req.body.contacts !== undefined) { fields.push('contacts=?'); vals.push(JSON.stringify(req.body.contacts)); }
    vals.push(req.params.id, req.user.id);
    db.prepare(`UPDATE job_applications SET ${fields.join(',')} WHERE id=? AND user_id=?`).run(...vals);
    res.json({ success: true });
  });
  app.delete('/api/career/jobs/:id', requireAuth, (req: any, res: any) => {
    db.prepare('DELETE FROM job_applications WHERE id=? AND user_id=?').run(req.params.id, req.user.id);
    res.json({ success: true });
  });

  app.get('/api/career/interviews', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM interview_preps WHERE user_id=? ORDER BY created_at DESC').all(req.user.id);
    res.json({ interviews: rows });
  });
  app.post('/api/career/interviews', requireAuth, (req: any, res: any) => {
    const { company, role, interview_type='behavioral', interview_date, job_application_id, questions=[], notes } = req.body;
    if (!company || !role) return res.status(400).json({ error: 'company and role required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO interview_preps(id,user_id,job_application_id,company,role,interview_type,interview_date,questions,notes) VALUES(?,?,?,?,?,?,?,?,?)').run(id, req.user.id, job_application_id||null, company, role, interview_type, interview_date||null, JSON.stringify(questions), notes||null);
    res.json({ success: true, id });
  });

  app.get('/api/career/skills', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM skills_inventory WHERE user_id=? ORDER BY category, skill_name').all(req.user.id);
    const gaps = (rows as any[]).filter(r => r.is_target && r.proficiency < r.target_proficiency);
    res.json({ skills: rows, gaps });
  });
  app.post('/api/career/skills', requireAuth, (req: any, res: any) => {
    const { skill_name, category='technical', proficiency=3, years_experience=0, is_target=false, target_proficiency=5, evidence } = req.body;
    if (!skill_name) return res.status(400).json({ error: 'skill_name required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO skills_inventory(id,user_id,skill_name,category,proficiency,years_experience,is_target,target_proficiency,evidence) VALUES(?,?,?,?,?,?,?,?,?)').run(id, req.user.id, skill_name, category, proficiency, years_experience, is_target?1:0, target_proficiency, evidence||null);
    res.json({ success: true, id });
  });
  app.put('/api/career/skills/:id', requireAuth, (req: any, res: any) => {
    const allowed = ['proficiency','years_experience','target_proficiency','evidence','category'];
    const fields: string[] = []; const vals: any[] = [];
    for (const k of allowed) { if (req.body[k] !== undefined) { fields.push(`${k}=?`); vals.push(req.body[k]); } }
    if (req.body.is_target !== undefined) { fields.push('is_target=?'); vals.push(req.body.is_target ? 1 : 0); }
    if (!fields.length) return res.status(400).json({ error: 'nothing to update' });
    vals.push(req.params.id, req.user.id);
    db.prepare(`UPDATE skills_inventory SET ${fields.join(',')} WHERE id=? AND user_id=?`).run(...vals);
    res.json({ success: true });
  });

  app.get('/api/career/goals', requireAuth, (req: any, res: any) => {
    res.json({ goals: db.prepare('SELECT * FROM career_goals WHERE user_id=? ORDER BY created_at DESC').all(req.user.id) });
  });
  app.post('/api/career/goals', requireAuth, (req: any, res: any) => {
    const { title, goal_type='promotion', target_role, target_company, target_salary, timeline_months=12, milestones=[] } = req.body;
    if (!title) return res.status(400).json({ error: 'title required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO career_goals(id,user_id,title,goal_type,target_role,target_company,target_salary,timeline_months,milestones) VALUES(?,?,?,?,?,?,?,?,?)').run(id, req.user.id, title, goal_type, target_role||null, target_company||null, target_salary||null, timeline_months, JSON.stringify(milestones));
    res.json({ success: true, id });
  });
}
// ─── End B208 ────────────────────────────────────────────────────────────────

// ─── B209: Mental Model Builder, Decision Framework, Second-Brain, Idea Incubator, Insight Capture ───
{
  const mental_models_table = `CREATE TABLE IF NOT EXISTS mental_models (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, name TEXT NOT NULL,
    category TEXT NOT NULL DEFAULT 'thinking', description TEXT NOT NULL,
    how_to_apply TEXT, example TEXT, source TEXT,
    use_count INTEGER NOT NULL DEFAULT 0, is_favorite INTEGER NOT NULL DEFAULT 0,
    tags TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const decisions_table = `CREATE TABLE IF NOT EXISTS decisions (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, title TEXT NOT NULL,
    context TEXT, options TEXT NOT NULL DEFAULT '[]',
    criteria TEXT NOT NULL DEFAULT '[]', chosen_option TEXT,
    reasoning TEXT, outcome TEXT, regret_score INTEGER,
    decision_date TEXT NOT NULL DEFAULT (date('now')),
    review_date TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const second_brain_table = `CREATE TABLE IF NOT EXISTS second_brain (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, title TEXT NOT NULL,
    content TEXT NOT NULL, content_type TEXT NOT NULL DEFAULT 'note',
    source TEXT, tags TEXT NOT NULL DEFAULT '[]',
    linked_ids TEXT NOT NULL DEFAULT '[]',
    is_processed INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const idea_incubator_table = `CREATE TABLE IF NOT EXISTS idea_incubator (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, title TEXT NOT NULL,
    description TEXT, status TEXT NOT NULL DEFAULT 'raw',
    potential_score INTEGER DEFAULT 5, effort_score INTEGER DEFAULT 5,
    tags TEXT NOT NULL DEFAULT '[]', next_step TEXT,
    incubated_since TEXT NOT NULL DEFAULT (date('now')),
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  try { db.exec(mental_models_table); db.exec(decisions_table);
        db.exec(second_brain_table); db.exec(idea_incubator_table); } catch(e) {}

  app.get('/api/mental-models', requireAuth, (req: any, res: any) => {
    const { category, search } = req.query as any;
    let q = 'SELECT * FROM mental_models WHERE user_id=?'; const vals: any[] = [req.user.id];
    if (category) { q += ' AND category=?'; vals.push(category); }
    if (search) { q += ' AND (name LIKE ? OR description LIKE ?)'; vals.push(`%${search}%`,`%${search}%`); }
    q += ' ORDER BY is_favorite DESC, use_count DESC';
    res.json({ models: db.prepare(q).all(...vals) });
  });
  app.post('/api/mental-models', requireAuth, (req: any, res: any) => {
    const { name, category='thinking', description, how_to_apply, example, source, tags=[] } = req.body;
    if (!name || !description) return res.status(400).json({ error: 'name and description required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO mental_models(id,user_id,name,category,description,how_to_apply,example,source,tags) VALUES(?,?,?,?,?,?,?,?,?)').run(id, req.user.id, name, category, description, how_to_apply||null, example||null, source||null, JSON.stringify(tags));
    res.json({ success: true, id });
  });
  app.post('/api/mental-models/:id/apply', requireAuth, (req: any, res: any) => {
    db.prepare('UPDATE mental_models SET use_count=use_count+1 WHERE id=? AND user_id=?').run(req.params.id, req.user.id);
    res.json({ success: true });
  });

  app.get('/api/decisions', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM decisions WHERE user_id=? ORDER BY decision_date DESC').all(req.user.id);
    res.json({ decisions: rows });
  });
  app.post('/api/decisions', requireAuth, (req: any, res: any) => {
    const { title, context, options=[], criteria=[], decision_date, review_date } = req.body;
    if (!title) return res.status(400).json({ error: 'title required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO decisions(id,user_id,title,context,options,criteria,decision_date,review_date) VALUES(?,?,?,?,?,?,?,?)').run(id, req.user.id, title, context||null, JSON.stringify(options), JSON.stringify(criteria), decision_date||new Date().toISOString().split('T')[0], review_date||null);
    res.json({ success: true, id });
  });
  app.put('/api/decisions/:id', requireAuth, (req: any, res: any) => {
    const { chosen_option, reasoning, outcome, regret_score } = req.body;
    const fields: string[] = []; const vals: any[] = [];
    if (chosen_option !== undefined) { fields.push('chosen_option=?'); vals.push(chosen_option); }
    if (reasoning !== undefined) { fields.push('reasoning=?'); vals.push(reasoning); }
    if (outcome !== undefined) { fields.push('outcome=?'); vals.push(outcome); }
    if (regret_score !== undefined) { fields.push('regret_score=?'); vals.push(regret_score); }
    if (!fields.length) return res.status(400).json({ error: 'nothing to update' });
    vals.push(req.params.id, req.user.id);
    db.prepare(`UPDATE decisions SET ${fields.join(',')} WHERE id=? AND user_id=?`).run(...vals);
    res.json({ success: true });
  });

  app.get('/api/second-brain', requireAuth, (req: any, res: any) => {
    const { content_type, search, unprocessed } = req.query as any;
    let q = 'SELECT * FROM second_brain WHERE user_id=?'; const vals: any[] = [req.user.id];
    if (content_type) { q += ' AND content_type=?'; vals.push(content_type); }
    if (unprocessed === 'true') { q += ' AND is_processed=0'; }
    if (search) { q += ' AND (title LIKE ? OR content LIKE ?)'; vals.push(`%${search}%`,`%${search}%`); }
    q += ' ORDER BY updated_at DESC';
    res.json({ items: db.prepare(q).all(...vals) });
  });
  app.post('/api/second-brain', requireAuth, (req: any, res: any) => {
    const { title, content, content_type='note', source, tags=[], linked_ids=[] } = req.body;
    if (!title || !content) return res.status(400).json({ error: 'title and content required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO second_brain(id,user_id,title,content,content_type,source,tags,linked_ids) VALUES(?,?,?,?,?,?,?,?)').run(id, req.user.id, title, content, content_type, source||null, JSON.stringify(tags), JSON.stringify(linked_ids));
    res.json({ success: true, id });
  });
  app.put('/api/second-brain/:id', requireAuth, (req: any, res: any) => {
    const { title, content, is_processed, tags, linked_ids } = req.body;
    const fields = ['updated_at=datetime("now")']; const vals: any[] = [];
    if (title !== undefined) { fields.push('title=?'); vals.push(title); }
    if (content !== undefined) { fields.push('content=?'); vals.push(content); }
    if (is_processed !== undefined) { fields.push('is_processed=?'); vals.push(is_processed ? 1 : 0); }
    if (tags !== undefined) { fields.push('tags=?'); vals.push(JSON.stringify(tags)); }
    if (linked_ids !== undefined) { fields.push('linked_ids=?'); vals.push(JSON.stringify(linked_ids)); }
    vals.push(req.params.id, req.user.id);
    db.prepare(`UPDATE second_brain SET ${fields.join(',')} WHERE id=? AND user_id=?`).run(...vals);
    res.json({ success: true });
  });

  app.get('/api/ideas', requireAuth, (req: any, res: any) => {
    const { status } = req.query as any;
    let q = 'SELECT * FROM idea_incubator WHERE user_id=?'; const vals: any[] = [req.user.id];
    if (status) { q += ' AND status=?'; vals.push(status); }
    q += ' ORDER BY potential_score DESC, created_at DESC';
    res.json({ ideas: db.prepare(q).all(...vals) });
  });
  app.post('/api/ideas', requireAuth, (req: any, res: any) => {
    const { title, description, potential_score=5, effort_score=5, tags=[], next_step } = req.body;
    if (!title) return res.status(400).json({ error: 'title required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO idea_incubator(id,user_id,title,description,potential_score,effort_score,tags,next_step) VALUES(?,?,?,?,?,?,?,?)').run(id, req.user.id, title, description||null, potential_score, effort_score, JSON.stringify(tags), next_step||null);
    res.json({ success: true, id });
  });
  app.put('/api/ideas/:id', requireAuth, (req: any, res: any) => {
    const { status, potential_score, effort_score, next_step, description } = req.body;
    const fields: string[] = []; const vals: any[] = [];
    if (status !== undefined) { fields.push('status=?'); vals.push(status); }
    if (potential_score !== undefined) { fields.push('potential_score=?'); vals.push(potential_score); }
    if (effort_score !== undefined) { fields.push('effort_score=?'); vals.push(effort_score); }
    if (next_step !== undefined) { fields.push('next_step=?'); vals.push(next_step); }
    if (description !== undefined) { fields.push('description=?'); vals.push(description); }
    if (!fields.length) return res.status(400).json({ error: 'nothing to update' });
    vals.push(req.params.id, req.user.id);
    db.prepare(`UPDATE idea_incubator SET ${fields.join(',')} WHERE id=? AND user_id=?`).run(...vals);
    res.json({ success: true });
  });
}
// ─── End B209 ────────────────────────────────────────────────────────────────

// ─── B210: Life OS, Weekly Review, Quarterly Planning, Life Domains, Personal Mission Statement ───
{
  const life_domains_table = `CREATE TABLE IF NOT EXISTS life_domains (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, domain TEXT NOT NULL,
    current_score INTEGER NOT NULL DEFAULT 5, target_score INTEGER NOT NULL DEFAULT 9,
    notes TEXT, color TEXT NOT NULL DEFAULT '#6366f1',
    updated_at TEXT NOT NULL DEFAULT (datetime('now')),
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const weekly_reviews_table = `CREATE TABLE IF NOT EXISTS weekly_reviews (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL,
    week_start TEXT NOT NULL, week_end TEXT NOT NULL,
    wins TEXT NOT NULL DEFAULT '[]', challenges TEXT NOT NULL DEFAULT '[]',
    lessons TEXT NOT NULL DEFAULT '[]', focus_next_week TEXT,
    energy_level INTEGER, overall_score INTEGER,
    gratitude TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const quarterly_plans_table = `CREATE TABLE IF NOT EXISTS quarterly_plans (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, quarter TEXT NOT NULL,
    year INTEGER NOT NULL, theme TEXT,
    big_goals TEXT NOT NULL DEFAULT '[]', key_results TEXT NOT NULL DEFAULT '[]',
    anti_goals TEXT NOT NULL DEFAULT '[]',
    reflection TEXT, score INTEGER, created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const mission_statements_table = `CREATE TABLE IF NOT EXISTS mission_statements (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL,
    mission TEXT NOT NULL, vision TEXT, core_values TEXT NOT NULL DEFAULT '[]',
    purpose TEXT, version INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  try { db.exec(life_domains_table); db.exec(weekly_reviews_table);
        db.exec(quarterly_plans_table); db.exec(mission_statements_table); } catch(e) {}

  app.get('/api/life/domains', requireAuth, (req: any, res: any) => {
    const DEFAULT_DOMAINS = ['Health','Relationships','Career','Finance','Personal Growth','Fun & Recreation','Environment','Spirituality'];
    let rows = db.prepare('SELECT * FROM life_domains WHERE user_id=? ORDER BY domain').all(req.user.id) as any[];
    if (!rows.length) {
      // Seed defaults
      DEFAULT_DOMAINS.forEach(d => {
        const id = require('crypto').randomUUID();
        try { db.prepare('INSERT INTO life_domains(id,user_id,domain) VALUES(?,?,?)').run(id, req.user.id, d); } catch(e) {}
      });
      rows = db.prepare('SELECT * FROM life_domains WHERE user_id=? ORDER BY domain').all(req.user.id) as any[];
    }
    const avg = rows.reduce((a, r) => a + r.current_score, 0) / Math.max(rows.length, 1);
    res.json({ domains: rows, avg_score: Math.round(avg*10)/10 });
  });
  app.put('/api/life/domains/:id', requireAuth, (req: any, res: any) => {
    const { current_score, target_score, notes, color } = req.body;
    const fields = ['updated_at=datetime("now")']; const vals: any[] = [];
    if (current_score !== undefined) { fields.push('current_score=?'); vals.push(current_score); }
    if (target_score !== undefined) { fields.push('target_score=?'); vals.push(target_score); }
    if (notes !== undefined) { fields.push('notes=?'); vals.push(notes); }
    if (color !== undefined) { fields.push('color=?'); vals.push(color); }
    vals.push(req.params.id, req.user.id);
    db.prepare(`UPDATE life_domains SET ${fields.join(',')} WHERE id=? AND user_id=?`).run(...vals);
    res.json({ success: true });
  });

  app.get('/api/life/weekly-reviews', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM weekly_reviews WHERE user_id=? ORDER BY week_start DESC LIMIT 12').all(req.user.id);
    res.json({ reviews: rows });
  });
  app.post('/api/life/weekly-reviews', requireAuth, (req: any, res: any) => {
    const { week_start, week_end, wins=[], challenges=[], lessons=[], focus_next_week, energy_level, overall_score, gratitude } = req.body;
    if (!week_start || !week_end) return res.status(400).json({ error: 'week_start and week_end required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO weekly_reviews(id,user_id,week_start,week_end,wins,challenges,lessons,focus_next_week,energy_level,overall_score,gratitude) VALUES(?,?,?,?,?,?,?,?,?,?,?)').run(id, req.user.id, week_start, week_end, JSON.stringify(wins), JSON.stringify(challenges), JSON.stringify(lessons), focus_next_week||null, energy_level||null, overall_score||null, gratitude||null);
    res.json({ success: true, id });
  });

  app.get('/api/life/quarterly-plans', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM quarterly_plans WHERE user_id=? ORDER BY year DESC, quarter DESC').all(req.user.id);
    res.json({ plans: rows });
  });
  app.post('/api/life/quarterly-plans', requireAuth, (req: any, res: any) => {
    const { quarter, year, theme, big_goals=[], key_results=[], anti_goals=[] } = req.body;
    if (!quarter || !year) return res.status(400).json({ error: 'quarter and year required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO quarterly_plans(id,user_id,quarter,year,theme,big_goals,key_results,anti_goals) VALUES(?,?,?,?,?,?,?,?)').run(id, req.user.id, quarter, year, theme||null, JSON.stringify(big_goals), JSON.stringify(key_results), JSON.stringify(anti_goals));
    res.json({ success: true, id });
  });
  app.put('/api/life/quarterly-plans/:id', requireAuth, (req: any, res: any) => {
    const { reflection, score } = req.body;
    const fields: string[] = []; const vals: any[] = [];
    if (reflection !== undefined) { fields.push('reflection=?'); vals.push(reflection); }
    if (score !== undefined) { fields.push('score=?'); vals.push(score); }
    if (!fields.length) return res.status(400).json({ error: 'nothing to update' });
    vals.push(req.params.id, req.user.id);
    db.prepare(`UPDATE quarterly_plans SET ${fields.join(',')} WHERE id=? AND user_id=?`).run(...vals);
    res.json({ success: true });
  });

  app.get('/api/life/mission', requireAuth, (req: any, res: any) => {
    const row = db.prepare('SELECT * FROM mission_statements WHERE user_id=? ORDER BY version DESC LIMIT 1').get(req.user.id);
    res.json({ mission: row || null });
  });
  app.post('/api/life/mission', requireAuth, (req: any, res: any) => {
    const { mission, vision, core_values=[], purpose } = req.body;
    if (!mission) return res.status(400).json({ error: 'mission required' });
    const latest = db.prepare('SELECT version FROM mission_statements WHERE user_id=? ORDER BY version DESC LIMIT 1').get(req.user.id) as any;
    const version = latest ? latest.version + 1 : 1;
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO mission_statements(id,user_id,mission,vision,core_values,purpose,version) VALUES(?,?,?,?,?,?,?)').run(id, req.user.id, mission, vision||null, JSON.stringify(core_values), purpose||null, version);
    res.json({ success: true, id, version });
  });

  // Life OS Dashboard
  app.get('/api/life/dashboard', requireAuth, (req: any, res: any) => {
    const uid = req.user.id;
    const domains = db.prepare('SELECT AVG(current_score) as avg FROM life_domains WHERE user_id=?').get(uid) as any;
    const reviews = (db.prepare('SELECT COUNT(*) as c FROM weekly_reviews WHERE user_id=?').get(uid) as any)?.c || 0;
    const plans = (db.prepare('SELECT COUNT(*) as c FROM quarterly_plans WHERE user_id=?').get(uid) as any)?.c || 0;
    const mission = db.prepare('SELECT mission FROM mission_statements WHERE user_id=? ORDER BY version DESC LIMIT 1').get(uid) as any;
    res.json({
      life_score: Math.round((domains?.avg || 0) * 10) / 10,
      weekly_reviews_done: reviews,
      quarterly_plans: plans,
      has_mission: !!mission,
      mission_preview: mission?.mission?.slice(0, 100) || null,
    });
  });
}
// ─── End B210 ────────────────────────────────────────────────────────────────

// ─── B211: AI Model Router v2, Smart Model Selector, Routing Rules, Cost Optimizer, Latency Monitor ───
{
  const routing_rules_table = `CREATE TABLE IF NOT EXISTS routing_rules (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, name TEXT NOT NULL,
    condition_type TEXT NOT NULL DEFAULT 'keyword', condition_value TEXT NOT NULL,
    preferred_model TEXT NOT NULL, fallback_model TEXT,
    max_cost_per_request REAL DEFAULT 0, max_latency_ms INTEGER DEFAULT 5000,
    priority INTEGER NOT NULL DEFAULT 5, is_active INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const model_benchmarks_table = `CREATE TABLE IF NOT EXISTS model_benchmarks (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, model TEXT NOT NULL,
    task_type TEXT NOT NULL DEFAULT 'general', avg_latency_ms REAL DEFAULT 0,
    avg_cost_per_1k_tokens REAL DEFAULT 0, quality_score REAL DEFAULT 8,
    sample_count INTEGER NOT NULL DEFAULT 0,
    last_updated TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const routing_log_table = `CREATE TABLE IF NOT EXISTS routing_log_v2 (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, input_hash TEXT NOT NULL,
    selected_model TEXT NOT NULL, routing_reason TEXT,
    rule_id TEXT, tokens_used INTEGER DEFAULT 0, cost_usd REAL DEFAULT 0,
    latency_ms INTEGER DEFAULT 0, quality_feedback INTEGER,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  try { db.exec(routing_rules_table); db.exec(model_benchmarks_table); db.exec(routing_log_table); } catch(e) {}

  app.get('/api/routing/rules', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM routing_rules WHERE user_id=? ORDER BY priority DESC, created_at DESC').all(req.user.id);
    res.json({ rules: rows });
  });
  app.post('/api/routing/rules', requireAuth, (req: any, res: any) => {
    const { name, condition_type='keyword', condition_value, preferred_model, fallback_model, max_cost_per_request=0, priority=5 } = req.body;
    if (!name || !condition_value || !preferred_model) return res.status(400).json({ error: 'name, condition_value, preferred_model required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO routing_rules(id,user_id,name,condition_type,condition_value,preferred_model,fallback_model,max_cost_per_request,priority) VALUES(?,?,?,?,?,?,?,?,?)').run(id, req.user.id, name, condition_type, condition_value, preferred_model, fallback_model||null, max_cost_per_request, priority);
    res.json({ success: true, id });
  });
  app.put('/api/routing/rules/:id', requireAuth, (req: any, res: any) => {
    const { is_active, priority, preferred_model, fallback_model } = req.body;
    const fields: string[] = []; const vals: any[] = [];
    if (is_active !== undefined) { fields.push('is_active=?'); vals.push(is_active ? 1 : 0); }
    if (priority !== undefined) { fields.push('priority=?'); vals.push(priority); }
    if (preferred_model !== undefined) { fields.push('preferred_model=?'); vals.push(preferred_model); }
    if (fallback_model !== undefined) { fields.push('fallback_model=?'); vals.push(fallback_model); }
    if (!fields.length) return res.status(400).json({ error: 'nothing to update' });
    vals.push(req.params.id, req.user.id);
    db.prepare(`UPDATE routing_rules SET ${fields.join(',')} WHERE id=? AND user_id=?`).run(...vals);
    res.json({ success: true });
  });
  app.delete('/api/routing/rules/:id', requireAuth, (req: any, res: any) => {
    db.prepare('DELETE FROM routing_rules WHERE id=? AND user_id=?').run(req.params.id, req.user.id);
    res.json({ success: true });
  });
  app.post('/api/routing/select', requireAuth, (req: any, res: any) => {
    const { prompt, task_type='general', available_models=['claude-opus-4-5','gpt-4o','gemini-2.0-flash'] } = req.body;
    if (!prompt) return res.status(400).json({ error: 'prompt required' });
    // Check user rules
    const rules = db.prepare('SELECT * FROM routing_rules WHERE user_id=? AND is_active=1 ORDER BY priority DESC').all(req.user.id) as any[];
    let selected = available_models[0]; let reason = 'default';
    for (const rule of rules) {
      if (rule.condition_type === 'keyword' && prompt.toLowerCase().includes(rule.condition_value.toLowerCase())) {
        selected = rule.preferred_model; reason = `rule:${rule.name}`; break;
      }
      if (rule.condition_type === 'task_type' && task_type === rule.condition_value) {
        selected = rule.preferred_model; reason = `rule:${rule.name}`; break;
      }
    }
    // Log the routing decision
    const id = require('crypto').randomUUID();
    const hash = require('crypto').createHash('md5').update(prompt.slice(0, 100)).digest('hex');
    try { db.prepare('INSERT INTO routing_log_v2(id,user_id,input_hash,selected_model,routing_reason) VALUES(?,?,?,?,?)').run(id, req.user.id, hash, selected, reason); } catch(e) {}
    res.json({ selected_model: selected, reason, available_models, routing_id: id });
  });
  app.get('/api/routing/analytics', requireAuth, (req: any, res: any) => {
    const logs = db.prepare('SELECT selected_model, COUNT(*) as uses, AVG(cost_usd) as avg_cost, AVG(latency_ms) as avg_latency FROM routing_log_v2 WHERE user_id=? GROUP BY selected_model').all(req.user.id);
    const total = (db.prepare('SELECT COUNT(*) as c, SUM(cost_usd) as total_cost FROM routing_log_v2 WHERE user_id=?').get(req.user.id) as any) || { c: 0, total_cost: 0 };
    res.json({ by_model: logs, total_requests: total.c, total_cost_usd: total.total_cost });
  });
  app.get('/api/model-benchmarks', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM model_benchmarks WHERE user_id=? ORDER BY quality_score DESC').all(req.user.id);
    if (!rows.length) {
      // Return default benchmarks
      const defaults = [
        { model: 'claude-opus-4-5', task_type: 'reasoning', avg_latency_ms: 2800, avg_cost_per_1k_tokens: 0.015, quality_score: 9.5 },
        { model: 'claude-sonnet-4-5', task_type: 'general', avg_latency_ms: 1200, avg_cost_per_1k_tokens: 0.003, quality_score: 9.0 },
        { model: 'gpt-4o', task_type: 'general', avg_latency_ms: 1500, avg_cost_per_1k_tokens: 0.005, quality_score: 8.8 },
        { model: 'gemini-2.0-flash', task_type: 'speed', avg_latency_ms: 600, avg_cost_per_1k_tokens: 0.0001, quality_score: 8.2 },
      ];
      return res.json({ benchmarks: defaults, source: 'defaults' });
    }
    res.json({ benchmarks: rows, source: 'user_data' });
  });
}
// ─── End B211 ────────────────────────────────────────────────────────────────

// ─── B212: Prompt Library v2, Prompt Templates, Prompt Variables, Version Control, Prompt Analytics ───
{
  const prompt_templates_v2_table = `CREATE TABLE IF NOT EXISTS prompt_templates_v2 (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, title TEXT NOT NULL,
    description TEXT, template TEXT NOT NULL,
    variables TEXT NOT NULL DEFAULT '[]', category TEXT NOT NULL DEFAULT 'general',
    model_hint TEXT, max_tokens INTEGER DEFAULT 2000,
    tags TEXT NOT NULL DEFAULT '[]', is_public INTEGER NOT NULL DEFAULT 0,
    use_count INTEGER NOT NULL DEFAULT 0, avg_rating REAL DEFAULT 0,
    version INTEGER NOT NULL DEFAULT 1, parent_id TEXT,
    created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const prompt_runs_table = `CREATE TABLE IF NOT EXISTS prompt_runs (
    id TEXT PRIMARY KEY, template_id TEXT NOT NULL, user_id TEXT NOT NULL,
    variables_used TEXT NOT NULL DEFAULT '{}', rendered_prompt TEXT NOT NULL,
    model_used TEXT, tokens_used INTEGER DEFAULT 0, response_quality INTEGER,
    notes TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  try { db.exec(prompt_templates_v2_table); db.exec(prompt_runs_table); } catch(e) {}

  app.get('/api/prompt-templates', requireAuth, (req: any, res: any) => {
    const { category, search, public_only } = req.query as any;
    let q = 'SELECT * FROM prompt_templates_v2 WHERE (user_id=? OR is_public=1)'; const vals: any[] = [req.user.id];
    if (public_only === 'true') { q = 'SELECT * FROM prompt_templates_v2 WHERE is_public=1'; vals.length = 0; }
    if (category) { q += ' AND category=?'; vals.push(category); }
    if (search) { q += ' AND (title LIKE ? OR description LIKE ?)'; vals.push(`%${search}%`,`%${search}%`); }
    q += ' ORDER BY use_count DESC, created_at DESC';
    res.json({ templates: db.prepare(q).all(...vals) });
  });
  app.post('/api/prompt-templates', requireAuth, (req: any, res: any) => {
    const { title, description, template, variables=[], category='general', model_hint, max_tokens=2000, tags=[], is_public=false } = req.body;
    if (!title || !template) return res.status(400).json({ error: 'title and template required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO prompt_templates_v2(id,user_id,title,description,template,variables,category,model_hint,max_tokens,tags,is_public) VALUES(?,?,?,?,?,?,?,?,?,?,?)').run(id, req.user.id, title, description||null, template, JSON.stringify(variables), category, model_hint||null, max_tokens, JSON.stringify(tags), is_public?1:0);
    res.json({ success: true, id });
  });
  app.post('/api/prompt-templates/:id/render', requireAuth, (req: any, res: any) => {
    const tpl = db.prepare('SELECT * FROM prompt_templates_v2 WHERE id=? AND (user_id=? OR is_public=1)').get(req.params.id, req.user.id) as any;
    if (!tpl) return res.status(404).json({ error: 'not found' });
    const { variables={} } = req.body;
    let rendered = tpl.template;
    for (const [k, v] of Object.entries(variables)) { rendered = rendered.replace(new RegExp(`\\{\\{${k}\\}\\}`, 'g'), v as string); }
    db.prepare('UPDATE prompt_templates_v2 SET use_count=use_count+1, updated_at=datetime("now") WHERE id=?').run(req.params.id);
    const runId = require('crypto').randomUUID();
    try { db.prepare('INSERT INTO prompt_runs(id,template_id,user_id,variables_used,rendered_prompt) VALUES(?,?,?,?,?)').run(runId, req.params.id, req.user.id, JSON.stringify(variables), rendered); } catch(e) {}
    res.json({ success: true, rendered, run_id: runId, variables_used: variables });
  });
  app.put('/api/prompt-templates/:id', requireAuth, (req: any, res: any) => {
    const { title, description, template, category, is_public } = req.body;
    const fields = ['updated_at=datetime("now")','version=version+1']; const vals: any[] = [];
    if (title !== undefined) { fields.push('title=?'); vals.push(title); }
    if (description !== undefined) { fields.push('description=?'); vals.push(description); }
    if (template !== undefined) { fields.push('template=?'); vals.push(template); }
    if (category !== undefined) { fields.push('category=?'); vals.push(category); }
    if (is_public !== undefined) { fields.push('is_public=?'); vals.push(is_public ? 1 : 0); }
    vals.push(req.params.id, req.user.id);
    db.prepare(`UPDATE prompt_templates_v2 SET ${fields.join(',')} WHERE id=? AND user_id=?`).run(...vals);
    res.json({ success: true });
  });
  app.delete('/api/prompt-templates/:id', requireAuth, (req: any, res: any) => {
    db.prepare('DELETE FROM prompt_templates_v2 WHERE id=? AND user_id=?').run(req.params.id, req.user.id);
    res.json({ success: true });
  });
  app.get('/api/prompt-templates/analytics', requireAuth, (req: any, res: any) => {
    const top = db.prepare('SELECT t.title, t.id, t.use_count, COUNT(r.id) as total_runs FROM prompt_templates_v2 t LEFT JOIN prompt_runs r ON r.template_id=t.id WHERE t.user_id=? GROUP BY t.id ORDER BY total_runs DESC LIMIT 10').all(req.user.id);
    res.json({ top_templates: top });
  });
}
// ─── End B212 ────────────────────────────────────────────────────────────────

// ─── B213: Context Manager, Thread Memory, Persona Switcher, System Prompt Builder, AI Config ───
{
  const personas_table = `CREATE TABLE IF NOT EXISTS personas (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, name TEXT NOT NULL,
    description TEXT, system_prompt TEXT NOT NULL,
    model_preference TEXT, temperature REAL DEFAULT 0.7,
    max_tokens INTEGER DEFAULT 4096, avatar_emoji TEXT NOT NULL DEFAULT '🤖',
    is_default INTEGER NOT NULL DEFAULT 0, use_count INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const thread_context_v2_table = `CREATE TABLE IF NOT EXISTS thread_context_v2 (
    id TEXT PRIMARY KEY, thread_id TEXT NOT NULL, user_id TEXT NOT NULL,
    context_type TEXT NOT NULL DEFAULT 'background', content TEXT NOT NULL,
    priority INTEGER NOT NULL DEFAULT 5, is_active INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const ai_configs_table = `CREATE TABLE IF NOT EXISTS ai_configs (
    user_id TEXT PRIMARY KEY, default_model TEXT NOT NULL DEFAULT 'claude-sonnet-4-5',
    default_temperature REAL NOT NULL DEFAULT 0.7, default_max_tokens INTEGER NOT NULL DEFAULT 4096,
    stream_responses INTEGER NOT NULL DEFAULT 1, show_token_counts INTEGER NOT NULL DEFAULT 1,
    auto_title_threads INTEGER NOT NULL DEFAULT 1, memory_injection INTEGER NOT NULL DEFAULT 1,
    response_format TEXT NOT NULL DEFAULT 'markdown',
    updated_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  try { db.exec(personas_table); db.exec(thread_context_v2_table); db.exec(ai_configs_table); } catch(e) {}

  app.get('/api/personas', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM personas WHERE user_id=? ORDER BY is_default DESC, use_count DESC').all(req.user.id);
    res.json({ personas: rows });
  });
  app.post('/api/personas', requireAuth, (req: any, res: any) => {
    const { name, description, system_prompt, model_preference, temperature=0.7, max_tokens=4096, avatar_emoji='🤖', is_default=false } = req.body;
    if (!name || !system_prompt) return res.status(400).json({ error: 'name and system_prompt required' });
    const id = require('crypto').randomUUID();
    if (is_default) { try { db.prepare('UPDATE personas SET is_default=0 WHERE user_id=?').run(req.user.id); } catch(e) {} }
    db.prepare('INSERT INTO personas(id,user_id,name,description,system_prompt,model_preference,temperature,max_tokens,avatar_emoji,is_default) VALUES(?,?,?,?,?,?,?,?,?,?)').run(id, req.user.id, name, description||null, system_prompt, model_preference||null, temperature, max_tokens, avatar_emoji, is_default?1:0);
    res.json({ success: true, id });
  });
  app.put('/api/personas/:id', requireAuth, (req: any, res: any) => {
    const { name, description, system_prompt, model_preference, temperature, max_tokens, avatar_emoji, is_default } = req.body;
    const fields: string[] = []; const vals: any[] = [];
    if (name !== undefined) { fields.push('name=?'); vals.push(name); }
    if (description !== undefined) { fields.push('description=?'); vals.push(description); }
    if (system_prompt !== undefined) { fields.push('system_prompt=?'); vals.push(system_prompt); }
    if (model_preference !== undefined) { fields.push('model_preference=?'); vals.push(model_preference); }
    if (temperature !== undefined) { fields.push('temperature=?'); vals.push(temperature); }
    if (max_tokens !== undefined) { fields.push('max_tokens=?'); vals.push(max_tokens); }
    if (avatar_emoji !== undefined) { fields.push('avatar_emoji=?'); vals.push(avatar_emoji); }
    if (is_default !== undefined) {
      if (is_default) { try { db.prepare('UPDATE personas SET is_default=0 WHERE user_id=?').run(req.user.id); } catch(e) {} }
      fields.push('is_default=?'); vals.push(is_default ? 1 : 0);
    }
    if (!fields.length) return res.status(400).json({ error: 'nothing to update' });
    vals.push(req.params.id, req.user.id);
    db.prepare(`UPDATE personas SET ${fields.join(',')} WHERE id=? AND user_id=?`).run(...vals);
    res.json({ success: true });
  });
  app.delete('/api/personas/:id', requireAuth, (req: any, res: any) => {
    db.prepare('DELETE FROM personas WHERE id=? AND user_id=?').run(req.params.id, req.user.id);
    res.json({ success: true });
  });
  app.post('/api/personas/:id/use', requireAuth, (req: any, res: any) => {
    const p = db.prepare('SELECT * FROM personas WHERE id=? AND user_id=?').get(req.params.id, req.user.id) as any;
    if (!p) return res.status(404).json({ error: 'not found' });
    db.prepare('UPDATE personas SET use_count=use_count+1 WHERE id=?').run(req.params.id);
    res.json({ persona: p, activated: true });
  });

  app.get('/api/threads/:threadId/context', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT * FROM thread_context_v2 WHERE thread_id=? AND user_id=? AND is_active=1 ORDER BY priority DESC').all(req.params.threadId, req.user.id);
    res.json({ context: rows });
  });
  app.post('/api/threads/:threadId/context', requireAuth, (req: any, res: any) => {
    const { content, context_type='background', priority=5 } = req.body;
    if (!content) return res.status(400).json({ error: 'content required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO thread_context_v2(id,thread_id,user_id,context_type,content,priority) VALUES(?,?,?,?,?,?)').run(id, req.params.threadId, req.user.id, context_type, content, priority);
    res.json({ success: true, id });
  });
  app.delete('/api/threads/:threadId/context/:contextId', requireAuth, (req: any, res: any) => {
    db.prepare('UPDATE thread_context_v2 SET is_active=0 WHERE id=? AND user_id=?').run(req.params.contextId, req.user.id);
    res.json({ success: true });
  });

  app.get('/api/ai-config', requireAuth, (req: any, res: any) => {
    const row = db.prepare('SELECT * FROM ai_configs WHERE user_id=?').get(req.user.id);
    res.json({ config: row || { user_id: req.user.id, default_model: 'claude-sonnet-4-5', default_temperature: 0.7, default_max_tokens: 4096, stream_responses: 1, show_token_counts: 1, auto_title_threads: 1, memory_injection: 1, response_format: 'markdown' } });
  });
  app.put('/api/ai-config', requireAuth, (req: any, res: any) => {
    const { default_model, default_temperature, default_max_tokens, stream_responses, show_token_counts, auto_title_threads, memory_injection, response_format } = req.body;
    try {
      db.prepare(`INSERT INTO ai_configs(user_id,default_model,default_temperature,default_max_tokens,stream_responses,show_token_counts,auto_title_threads,memory_injection,response_format) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(user_id) DO UPDATE SET default_model=COALESCE(?,default_model), default_temperature=COALESCE(?,default_temperature), default_max_tokens=COALESCE(?,default_max_tokens), stream_responses=COALESCE(?,stream_responses), show_token_counts=COALESCE(?,show_token_counts), auto_title_threads=COALESCE(?,auto_title_threads), memory_injection=COALESCE(?,memory_injection), response_format=COALESCE(?,response_format), updated_at=datetime("now")`).run(req.user.id, default_model||'claude-sonnet-4-5', default_temperature||0.7, default_max_tokens||4096, stream_responses??1, show_token_counts??1, auto_title_threads??1, memory_injection??1, response_format||'markdown', default_model||null, default_temperature||null, default_max_tokens||null, stream_responses??null, show_token_counts??null, auto_title_threads??null, memory_injection??null, response_format||null);
    } catch(e) { db.prepare('UPDATE ai_configs SET updated_at=datetime("now") WHERE user_id=?').run(req.user.id); }
    res.json({ success: true });
  });
}
// ─── End B213 ────────────────────────────────────────────────────────────────

// ─── B214: Multi-Step AI Tasks, Task Queue, Background Jobs, Progress Streaming, Result Cache ───
{
  const ai_tasks_table = `CREATE TABLE IF NOT EXISTS ai_tasks (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, title TEXT NOT NULL,
    task_type TEXT NOT NULL DEFAULT 'single', steps TEXT NOT NULL DEFAULT '[]',
    current_step INTEGER NOT NULL DEFAULT 0, total_steps INTEGER NOT NULL DEFAULT 1,
    status TEXT NOT NULL DEFAULT 'pending', priority INTEGER NOT NULL DEFAULT 5,
    input TEXT NOT NULL DEFAULT '{}', output TEXT NOT NULL DEFAULT '{}',
    error TEXT, model_used TEXT, tokens_used INTEGER DEFAULT 0,
    cost_usd REAL DEFAULT 0, progress_pct INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (datetime('now')),
    started_at TEXT, completed_at TEXT
  )`;
  const result_cache_table = `CREATE TABLE IF NOT EXISTS result_cache (
    id TEXT PRIMARY KEY, user_id TEXT NOT NULL, cache_key TEXT NOT NULL,
    model TEXT NOT NULL, prompt_hash TEXT NOT NULL, response TEXT NOT NULL,
    tokens_used INTEGER DEFAULT 0, hit_count INTEGER NOT NULL DEFAULT 0,
    expires_at TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  try { db.exec(ai_tasks_table); db.exec(result_cache_table); } catch(e) {}

  app.get('/api/ai-tasks', requireAuth, (req: any, res: any) => {
    const { status } = req.query as any;
    let q = 'SELECT * FROM ai_tasks WHERE user_id=?'; const vals: any[] = [req.user.id];
    if (status) { q += ' AND status=?'; vals.push(status); }
    q += ' ORDER BY priority DESC, created_at DESC LIMIT 50';
    res.json({ tasks: db.prepare(q).all(...vals) });
  });
  app.post('/api/ai-tasks', requireAuth, (req: any, res: any) => {
    const { title, task_type='single', steps=[], input={}, priority=5, model_used } = req.body;
    if (!title) return res.status(400).json({ error: 'title required' });
    const id = require('crypto').randomUUID();
    const total_steps = steps.length || 1;
    db.prepare('INSERT INTO ai_tasks(id,user_id,title,task_type,steps,total_steps,input,priority,model_used) VALUES(?,?,?,?,?,?,?,?,?)').run(id, req.user.id, title, task_type, JSON.stringify(steps), total_steps, JSON.stringify(input), priority, model_used||null);
    res.json({ success: true, id, status: 'pending' });
  });
  app.post('/api/ai-tasks/:id/start', requireAuth, (req: any, res: any) => {
    const task = db.prepare('SELECT * FROM ai_tasks WHERE id=? AND user_id=?').get(req.params.id, req.user.id) as any;
    if (!task) return res.status(404).json({ error: 'not found' });
    db.prepare('UPDATE ai_tasks SET status=?,started_at=datetime("now"),progress_pct=10 WHERE id=?').run('running', req.params.id);
    // Simulate task execution
    setTimeout(() => {
      try {
        db.prepare('UPDATE ai_tasks SET status=?,completed_at=datetime("now"),progress_pct=100,output=? WHERE id=?').run('completed', JSON.stringify({ result: 'Task completed successfully', steps_completed: task.total_steps }), req.params.id);
      } catch(e) {}
    }, 100);
    res.json({ success: true, status: 'running' });
  });
  app.get('/api/ai-tasks/:id/status', requireAuth, (req: any, res: any) => {
    const task = db.prepare('SELECT id,title,status,progress_pct,current_step,total_steps,error,completed_at FROM ai_tasks WHERE id=? AND user_id=?').get(req.params.id, req.user.id);
    if (!task) return res.status(404).json({ error: 'not found' });
    res.json({ task });
  });
  app.delete('/api/ai-tasks/:id', requireAuth, (req: any, res: any) => {
    db.prepare('UPDATE ai_tasks SET status=? WHERE id=? AND user_id=?').run('cancelled', req.params.id, req.user.id);
    res.json({ success: true });
  });
  app.get('/api/ai-tasks/queue', requireAuth, (req: any, res: any) => {
    const pending = db.prepare('SELECT COUNT(*) as c FROM ai_tasks WHERE user_id=? AND status="pending"').get(req.user.id) as any;
    const running = db.prepare('SELECT COUNT(*) as c FROM ai_tasks WHERE user_id=? AND status="running"').get(req.user.id) as any;
    const completed_today = db.prepare(`SELECT COUNT(*) as c FROM ai_tasks WHERE user_id=? AND status="completed" AND date(completed_at)=date('now')`).get(req.user.id) as any;
    res.json({ pending: pending?.c||0, running: running?.c||0, completed_today: completed_today?.c||0 });
  });

  app.get('/api/cache', requireAuth, (req: any, res: any) => {
    const rows = db.prepare('SELECT id,cache_key,model,hit_count,created_at,expires_at FROM result_cache WHERE user_id=? ORDER BY hit_count DESC LIMIT 20').all(req.user.id);
    const total_hits = (rows as any[]).reduce((a, r: any) => a + r.hit_count, 0);
    res.json({ cache_entries: rows, total_hits, entry_count: rows.length });
  });
  app.post('/api/cache', requireAuth, (req: any, res: any) => {
    const { cache_key, model, prompt, response, tokens_used=0, ttl_hours=24 } = req.body;
    if (!cache_key || !model || !response) return res.status(400).json({ error: 'cache_key, model, response required' });
    const id = require('crypto').randomUUID();
    const hash = require('crypto').createHash('md5').update(prompt||cache_key).digest('hex');
    const expires = new Date(Date.now() + ttl_hours*3600*1000).toISOString();
    db.prepare('INSERT OR REPLACE INTO result_cache(id,user_id,cache_key,model,prompt_hash,response,tokens_used,expires_at) VALUES(?,?,?,?,?,?,?,?)').run(id, req.user.id, cache_key, model, hash, response, tokens_used, expires);
    res.json({ success: true, id, expires_at: expires });
  });
  app.get('/api/cache/lookup', requireAuth, (req: any, res: any) => {
    const { key } = req.query as any;
    if (!key) return res.status(400).json({ error: 'key required' });
    const row = db.prepare("SELECT * FROM result_cache WHERE user_id=? AND cache_key=? AND (expires_at IS NULL OR expires_at>datetime('now'))").get(req.user.id, key) as any;
    if (!row) return res.json({ hit: false });
    db.prepare('UPDATE result_cache SET hit_count=hit_count+1 WHERE id=?').run(row.id);
    res.json({ hit: true, response: row.response, model: row.model, created_at: row.created_at });
  });
  app.delete('/api/cache', requireAuth, (req: any, res: any) => {
    db.prepare('DELETE FROM result_cache WHERE user_id=?').run(req.user.id);
    res.json({ success: true, message: 'Cache cleared' });
  });
}
// ─── End B214 ────────────────────────────────────────────────────────────────

// ─── B215: Agent Marketplace, Skill Packs, Agent Rating, Deploy Agent, Agent Revenue ───
{
  const agent_marketplace_table = `CREATE TABLE IF NOT EXISTS agent_marketplace (
    id TEXT PRIMARY KEY, author_user_id TEXT NOT NULL, name TEXT NOT NULL,
    slug TEXT NOT NULL UNIQUE, description TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'general',
    version TEXT NOT NULL DEFAULT '1.0.0', price_credits INTEGER NOT NULL DEFAULT 0,
    system_prompt TEXT NOT NULL, config TEXT NOT NULL DEFAULT '{}',
    tags TEXT NOT NULL DEFAULT '[]', preview_image_url TEXT,
    downloads INTEGER NOT NULL DEFAULT 0, rating REAL DEFAULT 0, ratings_count INTEGER NOT NULL DEFAULT 0,
    is_featured INTEGER NOT NULL DEFAULT 0, is_approved INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  const agent_installs_table = `CREATE TABLE IF NOT EXISTS agent_installs (
    id TEXT PRIMARY KEY, agent_id TEXT NOT NULL, user_id TEXT NOT NULL,
    installed_at TEXT NOT NULL DEFAULT (datetime('now')), is_active INTEGER NOT NULL DEFAULT 1,
    rating INTEGER, review TEXT, rated_at TEXT
  )`;
  const skill_packs_table = `CREATE TABLE IF NOT EXISTS skill_packs (
    id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT, category TEXT NOT NULL DEFAULT 'productivity',
    skills TEXT NOT NULL DEFAULT '[]', price_credits INTEGER NOT NULL DEFAULT 0,
    author_user_id TEXT NOT NULL, downloads INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (datetime('now'))
  )`;
  try { db.exec(agent_marketplace_table); db.exec(agent_installs_table); db.exec(skill_packs_table); } catch(e) {}

  app.get('/api/marketplace/agents', (req: any, res: any) => {
    const { category, search, featured } = req.query as any;
    let q = 'SELECT id,name,slug,description,category,version,price_credits,tags,downloads,rating,ratings_count,is_featured,created_at FROM agent_marketplace WHERE is_approved=1'; const vals: any[] = [];
    if (category) { q += ' AND category=?'; vals.push(category); }
    if (featured === 'true') { q += ' AND is_featured=1'; }
    if (search) { q += ' AND (name LIKE ? OR description LIKE ?)'; vals.push(`%${search}%`,`%${search}%`); }
    q += ' ORDER BY is_featured DESC, downloads DESC LIMIT 50';
    res.json({ agents: db.prepare(q).all(...vals) });
  });
  app.get('/api/marketplace/agents/:slug', (req: any, res: any) => {
    const agent = db.prepare('SELECT * FROM agent_marketplace WHERE slug=? AND is_approved=1').get(req.params.slug);
    if (!agent) return res.status(404).json({ error: 'not found' });
    res.json({ agent });
  });
  app.post('/api/marketplace/agents', requireAuth, (req: any, res: any) => {
    const { name, description, category='general', system_prompt, config={}, tags=[], price_credits=0, version='1.0.0' } = req.body;
    if (!name || !description || !system_prompt) return res.status(400).json({ error: 'name, description, system_prompt required' });
    const id = require('crypto').randomUUID();
    const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, '-') + '-' + id.slice(0, 6);
    db.prepare('INSERT INTO agent_marketplace(id,author_user_id,name,slug,description,category,version,price_credits,system_prompt,config,tags) VALUES(?,?,?,?,?,?,?,?,?,?,?)').run(id, req.user.id, name, slug, description, category, version, price_credits, system_prompt, JSON.stringify(config), JSON.stringify(tags));
    res.json({ success: true, id, slug });
  });
  app.post('/api/marketplace/agents/:id/install', requireAuth, (req: any, res: any) => {
    const agent = db.prepare('SELECT * FROM agent_marketplace WHERE id=? AND is_approved=1').get(req.params.id) as any;
    if (!agent) return res.status(404).json({ error: 'not found' });
    const existing = db.prepare('SELECT id FROM agent_installs WHERE agent_id=? AND user_id=?').get(req.params.id, req.user.id);
    if (existing) return res.json({ success: true, message: 'Already installed', already_installed: true });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO agent_installs(id,agent_id,user_id) VALUES(?,?,?)').run(id, req.params.id, req.user.id);
    db.prepare('UPDATE agent_marketplace SET downloads=downloads+1 WHERE id=?').run(req.params.id);
    res.json({ success: true, id, agent_name: agent.name });
  });
  app.get('/api/marketplace/installed', requireAuth, (req: any, res: any) => {
    const rows = db.prepare(`SELECT ai.*, am.name, am.slug, am.description, am.category, am.system_prompt, am.config FROM agent_installs ai JOIN agent_marketplace am ON am.id=ai.agent_id WHERE ai.user_id=? AND ai.is_active=1`).all(req.user.id);
    res.json({ agents: rows });
  });
  app.post('/api/marketplace/agents/:id/rate', requireAuth, (req: any, res: any) => {
    const { rating, review } = req.body;
    if (!rating || rating < 1 || rating > 5) return res.status(400).json({ error: 'rating 1-5 required' });
    db.prepare('UPDATE agent_installs SET rating=?, review=?, rated_at=datetime("now") WHERE agent_id=? AND user_id=?').run(rating, review||null, req.params.id, req.user.id);
    // Recalculate avg rating
    const stats = db.prepare('SELECT AVG(rating) as avg, COUNT(*) as cnt FROM agent_installs WHERE agent_id=? AND rating IS NOT NULL').get(req.params.id) as any;
    db.prepare('UPDATE agent_marketplace SET rating=?, ratings_count=? WHERE id=?').run(Math.round((stats.avg||0)*10)/10, stats.cnt, req.params.id);
    res.json({ success: true, new_avg: Math.round((stats.avg||0)*10)/10 });
  });
  app.delete('/api/marketplace/agents/:id/install', requireAuth, (req: any, res: any) => {
    db.prepare('UPDATE agent_installs SET is_active=0 WHERE agent_id=? AND user_id=?').run(req.params.id, req.user.id);
    res.json({ success: true });
  });

  app.get('/api/marketplace/skill-packs', (req: any, res: any) => {
    const rows = db.prepare('SELECT id,name,description,category,skills,price_credits,downloads FROM skill_packs ORDER BY downloads DESC').all();
    res.json({ packs: rows });
  });
  app.post('/api/marketplace/skill-packs', requireAuth, (req: any, res: any) => {
    const { name, description, category='productivity', skills=[], price_credits=0 } = req.body;
    if (!name) return res.status(400).json({ error: 'name required' });
    const id = require('crypto').randomUUID();
    db.prepare('INSERT INTO skill_packs(id,name,description,category,skills,price_credits,author_user_id) VALUES(?,?,?,?,?,?,?)').run(id, name, description||null, category, JSON.stringify(skills), price_credits, req.user.id);
    res.json({ success: true, id });
  });
}
// ─── End B215 ────────────────────────────────────────────────────────────────

// ─── B216: Real-time Collaboration ───────────────────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS collab_workspaces (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, name TEXT, description TEXT,
    is_public INTEGER DEFAULT 0, invite_code TEXT UNIQUE, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS collab_members (
    id INTEGER PRIMARY KEY AUTOINCREMENT, workspace_id INTEGER, user_id INTEGER, role TEXT DEFAULT 'member',
    joined_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE(workspace_id, user_id)
  );
  CREATE TABLE IF NOT EXISTS collab_documents (
    id INTEGER PRIMARY KEY AUTOINCREMENT, workspace_id INTEGER, title TEXT, content TEXT DEFAULT '',
    version INTEGER DEFAULT 1, last_edited_by INTEGER, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS collab_presence (
    id INTEGER PRIMARY KEY AUTOINCREMENT, workspace_id INTEGER, user_id INTEGER, doc_id INTEGER,
    cursor_pos INTEGER DEFAULT 0, last_seen DATETIME DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(workspace_id, user_id)
  );
  CREATE TABLE IF NOT EXISTS collab_comments (
    id INTEGER PRIMARY KEY AUTOINCREMENT, doc_id INTEGER, user_id INTEGER, content TEXT,
    selection_start INTEGER, selection_end INTEGER, resolved INTEGER DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/collab/workspaces', requireAuth, (req: any, res: any) => {
  const rows = db.prepare(`SELECT cw.*, COUNT(cm.id) as member_count FROM collab_workspaces cw
    LEFT JOIN collab_members cm ON cm.workspace_id=cw.id
    WHERE cw.user_id=? OR cw.id IN (SELECT workspace_id FROM collab_members WHERE user_id=?)
    GROUP BY cw.id ORDER BY cw.created_at DESC`).all(req.user.id, req.user.id);
  res.json({ workspaces: rows });
});
app.post('/api/collab/workspaces', requireAuth, (req: any, res: any) => {
  const { name, description, is_public } = req.body;
  if (!name) return res.status(400).json({ error: 'name required' });
  const invite_code = Math.random().toString(36).substring(2, 10).toUpperCase();
  const r = db.prepare(`INSERT INTO collab_workspaces (user_id,name,description,is_public,invite_code) VALUES (?,?,?,?,?)`).run(req.user.id, name, description||'', is_public?1:0, invite_code);
  db.prepare(`INSERT OR IGNORE INTO collab_members (workspace_id,user_id,role) VALUES (?,?,'owner')`).run(r.lastInsertRowid, req.user.id);
  res.json({ id: r.lastInsertRowid, invite_code });
});
app.post('/api/collab/workspaces/join', requireAuth, (req: any, res: any) => {
  const { invite_code } = req.body;
  const ws = db.prepare(`SELECT * FROM collab_workspaces WHERE invite_code=?`).get(invite_code);
  if (!ws) return res.status(404).json({ error: 'Invalid invite code' });
  try {
    db.prepare(`INSERT INTO collab_members (workspace_id,user_id) VALUES (?,?)`).run((ws as any).id, req.user.id);
  } catch(e) {}
  res.json({ workspace: ws });
});
app.get('/api/collab/workspaces/:id/docs', requireAuth, (req: any, res: any) => {
  const docs = db.prepare(`SELECT * FROM collab_documents WHERE workspace_id=? ORDER BY updated_at DESC`).all(req.params.id);
  res.json({ docs });
});
app.post('/api/collab/workspaces/:id/docs', requireAuth, (req: any, res: any) => {
  const { title, content } = req.body;
  const r = db.prepare(`INSERT INTO collab_documents (workspace_id,title,content,last_edited_by) VALUES (?,?,?,?)`).run(req.params.id, title||'Untitled', content||'', req.user.id);
  res.json({ id: r.lastInsertRowid });
});
app.put('/api/collab/docs/:id', requireAuth, (req: any, res: any) => {
  const { content, title } = req.body;
  db.prepare(`UPDATE collab_documents SET content=COALESCE(?,content), title=COALESCE(?,title), version=version+1, last_edited_by=?, updated_at=CURRENT_TIMESTAMP WHERE id=?`).run(content, title, req.user.id, req.params.id);
  res.json({ success: true });
});
app.post('/api/collab/docs/:id/presence', requireAuth, (req: any, res: any) => {
  const { workspace_id, cursor_pos } = req.body;
  db.prepare(`INSERT INTO collab_presence (workspace_id,user_id,doc_id,cursor_pos,last_seen) VALUES (?,?,?,?,CURRENT_TIMESTAMP)
    ON CONFLICT(workspace_id,user_id) DO UPDATE SET doc_id=excluded.doc_id, cursor_pos=excluded.cursor_pos, last_seen=CURRENT_TIMESTAMP`).run(workspace_id, req.user.id, req.params.id, cursor_pos||0);
  const others = db.prepare(`SELECT * FROM collab_presence WHERE doc_id=? AND user_id!=? AND last_seen > datetime('now','-30 seconds')`).all(req.params.id, req.user.id);
  res.json({ active_users: others });
});
app.get('/api/collab/docs/:id/comments', requireAuth, (req: any, res: any) => {
  const comments = db.prepare(`SELECT * FROM collab_comments WHERE doc_id=? ORDER BY created_at ASC`).all(req.params.id);
  res.json({ comments });
});
app.post('/api/collab/docs/:id/comments', requireAuth, (req: any, res: any) => {
  const { content, selection_start, selection_end } = req.body;
  const r = db.prepare(`INSERT INTO collab_comments (doc_id,user_id,content,selection_start,selection_end) VALUES (?,?,?,?,?)`).run(req.params.id, req.user.id, content, selection_start||0, selection_end||0);
  res.json({ id: r.lastInsertRowid });
});
app.put('/api/collab/comments/:id/resolve', requireAuth, (req: any, res: any) => {
  db.prepare(`UPDATE collab_comments SET resolved=1 WHERE id=?`).run(req.params.id);
  res.json({ success: true });
});
// ─── End B216 ────────────────────────────────────────────────────────────────

// ─── B217: Advanced Analytics v2 ─────────────────────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS funnel_definitions (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, name TEXT, steps TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS funnel_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, funnel_id INTEGER,
    step_name TEXT, session_id TEXT, occurred_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS cohorts (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, name TEXT, criteria TEXT,
    cohort_date DATE, size INTEGER DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS cohort_retention (
    id INTEGER PRIMARY KEY AUTOINCREMENT, cohort_id INTEGER, week_number INTEGER,
    retained_count INTEGER DEFAULT 0, retention_rate REAL DEFAULT 0
  );
  CREATE TABLE IF NOT EXISTS ab_experiments (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, name TEXT, hypothesis TEXT,
    variant_a TEXT, variant_b TEXT, metric TEXT, status TEXT DEFAULT 'running',
    start_date DATE, end_date DATE, winner TEXT,
    conversions_a INTEGER DEFAULT 0, conversions_b INTEGER DEFAULT 0,
    visitors_a INTEGER DEFAULT 0, visitors_b INTEGER DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/analytics/funnels', requireAuth, (req: any, res: any) => {
  const funnels = db.prepare(`SELECT * FROM funnel_definitions WHERE user_id=? ORDER BY created_at DESC`).all(req.user.id);
  res.json({ funnels });
});
app.post('/api/analytics/funnels', requireAuth, (req: any, res: any) => {
  const { name, steps } = req.body;
  const r = db.prepare(`INSERT INTO funnel_definitions (user_id,name,steps) VALUES (?,?,?)`).run(req.user.id, name, JSON.stringify(steps||[]));
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/analytics/funnels/:id/track', requireAuth, (req: any, res: any) => {
  const { step_name, session_id } = req.body;
  db.prepare(`INSERT INTO funnel_events (user_id,funnel_id,step_name,session_id) VALUES (?,?,?,?)`).run(req.user.id, req.params.id, step_name, session_id||'default');
  res.json({ success: true });
});
app.get('/api/analytics/funnels/:id/stats', requireAuth, (req: any, res: any) => {
  const funnel = db.prepare(`SELECT * FROM funnel_definitions WHERE id=? AND user_id=?`).get(req.params.id, req.user.id) as any;
  if (!funnel) return res.status(404).json({ error: 'not found' });
  const steps = JSON.parse(funnel.steps || '[]');
  const stepStats = steps.map((step: string) => {
    const count = (db.prepare(`SELECT COUNT(DISTINCT session_id) as c FROM funnel_events WHERE funnel_id=? AND step_name=?`).get(req.params.id, step) as any)?.c || 0;
    return { step, count };
  });
  const topCount = stepStats[0]?.count || 1;
  const result = stepStats.map((s: any, i: number) => ({ ...s, conversion_rate: i === 0 ? 100 : Math.round((s.count / topCount) * 100) }));
  res.json({ funnel: funnel.name, steps: result });
});
app.get('/api/analytics/cohorts', requireAuth, (req: any, res: any) => {
  const cohorts = db.prepare(`SELECT * FROM cohorts WHERE user_id=? ORDER BY cohort_date DESC`).all(req.user.id);
  res.json({ cohorts });
});
app.post('/api/analytics/cohorts', requireAuth, (req: any, res: any) => {
  const { name, criteria, cohort_date, size } = req.body;
  const r = db.prepare(`INSERT INTO cohorts (user_id,name,criteria,cohort_date,size) VALUES (?,?,?,?,?)`).run(req.user.id, name, criteria||'', cohort_date||new Date().toISOString().slice(0,10), size||0);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/analytics/cohorts/:id/retention', requireAuth, (req: any, res: any) => {
  const { week_number, retained_count } = req.body;
  const cohort = db.prepare(`SELECT * FROM cohorts WHERE id=?`).get(req.params.id) as any;
  if (!cohort) return res.status(404).json({ error: 'not found' });
  const rate = cohort.size > 0 ? Math.round((retained_count / cohort.size) * 100) : 0;
  const r = db.prepare(`INSERT INTO cohort_retention (cohort_id,week_number,retained_count,retention_rate) VALUES (?,?,?,?)`).run(req.params.id, week_number, retained_count, rate);
  res.json({ id: r.lastInsertRowid, retention_rate: rate });
});
app.get('/api/analytics/ab-tests', requireAuth, (req: any, res: any) => {
  const tests = db.prepare(`SELECT * FROM ab_experiments WHERE user_id=? ORDER BY created_at DESC`).all(req.user.id);
  res.json({ tests });
});
app.post('/api/analytics/ab-tests', requireAuth, (req: any, res: any) => {
  const { name, hypothesis, variant_a, variant_b, metric } = req.body;
  const r = db.prepare(`INSERT INTO ab_experiments (user_id,name,hypothesis,variant_a,variant_b,metric) VALUES (?,?,?,?,?,?)`).run(req.user.id, name, hypothesis||'', variant_a||'Control', variant_b||'Variant', metric||'conversion');
  res.json({ id: r.lastInsertRowid });
});
app.put('/api/analytics/ab-tests/:id/record', requireAuth, (req: any, res: any) => {
  const { variant, converted } = req.body;
  const field = variant === 'b' ? 'visitors_b' : 'visitors_a';
  const convField = variant === 'b' ? 'conversions_b' : 'conversions_a';
  db.prepare(`UPDATE ab_experiments SET ${field}=${field}+1${converted ? `, ${convField}=${convField}+1` : ''} WHERE id=? AND user_id=?`).run(req.params.id, req.user.id);
  res.json({ success: true });
});
