app.post('/api/podcast-outlines', requireAuth, (req: any, res: any) => {
  const { episode_title, topic, estimated_duration, intro, segments, outro, show_notes } = req.body;
  const last = db.prepare(`SELECT MAX(episode_number) as max_ep FROM podcast_outlines WHERE user_id=?`).get(req.user.id) as any;
  const episode_number = (last?.max_ep || 0) + 1;
  const r = db.prepare(`INSERT INTO podcast_outlines (user_id,episode_title,episode_number,topic,intro,segments,outro,show_notes,estimated_duration) VALUES (?,?,?,?,?,?,?,?,?)`).run(req.user.id, episode_title||`Episode ${episode_number}`, episode_number, topic, intro||'', JSON.stringify(segments||[]), outro||'', show_notes||'', estimated_duration||30);
  res.json({ id: r.lastInsertRowid, episode_number });
});
app.get('/api/content-calendar-ai', requireAuth, (req: any, res: any) => {
  const { month } = req.query as any;
  let q = `SELECT * FROM content_calendar_ai WHERE user_id=?`;
  const params: any[] = [req.user.id];
  if (month) { q += ` AND strftime('%Y-%m', date)=?`; params.push(month); }
  q += ` ORDER BY date ASC`;
  const items = db.prepare(q).all(...params);
  res.json({ items });
});
