try { db.exec(`
  CREATE TABLE IF NOT EXISTS knowledge_nodes (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, title TEXT, content TEXT,
    node_type TEXT DEFAULT 'note', tags TEXT, x_pos REAL DEFAULT 0, y_pos REAL DEFAULT 0,
    color TEXT DEFAULT '#6366f1', created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS knowledge_edges (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, source_id INTEGER, target_id INTEGER,
    relationship TEXT DEFAULT 'related', weight REAL DEFAULT 1.0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE(source_id, target_id)
  );
  CREATE TABLE IF NOT EXISTS knowledge_clusters (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, name TEXT, color TEXT DEFAULT '#8b5cf6',
    node_ids TEXT DEFAULT '[]', created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS atomic_notes (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, title TEXT, body TEXT,
    source TEXT, backlinks TEXT DEFAULT '[]', is_permanent INTEGER DEFAULT 0,
    review_date DATE, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

