  const r = db.prepare(`INSERT INTO atomic_notes (user_id,title,body,source,is_permanent,review_date) VALUES (?,?,?,?,?,?)`).run(req.user.id, title||'Untitled', body||'', source||'', is_permanent?1:0, review_date);
