try { db.exec(`
  CREATE TABLE IF NOT EXISTS research_projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, title TEXT, description TEXT,
    status TEXT DEFAULT 'active', tags TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS research_sources (
    id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER, user_id INTEGER,
    url TEXT, title TEXT, summary TEXT, credibility_score INTEGER DEFAULT 5,
    source_type TEXT DEFAULT 'web', notes TEXT, saved_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS research_findings (
    id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER, user_id INTEGER,
    finding TEXT, evidence TEXT, source_ids TEXT DEFAULT '[]', confidence INTEGER DEFAULT 3,
    category TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS research_questions (
    id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER, user_id INTEGER,
    question TEXT, answer TEXT, answered INTEGER DEFAULT 0,
    priority INTEGER DEFAULT 3, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/research', requireAuth, (req: any, res: any) => {
  const projects = db.prepare(`SELECT rp.*, COUNT(rs.id) as source_count, COUNT(rf.id) as finding_count FROM research_projects rp LEFT JOIN research_sources rs ON rs.project_id=rp.id LEFT JOIN research_findings rf ON rf.project_id=rp.id WHERE rp.user_id=? GROUP BY rp.id ORDER BY rp.created_at DESC`).all(req.user.id);
  res.json({ projects });
});
app.post('/api/research', requireAuth, (req: any, res: any) => {
  const { title, description, tags } = req.body;
  if (!title) return res.status(400).json({ error: 'title required' });
  const r = db.prepare(`INSERT INTO research_projects (user_id,title,description,tags) VALUES (?,?,?,?)`).run(req.user.id, title, description||'', tags||'');
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/research/:id', requireAuth, (req: any, res: any) => {
  const project = db.prepare(`SELECT * FROM research_projects WHERE id=? AND user_id=?`).get(req.params.id, req.user.id);
  if (!project) return res.status(404).json({ error: 'not found' });
  const sources = db.prepare(`SELECT * FROM research_sources WHERE project_id=? ORDER BY saved_at DESC`).all(req.params.id);
  const findings = db.prepare(`SELECT * FROM research_findings WHERE project_id=? ORDER BY confidence DESC`).all(req.params.id);
  const questions = db.prepare(`SELECT * FROM research_questions WHERE project_id=? ORDER BY priority DESC, answered ASC`).all(req.params.id);
  res.json({ project, sources, findings, questions });
});
app.post('/api/research/:id/sources', requireAuth, (req: any, res: any) => {
  const { url, title, summary, credibility_score, source_type, notes } = req.body;
  const r = db.prepare(`INSERT INTO research_sources (project_id,user_id,url,title,summary,credibility_score,source_type,notes) VALUES (?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, url||'', title||'', summary||'', credibility_score||5, source_type||'web', notes||'');
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/research/:id/findings', requireAuth, (req: any, res: any) => {
  const { finding, evidence, source_ids, confidence, category } = req.body;
  if (!finding) return res.status(400).json({ error: 'finding required' });
  const r = db.prepare(`INSERT INTO research_findings (project_id,user_id,finding,evidence,source_ids,confidence,category) VALUES (?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, finding, evidence||'', JSON.stringify(source_ids||[]), confidence||3, category||'general');
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/research/:id/questions', requireAuth, (req: any, res: any) => {
  const { question, priority } = req.body;
  if (!question) return res.status(400).json({ error: 'question required' });
  const r = db.prepare(`INSERT INTO research_questions (project_id,user_id,question,priority) VALUES (?,?,?,?)`).run(req.params.id, req.user.id, question, priority||3);
  res.json({ id: r.lastInsertRowid });
});
app.put('/api/research/questions/:id/answer', requireAuth, (req: any, res: any) => {
  const { answer } = req.body;
  db.prepare(`UPDATE research_questions SET answer=?, answered=1 WHERE id=? AND user_id=?`).run(answer, req.params.id, req.user.id);
  res.json({ success: true });
});
app.get('/api/research/:id/synthesis', requireAuth, (req: any, res: any) => {
  const findings = db.prepare(`SELECT * FROM research_findings WHERE project_id=? ORDER BY confidence DESC`).all(req.params.id) as any[];
  const byCategory: Record<string,any[]> = {};
  findings.forEach((f: any) => {
    if (!byCategory[f.category]) byCategory[f.category] = [];
    byCategory[f.category].push(f);
  });
  const avg_confidence = findings.length > 0 ? Math.round(findings.reduce((s: number, f: any) => s + f.confidence, 0) / findings.length * 10) / 10 : 0;
  res.json({ by_category: byCategory, total_findings: findings.length, avg_confidence });
});
// ─── End B224 ────────────────────────────────────────────────────────────────

