  const invoices = db.prepare(`SELECT * FROM project_invoices WHERE project_id=? AND user_id=? ORDER BY issued_date DESC`).all(req.params.id, req.user.id);
  const total_billed = (invoices as any[]).reduce((s: number, i: any) => s + i.amount, 0);
  const total_paid = (invoices as any[]).filter((i: any) => i.status === 'paid').reduce((s: number, i: any) => s + i.amount, 0);
  res.json({ invoices, total_billed, total_paid, outstanding: total_billed - total_paid });
