app.get('/api/properties/roi-summary', requireAuth, (req: any, res: any) => {
  const props = db.prepare(`SELECT * FROM properties WHERE user_id=?`).all(req.user.id) as any[];
  const summary = props.map((p: any) => {
    const annual_rent = p.monthly_rent * 12;
    const annual_expenses = (p.monthly_mortgage + p.monthly_expenses) * 12;
    const noi = annual_rent - annual_expenses;
    const cap_rate = p.current_value > 0 ? Math.round((noi / p.current_value) * 1000) / 10 : 0;
    const appreciation = p.current_value - p.purchase_price;
    return { id: p.id, address: p.address, noi, cap_rate, appreciation, equity: p.current_value - p.mortgage_balance };
  });
  res.json({ summary });
});
