app.get('/api/meetings', requireAuth, (req: any, res: any) => {
  const { status } = req.query as any;
  let q = `SELECT m.*, COUNT(ma.id) as action_count FROM meetings_v2 m LEFT JOIN meeting_action_items ma ON ma.meeting_id=m.id WHERE m.user_id=?`;
  const p: any[] = [req.user.id];
  if (status) { q += ` AND m.status=?`; p.push(status); }
  q += ` GROUP BY m.id ORDER BY m.start_time DESC LIMIT 100`;
  res.json({ meetings: db.prepare(q).all(...p) });
});
