app.post('/api/meetings/ai-summary', requireAuth, (req: any, res: any) => {
  const { meeting_id } = req.body;
  const meeting = db.prepare(`SELECT * FROM meetings_v2 WHERE id=? AND user_id=?`).get(meeting_id, req.user.id) as any;
  if (!meeting) return res.status(404).json({ error: 'not found' });
  const actions = db.prepare(`SELECT * FROM meeting_action_items WHERE meeting_id=?`).all(meeting_id) as any[];
  const summary = {
    title: meeting.title, duration: meeting.duration_minutes,
    attendees: JSON.parse(meeting.attendees || '[]').length,
    open_actions: actions.filter((a: any) => a.status === 'open').length,
    completed_actions: actions.filter((a: any) => a.status === 'completed').length,
    has_transcript: !!meeting.transcript,
    summary_generated: new Date().toISOString()
  };
  res.json({ summary });
});
