try { db.exec(`
  CREATE TABLE IF NOT EXISTS freelance_clients (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, name TEXT, company TEXT,
    email TEXT, phone TEXT, hourly_rate REAL DEFAULT 0, currency TEXT DEFAULT 'USD',
    timezone TEXT, status TEXT DEFAULT 'active', total_billed REAL DEFAULT 0,
    total_paid REAL DEFAULT 0, notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS time_entries (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, client_id INTEGER,
    project_name TEXT, description TEXT, hours REAL DEFAULT 0, hourly_rate REAL DEFAULT 0,
    date DATE, billable INTEGER DEFAULT 1, invoice_id INTEGER,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS freelance_invoices (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, client_id INTEGER,
    invoice_number TEXT UNIQUE, line_items TEXT DEFAULT '[]', subtotal REAL DEFAULT 0,
    tax_rate REAL DEFAULT 0, tax_amount REAL DEFAULT 0, total REAL DEFAULT 0,
    status TEXT DEFAULT 'draft', issued_date DATE, due_date DATE,
    paid_date DATE, notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS freelance_proposals (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, client_id INTEGER,
    title TEXT, scope TEXT, deliverables TEXT DEFAULT '[]', timeline TEXT,
    total_price REAL DEFAULT 0, price_type TEXT DEFAULT 'fixed', status TEXT DEFAULT 'draft',
    sent_date DATE, accepted_date DATE, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/freelance/clients', requireAuth, (req: any, res: any) => {
  const clients = db.prepare(`SELECT fc.*, COALESCE(SUM(te.hours * te.hourly_rate),0) as unbilled_amount FROM freelance_clients fc LEFT JOIN time_entries te ON te.client_id=fc.id AND te.billable=1 AND te.invoice_id IS NULL WHERE fc.user_id=? GROUP BY fc.id ORDER BY fc.name ASC`).all(req.user.id);
  res.json({ clients });
});
app.post('/api/freelance/clients', requireAuth, (req: any, res: any) => {
  const { name, company, email, phone, hourly_rate, currency, timezone } = req.body;
  if (!name) return res.status(400).json({ error: 'name required' });
  const r = db.prepare(`INSERT INTO freelance_clients (user_id,name,company,email,phone,hourly_rate,currency,timezone) VALUES (?,?,?,?,?,?,?,?)`).run(req.user.id, name, company||'', email||'', phone||'', hourly_rate||0, currency||'USD', timezone||'UTC');
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/freelance/time', requireAuth, (req: any, res: any) => {
  const { client_id, project_name, description, hours, hourly_rate, date, billable } = req.body;
  if (!client_id || !hours) return res.status(400).json({ error: 'client_id and hours required' });
  const client = db.prepare(`SELECT hourly_rate FROM freelance_clients WHERE id=? AND user_id=?`).get(client_id, req.user.id) as any;
  const rate = hourly_rate || client?.hourly_rate || 0;
  const r = db.prepare(`INSERT INTO time_entries (user_id,client_id,project_name,description,hours,hourly_rate,date,billable) VALUES (?,?,?,?,?,?,?,?)`).run(req.user.id, client_id, project_name||'', description||'', hours, rate, date||new Date().toISOString().slice(0,10), billable!==false?1:0);
  res.json({ id: r.lastInsertRowid, amount: hours * rate });
});
app.get('/api/freelance/time', requireAuth, (req: any, res: any) => {
  const { client_id, unbilled_only } = req.query as any;
  let q = `SELECT te.*, fc.name as client_name, (te.hours * te.hourly_rate) as amount FROM time_entries te JOIN freelance_clients fc ON fc.id=te.client_id WHERE te.user_id=?`;
  const p: any[] = [req.user.id];
  if (client_id) { q += ` AND te.client_id=?`; p.push(client_id); }
  if (unbilled_only === 'true') { q += ` AND te.invoice_id IS NULL AND te.billable=1`; }
  q += ` ORDER BY te.date DESC LIMIT 500`;
  const entries = db.prepare(q).all(...p) as any[];
  const total_hours = entries.reduce((s: number, e: any) => s + e.hours, 0);
  const total_amount = entries.reduce((s: number, e: any) => s + e.amount, 0);
  res.json({ entries, total_hours: Math.round(total_hours * 10) / 10, total_amount });
});
app.post('/api/freelance/invoices/generate', requireAuth, (req: any, res: any) => {
  const { client_id, time_entry_ids, extra_line_items, tax_rate, due_days, notes } = req.body;
  if (!client_id) return res.status(400).json({ error: 'client_id required' });
  const count = (db.prepare(`SELECT COUNT(*) as c FROM freelance_invoices WHERE user_id=?`).get(req.user.id) as any)?.c || 0;
  const invoice_number = `INV-${new Date().getFullYear()}-${String(count + 1).padStart(4, '0')}`;
  const time_entries_data = time_entry_ids?.length ? db.prepare(`SELECT *, (hours*hourly_rate) as amount FROM time_entries WHERE id IN (${time_entry_ids.map(() => '?').join(',')}) AND user_id=?`).all(...time_entry_ids, req.user.id) as any[] : [];
  const line_items = [
    ...time_entries_data.map((te: any) => ({ description: te.description || te.project_name, qty: te.hours, rate: te.hourly_rate, amount: te.amount })),
    ...(extra_line_items || [])
  ];
  const subtotal = line_items.reduce((s: number, li: any) => s + (li.amount || 0), 0);
  const tax = Math.round(subtotal * ((tax_rate || 0) / 100) * 100) / 100;
  const total = subtotal + tax;
  const due_date = new Date(Date.now() + (due_days || 30) * 86400000).toISOString().slice(0, 10);
  const r = db.prepare(`INSERT INTO freelance_invoices (user_id,client_id,invoice_number,line_items,subtotal,tax_rate,tax_amount,total,issued_date,due_date,notes) VALUES (?,?,?,?,?,?,?,?,date('now'),?,?)`).run(req.user.id, client_id, invoice_number, JSON.stringify(line_items), subtotal, tax_rate||0, tax, total, due_date, notes||'');
  if (time_entry_ids?.length) db.prepare(`UPDATE time_entries SET invoice_id=? WHERE id IN (${time_entry_ids.map(() => '?').join(',')})`).run(r.lastInsertRowid, ...time_entry_ids);
  res.json({ id: r.lastInsertRowid, invoice_number, total });
});
app.put('/api/freelance/invoices/:id/paid', requireAuth, (req: any, res: any) => {
  const inv = db.prepare(`SELECT * FROM freelance_invoices WHERE id=? AND user_id=?`).get(req.params.id, req.user.id) as any;
  if (!inv) return res.status(404).json({ error: 'not found' });
  db.prepare(`UPDATE freelance_invoices SET status='paid', paid_date=date('now') WHERE id=?`).run(req.params.id);
  db.prepare(`UPDATE freelance_clients SET total_paid=total_paid+? WHERE id=?`).run(inv.total, inv.client_id);
  res.json({ success: true, total_paid: inv.total });
});
app.get('/api/freelance/revenue', requireAuth, (req: any, res: any) => {
  const stats = db.prepare(`SELECT SUM(CASE WHEN status='paid' THEN total ELSE 0 END) as total_paid, SUM(CASE WHEN status='sent' THEN total ELSE 0 END) as outstanding, SUM(CASE WHEN status='draft' THEN total ELSE 0 END) as draft_value, COUNT(*) as total_invoices FROM freelance_invoices WHERE user_id=?`).get(req.user.id) as any;
  const hours = db.prepare(`SELECT SUM(hours) as total_hours, SUM(hours*hourly_rate) as total_earned FROM time_entries WHERE user_id=? AND billable=1`).get(req.user.id) as any;
  res.json({ ...stats, ...hours });
});
