// ─── B247: Scientific Research & Lab Notebook ─────────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS experiments (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, title TEXT, hypothesis TEXT,
    methodology TEXT, status TEXT DEFAULT 'planned', start_date DATE, end_date DATE,
    tags TEXT DEFAULT '[]', created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS lab_observations (
    id INTEGER PRIMARY KEY AUTOINCREMENT, experiment_id INTEGER, user_id INTEGER,
    observation TEXT, data_type TEXT DEFAULT 'qualitative', raw_data TEXT,
    conditions TEXT, timestamp DATETIME DEFAULT CURRENT_TIMESTAMP, is_anomaly INTEGER DEFAULT 0
  );
  CREATE TABLE IF NOT EXISTS lab_samples (
    id INTEGER PRIMARY KEY AUTOINCREMENT, experiment_id INTEGER, user_id INTEGER,
    sample_id TEXT, description TEXT, quantity REAL, unit TEXT,
    preparation_notes TEXT, storage_location TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS research_citations (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, experiment_id INTEGER,
    title TEXT, authors TEXT, journal TEXT, year INTEGER, doi TEXT,
    url TEXT, notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS experiment_results (
    id INTEGER PRIMARY KEY AUTOINCREMENT, experiment_id INTEGER, user_id INTEGER,
    result_type TEXT DEFAULT 'primary', summary TEXT, quantitative_data TEXT,
    charts_data TEXT, conclusion TEXT, supports_hypothesis INTEGER,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/experiments', requireAuth, (req: any, res: any) => {
  const experiments = db.prepare(`SELECT e.*, COUNT(lo.id) as observation_count FROM experiments e LEFT JOIN lab_observations lo ON lo.experiment_id=e.id WHERE e.user_id=? GROUP BY e.id ORDER BY e.created_at DESC`).all(req.user.id);
  res.json({ experiments });
});
