// ─── B249: E-Learning & Course Marketplace ───────────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS marketplace_courses (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, title TEXT, subtitle TEXT,
    description TEXT, category TEXT, level TEXT DEFAULT 'beginner',
    price REAL DEFAULT 0, currency TEXT DEFAULT 'USD', thumbnail_url TEXT,
    preview_video_url TEXT, language TEXT DEFAULT 'English',
    total_lectures INTEGER DEFAULT 0, total_duration_hours REAL DEFAULT 0,
    rating REAL DEFAULT 0, enrollment_count INTEGER DEFAULT 0,
    is_published INTEGER DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS course_sections (
    id INTEGER PRIMARY KEY AUTOINCREMENT, course_id INTEGER, title TEXT,
    order_index INTEGER DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS course_lectures (
    id INTEGER PRIMARY KEY AUTOINCREMENT, section_id INTEGER, course_id INTEGER,
    title TEXT, content_type TEXT DEFAULT 'video', content_url TEXT, duration_seconds INTEGER DEFAULT 0,
    content_text TEXT, is_preview INTEGER DEFAULT 0, order_index INTEGER DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS course_enrollments (
    id INTEGER PRIMARY KEY AUTOINCREMENT, course_id INTEGER, user_id INTEGER,
    enrolled_at DATETIME DEFAULT CURRENT_TIMESTAMP, completed_at DATETIME,
    progress_pct INTEGER DEFAULT 0, last_lecture_id INTEGER, certificate_issued INTEGER DEFAULT 0
  );
  CREATE TABLE IF NOT EXISTS course_reviews (
    id INTEGER PRIMARY KEY AUTOINCREMENT, course_id INTEGER, user_id INTEGER,
    rating INTEGER, review TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/marketplace/courses', (req: any, res: any) => {
  const { category, level, search, sort } = req.query as any;
  let q = `SELECT id,title,subtitle,category,level,price,currency,thumbnail_url,rating,enrollment_count,total_lectures,total_duration_hours,language FROM marketplace_courses WHERE is_published=1`;
  const p: any[] = [];
  if (category) { q += ` AND category=?`; p.push(category); }
  if (level) { q += ` AND level=?`; p.push(level); }
  if (search) { q += ` AND (title LIKE ? OR description LIKE ?)`; p.push(`%${search}%`, `%${search}%`); }
  if (sort === 'popular') q += ` ORDER BY enrollment_count DESC`;
  else if (sort === 'rating') q += ` ORDER BY rating DESC`;
  else q += ` ORDER BY created_at DESC`;
  q += ` LIMIT 100`;
  res.json({ courses: db.prepare(q).all(...p) });
});
app.post('/api/marketplace/courses', requireAuth, (req: any, res: any) => {
  const { title, subtitle, description, category, level, price, language } = req.body;
  if (!title) return res.status(400).json({ error: 'title required' });
  const r = db.prepare(`INSERT INTO marketplace_courses (user_id,title,subtitle,description,category,level,price,language) VALUES (?,?,?,?,?,?,?,?)`).run(req.user.id, title, subtitle||'', description||'', category||'general', level||'beginner', price||0, language||'English');
  res.json({ id: r.lastInsertRowid });
});
app.put('/api/marketplace/courses/:id/publish', requireAuth, (req: any, res: any) => {
  db.prepare(`UPDATE marketplace_courses SET is_published=1 WHERE id=? AND user_id=?`).run(req.params.id, req.user.id);
  res.json({ success: true });
});
app.post('/api/marketplace/courses/:id/sections', requireAuth, (req: any, res: any) => {
  const { title } = req.body;
  const max = (db.prepare(`SELECT MAX(order_index) as m FROM course_sections WHERE course_id=?`).get(req.params.id) as any)?.m || 0;
  const r = db.prepare(`INSERT INTO course_sections (course_id,title,order_index) VALUES (?,?,?)`).run(req.params.id, title||'Section', max+1);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/marketplace/sections/:id/lectures', requireAuth, (req: any, res: any) => {
  const { course_id, title, content_type, content_url, duration_seconds, content_text, is_preview } = req.body;
  const max = (db.prepare(`SELECT MAX(order_index) as m FROM course_lectures WHERE section_id=?`).get(req.params.id) as any)?.m || 0;
  const r = db.prepare(`INSERT INTO course_lectures (section_id,course_id,title,content_type,content_url,duration_seconds,content_text,is_preview,order_index) VALUES (?,?,?,?,?,?,?,?,?)`).run(req.params.id, course_id, title||'Lecture', content_type||'video', content_url||'', duration_seconds||0, content_text||'', is_preview?1:0, max+1);
  db.prepare(`UPDATE marketplace_courses SET total_lectures=total_lectures+1 WHERE id=?`).run(course_id);
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/marketplace/courses/:id', (req: any, res: any) => {
  const course = db.prepare(`SELECT * FROM marketplace_courses WHERE id=?`).get(req.params.id);
  if (!course) return res.status(404).json({ error: 'not found' });
  const sections = db.prepare(`SELECT cs.*, json_group_array(json_object('id',cl.id,'title',cl.title,'content_type',cl.content_type,'duration_seconds',cl.duration_seconds,'is_preview',cl.is_preview,'order_index',cl.order_index)) as lectures FROM course_sections cs LEFT JOIN course_lectures cl ON cl.section_id=cs.id WHERE cs.course_id=? GROUP BY cs.id ORDER BY cs.order_index`).all(req.params.id);
  const reviews = db.prepare(`SELECT rating, review, created_at FROM course_reviews WHERE course_id=? ORDER BY created_at DESC LIMIT 10`).all(req.params.id);
  res.json({ course, sections, reviews });
});
app.post('/api/marketplace/courses/:id/enroll', requireAuth, (req: any, res: any) => {
  const existing = db.prepare(`SELECT id FROM course_enrollments WHERE course_id=? AND user_id=?`).get(req.params.id, req.user.id);
  if (existing) return res.json({ message: 'already enrolled', enrollment_id: (existing as any).id });
  const r = db.prepare(`INSERT INTO course_enrollments (course_id,user_id) VALUES (?,?)`).run(req.params.id, req.user.id);
  db.prepare(`UPDATE marketplace_courses SET enrollment_count=enrollment_count+1 WHERE id=?`).run(req.params.id);
  res.json({ id: r.lastInsertRowid });
});
app.put('/api/marketplace/courses/:id/progress', requireAuth, (req: any, res: any) => {
  const { progress_pct, last_lecture_id } = req.body;
  db.prepare(`UPDATE course_enrollments SET progress_pct=?, last_lecture_id=COALESCE(?,last_lecture_id), completed_at=CASE WHEN ?>=100 THEN CURRENT_TIMESTAMP ELSE completed_at END WHERE course_id=? AND user_id=?`).run(progress_pct||0, last_lecture_id, progress_pct||0, req.params.id, req.user.id);
  res.json({ success: true });
});
app.post('/api/marketplace/courses/:id/review', requireAuth, (req: any, res: any) => {
  const { rating, review } = req.body;
  if (!rating) return res.status(400).json({ error: 'rating required' });
  db.prepare(`INSERT OR REPLACE INTO course_reviews (course_id,user_id,rating,review) VALUES (?,?,?,?)`).run(req.params.id, req.user.id, Math.min(5, Math.max(1, rating)), review||'');
  const avg = (db.prepare(`SELECT AVG(rating) as avg FROM course_reviews WHERE course_id=?`).get(req.params.id) as any)?.avg || 0;
  db.prepare(`UPDATE marketplace_courses SET rating=? WHERE id=?`).run(Math.round(avg * 10) / 10, req.params.id);
  res.json({ success: true, new_rating: Math.round(avg * 10) / 10 });
});
