app.get('/api/trips', requireAuth, (req: any, res: any) => {
  const trips = db.prepare(`SELECT t.*, COALESCE(SUM(te.amount),0) as spent FROM trips_v2 t LEFT JOIN trip_expenses te ON te.trip_id=t.id WHERE t.user_id=? GROUP BY t.id ORDER BY t.start_date DESC`).all(req.user.id) as any[];
  const active = trips.filter((t: any) => t.status !== 'completed');
  res.json({ trips, active_count: active.length });
});
