  const r = db.prepare(`INSERT INTO trips_v2 (user_id,name,destination,start_date,end_date,budget,currency,purpose) VALUES (?,?,?,?,?,?,?,?)`).run(req.user.id, name, destination||'', start_date||'', end_date||'', budget||0, currency||'USD', purpose||'leisure');
