  const r = db.prepare(`INSERT INTO health_appointments (user_id,provider,specialty,appointment_date,location,purpose) VALUES (?,?,?,?,?,?)`).run(req.user.id, provider||'', specialty||'', appointment_date, location||'', purpose||'');
