  const { vaccine_name, dose_number, date_given, provider, lot_number, next_due_date } = req.body;
  if (!vaccine_name) return res.status(400).json({ error: 'vaccine_name required' });
  const r = db.prepare(`INSERT INTO vaccination_records (user_id,vaccine_name,dose_number,date_given,provider,lot_number,next_due_date) VALUES (?,?,?,?,?,?,?)`).run(req.user.id, vaccine_name, dose_number||1, date_given||new Date().toISOString().slice(0,10), provider||'', lot_number||'', next_due_date||null);
