app.get('/api/health/summary', requireAuth, (req: any, res: any) => {
  const latest_metrics = db.prepare(`SELECT metric_type, value, unit, recorded_at FROM health_metrics_v2 WHERE user_id=? GROUP BY metric_type HAVING MAX(recorded_at) ORDER BY recorded_at DESC`).all(req.user.id);
  const upcoming_appts = db.prepare(`SELECT * FROM health_appointments WHERE user_id=? AND appointment_date > CURRENT_TIMESTAMP AND status='scheduled' ORDER BY appointment_date ASC LIMIT 3`).all(req.user.id);
  const active_meds = db.prepare(`SELECT COUNT(*) as c FROM medications_tracker WHERE user_id=? AND is_active=1`).get(req.user.id) as any;
  res.json({ latest_metrics, upcoming_appointments: upcoming_appts, active_medications: active_meds?.c || 0 });
});
