app.post('/api/books', requireAuth, (req: any, res: any) => {
  const { title, author, isbn, genre, pages, cover_url, status } = req.body;
  if (!title) return res.status(400).json({ error: 'title required' });
  const r = db.prepare(`INSERT INTO books_v2 (user_id,title,author,isbn,genre,pages,cover_url,status) VALUES (?,?,?,?,?,?,?,?)`).run(req.user.id, title, author||'', isbn||'', genre||'', pages||0, cover_url||'', status||'want_to_read');
  res.json({ id: r.lastInsertRowid });
});
app.put('/api/books/:id/status', requireAuth, (req: any, res: any) => {
  const { status, rating, review } = req.body;
  const updates: any = { status, rating: rating||null, review: review||null };
  if (status === 'reading') updates.started_date = new Date().toISOString().slice(0,10);
  if (status === 'finished') {
    updates.finished_date = new Date().toISOString().slice(0,10);
    db.prepare(`UPDATE reading_goals SET completed_books=completed_books+1 WHERE user_id=? AND year=?`).run(req.user.id, new Date().getFullYear());
  }
  db.prepare(`UPDATE books_v2 SET status=?, rating=COALESCE(?,rating), review=COALESCE(?,review), started_date=COALESCE(?,started_date), finished_date=COALESCE(?,finished_date) WHERE id=? AND user_id=?`).run(status, updates.rating, updates.review, updates.started_date||null, updates.finished_date||null, req.params.id, req.user.id);
  res.json({ success: true });
});
app.post('/api/books/:id/sessions', requireAuth, (req: any, res: any) => {
  const { pages_read, start_page, end_page, duration_minutes, notes } = req.body;
  const today = new Date().toISOString().slice(0,10);
  const r = db.prepare(`INSERT INTO reading_sessions (book_id,user_id,pages_read,start_page,end_page,duration_minutes,notes,reading_date) VALUES (?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, pages_read||((end_page||0)-(start_page||0)), start_page||0, end_page||0, duration_minutes||30, notes||'', today);
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/reading/stats', requireAuth, (req: any, res: any) => {
  const year = new Date().getFullYear();
  const finished = (db.prepare(`SELECT COUNT(*) as c, SUM(pages) as pages FROM books_v2 WHERE user_id=? AND status='finished' AND strftime('%Y',finished_date)=?`).get(req.user.id, String(year)) as any);
  const sessions = (db.prepare(`SELECT SUM(pages_read) as pages, SUM(duration_minutes) as minutes FROM reading_sessions WHERE user_id=? AND strftime('%Y',reading_date)=?`).get(req.user.id, String(year)) as any);
  const goal = db.prepare(`SELECT * FROM reading_goals WHERE user_id=? AND year=?`).get(req.user.id, year) as any;
  res.json({ books_finished: finished?.c||0, pages_read: sessions?.pages||0, minutes_read: sessions?.minutes||0, goal_books: goal?.target_books||12, goal_pct: goal?.target_books ? Math.min(100, Math.round(((finished?.c||0) / goal.target_books) * 100)) : 0 });
});
app.post('/api/book-clubs', requireAuth, (req: any, res: any) => {
  const { name, description, meeting_day } = req.body;
  if (!name) return res.status(400).json({ error: 'name required' });
  const code = Math.random().toString(36).slice(2, 8).toUpperCase();
  const r = db.prepare(`INSERT INTO book_clubs (user_id,name,description,meeting_day,invite_code) VALUES (?,?,?,?,?)`).run(req.user.id, name, description||'', meeting_day||'', code);
  res.json({ id: r.lastInsertRowid, invite_code: code });
});
app.put('/api/reading/goals/:year', requireAuth, (req: any, res: any) => {
  const { target_books } = req.body;
  const existing = db.prepare(`SELECT id FROM reading_goals WHERE user_id=? AND year=?`).get(req.user.id, req.params.year);
  if (existing) {
    db.prepare(`UPDATE reading_goals SET target_books=? WHERE user_id=? AND year=?`).run(target_books||12, req.user.id, req.params.year);
  } else {
    db.prepare(`INSERT INTO reading_goals (user_id,year,target_books) VALUES (?,?,?)`).run(req.user.id, req.params.year, target_books||12);
  }
  res.json({ success: true });
});
// ─── End B256 ────────────────────────────────────────────────────────────────

// ─── B257: Music Practice & Instrument Tracker ───────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS instruments (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, name TEXT, type TEXT,
    brand TEXT, skill_level TEXT DEFAULT 'beginner', started_playing DATE,
    is_primary INTEGER DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS practice_sessions_music (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, instrument_id INTEGER,
    duration_minutes INTEGER DEFAULT 30, focus_areas TEXT DEFAULT '[]',
    pieces_practiced TEXT DEFAULT '[]', bpm_achieved INTEGER, quality_rating INTEGER DEFAULT 3,
    notes TEXT, practice_date DATE, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS repertoire (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, instrument_id INTEGER,
    title TEXT, composer TEXT, difficulty TEXT DEFAULT 'intermediate',
    status TEXT DEFAULT 'learning', tempo_target INTEGER, tempo_achieved INTEGER,
    started_date DATE, performance_ready INTEGER DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS music_goals_tracker (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, instrument_id INTEGER,
    goal TEXT, target_date DATE, category TEXT DEFAULT 'technique',
    status TEXT DEFAULT 'active', notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/music/instruments', requireAuth, (req: any, res: any) => {
  const instruments = db.prepare(`SELECT i.*, SUM(ps.duration_minutes) as total_practice_minutes, COUNT(ps.id) as session_count FROM instruments i LEFT JOIN practice_sessions_music ps ON ps.instrument_id=i.id WHERE i.user_id=? GROUP BY i.id ORDER BY i.is_primary DESC`).all(req.user.id);
  res.json({ instruments });
});
app.post('/api/music/instruments', requireAuth, (req: any, res: any) => {
  const { name, type, brand, skill_level, started_playing, is_primary } = req.body;
  if (!name) return res.status(400).json({ error: 'name required' });
  if (is_primary) db.prepare(`UPDATE instruments SET is_primary=0 WHERE user_id=?`).run(req.user.id);
  const r = db.prepare(`INSERT INTO instruments (user_id,name,type,brand,skill_level,started_playing,is_primary) VALUES (?,?,?,?,?,?,?)`).run(req.user.id, name, type||'other', brand||'', skill_level||'beginner', started_playing||null, is_primary?1:0);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/music/practice', requireAuth, (req: any, res: any) => {
  const { instrument_id, duration_minutes, focus_areas, pieces_practiced, bpm_achieved, quality_rating, notes } = req.body;
  if (!instrument_id) return res.status(400).json({ error: 'instrument_id required' });
  const r = db.prepare(`INSERT INTO practice_sessions_music (user_id,instrument_id,duration_minutes,focus_areas,pieces_practiced,bpm_achieved,quality_rating,notes,practice_date) VALUES (?,?,?,?,?,?,?,?,date('now'))`).run(req.user.id, instrument_id, duration_minutes||30, JSON.stringify(focus_areas||[]), JSON.stringify(pieces_practiced||[]), bpm_achieved||null, quality_rating||3, notes||'');
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/music/practice/stats', requireAuth, (req: any, res: any) => {
  const { days } = req.query as any;
  const since = new Date(Date.now() - (parseInt(days)||30) * 86400000).toISOString().slice(0,10);
  const stats = db.prepare(`SELECT SUM(duration_minutes) as total_minutes, COUNT(*) as session_count, AVG(quality_rating) as avg_quality, COUNT(DISTINCT practice_date) as practice_days FROM practice_sessions_music WHERE user_id=? AND practice_date >= ?`).get(req.user.id, since) as any;
  const streak = (db.prepare(`SELECT COUNT(DISTINCT practice_date) as s FROM practice_sessions_music WHERE user_id=? AND practice_date >= date('now','-7 days')`).get(req.user.id) as any)?.s || 0;
  res.json({ ...stats, weekly_days: streak, avg_quality: Math.round((stats?.avg_quality||0) * 10) / 10 });
});
app.get('/api/music/repertoire', requireAuth, (req: any, res: any) => {
  const { status, instrument_id } = req.query as any;
  let q = `SELECT * FROM repertoire WHERE user_id=?`;
  const p: any[] = [req.user.id];
  if (status) { q += ` AND status=?`; p.push(status); }
  if (instrument_id) { q += ` AND instrument_id=?`; p.push(instrument_id); }
  q += ` ORDER BY CASE status WHEN 'performing' THEN 1 WHEN 'polishing' THEN 2 WHEN 'learning' THEN 3 ELSE 4 END, title`;
  res.json({ repertoire: db.prepare(q).all(...p) });
});
app.post('/api/music/repertoire', requireAuth, (req: any, res: any) => {
  const { instrument_id, title, composer, difficulty, tempo_target } = req.body;
  if (!title) return res.status(400).json({ error: 'title required' });
  const r = db.prepare(`INSERT INTO repertoire (user_id,instrument_id,title,composer,difficulty,tempo_target,started_date) VALUES (?,?,?,?,?,?,date('now'))`).run(req.user.id, instrument_id||null, title, composer||'', difficulty||'intermediate', tempo_target||null);
  res.json({ id: r.lastInsertRowid });
});
app.put('/api/music/repertoire/:id', requireAuth, (req: any, res: any) => {
  const { status, tempo_achieved, performance_ready } = req.body;
  db.prepare(`UPDATE repertoire SET status=COALESCE(?,status), tempo_achieved=COALESCE(?,tempo_achieved), performance_ready=COALESCE(?,performance_ready) WHERE id=? AND user_id=?`).run(status, tempo_achieved, performance_ready!==undefined?performance_ready?1:0:null, req.params.id, req.user.id);
  res.json({ success: true });
});
// ─── End B257 ────────────────────────────────────────────────────────────────

// ─── B258: Nonprofit & Volunteer Management ───────────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS volunteer_profiles (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, first_name TEXT, last_name TEXT,
    email TEXT, phone TEXT, skills TEXT DEFAULT '[]', availability TEXT DEFAULT '[]',
    hours_volunteered REAL DEFAULT 0, status TEXT DEFAULT 'active',
    background_check_date DATE, emergency_contact TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS volunteer_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, title TEXT, description TEXT,
    location TEXT, start_datetime DATETIME, end_datetime DATETIME,
    volunteers_needed INTEGER DEFAULT 5, volunteers_confirmed INTEGER DEFAULT 0,
    coordinator TEXT, status TEXT DEFAULT 'planned', created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS volunteer_shifts (
    id INTEGER PRIMARY KEY AUTOINCREMENT, event_id INTEGER, volunteer_id INTEGER, user_id INTEGER,
    status TEXT DEFAULT 'confirmed', hours_logged REAL DEFAULT 0,
    check_in DATETIME, check_out DATETIME, notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS donations (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, donor_name TEXT,
    donor_email TEXT, amount REAL, donation_type TEXT DEFAULT 'monetary',
    campaign TEXT, is_recurring INTEGER DEFAULT 0, payment_method TEXT,
    receipt_sent INTEGER DEFAULT 0, notes TEXT, donated_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/volunteers', requireAuth, (req: any, res: any) => {
  const volunteers = db.prepare(`SELECT * FROM volunteer_profiles WHERE user_id=? ORDER BY hours_volunteered DESC`).all(req.user.id);
  res.json({ volunteers, total: (volunteers as any[]).length, active: (volunteers as any[]).filter((v: any) => v.status === 'active').length });
});
app.post('/api/volunteers', requireAuth, (req: any, res: any) => {
  const { first_name, last_name, email, phone, skills, availability } = req.body;
  if (!first_name || !email) return res.status(400).json({ error: 'name and email required' });
  const r = db.prepare(`INSERT INTO volunteer_profiles (user_id,first_name,last_name,email,phone,skills,availability) VALUES (?,?,?,?,?,?,?)`).run(req.user.id, first_name, last_name||'', email, phone||'', JSON.stringify(skills||[]), JSON.stringify(availability||[]));
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/volunteer-events', requireAuth, (req: any, res: any) => {
  const events = db.prepare(`SELECT * FROM volunteer_events WHERE user_id=? ORDER BY start_datetime ASC`).all(req.user.id);
  res.json({ events, upcoming: (events as any[]).filter((e: any) => e.start_datetime > new Date().toISOString()) });
});
app.post('/api/volunteer-events', requireAuth, (req: any, res: any) => {
  const { title, description, location, start_datetime, end_datetime, volunteers_needed, coordinator } = req.body;
  if (!title || !start_datetime) return res.status(400).json({ error: 'title and start_datetime required' });
  const r = db.prepare(`INSERT INTO volunteer_events (user_id,title,description,location,start_datetime,end_datetime,volunteers_needed,coordinator) VALUES (?,?,?,?,?,?,?,?)`).run(req.user.id, title, description||'', location||'', start_datetime, end_datetime||'', volunteers_needed||5, coordinator||'');
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/volunteer-events/:id/signup', requireAuth, (req: any, res: any) => {
  const { volunteer_id } = req.body;
  const existing = db.prepare(`SELECT id FROM volunteer_shifts WHERE event_id=? AND volunteer_id=?`).get(req.params.id, volunteer_id);
  if (existing) return res.status(400).json({ error: 'already signed up' });
  const r = db.prepare(`INSERT INTO volunteer_shifts (event_id,volunteer_id,user_id) VALUES (?,?,?)`).run(req.params.id, volunteer_id, req.user.id);
  db.prepare(`UPDATE volunteer_events SET volunteers_confirmed=volunteers_confirmed+1 WHERE id=?`).run(req.params.id);
  res.json({ id: r.lastInsertRowid });
});
app.put('/api/volunteer-shifts/:id/checkin', requireAuth, (req: any, res: any) => {
  db.prepare(`UPDATE volunteer_shifts SET check_in=CURRENT_TIMESTAMP, status='checked_in' WHERE id=? AND user_id=?`).run(req.params.id, req.user.id);
  res.json({ success: true });
});
app.put('/api/volunteer-shifts/:id/checkout', requireAuth, (req: any, res: any) => {
  const shift = db.prepare(`SELECT * FROM volunteer_shifts WHERE id=?`).get(req.params.id) as any;
  if (!shift?.check_in) return res.status(400).json({ error: 'must check in first' });
  const hours = Math.round((Date.now() - new Date(shift.check_in).getTime()) / 3600000 * 10) / 10;
  db.prepare(`UPDATE volunteer_shifts SET check_out=CURRENT_TIMESTAMP, hours_logged=?, status='completed' WHERE id=?`).run(hours, req.params.id);
  db.prepare(`UPDATE volunteer_profiles SET hours_volunteered=hours_volunteered+? WHERE id=?`).run(hours, shift.volunteer_id);
  res.json({ success: true, hours_logged: hours });
});
app.get('/api/donations', requireAuth, (req: any, res: any) => {
  const { campaign } = req.query as any;
  let q = `SELECT * FROM donations WHERE user_id=?`;
  const p: any[] = [req.user.id];
  if (campaign) { q += ` AND campaign=?`; p.push(campaign); }
  q += ` ORDER BY donated_at DESC`;
  const donations = db.prepare(q).all(...p) as any[];
  const total = donations.reduce((s: number, d: any) => s + d.amount, 0);
  res.json({ donations, total_raised: total, donor_count: new Set(donations.map((d: any) => d.donor_email)).size });
});
app.post('/api/donations', requireAuth, (req: any, res: any) => {
  const { donor_name, donor_email, amount, donation_type, campaign, is_recurring, payment_method } = req.body;
  if (!amount) return res.status(400).json({ error: 'amount required' });
  const r = db.prepare(`INSERT INTO donations (user_id,donor_name,donor_email,amount,donation_type,campaign,is_recurring,payment_method) VALUES (?,?,?,?,?,?,?,?)`).run(req.user.id, donor_name||'Anonymous', donor_email||'', amount, donation_type||'monetary', campaign||'general', is_recurring?1:0, payment_method||'');
  res.json({ id: r.lastInsertRowid });
});
