app.post('/api/podcasts/:id/episodes', requireAuth, (req: any, res: any) => {
  const { title, description, show_notes, audio_url, duration_seconds, transcript, tags } = req.body;
  if (!title) return res.status(400).json({ error: 'title required' });
  const ep_num = ((db.prepare(`SELECT MAX(episode_number) as m FROM podcast_episodes WHERE podcast_id=?`).get(req.params.id) as any)?.m || 0) + 1;
  const r = db.prepare(`INSERT INTO podcast_episodes (podcast_id,user_id,title,description,show_notes,episode_number,audio_url,duration_seconds,transcript,tags) VALUES (?,?,?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, title, description||'', show_notes||'', ep_num, audio_url||'', duration_seconds||0, transcript||'', JSON.stringify(tags||[]));
  db.prepare(`UPDATE podcasts SET episode_count=episode_count+1 WHERE id=?`).run(req.params.id);
  res.json({ id: r.lastInsertRowid, episode_number: ep_num });
});
app.put('/api/podcasts/episodes/:id/publish', requireAuth, (req: any, res: any) => {
  db.prepare(`UPDATE podcast_episodes SET status='published', published_at=CURRENT_TIMESTAMP WHERE id=? AND user_id=?`).run(req.params.id, req.user.id);
  res.json({ success: true, published_at: new Date().toISOString() });
});
app.post('/api/podcasts/:id/guests', requireAuth, (req: any, res: any) => {
  const { name, bio, website, social_links } = req.body;
  if (!name) return res.status(400).json({ error: 'name required' });
  const r = db.prepare(`INSERT INTO podcast_guests (podcast_id,user_id,name,bio,website,social_links) VALUES (?,?,?,?,?,?)`).run(req.params.id, req.user.id, name, bio||'', website||'', JSON.stringify(social_links||{}));
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/podcasts/episodes/:id/analytics', requireAuth, (req: any, res: any) => {
  const { listens, unique_listeners, avg_completion_pct } = req.body;
  const r = db.prepare(`INSERT INTO podcast_analytics (episode_id,user_id,listens,unique_listeners,avg_completion_pct,recorded_date) VALUES (?,?,?,?,?,date('now'))`).run(req.params.id, req.user.id, listens||0, unique_listeners||0, avg_completion_pct||0);
  db.prepare(`UPDATE podcast_episodes SET plays=plays+? WHERE id=?`).run(listens||0, req.params.id);
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/podcasts/:id/stats', requireAuth, (req: any, res: any) => {
  const stats = db.prepare(`SELECT SUM(pa.listens) as total_listens, SUM(pa.unique_listeners) as total_unique, AVG(pa.avg_completion_pct) as avg_completion, COUNT(DISTINCT pe.id) as published_episodes FROM podcast_episodes pe LEFT JOIN podcast_analytics pa ON pa.episode_id=pe.id WHERE pe.podcast_id=? AND pe.user_id=? AND pe.status='published'`).get(req.params.id, req.user.id) as any;
  res.json({ stats });
});
