app.get('/api/papers', requireAuth, (req: any, res: any) => {
  const { status, search, year } = req.query as any;
  let q = `SELECT id,title,authors,journal,year,doi,status,rating,read_date,keywords FROM papers WHERE user_id=?`;
  const p: any[] = [req.user.id];
  if (status) { q += ` AND status=?`; p.push(status); }
  if (year) { q += ` AND year=?`; p.push(year); }
  if (search) { q += ` AND (title LIKE ? OR authors LIKE ? OR keywords LIKE ?)`; p.push(`%${search}%`, `%${search}%`, `%${search}%`); }
  q += ` ORDER BY CASE status WHEN 'reading' THEN 1 WHEN 'to_read' THEN 2 ELSE 3 END, year DESC LIMIT 500`;
  const papers = db.prepare(q).all(...p) as any[];
  const stats = { total: papers.length, read: papers.filter((p: any) => p.status === 'read').length, reading: papers.filter((p: any) => p.status === 'reading').length, to_read: papers.filter((p: any) => p.status === 'to_read').length };
  res.json({ papers, stats });
});
