app.post('/api/campaigns/:id/pledge', (req: any, res: any) => {
  const { reward_id, backer_name, backer_email, amount, anonymous, message } = req.body;
  if (!amount || !backer_email) return res.status(400).json({ error: 'amount and backer_email required' });
  const campaign = db.prepare(`SELECT * FROM campaigns_v2 WHERE id=? AND status='active'`).get(req.params.id) as any;
  if (!campaign) return res.status(404).json({ error: 'campaign not found or inactive' });
  if (reward_id) {
    const reward = db.prepare(`SELECT * FROM campaign_rewards WHERE id=?`).get(reward_id) as any;
    if (reward?.limit_quantity && reward.claimed >= reward.limit_quantity) return res.status(400).json({ error: 'reward sold out' });
    db.prepare(`UPDATE campaign_rewards SET claimed=claimed+1 WHERE id=?`).run(reward_id);
  }
  const r = db.prepare(`INSERT INTO campaign_pledges (campaign_id,reward_id,user_id,backer_name,backer_email,amount,anonymous,message) VALUES (?,?,?,?,?,?,?,?)`).run(req.params.id, reward_id||null, campaign.user_id, backer_name||'Backer', backer_email, amount, anonymous?1:0, message||'');
  db.prepare(`UPDATE campaigns_v2 SET raised_amount=raised_amount+?, backer_count=backer_count+1 WHERE id=?`).run(amount, req.params.id);
  const updated = db.prepare(`SELECT raised_amount, goal_amount, backer_count FROM campaigns_v2 WHERE id=?`).get(req.params.id) as any;
  res.json({ id: r.lastInsertRowid, new_total: updated?.raised_amount, funding_pct: updated?.goal_amount > 0 ? Math.round(updated.raised_amount / updated.goal_amount * 1000) / 10 : 0 });
});
app.post('/api/campaigns/:id/updates', requireAuth, (req: any, res: any) => {
  const { title, content, is_public } = req.body;
  if (!title) return res.status(400).json({ error: 'title required' });
  const r = db.prepare(`INSERT INTO campaign_updates (campaign_id,user_id,title,content,is_public) VALUES (?,?,?,?,?)`).run(req.params.id, req.user.id, title, content||'', is_public!==false?1:0);
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/campaigns/:id/stats', requireAuth, (req: any, res: any) => {
  const campaign = db.prepare(`SELECT * FROM campaigns_v2 WHERE id=? AND user_id=?`).get(req.params.id, req.user.id) as any;
  if (!campaign) return res.status(404).json({ error: 'not found' });
  const top_pledges = db.prepare(`SELECT backer_name, amount, message, anonymous FROM campaign_pledges WHERE campaign_id=? AND anonymous=0 ORDER BY amount DESC LIMIT 10`).all(req.params.id);
  const by_reward = db.prepare(`SELECT cr.title, COUNT(cp.id) as pledges, SUM(cp.amount) as revenue FROM campaign_pledges cp LEFT JOIN campaign_rewards cr ON cr.id=cp.reward_id WHERE cp.campaign_id=? GROUP BY cp.reward_id`).all(req.params.id);
  const funding_pct = campaign.goal_amount > 0 ? Math.round(campaign.raised_amount / campaign.goal_amount * 1000) / 10 : 0;
  res.json({ campaign, funding_pct, top_pledges, by_reward });
});
