try { db.exec(`
  CREATE TABLE IF NOT EXISTS pos_products (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, sku TEXT, name TEXT,
    category TEXT, price REAL DEFAULT 0, cost REAL DEFAULT 0,
    stock INTEGER DEFAULT 0, low_stock_threshold INTEGER DEFAULT 10,
    barcode TEXT, unit TEXT DEFAULT 'each', is_active INTEGER DEFAULT 1,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS pos_sales (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, receipt_number TEXT,
    total_amount REAL DEFAULT 0, discount_amount REAL DEFAULT 0, tax_amount REAL DEFAULT 0,
    payment_method TEXT DEFAULT 'cash', customer_name TEXT, status TEXT DEFAULT 'completed',
    sold_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS pos_sale_items (
    id INTEGER PRIMARY KEY AUTOINCREMENT, sale_id INTEGER, product_id INTEGER,
    product_name TEXT, sku TEXT, quantity INTEGER DEFAULT 1,
    unit_price REAL DEFAULT 0, line_total REAL DEFAULT 0
  );
  CREATE TABLE IF NOT EXISTS pos_adjustments (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, product_id INTEGER,
    adjustment_type TEXT DEFAULT 'restock', quantity_change INTEGER,
    reason TEXT, new_stock INTEGER, adjusted_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/pos/products', requireAuth, (req: any, res: any) => {
  const { category, low_stock, search } = req.query as any;
  let q = `SELECT * FROM pos_products WHERE user_id=? AND is_active=1`;
  const p: any[] = [req.user.id];
  if (category) { q += ` AND category=?`; p.push(category); }
  if (low_stock === 'true') { q += ` AND stock <= low_stock_threshold`; }
  if (search) { q += ` AND (name LIKE ? OR sku LIKE ? OR barcode LIKE ?)`; p.push(`%${search}%`, `%${search}%`, `%${search}%`); }
  q += ` ORDER BY name ASC`;
  const products = db.prepare(q).all(...p) as any[];
  res.json({ products, low_stock_count: products.filter((p: any) => p.stock <= p.low_stock_threshold).length });
});
app.post('/api/pos/products', requireAuth, (req: any, res: any) => {
  const { sku, name, category, price, cost, stock, low_stock_threshold, barcode, unit } = req.body;
  if (!name || price === undefined) return res.status(400).json({ error: 'name and price required' });
  const r = db.prepare(`INSERT INTO pos_products (user_id,sku,name,category,price,cost,stock,low_stock_threshold,barcode,unit) VALUES (?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, sku||`SKU-${Date.now().toString().slice(-6)}`, name, category||'general', price, cost||0, stock||0, low_stock_threshold||10, barcode||'', unit||'each');
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/pos/sales', requireAuth, (req: any, res: any) => {
  const { items, payment_method, customer_name, discount_amount } = req.body;
  if (!items || !items.length) return res.status(400).json({ error: 'items required' });
  let subtotal = 0;
  for (const item of items) {
    const product = db.prepare(`SELECT * FROM pos_products WHERE id=? AND user_id=?`).get(item.product_id, req.user.id) as any;
    if (!product) return res.status(404).json({ error: `product ${item.product_id} not found` });
    if (product.stock < item.quantity) return res.status(400).json({ error: `insufficient stock for ${product.name}` });
    subtotal += product.price * item.quantity;
  }
  const disc = discount_amount || 0;
  const tax = Math.round((subtotal - disc) * 0.08 * 100) / 100;
  const total = subtotal - disc + tax;
  const receipt_number = `RCP-${Date.now().toString().slice(-8)}`;
  const sale = db.prepare(`INSERT INTO pos_sales (user_id,receipt_number,total_amount,discount_amount,tax_amount,payment_method,customer_name) VALUES (?,?,?,?,?,?,?)`).run(req.user.id, receipt_number, total, disc, tax, payment_method||'cash', customer_name||'');
  for (const item of items) {
    const product = db.prepare(`SELECT * FROM pos_products WHERE id=?`).get(item.product_id) as any;
    db.prepare(`INSERT INTO pos_sale_items (sale_id,product_id,product_name,sku,quantity,unit_price,line_total) VALUES (?,?,?,?,?,?,?)`).run(sale.lastInsertRowid, item.product_id, product.name, product.sku, item.quantity, product.price, product.price * item.quantity);
    db.prepare(`UPDATE pos_products SET stock=stock-? WHERE id=?`).run(item.quantity, item.product_id);
  }
  res.json({ id: sale.lastInsertRowid, receipt_number, total, tax });
});
app.get('/api/pos/sales', requireAuth, (req: any, res: any) => {
  const { date } = req.query as any;
  const filter = date ? ` AND date(sold_at)=?` : '';
  const p: any[] = date ? [req.user.id, date] : [req.user.id];
  const sales = db.prepare(`SELECT * FROM pos_sales WHERE user_id=?${filter} ORDER BY sold_at DESC LIMIT 100`).all(...p) as any[];
  const total_revenue = sales.reduce((s: number, x: any) => s + x.total_amount, 0);
  res.json({ sales, total_revenue, count: sales.length });
});
app.post('/api/pos/products/:id/adjust', requireAuth, (req: any, res: any) => {
  const { adjustment_type, quantity_change, reason } = req.body;
  const product = db.prepare(`SELECT * FROM pos_products WHERE id=? AND user_id=?`).get(req.params.id, req.user.id) as any;
  if (!product) return res.status(404).json({ error: 'not found' });
  const new_stock = product.stock + (quantity_change || 0);
  db.prepare(`UPDATE pos_products SET stock=? WHERE id=?`).run(Math.max(0, new_stock), req.params.id);
  db.prepare(`INSERT INTO pos_adjustments (user_id,product_id,adjustment_type,quantity_change,reason,new_stock) VALUES (?,?,?,?,?,?)`).run(req.user.id, req.params.id, adjustment_type||'restock', quantity_change||0, reason||'', Math.max(0, new_stock));
  res.json({ success: true, new_stock: Math.max(0, new_stock) });
});
// ─── End B266 ────────────────────────────────────────────────────────────────

