app.get('/api/membership/mrr', requireAuth, (req: any, res: any) => {
  const plans = db.prepare(`SELECT mp.billing_cycle, mp.price, COUNT(m.id) as count FROM members m JOIN membership_plans mp ON mp.id=m.plan_id WHERE m.user_id=? AND m.status='active' GROUP BY mp.id`).all(req.user.id) as any[];
  let mrr = 0;
  for (const plan of plans) {
    const monthly = plan.billing_cycle === 'annual' ? plan.price / 12 : plan.billing_cycle === 'quarterly' ? plan.price / 3 : plan.price;
    mrr += monthly * plan.count;
  }
  const total_members = plans.reduce((s: number, p: any) => s + p.count, 0);
  res.json({ mrr: Math.round(mrr * 100) / 100, arr: Math.round(mrr * 12 * 100) / 100, total_members });
});
