try { db.exec(`
  CREATE TABLE IF NOT EXISTS booking_services (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, name TEXT,
    description TEXT, duration_minutes INTEGER DEFAULT 60, price REAL DEFAULT 0,
    buffer_minutes INTEGER DEFAULT 0, color TEXT DEFAULT '#4f46e5',
    is_active INTEGER DEFAULT 1, max_advance_days INTEGER DEFAULT 60,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS booking_availability (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER,
    day_of_week INTEGER, start_time TEXT DEFAULT '09:00', end_time TEXT DEFAULT '17:00',
    is_available INTEGER DEFAULT 1
  );
  CREATE TABLE IF NOT EXISTS appointments_v2 (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, service_id INTEGER,
    client_name TEXT, client_email TEXT, client_phone TEXT,
    appointment_date DATE, start_time TEXT, end_time TEXT,
    status TEXT DEFAULT 'confirmed', price REAL DEFAULT 0,
    notes TEXT, cancellation_reason TEXT, reminder_sent INTEGER DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS booking_blocks (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, block_date DATE,
    start_time TEXT, end_time TEXT, reason TEXT DEFAULT 'blocked',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

