// ─── B271: AI Prompt Marketplace ─────────────────────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS prompt_listings (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, title TEXT, description TEXT,
    prompt_text TEXT, category TEXT DEFAULT 'general', tags TEXT DEFAULT '[]',
    price REAL DEFAULT 0, is_free INTEGER DEFAULT 1, is_published INTEGER DEFAULT 0,
    model_compatibility TEXT DEFAULT '[]', preview TEXT,
    downloads INTEGER DEFAULT 0, rating_sum REAL DEFAULT 0, rating_count INTEGER DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS prompt_purchases (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, listing_id INTEGER,
    amount_paid REAL DEFAULT 0, purchased_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS prompt_reviews (
    id INTEGER PRIMARY KEY AUTOINCREMENT, listing_id INTEGER, user_id INTEGER,
    rating INTEGER, review_text TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS prompt_collections (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, name TEXT,
    listing_ids TEXT DEFAULT '[]', is_public INTEGER DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/prompt-marketplace', (req: any, res: any) => {
  const { category, search, sort } = req.query as any;
  let q = `SELECT pl.id,pl.title,pl.description,pl.category,pl.tags,pl.price,pl.is_free,pl.preview,pl.downloads,pl.model_compatibility,CASE WHEN pl.rating_count>0 THEN ROUND(pl.rating_sum/pl.rating_count,1) ELSE 0 END as avg_rating,pl.rating_count FROM prompt_listings pl WHERE pl.is_published=1`;
  const p: any[] = [];
  if (category) { q += ` AND pl.category=?`; p.push(category); }
  if (search) { q += ` AND (pl.title LIKE ? OR pl.description LIKE ? OR pl.tags LIKE ?)`; p.push(`%${search}%`, `%${search}%`, `%${search}%`); }
  if (sort === 'popular') q += ` ORDER BY pl.downloads DESC`;
  else if (sort === 'rating') q += ` ORDER BY avg_rating DESC`;
  else q += ` ORDER BY pl.created_at DESC`;
  q += ` LIMIT 100`;
  res.json({ listings: db.prepare(q).all(...p) });
});
app.post('/api/prompt-marketplace', requireAuth, (req: any, res: any) => {
  const { title, description, prompt_text, category, tags, price, preview, model_compatibility } = req.body;
  if (!title || !prompt_text) return res.status(400).json({ error: 'title and prompt_text required' });
  const is_free = !price || price === 0 ? 1 : 0;
  const r = db.prepare(`INSERT INTO prompt_listings (user_id,title,description,prompt_text,category,tags,price,is_free,preview,model_compatibility) VALUES (?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, title, description||'', prompt_text, category||'general', JSON.stringify(tags||[]), price||0, is_free, preview||prompt_text.slice(0,200), JSON.stringify(model_compatibility||[]));
  res.json({ id: r.lastInsertRowid });
});
app.put('/api/prompt-marketplace/:id/publish', requireAuth, (req: any, res: any) => {
  db.prepare(`UPDATE prompt_listings SET is_published=1 WHERE id=? AND user_id=?`).run(req.params.id, req.user.id);
  res.json({ success: true });
});
app.post('/api/prompt-marketplace/:id/download', requireAuth, (req: any, res: any) => {
  const listing = db.prepare(`SELECT * FROM prompt_listings WHERE id=? AND is_published=1`).get(req.params.id) as any;
  if (!listing) return res.status(404).json({ error: 'not found' });
  if (!listing.is_free && listing.user_id !== req.user.id) {
    const owned = db.prepare(`SELECT id FROM prompt_purchases WHERE user_id=? AND listing_id=?`).get(req.user.id, req.params.id);
    if (!owned) return res.status(403).json({ error: 'purchase required' });
  }
  db.prepare(`UPDATE prompt_listings SET downloads=downloads+1 WHERE id=?`).run(req.params.id);
  res.json({ prompt_text: listing.prompt_text });
});
app.post('/api/prompt-marketplace/:id/review', requireAuth, (req: any, res: any) => {
  const { rating, review_text } = req.body;
  if (!rating || rating < 1 || rating > 5) return res.status(400).json({ error: 'rating 1-5 required' });
  const r = db.prepare(`INSERT INTO prompt_reviews (listing_id,user_id,rating,review_text) VALUES (?,?,?,?)`).run(req.params.id, req.user.id, rating, review_text||'');
  db.prepare(`UPDATE prompt_listings SET rating_sum=rating_sum+?, rating_count=rating_count+1 WHERE id=?`).run(rating, req.params.id);
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/prompt-marketplace/my-listings', requireAuth, (req: any, res: any) => {
  const listings = db.prepare(`SELECT *, CASE WHEN rating_count>0 THEN ROUND(rating_sum/rating_count,1) ELSE 0 END as avg_rating FROM prompt_listings WHERE user_id=? ORDER BY created_at DESC`).all(req.user.id);
  res.json({ listings });
});
