// ─── B272: Social Network & Community Builder ─────────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS community_posts (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, community_id INTEGER,
    content TEXT, media_urls TEXT DEFAULT '[]', post_type TEXT DEFAULT 'text',
    like_count INTEGER DEFAULT 0, comment_count INTEGER DEFAULT 0,
    share_count INTEGER DEFAULT 0, is_pinned INTEGER DEFAULT 0,
    status TEXT DEFAULT 'published', created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS communities (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, name TEXT, slug TEXT,
    description TEXT, category TEXT, cover_image TEXT, avatar_image TEXT,
    is_private INTEGER DEFAULT 0, member_count INTEGER DEFAULT 0,
    require_approval INTEGER DEFAULT 0, rules TEXT DEFAULT '[]',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS community_members (
    id INTEGER PRIMARY KEY AUTOINCREMENT, community_id INTEGER, user_id INTEGER,
    role TEXT DEFAULT 'member', status TEXT DEFAULT 'active', joined_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS post_comments (
    id INTEGER PRIMARY KEY AUTOINCREMENT, post_id INTEGER, user_id INTEGER,
    content TEXT, like_count INTEGER DEFAULT 0, parent_comment_id INTEGER,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS post_reactions (
    id INTEGER PRIMARY KEY AUTOINCREMENT, post_id INTEGER, user_id INTEGER,
    reaction_type TEXT DEFAULT 'like', created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(post_id, user_id)
  );
`); } catch(e) {}

app.get('/api/communities', (req: any, res: any) => {
  const { category, search } = req.query as any;
  let q = `SELECT id,name,slug,description,category,member_count,is_private FROM communities WHERE is_private=0`;
  const p: any[] = [];
  if (category) { q += ` AND category=?`; p.push(category); }
  if (search) { q += ` AND (name LIKE ? OR description LIKE ?)`; p.push(`%${search}%`, `%${search}%`); }
  q += ` ORDER BY member_count DESC LIMIT 50`;
  res.json({ communities: db.prepare(q).all(...p) });
});
app.post('/api/communities', requireAuth, (req: any, res: any) => {
  const { name, description, category, is_private, require_approval, rules } = req.body;
  if (!name) return res.status(400).json({ error: 'name required' });
  const slug = name.toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '') + '-' + Date.now().toString().slice(-4);
  const r = db.prepare(`INSERT INTO communities (user_id,name,slug,description,category,is_private,require_approval,rules,member_count) VALUES (?,?,?,?,?,?,?,?,1)`).run(req.user.id, name, slug, description||'', category||'general', is_private?1:0, require_approval?1:0, JSON.stringify(rules||[]));
  db.prepare(`INSERT INTO community_members (community_id,user_id,role) VALUES (?,?,'owner')`).run(r.lastInsertRowid, req.user.id);
  res.json({ id: r.lastInsertRowid, slug });
});
app.post('/api/communities/:id/join', requireAuth, (req: any, res: any) => {
  const community = db.prepare(`SELECT * FROM communities WHERE id=?`).get(req.params.id) as any;
  if (!community) return res.status(404).json({ error: 'not found' });
  const existing = db.prepare(`SELECT id,status FROM community_members WHERE community_id=? AND user_id=?`).get(req.params.id, req.user.id) as any;
  if (existing) return res.json({ status: existing.status });
  const status = community.require_approval ? 'pending' : 'active';
  db.prepare(`INSERT INTO community_members (community_id,user_id,role,status) VALUES (?,?,'member',?)`).run(req.params.id, req.user.id, status);
  if (status === 'active') db.prepare(`UPDATE communities SET member_count=member_count+1 WHERE id=?`).run(req.params.id);
  res.json({ status });
});
app.get('/api/communities/:id/posts', (req: any, res: any) => {
  const posts = db.prepare(`SELECT cp.*, cp.user_id as author_id FROM community_posts cp WHERE cp.community_id=? AND cp.status='published' ORDER BY cp.is_pinned DESC, cp.created_at DESC LIMIT 50`).all(req.params.id);
  res.json({ posts });
});
app.post('/api/communities/:id/posts', requireAuth, (req: any, res: any) => {
  const { content, media_urls, post_type } = req.body;
  if (!content) return res.status(400).json({ error: 'content required' });
  const r = db.prepare(`INSERT INTO community_posts (user_id,community_id,content,media_urls,post_type) VALUES (?,?,?,?,?)`).run(req.user.id, req.params.id, content, JSON.stringify(media_urls||[]), post_type||'text');
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/posts/:id/react', requireAuth, (req: any, res: any) => {
  const { reaction_type } = req.body;
  const existing = db.prepare(`SELECT id FROM post_reactions WHERE post_id=? AND user_id=?`).get(req.params.id, req.user.id);
  if (existing) {
    db.prepare(`DELETE FROM post_reactions WHERE post_id=? AND user_id=?`).run(req.params.id, req.user.id);
    db.prepare(`UPDATE community_posts SET like_count=MAX(0,like_count-1) WHERE id=?`).run(req.params.id);
    return res.json({ liked: false });
  }
  db.prepare(`INSERT OR REPLACE INTO post_reactions (post_id,user_id,reaction_type) VALUES (?,?,?)`).run(req.params.id, req.user.id, reaction_type||'like');
  db.prepare(`UPDATE community_posts SET like_count=like_count+1 WHERE id=?`).run(req.params.id);
  res.json({ liked: true });
});
app.post('/api/posts/:id/comments', requireAuth, (req: any, res: any) => {
  const { content, parent_comment_id } = req.body;
  if (!content) return res.status(400).json({ error: 'content required' });
  const r = db.prepare(`INSERT INTO post_comments (post_id,user_id,content,parent_comment_id) VALUES (?,?,?,?)`).run(req.params.id, req.user.id, content, parent_comment_id||null);
  db.prepare(`UPDATE community_posts SET comment_count=comment_count+1 WHERE id=?`).run(req.params.id);
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/posts/:id/comments', (req: any, res: any) => {
  const comments = db.prepare(`SELECT * FROM post_comments WHERE post_id=? AND parent_comment_id IS NULL ORDER BY created_at ASC`).all(req.params.id);
  res.json({ comments });
});
