// ─── B280: Language Exchange & Tutoring Platform ─────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS language_profiles (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, native_language TEXT,
    learning_languages TEXT DEFAULT '[]', proficiency_levels TEXT DEFAULT '{}',
    available_hours TEXT DEFAULT '[]', bio TEXT, timezone TEXT,
    is_tutor INTEGER DEFAULT 0, hourly_rate REAL DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS exchange_sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, partner_id INTEGER,
    language_practiced TEXT, session_date DATE, duration_minutes INTEGER DEFAULT 60,
    session_type TEXT DEFAULT 'conversation', notes TEXT, rating INTEGER,
    feedback TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS vocabulary_lists (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, language TEXT,
    list_name TEXT, words TEXT DEFAULT '[]', mastered_count INTEGER DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS language_progress (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, language TEXT,
    skill_type TEXT DEFAULT 'vocabulary', current_level TEXT DEFAULT 'A1',
    xp_points INTEGER DEFAULT 0, streak_days INTEGER DEFAULT 0,
    last_practice_date DATE, created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(user_id, language, skill_type)
  );
`); } catch(e) {}

app.get('/api/language/tutors', (req: any, res: any) => {
  const { language } = req.query as any;
  let q = `SELECT lp.*,lp.user_id as tutor_user_id FROM language_profiles lp WHERE lp.is_tutor=1`;
  const p: any[] = [];
  if (language) { q += ` AND lp.learning_languages LIKE ?`; p.push(`%${language}%`); }
  q += ` ORDER BY lp.hourly_rate ASC LIMIT 50`;
  res.json({ tutors: db.prepare(q).all(...p) });
});
app.post('/api/language/profile', requireAuth, (req: any, res: any) => {
  const { native_language, learning_languages, proficiency_levels, available_hours, bio, timezone, is_tutor, hourly_rate } = req.body;
  const existing = db.prepare(`SELECT id FROM language_profiles WHERE user_id=?`).get(req.user.id);
  if (existing) {
    db.prepare(`UPDATE language_profiles SET native_language=COALESCE(?,native_language), learning_languages=COALESCE(?,learning_languages), proficiency_levels=COALESCE(?,proficiency_levels), available_hours=COALESCE(?,available_hours), bio=COALESCE(?,bio), is_tutor=COALESCE(?,is_tutor), hourly_rate=COALESCE(?,hourly_rate) WHERE user_id=?`).run(native_language, learning_languages?JSON.stringify(learning_languages):null, proficiency_levels?JSON.stringify(proficiency_levels):null, available_hours?JSON.stringify(available_hours):null, bio, is_tutor!==undefined?is_tutor?1:0:null, hourly_rate, req.user.id);
    return res.json({ updated: true });
  }
  const r = db.prepare(`INSERT INTO language_profiles (user_id,native_language,learning_languages,proficiency_levels,available_hours,bio,timezone,is_tutor,hourly_rate) VALUES (?,?,?,?,?,?,?,?,?)`).run(req.user.id, native_language||'', JSON.stringify(learning_languages||[]), JSON.stringify(proficiency_levels||{}), JSON.stringify(available_hours||[]), bio||'', timezone||'UTC', is_tutor?1:0, hourly_rate||0);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/language/sessions', requireAuth, (req: any, res: any) => {
  const { partner_id, language_practiced, session_date, duration_minutes, session_type, notes } = req.body;
  if (!language_practiced) return res.status(400).json({ error: 'language_practiced required' });
  const r = db.prepare(`INSERT INTO exchange_sessions (user_id,partner_id,language_practiced,session_date,duration_minutes,session_type,notes) VALUES (?,?,?,?,?,?,?)`).run(req.user.id, partner_id||null, language_practiced, session_date||new Date().toISOString().slice(0,10), duration_minutes||60, session_type||'conversation', notes||'');
  const today = new Date().toISOString().slice(0,10);
  try {
    db.prepare(`INSERT INTO language_progress (user_id,language,skill_type,xp_points,streak_days,last_practice_date) VALUES (?,?,?,10,1,?) ON CONFLICT(user_id,language,skill_type) DO UPDATE SET xp_points=xp_points+10, streak_days=CASE WHEN last_practice_date=date('now','-1 day') THEN streak_days+1 ELSE 1 END, last_practice_date=?`).run(req.user.id, language_practiced, 'speaking', today, today);
  } catch(e) {}
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/language/vocabulary', requireAuth, (req: any, res: any) => {
  const { language, list_name, words } = req.body;
  if (!language || !list_name) return res.status(400).json({ error: 'language and list_name required' });
  const r = db.prepare(`INSERT INTO vocabulary_lists (user_id,language,list_name,words) VALUES (?,?,?,?)`).run(req.user.id, language, list_name, JSON.stringify(words||[]));
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/language/progress', requireAuth, (req: any, res: any) => {
  const progress = db.prepare(`SELECT * FROM language_progress WHERE user_id=? ORDER BY xp_points DESC`).all(req.user.id);
  const sessions_30d = db.prepare(`SELECT language_practiced, COUNT(*) as count, SUM(duration_minutes) as minutes FROM exchange_sessions WHERE user_id=? AND session_date >= date('now','-30 days') GROUP BY language_practiced`).all(req.user.id);
  res.json({ progress, sessions_30d });
});
app.get('/api/language/vocabulary', requireAuth, (req: any, res: any) => {
  const { language } = req.query as any;
  let q = `SELECT * FROM vocabulary_lists WHERE user_id=?`;
  const p: any[] = [req.user.id];
  if (language) { q += ` AND language=?`; p.push(language); }
  q += ` ORDER BY created_at DESC`;
  res.json({ lists: db.prepare(q).all(...p) });
});
