// ─── B281: Investment Portfolio & Stock Tracker v2 ───────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS portfolios (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, name TEXT,
    portfolio_type TEXT DEFAULT 'brokerage', currency TEXT DEFAULT 'USD',
    benchmark TEXT DEFAULT 'SPY', total_invested REAL DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS portfolio_holdings (
    id INTEGER PRIMARY KEY AUTOINCREMENT, portfolio_id INTEGER, user_id INTEGER,
    ticker TEXT, asset_type TEXT DEFAULT 'stock', name TEXT,
    shares REAL DEFAULT 0, avg_cost REAL DEFAULT 0, current_price REAL DEFAULT 0,
    sector TEXT DEFAULT 'unknown', country TEXT DEFAULT 'US',
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS stock_transactions (
    id INTEGER PRIMARY KEY AUTOINCREMENT, portfolio_id INTEGER, user_id INTEGER,
    ticker TEXT, transaction_type TEXT DEFAULT 'buy', shares REAL DEFAULT 0,
    price REAL DEFAULT 0, total REAL DEFAULT 0, fees REAL DEFAULT 0,
    transaction_date DATE, notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS watchlist_v2 (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, ticker TEXT,
    name TEXT, target_price REAL, alert_below REAL, alert_above REAL,
    notes TEXT, added_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/portfolios', requireAuth, (req: any, res: any) => {
  const portfolios = db.prepare(`SELECT p.*, COUNT(ph.id) as holding_count FROM portfolios p LEFT JOIN portfolio_holdings ph ON ph.portfolio_id=p.id WHERE p.user_id=? GROUP BY p.id ORDER BY p.name ASC`).all(req.user.id);
  res.json({ portfolios });
});
app.post('/api/portfolios', requireAuth, (req: any, res: any) => {
  const { name, portfolio_type, currency, benchmark } = req.body;
  if (!name) return res.status(400).json({ error: 'name required' });
  const r = db.prepare(`INSERT INTO portfolios (user_id,name,portfolio_type,currency,benchmark) VALUES (?,?,?,?,?)`).run(req.user.id, name, portfolio_type||'brokerage', currency||'USD', benchmark||'SPY');
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/portfolios/:id/holdings', requireAuth, (req: any, res: any) => {
  const holdings = db.prepare(`SELECT ph.*, ROUND((ph.current_price - ph.avg_cost) / ph.avg_cost * 100, 2) as gain_pct, ROUND((ph.current_price - ph.avg_cost) * ph.shares, 2) as unrealized_gain, ROUND(ph.current_price * ph.shares, 2) as market_value FROM portfolio_holdings ph WHERE ph.portfolio_id=? AND ph.user_id=? AND ph.shares>0 ORDER BY market_value DESC`).all(req.params.id, req.user.id) as any[];
  const total_value = holdings.reduce((s: number, h: any) => s + h.market_value, 0);
  const total_gain = holdings.reduce((s: number, h: any) => s + h.unrealized_gain, 0);
  const by_sector = holdings.reduce((acc: any, h: any) => { if (!acc[h.sector]) acc[h.sector] = 0; acc[h.sector] += h.market_value; return acc; }, {});
  res.json({ holdings, total_value: Math.round(total_value*100)/100, total_gain: Math.round(total_gain*100)/100, by_sector });
});
app.post('/api/portfolios/:id/trade', requireAuth, (req: any, res: any) => {
  const { ticker, transaction_type, shares, price, fees, transaction_date, name, sector, asset_type } = req.body;
  if (!ticker || !shares || !price) return res.status(400).json({ error: 'ticker, shares, price required' });
  const total = Math.round(shares * price * 100) / 100;
  db.prepare(`INSERT INTO stock_transactions (portfolio_id,user_id,ticker,transaction_type,shares,price,total,fees,transaction_date) VALUES (?,?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, ticker.toUpperCase(), transaction_type||'buy', shares, price, total, fees||0, transaction_date||new Date().toISOString().slice(0,10));
  const existing = db.prepare(`SELECT * FROM portfolio_holdings WHERE portfolio_id=? AND user_id=? AND ticker=?`).get(req.params.id, req.user.id, ticker.toUpperCase()) as any;
  if (transaction_type === 'buy') {
    if (existing) {
      const new_shares = existing.shares + shares;
      const new_avg = (existing.avg_cost * existing.shares + price * shares) / new_shares;
      db.prepare(`UPDATE portfolio_holdings SET shares=?, avg_cost=?, current_price=?, updated_at=CURRENT_TIMESTAMP WHERE id=?`).run(new_shares, Math.round(new_avg*10000)/10000, price, existing.id);
    } else {
      db.prepare(`INSERT INTO portfolio_holdings (portfolio_id,user_id,ticker,asset_type,name,shares,avg_cost,current_price,sector) VALUES (?,?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, ticker.toUpperCase(), asset_type||'stock', name||ticker.toUpperCase(), shares, price, price, sector||'unknown');
    }
  } else if (transaction_type === 'sell' && existing) {
    const new_shares = Math.max(0, existing.shares - shares);
    db.prepare(`UPDATE portfolio_holdings SET shares=?, current_price=?, updated_at=CURRENT_TIMESTAMP WHERE id=?`).run(new_shares, price, existing.id);
  }
  res.json({ success: true, total });
});
app.put('/api/portfolios/:id/prices', requireAuth, (req: any, res: any) => {
  const { prices } = req.body;
  if (!prices || typeof prices !== 'object') return res.status(400).json({ error: 'prices object required {TICKER: price}' });
  for (const [ticker, price] of Object.entries(prices)) {
    db.prepare(`UPDATE portfolio_holdings SET current_price=?, updated_at=CURRENT_TIMESTAMP WHERE portfolio_id=? AND user_id=? AND ticker=?`).run(price, req.params.id, req.user.id, ticker.toUpperCase());
  }
  res.json({ success: true, updated: Object.keys(prices).length });
});
app.get('/api/watchlist', requireAuth, (req: any, res: any) => {
  res.json({ watchlist: db.prepare(`SELECT * FROM watchlist_v2 WHERE user_id=? ORDER BY added_at DESC`).all(req.user.id) });
});
app.post('/api/watchlist', requireAuth, (req: any, res: any) => {
  const { ticker, name, target_price, alert_below, alert_above, notes } = req.body;
  if (!ticker) return res.status(400).json({ error: 'ticker required' });
  const r = db.prepare(`INSERT OR REPLACE INTO watchlist_v2 (user_id,ticker,name,target_price,alert_below,alert_above,notes) VALUES (?,?,?,?,?,?,?)`).run(req.user.id, ticker.toUpperCase(), name||ticker.toUpperCase(), target_price||null, alert_below||null, alert_above||null, notes||'');
  res.json({ id: r.lastInsertRowid });
});
