// ─── B282: Contract Lifecycle Management (CLM) ───────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS clm_contracts (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, contract_number TEXT,
    title TEXT, vendor_name TEXT, contract_type TEXT DEFAULT 'service',
    value REAL DEFAULT 0, currency TEXT DEFAULT 'USD',
    start_date DATE, end_date DATE, auto_renew INTEGER DEFAULT 0,
    renewal_notice_days INTEGER DEFAULT 30, owner TEXT, department TEXT,
    status TEXT DEFAULT 'draft', risk_level TEXT DEFAULT 'low',
    tags TEXT DEFAULT '[]', created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS clm_obligations (
    id INTEGER PRIMARY KEY AUTOINCREMENT, contract_id INTEGER, user_id INTEGER,
    obligation_text TEXT, due_date DATE, responsible_party TEXT,
    frequency TEXT DEFAULT 'one_time', status TEXT DEFAULT 'pending',
    completed_at DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS clm_amendments (
    id INTEGER PRIMARY KEY AUTOINCREMENT, contract_id INTEGER, user_id INTEGER,
    amendment_number INTEGER DEFAULT 1, description TEXT, effective_date DATE,
    value_change REAL DEFAULT 0, approved_by TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS clm_approvals (
    id INTEGER PRIMARY KEY AUTOINCREMENT, contract_id INTEGER, user_id INTEGER,
    approver_name TEXT, approver_email TEXT, status TEXT DEFAULT 'pending',
    comments TEXT, responded_at DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/clm/contracts', requireAuth, (req: any, res: any) => {
  const { status, risk_level, expiring_days } = req.query as any;
  let q = `SELECT cc.*, COUNT(co.id) as obligation_count, COUNT(ca.id) as amendment_count FROM clm_contracts cc LEFT JOIN clm_obligations co ON co.contract_id=cc.id AND co.status='pending' LEFT JOIN clm_amendments ca ON ca.contract_id=cc.id WHERE cc.user_id=?`;
  const p: any[] = [req.user.id];
  if (status) { q += ` AND cc.status=?`; p.push(status); }
  if (risk_level) { q += ` AND cc.risk_level=?`; p.push(risk_level); }
  if (expiring_days) { q += ` AND cc.end_date <= date('now','+' || ? || ' days') AND cc.end_date >= date('now')`; p.push(expiring_days); }
  q += ` GROUP BY cc.id ORDER BY cc.end_date ASC`;
  const contracts = db.prepare(q).all(...p) as any[];
  const total_value = contracts.reduce((s: number, c: any) => s + c.value, 0);
  res.json({ contracts, total_value, expiring_soon: contracts.filter((c: any) => c.end_date && c.end_date <= new Date(Date.now() + 30*86400000).toISOString().slice(0,10)).length });
});
app.post('/api/clm/contracts', requireAuth, (req: any, res: any) => {
  const { title, vendor_name, contract_type, value, start_date, end_date, auto_renew, renewal_notice_days, owner, department, tags } = req.body;
  if (!title) return res.status(400).json({ error: 'title required' });
  const contract_number = `CLM-${new Date().getFullYear()}-${Date.now().toString().slice(-5)}`;
  const r = db.prepare(`INSERT INTO clm_contracts (user_id,contract_number,title,vendor_name,contract_type,value,start_date,end_date,auto_renew,renewal_notice_days,owner,department,tags) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, contract_number, title, vendor_name||'', contract_type||'service', value||0, start_date||'', end_date||'', auto_renew?1:0, renewal_notice_days||30, owner||'', department||'', JSON.stringify(tags||[]));
  res.json({ id: r.lastInsertRowid, contract_number });
});
app.put('/api/clm/contracts/:id/status', requireAuth, (req: any, res: any) => {
  const { status } = req.body;
  db.prepare(`UPDATE clm_contracts SET status=? WHERE id=? AND user_id=?`).run(status, req.params.id, req.user.id);
  res.json({ success: true });
});
app.post('/api/clm/contracts/:id/obligations', requireAuth, (req: any, res: any) => {
  const { obligation_text, due_date, responsible_party, frequency } = req.body;
  if (!obligation_text) return res.status(400).json({ error: 'obligation_text required' });
  const r = db.prepare(`INSERT INTO clm_obligations (contract_id,user_id,obligation_text,due_date,responsible_party,frequency) VALUES (?,?,?,?,?,?)`).run(req.params.id, req.user.id, obligation_text, due_date||'', responsible_party||'', frequency||'one_time');
  res.json({ id: r.lastInsertRowid });
});
app.put('/api/clm/obligations/:id/complete', requireAuth, (req: any, res: any) => {
  db.prepare(`UPDATE clm_obligations SET status='completed', completed_at=CURRENT_TIMESTAMP WHERE id=? AND user_id=?`).run(req.params.id, req.user.id);
  res.json({ success: true });
});
app.post('/api/clm/contracts/:id/amendments', requireAuth, (req: any, res: any) => {
  const { description, effective_date, value_change, approved_by } = req.body;
  if (!description) return res.status(400).json({ error: 'description required' });
  const max_num = (db.prepare(`SELECT MAX(amendment_number) as m FROM clm_amendments WHERE contract_id=?`).get(req.params.id) as any)?.m || 0;
  const r = db.prepare(`INSERT INTO clm_amendments (contract_id,user_id,amendment_number,description,effective_date,value_change,approved_by) VALUES (?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, max_num+1, description, effective_date||'', value_change||0, approved_by||'');
  if (value_change) db.prepare(`UPDATE clm_contracts SET value=value+? WHERE id=?`).run(value_change, req.params.id);
  res.json({ id: r.lastInsertRowid, amendment_number: max_num+1 });
});
