// ─── B284: Dream Journal & Sleep Analysis ────────────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS dream_entries (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, dream_date DATE,
    title TEXT, description TEXT, dream_type TEXT DEFAULT 'regular',
    emotions TEXT DEFAULT '[]', symbols TEXT DEFAULT '[]', people TEXT DEFAULT '[]',
    locations TEXT DEFAULT '[]', lucid INTEGER DEFAULT 0, recurring INTEGER DEFAULT 0,
    vividness INTEGER DEFAULT 5, mood_on_wake INTEGER DEFAULT 5,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS sleep_logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, sleep_date DATE,
    bedtime TEXT, wake_time TEXT, sleep_duration_hours REAL,
    sleep_quality INTEGER DEFAULT 5, deep_sleep_pct INTEGER DEFAULT 20,
    rem_pct INTEGER DEFAULT 20, awakenings INTEGER DEFAULT 0,
    pre_sleep_activities TEXT DEFAULT '[]', notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS dream_symbols (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, symbol TEXT,
    personal_meaning TEXT, frequency INTEGER DEFAULT 1, first_seen DATE,
    last_seen DATE, created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(user_id, symbol)
  );
  CREATE TABLE IF NOT EXISTS sleep_goals_tracker (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER,
    target_hours REAL DEFAULT 8, target_bedtime TEXT DEFAULT '22:30',
    target_wake_time TEXT DEFAULT '06:30', created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.post('/api/dreams', requireAuth, (req: any, res: any) => {
  const { dream_date, title, description, dream_type, emotions, symbols, people, locations, lucid, recurring, vividness, mood_on_wake } = req.body;
  if (!description) return res.status(400).json({ error: 'description required' });
  const r = db.prepare(`INSERT INTO dream_entries (user_id,dream_date,title,description,dream_type,emotions,symbols,people,locations,lucid,recurring,vividness,mood_on_wake) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, dream_date||new Date().toISOString().slice(0,10), title||'Dream entry', description, dream_type||'regular', JSON.stringify(emotions||[]), JSON.stringify(symbols||[]), JSON.stringify(people||[]), JSON.stringify(locations||[]), lucid?1:0, recurring?1:0, vividness||5, mood_on_wake||5);
  for (const sym of (symbols||[])) {
    const today = new Date().toISOString().slice(0,10);
    try { db.prepare(`INSERT INTO dream_symbols (user_id,symbol,frequency,first_seen,last_seen) VALUES (?,?,1,?,?) ON CONFLICT(user_id,symbol) DO UPDATE SET frequency=frequency+1, last_seen=?`).run(req.user.id, sym, today, today, today); } catch(e) {}
  }
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/dreams', requireAuth, (req: any, res: any) => {
  const { lucid, recurring, month } = req.query as any;
  let q = `SELECT id,dream_date,title,dream_type,emotions,vividness,mood_on_wake,lucid,recurring FROM dream_entries WHERE user_id=?`;
  const p: any[] = [req.user.id];
  if (lucid === 'true') { q += ` AND lucid=1`; }
  if (recurring === 'true') { q += ` AND recurring=1`; }
  if (month) { q += ` AND strftime('%Y-%m',dream_date)=?`; p.push(month); }
  q += ` ORDER BY dream_date DESC LIMIT 100`;
  res.json({ dreams: db.prepare(q).all(...p) });
});
app.post('/api/sleep/log', requireAuth, (req: any, res: any) => {
  const { sleep_date, bedtime, wake_time, sleep_quality, deep_sleep_pct, rem_pct, awakenings, pre_sleep_activities, notes } = req.body;
  let duration = null;
  if (bedtime && wake_time) {
    const [bh, bm] = bedtime.split(':').map(Number);
    const [wh, wm] = wake_time.split(':').map(Number);
    let mins = (wh * 60 + wm) - (bh * 60 + bm);
    if (mins < 0) mins += 24 * 60;
    duration = Math.round(mins / 60 * 10) / 10;
  }
  const r = db.prepare(`INSERT INTO sleep_logs (user_id,sleep_date,bedtime,wake_time,sleep_duration_hours,sleep_quality,deep_sleep_pct,rem_pct,awakenings,pre_sleep_activities,notes) VALUES (?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, sleep_date||new Date().toISOString().slice(0,10), bedtime||'', wake_time||'', duration, sleep_quality||5, deep_sleep_pct||20, rem_pct||20, awakenings||0, JSON.stringify(pre_sleep_activities||[]), notes||'');
  res.json({ id: r.lastInsertRowid, sleep_duration_hours: duration });
});
app.get('/api/sleep/stats', requireAuth, (req: any, res: any) => {
  const stats = db.prepare(`SELECT AVG(sleep_duration_hours) as avg_hours, AVG(sleep_quality) as avg_quality, AVG(deep_sleep_pct) as avg_deep, AVG(rem_pct) as avg_rem, COUNT(*) as nights_logged FROM sleep_logs WHERE user_id=? AND sleep_date >= date('now','-30 days')`).get(req.user.id) as any;
  const best = db.prepare(`SELECT sleep_date, sleep_quality, sleep_duration_hours FROM sleep_logs WHERE user_id=? ORDER BY sleep_quality DESC LIMIT 1`).get(req.user.id);
  const symbols = db.prepare(`SELECT symbol, frequency FROM dream_symbols WHERE user_id=? ORDER BY frequency DESC LIMIT 10`).all(req.user.id);
  res.json({ last_30_days: { avg_hours: Math.round((stats?.avg_hours||0)*10)/10, avg_quality: Math.round((stats?.avg_quality||0)*10)/10, nights_logged: stats?.nights_logged||0 }, best_night: best, top_dream_symbols: symbols });
});
app.get('/api/dream-symbols', requireAuth, (req: any, res: any) => {
  res.json({ symbols: db.prepare(`SELECT * FROM dream_symbols WHERE user_id=? ORDER BY frequency DESC`).all(req.user.id) });
});
