// ─── B288: Genealogy & Family Tree Builder ───────────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS family_members (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, first_name TEXT, last_name TEXT,
    maiden_name TEXT, date_of_birth DATE, date_of_death DATE, gender TEXT,
    birth_place TEXT, death_place TEXT, occupation TEXT, bio TEXT,
    photo_url TEXT, is_living INTEGER DEFAULT 1,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS family_relationships (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER,
    member_id INTEGER, related_member_id INTEGER,
    relationship_type TEXT DEFAULT 'child',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(user_id, member_id, related_member_id, relationship_type)
  );
  CREATE TABLE IF NOT EXISTS family_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, event_name TEXT,
    event_type TEXT DEFAULT 'birth', event_date DATE, location TEXT,
    description TEXT, member_ids TEXT DEFAULT '[]', media_urls TEXT DEFAULT '[]',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS genealogy_sources (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, member_id INTEGER,
    source_type TEXT DEFAULT 'document', title TEXT, description TEXT,
    url TEXT, repository TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/genealogy/members', requireAuth, (req: any, res: any) => {
  const { search, is_living } = req.query as any;
  let q = `SELECT * FROM family_members WHERE user_id=?`;
  const p: any[] = [req.user.id];
  if (is_living !== undefined) { q += ` AND is_living=?`; p.push(is_living==='true'?1:0); }
  if (search) { q += ` AND (first_name LIKE ? OR last_name LIKE ? OR maiden_name LIKE ?)`; p.push(`%${search}%`, `%${search}%`, `%${search}%`); }
  q += ` ORDER BY last_name, first_name`;
  res.json({ members: db.prepare(q).all(...p) });
});
app.post('/api/genealogy/members', requireAuth, (req: any, res: any) => {
  const { first_name, last_name, maiden_name, date_of_birth, date_of_death, gender, birth_place, death_place, occupation, bio, is_living } = req.body;
  if (!first_name || !last_name) return res.status(400).json({ error: 'first_name and last_name required' });
  const r = db.prepare(`INSERT INTO family_members (user_id,first_name,last_name,maiden_name,date_of_birth,date_of_death,gender,birth_place,death_place,occupation,bio,is_living) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, first_name, last_name, maiden_name||'', date_of_birth||null, date_of_death||null, gender||'', birth_place||'', death_place||'', occupation||'', bio||'', is_living!==false?1:0);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/genealogy/relationships', requireAuth, (req: any, res: any) => {
  const { member_id, related_member_id, relationship_type } = req.body;
  if (!member_id || !related_member_id || !relationship_type) return res.status(400).json({ error: 'member_id, related_member_id, relationship_type required' });
  try {
    const r = db.prepare(`INSERT INTO family_relationships (user_id,member_id,related_member_id,relationship_type) VALUES (?,?,?,?)`).run(req.user.id, member_id, related_member_id, relationship_type);
    res.json({ id: r.lastInsertRowid });
  } catch(e: any) { res.json({ exists: true }); }
});
app.get('/api/genealogy/members/:id/tree', requireAuth, (req: any, res: any) => {
  const member = db.prepare(`SELECT * FROM family_members WHERE id=? AND user_id=?`).get(req.params.id, req.user.id);
  if (!member) return res.status(404).json({ error: 'not found' });
  const relationships = db.prepare(`SELECT fr.*, fm.first_name, fm.last_name, fm.date_of_birth FROM family_relationships fr JOIN family_members fm ON fm.id=fr.related_member_id WHERE fr.user_id=? AND fr.member_id=?`).all(req.user.id, req.params.id);
  const sources = db.prepare(`SELECT * FROM genealogy_sources WHERE user_id=? AND member_id=?`).all(req.user.id, req.params.id);
  res.json({ member, relationships, sources });
});
app.post('/api/genealogy/events', requireAuth, (req: any, res: any) => {
  const { event_name, event_type, event_date, location, description, member_ids } = req.body;
  if (!event_name || !event_date) return res.status(400).json({ error: 'event_name and event_date required' });
  const r = db.prepare(`INSERT INTO family_events (user_id,event_name,event_type,event_date,location,description,member_ids) VALUES (?,?,?,?,?,?,?)`).run(req.user.id, event_name, event_type||'birth', event_date, location||'', description||'', JSON.stringify(member_ids||[]));
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/genealogy/timeline', requireAuth, (req: any, res: any) => {
  const events = db.prepare(`SELECT * FROM family_events WHERE user_id=? ORDER BY event_date ASC`).all(req.user.id);
  const births = db.prepare(`SELECT id,first_name,last_name,date_of_birth FROM family_members WHERE user_id=? AND date_of_birth IS NOT NULL ORDER BY date_of_birth ASC`).all(req.user.id);
  res.json({ events, births, total_members: (births as any[]).length });
});
