// ─── B293: Freelance Project & Invoice Manager ───────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS freelance_clients (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, name TEXT,
    company TEXT, email TEXT, phone TEXT, address TEXT,
    payment_terms INTEGER DEFAULT 30, currency TEXT DEFAULT 'USD',
    hourly_rate REAL DEFAULT 0, notes TEXT, status TEXT DEFAULT 'active',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS freelance_projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT, client_id INTEGER, user_id INTEGER,
    name TEXT, description TEXT, project_type TEXT DEFAULT 'fixed',
    budget REAL DEFAULT 0, hourly_rate REAL DEFAULT 0, estimated_hours REAL DEFAULT 0,
    start_date DATE, deadline DATE, status TEXT DEFAULT 'active',
    total_logged_hours REAL DEFAULT 0, total_billed REAL DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS time_entries (
    id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER, user_id INTEGER,
    description TEXT, date DATE, hours REAL DEFAULT 0,
    is_billable INTEGER DEFAULT 1, is_billed INTEGER DEFAULT 0,
    hourly_rate REAL DEFAULT 0, amount REAL DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS freelance_invoices (
    id INTEGER PRIMARY KEY AUTOINCREMENT, client_id INTEGER, user_id INTEGER,
    invoice_number TEXT UNIQUE, project_id INTEGER, issue_date DATE,
    due_date DATE, subtotal REAL DEFAULT 0, tax_rate REAL DEFAULT 0,
    tax_amount REAL DEFAULT 0, total REAL DEFAULT 0, paid_amount REAL DEFAULT 0,
    status TEXT DEFAULT 'draft', notes TEXT, payment_date DATE,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/freelance/clients', requireAuth, (req: any, res: any) => {
  const clients = db.prepare(`SELECT c.*, COUNT(p.id) as project_count, SUM(p.total_billed) as lifetime_value FROM freelance_clients c LEFT JOIN freelance_projects p ON p.client_id=c.id AND p.user_id=c.user_id WHERE c.user_id=? GROUP BY c.id ORDER BY c.name ASC`).all(req.user.id);
  res.json({ clients });
});
app.post('/api/freelance/clients', requireAuth, (req: any, res: any) => {
  const { name, company, email, phone, address, payment_terms, currency, hourly_rate } = req.body;
  if (!name) return res.status(400).json({ error: 'name required' });
  const r = db.prepare(`INSERT INTO freelance_clients (user_id,name,company,email,phone,address,payment_terms,currency,hourly_rate) VALUES (?,?,?,?,?,?,?,?,?)`).run(req.user.id, name, company||'', email||'', phone||'', address||'', payment_terms||30, currency||'USD', hourly_rate||0);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/freelance/projects', requireAuth, (req: any, res: any) => {
  const { client_id, name, description, project_type, budget, hourly_rate, estimated_hours, start_date, deadline } = req.body;
  if (!client_id || !name) return res.status(400).json({ error: 'client_id and name required' });
  const r = db.prepare(`INSERT INTO freelance_projects (client_id,user_id,name,description,project_type,budget,hourly_rate,estimated_hours,start_date,deadline) VALUES (?,?,?,?,?,?,?,?,?,?)`).run(client_id, req.user.id, name, description||'', project_type||'fixed', budget||0, hourly_rate||0, estimated_hours||0, start_date||null, deadline||null);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/freelance/projects/:id/time', requireAuth, (req: any, res: any) => {
  const { description, date, hours, is_billable, hourly_rate } = req.body;
  if (!hours) return res.status(400).json({ error: 'hours required' });
  const proj = db.prepare(`SELECT hourly_rate FROM freelance_projects WHERE id=? AND user_id=?`).get(req.params.id, req.user.id) as any;
  const rate = hourly_rate || proj?.hourly_rate || 0;
  const amount = is_billable!==false ? hours * rate : 0;
  const r = db.prepare(`INSERT INTO time_entries (project_id,user_id,description,date,hours,is_billable,hourly_rate,amount) VALUES (?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, description||'', date||new Date().toISOString().slice(0,10), hours, is_billable!==false?1:0, rate, amount);
  db.prepare(`UPDATE freelance_projects SET total_logged_hours=total_logged_hours+? WHERE id=?`).run(hours, req.params.id);
  res.json({ id: r.lastInsertRowid, amount });
});
app.post('/api/freelance/invoices', requireAuth, (req: any, res: any) => {
  const { client_id, project_id, issue_date, due_date, subtotal, tax_rate, notes } = req.body;
  if (!client_id || !subtotal) return res.status(400).json({ error: 'client_id and subtotal required' });
  const year = new Date().getFullYear();
  const count = (db.prepare(`SELECT COUNT(*) as c FROM freelance_invoices WHERE user_id=? AND invoice_number LIKE ?`).get(req.user.id, `INV-${year}-%`) as any)?.c || 0;
  const invoice_number = `INV-${year}-${String(count+1).padStart(4,'0')}`;
  const tax_amount = subtotal * (tax_rate||0) / 100;
  const total = subtotal + tax_amount;
  const r = db.prepare(`INSERT INTO freelance_invoices (client_id,user_id,invoice_number,project_id,issue_date,due_date,subtotal,tax_rate,tax_amount,total,notes) VALUES (?,?,?,?,?,?,?,?,?,?,?)`).run(client_id, req.user.id, invoice_number, project_id||null, issue_date||new Date().toISOString().slice(0,10), due_date||'', subtotal, tax_rate||0, tax_amount, total, notes||'');
  res.json({ id: r.lastInsertRowid, invoice_number, total });
});
app.put('/api/freelance/invoices/:id/pay', requireAuth, (req: any, res: any) => {
  const { paid_amount, payment_date } = req.body;
  const inv = db.prepare(`SELECT total FROM freelance_invoices WHERE id=? AND user_id=?`).get(req.params.id, req.user.id) as any;
  if (!inv) return res.status(404).json({ error: 'not found' });
  const status = paid_amount >= inv.total ? 'paid' : 'partial';
  db.prepare(`UPDATE freelance_invoices SET paid_amount=?, payment_date=?, status=? WHERE id=?`).run(paid_amount||inv.total, payment_date||new Date().toISOString().slice(0,10), status, req.params.id);
  res.json({ success: true, status });
});
app.get('/api/freelance/revenue', requireAuth, (req: any, res: any) => {
  const ytd = db.prepare(`SELECT SUM(total) as billed, SUM(paid_amount) as collected FROM freelance_invoices WHERE user_id=? AND strftime('%Y',issue_date)=strftime('%Y','now')`).get(req.user.id) as any;
  const outstanding = db.prepare(`SELECT COUNT(*) as count, SUM(total-paid_amount) as amount FROM freelance_invoices WHERE user_id=? AND status IN ('sent','partial')`).get(req.user.id) as any;
  const top_clients = db.prepare(`SELECT c.name, SUM(i.total) as billed FROM freelance_invoices i JOIN freelance_clients c ON c.id=i.client_id WHERE i.user_id=? GROUP BY c.id ORDER BY billed DESC LIMIT 5`).all(req.user.id);
  res.json({ ytd, outstanding, top_clients });
});
// ─── End B293 ────────────────────────────────────────────────────────────────

