// ─── B295: AI Workflow & Automation Builder ───────────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS automation_workflows (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, name TEXT,
    description TEXT, trigger_type TEXT DEFAULT 'manual',
    trigger_config TEXT DEFAULT '{}', is_active INTEGER DEFAULT 1,
    run_count INTEGER DEFAULT 0, last_run_at DATETIME, last_run_status TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS workflow_steps (
    id INTEGER PRIMARY KEY AUTOINCREMENT, workflow_id INTEGER, user_id INTEGER,
    step_name TEXT, step_type TEXT DEFAULT 'action', action_type TEXT,
    config TEXT DEFAULT '{}', order_index INTEGER DEFAULT 0,
    on_error TEXT DEFAULT 'stop', created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS workflow_runs (
    id INTEGER PRIMARY KEY AUTOINCREMENT, workflow_id INTEGER, user_id INTEGER,
    started_at DATETIME DEFAULT CURRENT_TIMESTAMP, completed_at DATETIME,
    status TEXT DEFAULT 'running', steps_completed INTEGER DEFAULT 0,
    steps_failed INTEGER DEFAULT 0, output TEXT DEFAULT '{}',
    error_message TEXT, triggered_by TEXT DEFAULT 'manual'
  );
  CREATE TABLE IF NOT EXISTS workflow_variables (
    id INTEGER PRIMARY KEY AUTOINCREMENT, workflow_id INTEGER, user_id INTEGER,
    var_name TEXT, var_type TEXT DEFAULT 'string', default_value TEXT,
    description TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(workflow_id, var_name)
  );
`); } catch(e) {}

app.get('/api/automations', requireAuth, (req: any, res: any) => {
  const workflows = db.prepare(`SELECT w.*, (SELECT COUNT(*) FROM workflow_steps WHERE workflow_id=w.id) as step_count FROM automation_workflows w WHERE w.user_id=? ORDER BY w.created_at DESC`).all(req.user.id);
  res.json({ workflows });
});
app.post('/api/automations', requireAuth, (req: any, res: any) => {
  const { name, description, trigger_type, trigger_config } = req.body;
  if (!name) return res.status(400).json({ error: 'name required' });
  const r = db.prepare(`INSERT INTO automation_workflows (user_id,name,description,trigger_type,trigger_config) VALUES (?,?,?,?,?)`).run(req.user.id, name, description||'', trigger_type||'manual', JSON.stringify(trigger_config||{}));
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/automations/:id', requireAuth, (req: any, res: any) => {
  const workflow = db.prepare(`SELECT * FROM automation_workflows WHERE id=? AND user_id=?`).get(req.params.id, req.user.id);
  if (!workflow) return res.status(404).json({ error: 'not found' });
  const steps = db.prepare(`SELECT * FROM workflow_steps WHERE workflow_id=? ORDER BY order_index ASC`).all(req.params.id);
  const variables = db.prepare(`SELECT * FROM workflow_variables WHERE workflow_id=?`).all(req.params.id);
  const recent_runs = db.prepare(`SELECT * FROM workflow_runs WHERE workflow_id=? ORDER BY started_at DESC LIMIT 10`).all(req.params.id);
  res.json({ workflow, steps, variables, recent_runs });
});
app.post('/api/automations/:id/steps', requireAuth, (req: any, res: any) => {
  const { step_name, step_type, action_type, config, on_error } = req.body;
  if (!step_name || !action_type) return res.status(400).json({ error: 'step_name and action_type required' });
  const max = (db.prepare(`SELECT MAX(order_index) as m FROM workflow_steps WHERE workflow_id=?`).get(req.params.id) as any)?.m || 0;
  const r = db.prepare(`INSERT INTO workflow_steps (workflow_id,user_id,step_name,step_type,action_type,config,order_index,on_error) VALUES (?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, step_name, step_type||'action', action_type, JSON.stringify(config||{}), max+1, on_error||'stop');
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/automations/:id/run', requireAuth, (req: any, res: any) => {
  const { input_variables } = req.body;
  const workflow = db.prepare(`SELECT * FROM automation_workflows WHERE id=? AND user_id=? AND is_active=1`).get(req.params.id, req.user.id) as any;
  if (!workflow) return res.status(404).json({ error: 'workflow not found or inactive' });
  const steps = db.prepare(`SELECT * FROM workflow_steps WHERE workflow_id=? ORDER BY order_index ASC`).all(req.params.id) as any[];
  const run = db.prepare(`INSERT INTO workflow_runs (workflow_id,user_id,triggered_by) VALUES (?,?,'api')`).run(req.params.id, req.user.id);
  const runId = run.lastInsertRowid;
  // Simulate workflow execution
  let completed = 0; let failed = 0;
  for (const step of steps) {
    try { completed++; } catch(e) { failed++; if (step.on_error === 'stop') break; }
  }
  db.prepare(`UPDATE workflow_runs SET status=?, completed_at=CURRENT_TIMESTAMP, steps_completed=?, steps_failed=?, output=? WHERE id=?`).run(failed===0?'success':'partial', completed, failed, JSON.stringify({ input: input_variables||{}, steps_run: completed }), runId);
  db.prepare(`UPDATE automation_workflows SET run_count=run_count+1, last_run_at=CURRENT_TIMESTAMP, last_run_status=? WHERE id=?`).run(failed===0?'success':'partial', req.params.id);
  res.json({ run_id: runId, status: failed===0?'success':'partial', steps_completed: completed, steps_failed: failed });
});
app.put('/api/automations/:id/toggle', requireAuth, (req: any, res: any) => {
  const w = db.prepare(`SELECT is_active FROM automation_workflows WHERE id=? AND user_id=?`).get(req.params.id, req.user.id) as any;
  if (!w) return res.status(404).json({ error: 'not found' });
  db.prepare(`UPDATE automation_workflows SET is_active=? WHERE id=?`).run(w.is_active?0:1, req.params.id);
  res.json({ is_active: !w.is_active });
});
app.post('/api/automations/:id/variables', requireAuth, (req: any, res: any) => {
  const { var_name, var_type, default_value, description } = req.body;
  if (!var_name) return res.status(400).json({ error: 'var_name required' });
  try {
    const r = db.prepare(`INSERT INTO workflow_variables (workflow_id,user_id,var_name,var_type,default_value,description) VALUES (?,?,?,?,?,?)`).run(req.params.id, req.user.id, var_name, var_type||'string', default_value||'', description||'');
    res.json({ id: r.lastInsertRowid });
  } catch(e: any) { res.status(409).json({ error: 'variable already exists' }); }
});
app.get('/api/automations/:id/runs', requireAuth, (req: any, res: any) => {
  const runs = db.prepare(`SELECT * FROM workflow_runs WHERE workflow_id=? AND user_id=? ORDER BY started_at DESC LIMIT 50`).all(req.params.id, req.user.id) as any[];
  const success_rate = runs.length ? Math.round((runs.filter((r: any) => r.status==='success').length / runs.length) * 100) : 0;
  res.json({ runs, success_rate });
});
