app.get('/api/escape-rooms/stats', requireAuth, (req: any, res: any) => {
  const total = db.prepare(`SELECT COUNT(*) as rooms, SUM(escaped) as escaped FROM escape_attempts WHERE user_id=?`).get(req.user.id) as any;
  const escape_rate = total?.rooms ? Math.round((total.escaped / total.rooms) * 100) : 0;
  const best = db.prepare(`SELECT er.room_name, ev.venue_name, ea.time_used_minutes FROM escape_attempts ea JOIN escape_rooms er ON er.id=ea.room_id JOIN escape_venues ev ON ev.id=er.venue_id WHERE ea.user_id=? AND ea.escaped=1 ORDER BY ea.time_used_minutes ASC LIMIT 1`).get(req.user.id);
  const recent = db.prepare(`SELECT er.room_name, ev.venue_name, ea.escaped, ea.played_date FROM escape_attempts ea JOIN escape_rooms er ON er.id=ea.room_id JOIN escape_venues ev ON ev.id=er.venue_id WHERE ea.user_id=? ORDER BY ea.played_date DESC LIMIT 5`).all(req.user.id);
  res.json({ total_attempts: total?.rooms||0, total_escaped: total?.escaped||0, escape_rate, fastest_escape: best, recent });
});
