app.get('/api/meditation/stats', requireAuth, (req: any, res: any) => {
  const stats = db.prepare(`SELECT COUNT(*) as total_sessions, SUM(duration_minutes) as total_minutes, AVG(duration_minutes) as avg_duration, AVG(mood_after - mood_before) as avg_mood_lift, MAX(session_date) as last_session FROM meditation_sessions_v2 WHERE user_id=?`).get(req.user.id) as any;
  const this_month = db.prepare(`SELECT COUNT(*) as sessions, SUM(duration_minutes) as minutes FROM meditation_sessions_v2 WHERE user_id=? AND strftime('%Y-%m',session_date)=strftime('%Y-%m','now')`).get(req.user.id) as any;
  const streak = (() => {
    const dates = (db.prepare(`SELECT DISTINCT session_date FROM meditation_sessions_v2 WHERE user_id=? ORDER BY session_date DESC LIMIT 365`).all(req.user.id) as any[]).map((r: any) => r.session_date);
    let s = 0; const today = new Date().toISOString().slice(0,10);
    for (let i = 0; i < dates.length; i++) {
      const expected = new Date(); expected.setDate(expected.getDate() - i);
      if (dates[i] === expected.toISOString().slice(0,10)) s++; else break;
    }
    return s;
  })();
  const by_technique = db.prepare(`SELECT technique, COUNT(*) as count, SUM(duration_minutes) as minutes FROM meditation_sessions_v2 WHERE user_id=? GROUP BY technique ORDER BY count DESC`).all(req.user.id);
  res.json({ stats, this_month, streak_days: streak, by_technique });
});
