app.post('/api/feedback/forms/:code/respond', (req: any, res: any) => {
  const form = db.prepare(`SELECT id,user_id FROM feedback_forms WHERE access_code=? AND is_active=1`).get(req.params.code) as any;
  if (!form) return res.status(404).json({ error: 'form not found' });
  const { respondent_email, respondent_name, answers, overall_rating, source } = req.body;
  const sentiment = overall_rating >= 4 ? 'positive' : overall_rating <= 2 ? 'negative' : 'neutral';
  db.prepare(`INSERT INTO feedback_responses_v2 (form_id,user_id,respondent_email,respondent_name,answers,overall_rating,source,sentiment) VALUES (?,?,?,?,?,?,?,?)`).run(form.id, form.user_id, respondent_email||'', respondent_name||'', JSON.stringify(answers||{}), overall_rating||0, source||'direct', sentiment);
  db.prepare(`UPDATE feedback_forms SET total_responses=total_responses+1 WHERE id=?`).run(form.id);
  res.json({ success: true });
});
app.get('/api/feedback/forms/:id/results', requireAuth, (req: any, res: any) => {
  const form = db.prepare(`SELECT * FROM feedback_forms WHERE id=? AND user_id=?`).get(req.params.id, req.user.id);
  if (!form) return res.status(404).json({ error: 'not found' });
  const responses = db.prepare(`SELECT * FROM feedback_responses_v2 WHERE form_id=? ORDER BY submitted_at DESC`).all(req.params.id) as any[];
  const avg_rating = responses.length ? responses.reduce((s: number, r: any) => s + r.overall_rating, 0) / responses.length : 0;
  const sentiment_breakdown = { positive: 0, neutral: 0, negative: 0 } as any;
  responses.forEach((r: any) => sentiment_breakdown[r.sentiment]++);
  res.json({ form, responses, avg_rating: Math.round(avg_rating * 10) / 10, sentiment_breakdown });
});
app.post('/api/nps/campaigns', requireAuth, (req: any, res: any) => {
  const { campaign_name, question } = req.body;
  if (!campaign_name) return res.status(400).json({ error: 'campaign_name required' });
  const code = Math.random().toString(36).substring(2, 10);
  const r = db.prepare(`INSERT INTO nps_campaigns (user_id,campaign_name,question,access_code) VALUES (?,?,?,?)`).run(req.user.id, campaign_name, question||'How likely are you to recommend us to a friend or colleague?', code);
  res.json({ id: r.lastInsertRowid, access_code: code });
});
app.post('/api/nps/:code/respond', (req: any, res: any) => {
  const c = db.prepare(`SELECT id,user_id FROM nps_campaigns WHERE access_code=? AND is_active=1`).get(req.params.code) as any;
  if (!c) return res.status(404).json({ error: 'campaign not found' });
  const { score, reason, respondent_email } = req.body;
  if (score === undefined || score < 0 || score > 10) return res.status(400).json({ error: 'score must be 0-10' });
  const segment = score >= 9 ? 'promoter' : score >= 7 ? 'passive' : 'detractor';
  db.prepare(`INSERT INTO nps_responses (campaign_id,user_id,score,reason,respondent_email,segment) VALUES (?,?,?,?,?,?)`).run(c.id, c.user_id, score, reason||'', respondent_email||'', segment);
  const field = segment === 'promoter' ? 'promoters' : segment === 'passive' ? 'passives' : 'detractors';
  db.prepare(`UPDATE nps_campaigns SET total_responses=total_responses+1, ${field}=${field}+1 WHERE id=?`).run(c.id);
  const camp = db.prepare(`SELECT promoters,passives,detractors,total_responses FROM nps_campaigns WHERE id=?`).get(c.id) as any;
  const nps = camp.total_responses ? Math.round(((camp.promoters - camp.detractors) / camp.total_responses) * 100) : 0;
  db.prepare(`UPDATE nps_campaigns SET nps_score=? WHERE id=?`).run(nps, c.id);
  res.json({ success: true, segment });
});
app.get('/api/nps/campaigns', requireAuth, (req: any, res: any) => {
  res.json({ campaigns: db.prepare(`SELECT * FROM nps_campaigns WHERE user_id=? ORDER BY created_at DESC`).all(req.user.id) });
});
