  const suppliers = db.prepare(`SELECT s.*, COUNT(po.id) as po_count, SUM(po.total) as total_spent FROM suppliers s LEFT JOIN purchase_orders po ON po.supplier_id=s.id WHERE s.user_id=? GROUP BY s.id ORDER BY s.name ASC`).all(req.user.id);
  res.json({ suppliers });
