  const { content_url, reach, impressions, clicks, conversions } = req.body;
  db.prepare(`UPDATE collab_deliverables SET status='submitted', content_url=COALESCE(?,content_url), submitted_date=date('now'), reach=?, impressions=?, clicks=?, conversions=? WHERE id=? AND user_id=?`).run(content_url, reach||0, impressions||0, clicks||0, conversions||0, req.params.id, req.user.id);
