  const r = db.prepare(`INSERT INTO practice_sessions_v2 (instrument_id,user_id,session_date,duration_minutes,focus_areas,bpm_practiced,mood,quality,notes,pieces_practiced) VALUES (?,?,?,?,?,?,?,?,?,?)`).run(instrument_id, req.user.id, session_date||new Date().toISOString().slice(0,10), duration_minutes, JSON.stringify(focus_areas||[]), bpm_practiced||0, mood||5, quality||5, notes||'', JSON.stringify(pieces_practiced||[]));
