  if (!study_id || !scheduled_date) return res.status(400).json({ error: 'study_id and scheduled_date required' });
  const r = db.prepare(`INSERT INTO study_visits (participant_id,study_id,user_id,visit_number,visit_type,scheduled_date) VALUES (?,?,?,?,?,?)`).run(req.params.id, study_id, req.user.id, visit_number||1, visit_type||'follow_up', scheduled_date);
