  db.prepare(`UPDATE study_visits SET status='completed', actual_date=date('now'), assessments_completed=?, adverse_events=?, notes=? WHERE id=? AND user_id=?`).run(JSON.stringify(assessments_completed||[]), adverse_events||'none', notes||'', req.params.id, req.user.id);
