app.get('/api/research/studies/:id/summary', requireAuth, (req: any, res: any) => {
  const study = db.prepare(`SELECT * FROM research_studies WHERE id=? AND user_id=?`).get(req.params.id, req.user.id) as any;
  if (!study) return res.status(404).json({ error: 'not found' });
  const enrollment_rate = study.target_enrollment ? Math.round((study.enrolled_count / study.target_enrollment) * 100) : 0;
  const by_arm = db.prepare(`SELECT arm, COUNT(*) as count FROM study_participants WHERE study_id=? AND status='active' GROUP BY arm`).all(req.params.id);
  const data_points = db.prepare(`SELECT COUNT(*) as count FROM study_data_points WHERE study_id=?`).get(req.params.id) as any;
  res.json({ study, enrollment_rate, by_arm, data_points_collected: data_points?.count||0 });
});
