  const r = db.prepare(`INSERT INTO aquarium_fish (aquarium_id,user_id,species,common_name,quantity,acquired_date,acquired_from,gender,age_months) VALUES (?,?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, species, common_name||species, quantity||1, acquired_date||new Date().toISOString().slice(0,10), acquired_from||'', gender||'unknown', age_months||0);
  res.json({ id: r.lastInsertRowid });
