app.post('/api/aquariums/:id/water-test', requireAuth, (req: any, res: any) => {
  const { test_date, temperature_f, ph, ammonia_ppm, nitrite_ppm, nitrate_ppm, gh, kh, tds, notes } = req.body;
  const r = db.prepare(`INSERT INTO water_tests (aquarium_id,user_id,test_date,temperature_f,ph,ammonia_ppm,nitrite_ppm,nitrate_ppm,gh,kh,tds,notes) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, test_date||new Date().toISOString().slice(0,10), temperature_f||null, ph||null, ammonia_ppm||0, nitrite_ppm||0, nitrate_ppm||0, gh||0, kh||0, tds||0, notes||'');
  const alerts: string[] = [];
  if ((ammonia_ppm||0) > 0) alerts.push('High ammonia detected!');
  if ((nitrite_ppm||0) > 0.25) alerts.push('Nitrite elevated!');
  if ((nitrate_ppm||0) > 40) alerts.push('Nitrate too high — water change recommended');
  res.json({ id: r.lastInsertRowid, alerts });
});
app.get('/api/aquariums/:id/history', requireAuth, (req: any, res: any) => {
  const tests = db.prepare(`SELECT * FROM water_tests WHERE aquarium_id=? AND user_id=? ORDER BY test_date DESC LIMIT 30`).all(req.params.id, req.user.id);
  const maintenance = db.prepare(`SELECT * FROM tank_maintenance WHERE aquarium_id=? AND user_id=? ORDER BY maintenance_date DESC LIMIT 20`).all(req.params.id, req.user.id);
  res.json({ water_tests: tests, maintenance });
});
