// ─── B313: Legal Expense & Case Cost Tracker ─────────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS legal_matters (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, matter_name TEXT,
    matter_type TEXT DEFAULT 'civil', case_number TEXT, court TEXT,
    opposing_party TEXT, attorney_name TEXT, attorney_email TEXT, law_firm TEXT,
    retainer_paid REAL DEFAULT 0, retainer_remaining REAL DEFAULT 0,
    hourly_rate REAL DEFAULT 0, flat_fee REAL DEFAULT 0,
    status TEXT DEFAULT 'active', key_dates TEXT DEFAULT '{}',
    outcome TEXT, notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS legal_billing_entries (
    id INTEGER PRIMARY KEY AUTOINCREMENT, matter_id INTEGER, user_id INTEGER,
    entry_date DATE, description TEXT, hours REAL DEFAULT 0,
    rate REAL DEFAULT 0, amount REAL DEFAULT 0, expense_type TEXT DEFAULT 'attorney',
    is_billable INTEGER DEFAULT 1, invoice_number TEXT, status TEXT DEFAULT 'pending',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS legal_deadlines (
    id INTEGER PRIMARY KEY AUTOINCREMENT, matter_id INTEGER, user_id INTEGER,
    deadline_name TEXT, due_date DATE, description TEXT, is_court_deadline INTEGER DEFAULT 0,
    status TEXT DEFAULT 'pending', reminder_days_before INTEGER DEFAULT 7,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS legal_communications (
    id INTEGER PRIMARY KEY AUTOINCREMENT, matter_id INTEGER, user_id INTEGER,
    comm_date DATE, comm_type TEXT DEFAULT 'email', with_whom TEXT,
    summary TEXT, follow_up_needed INTEGER DEFAULT 0, follow_up_date DATE,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/legal-matters', requireAuth, (req: any, res: any) => {
  const matters = db.prepare(`SELECT m.*, (SELECT SUM(amount) FROM legal_billing_entries WHERE matter_id=m.id) as total_spent, (SELECT COUNT(*) FROM legal_deadlines WHERE matter_id=m.id AND status='pending' AND due_date >= date('now')) as upcoming_deadlines FROM legal_matters m WHERE m.user_id=? ORDER BY m.created_at DESC`).all(req.user.id);
  res.json({ matters });
});
app.post('/api/legal-matters', requireAuth, (req: any, res: any) => {
  const { matter_name, matter_type, case_number, court, opposing_party, attorney_name, attorney_email, law_firm, retainer_paid, hourly_rate, flat_fee } = req.body;
  if (!matter_name) return res.status(400).json({ error: 'matter_name required' });
  const r = db.prepare(`INSERT INTO legal_matters (user_id,matter_name,matter_type,case_number,court,opposing_party,attorney_name,attorney_email,law_firm,retainer_paid,retainer_remaining,hourly_rate,flat_fee) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, matter_name, matter_type||'civil', case_number||'', court||'', opposing_party||'', attorney_name||'', attorney_email||'', law_firm||'', retainer_paid||0, retainer_paid||0, hourly_rate||0, flat_fee||0);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/legal-matters/:id/billing', requireAuth, (req: any, res: any) => {
  const { entry_date, description, hours, rate, amount, expense_type, invoice_number } = req.body;
  if (!description) return res.status(400).json({ error: 'description required' });
  const total = amount || (hours||0) * (rate||0);
  const r = db.prepare(`INSERT INTO legal_billing_entries (matter_id,user_id,entry_date,description,hours,rate,amount,expense_type,invoice_number) VALUES (?,?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, entry_date||new Date().toISOString().slice(0,10), description, hours||0, rate||0, total, expense_type||'attorney', invoice_number||'');
  db.prepare(`UPDATE legal_matters SET retainer_remaining=MAX(0,retainer_remaining-?) WHERE id=?`).run(total, req.params.id);
  res.json({ id: r.lastInsertRowid, amount: total });
});
app.get('/api/legal-matters/:id/summary', requireAuth, (req: any, res: any) => {
  const matter = db.prepare(`SELECT * FROM legal_matters WHERE id=? AND user_id=?`).get(req.params.id, req.user.id) as any;
  if (!matter) return res.status(404).json({ error: 'not found' });
  const billing = db.prepare(`SELECT SUM(amount) as total, SUM(hours) as total_hours, COUNT(*) as entries FROM legal_billing_entries WHERE matter_id=? AND user_id=?`).get(req.params.id, req.user.id) as any;
  const upcoming = db.prepare(`SELECT * FROM legal_deadlines WHERE matter_id=? AND status='pending' AND due_date >= date('now') ORDER BY due_date ASC LIMIT 5`).all(req.params.id);
  const by_type = db.prepare(`SELECT expense_type, SUM(amount) as total FROM legal_billing_entries WHERE matter_id=? GROUP BY expense_type`).all(req.params.id);
  res.json({ matter, billing, upcoming_deadlines: upcoming, breakdown: by_type });
});
app.post('/api/legal-matters/:id/deadlines', requireAuth, (req: any, res: any) => {
  const { deadline_name, due_date, description, is_court_deadline, reminder_days_before } = req.body;
  if (!deadline_name || !due_date) return res.status(400).json({ error: 'deadline_name and due_date required' });
  const r = db.prepare(`INSERT INTO legal_deadlines (matter_id,user_id,deadline_name,due_date,description,is_court_deadline,reminder_days_before) VALUES (?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, deadline_name, due_date, description||'', is_court_deadline?1:0, reminder_days_before||7);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/legal-matters/:id/comms', requireAuth, (req: any, res: any) => {
  const { comm_date, comm_type, with_whom, summary, follow_up_needed, follow_up_date } = req.body;
  if (!summary) return res.status(400).json({ error: 'summary required' });
  const r = db.prepare(`INSERT INTO legal_communications (matter_id,user_id,comm_date,comm_type,with_whom,summary,follow_up_needed,follow_up_date) VALUES (?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, comm_date||new Date().toISOString().slice(0,10), comm_type||'email', with_whom||'', summary, follow_up_needed?1:0, follow_up_date||null);
  res.json({ id: r.lastInsertRowid });
});
