try { db.exec(`
  CREATE TABLE IF NOT EXISTS drones (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, name TEXT,
    model TEXT, manufacturer TEXT, drone_type TEXT DEFAULT 'quad',
    weight_grams REAL DEFAULT 0, max_speed_mph REAL DEFAULT 0,
    max_range_ft INTEGER DEFAULT 0, battery_life_minutes INTEGER DEFAULT 20,
    camera TEXT, purchase_date DATE, purchase_price REAL DEFAULT 0,
    registration_number TEXT, registration_expiry DATE,
    status TEXT DEFAULT 'airworthy', notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS flight_logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT, drone_id INTEGER, user_id INTEGER,
    flight_date DATE, location TEXT, latitude REAL DEFAULT 0, longitude REAL DEFAULT 0,
    duration_minutes INTEGER DEFAULT 0, max_altitude_ft INTEGER DEFAULT 0,
    max_speed_mph REAL DEFAULT 0, distance_miles REAL DEFAULT 0,
    purpose TEXT DEFAULT 'recreational', weather TEXT, wind_mph INTEGER DEFAULT 0,
    incidents TEXT, battery_start_pct INTEGER DEFAULT 100, battery_end_pct INTEGER DEFAULT 20,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS drone_batteries (
    id INTEGER PRIMARY KEY AUTOINCREMENT, drone_id INTEGER, user_id INTEGER,
    battery_name TEXT, capacity_mah INTEGER DEFAULT 0, voltage REAL DEFAULT 0,
    cycle_count INTEGER DEFAULT 0, max_cycles INTEGER DEFAULT 200,
    condition TEXT DEFAULT 'good', purchase_date DATE, notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS drone_maintenance (
    id INTEGER PRIMARY KEY AUTOINCREMENT, drone_id INTEGER, user_id INTEGER,
    maintenance_date DATE, maintenance_type TEXT DEFAULT 'inspection',
    description TEXT, cost REAL DEFAULT 0, next_due_date DATE,
    technician TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/drones', requireAuth, (req: any, res: any) => {
  const drones = db.prepare(`SELECT d.*, COUNT(f.id) as total_flights, COALESCE(SUM(f.duration_minutes),0) as total_flight_minutes FROM drones d LEFT JOIN flight_logs f ON f.drone_id=d.id AND f.user_id=d.user_id WHERE d.user_id=? GROUP BY d.id ORDER BY d.name ASC`).all(req.user.id);
  res.json({ drones });
});
app.post('/api/drones', requireAuth, (req: any, res: any) => {
  const { name, model, manufacturer, drone_type, weight_grams, max_speed_mph, max_range_ft, battery_life_minutes, camera, purchase_date, purchase_price, registration_number, registration_expiry } = req.body;
  if (!name) return res.status(400).json({ error: 'name required' });
  const r = db.prepare(`INSERT INTO drones (user_id,name,model,manufacturer,drone_type,weight_grams,max_speed_mph,max_range_ft,battery_life_minutes,camera,purchase_date,purchase_price,registration_number,registration_expiry) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, name, model||'', manufacturer||'', drone_type||'quad', weight_grams||0, max_speed_mph||0, max_range_ft||0, battery_life_minutes||20, camera||'', purchase_date||null, purchase_price||0, registration_number||'', registration_expiry||null);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/drones/:id/flights', requireAuth, (req: any, res: any) => {
  const { flight_date, location, duration_minutes, max_altitude_ft, max_speed_mph, distance_miles, purpose, weather, wind_mph, incidents, battery_start_pct, battery_end_pct, notes } = req.body;
  if (!location) return res.status(400).json({ error: 'location required' });
  const r = db.prepare(`INSERT INTO flight_logs (drone_id,user_id,flight_date,location,duration_minutes,max_altitude_ft,max_speed_mph,distance_miles,purpose,weather,wind_mph,incidents,battery_start_pct,battery_end_pct,notes) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, flight_date||new Date().toISOString().slice(0,10), location, duration_minutes||0, max_altitude_ft||0, max_speed_mph||0, distance_miles||0, purpose||'recreational', weather||'', wind_mph||0, incidents||'', battery_start_pct||100, battery_end_pct||20, notes||'');
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/drones/:id/logbook', requireAuth, (req: any, res: any) => {
  const flights = db.prepare(`SELECT * FROM flight_logs WHERE drone_id=? AND user_id=? ORDER BY flight_date DESC`).all(req.params.id, req.user.id) as any[];
  const stats = { total_flights: flights.length, total_minutes: flights.reduce((s: number, f: any) => s + f.duration_minutes, 0), total_miles: Math.round(flights.reduce((s: number, f: any) => s + f.distance_miles, 0) * 10) / 10, max_altitude: Math.max(...flights.map((f: any) => f.max_altitude_ft), 0) };
  res.json({ flights, stats });
});
app.post('/api/drones/:id/maintenance', requireAuth, (req: any, res: any) => {
  const { maintenance_date, maintenance_type, description, cost, next_due_date, technician } = req.body;
  if (!description) return res.status(400).json({ error: 'description required' });
  const r = db.prepare(`INSERT INTO drone_maintenance (drone_id,user_id,maintenance_date,maintenance_type,description,cost,next_due_date,technician) VALUES (?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, maintenance_date||new Date().toISOString().slice(0,10), maintenance_type||'inspection', description, cost||0, next_due_date||null, technician||'self');
  res.json({ id: r.lastInsertRowid });
});
