// ─── B320: Personal Carbon Footprint Tracker ─────────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS carbon_profile (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER UNIQUE,
    country TEXT DEFAULT 'US', household_size INTEGER DEFAULT 1,
    annual_baseline_kg REAL DEFAULT 10000,
    reduction_goal_pct INTEGER DEFAULT 20, goal_year INTEGER DEFAULT 2026,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS carbon_entries (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER,
    entry_date DATE, category TEXT DEFAULT 'transport',
    subcategory TEXT, description TEXT, quantity REAL DEFAULT 0,
    unit TEXT DEFAULT 'miles', co2_kg REAL DEFAULT 0,
    offset INTEGER DEFAULT 0, notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS carbon_offsets (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER,
    offset_date DATE, provider TEXT, project_name TEXT,
    amount_kg REAL DEFAULT 0, cost_usd REAL DEFAULT 0, certificate_url TEXT,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS carbon_goals (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, goal_name TEXT,
    category TEXT, target_reduction_kg REAL DEFAULT 0,
    start_date DATE, end_date DATE, status TEXT DEFAULT 'active', notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

const CO2_FACTORS: Record<string, number> = {
  car_gasoline: 0.404, car_electric: 0.1, flight_short: 0.255, flight_long: 0.195,
  train: 0.041, bus: 0.089, natural_gas_therm: 5.307, electricity_kwh: 0.386,
  beef_kg: 27, chicken_kg: 6.9, pork_kg: 12, dairy_kg: 3.2,
  streaming_hr: 0.036, ecommerce_package: 0.5
};
app.post('/api/carbon/profile', requireAuth, (req: any, res: any) => {
  const { country, household_size, annual_baseline_kg, reduction_goal_pct, goal_year } = req.body;
  const ex = db.prepare(`SELECT id FROM carbon_profile WHERE user_id=?`).get(req.user.id);
  if (ex) { db.prepare(`UPDATE carbon_profile SET country=COALESCE(?,country), household_size=COALESCE(?,household_size), annual_baseline_kg=COALESCE(?,annual_baseline_kg), reduction_goal_pct=COALESCE(?,reduction_goal_pct) WHERE user_id=?`).run(country, household_size, annual_baseline_kg, reduction_goal_pct, req.user.id); return res.json({ updated: true }); }
  const r = db.prepare(`INSERT INTO carbon_profile (user_id,country,household_size,annual_baseline_kg,reduction_goal_pct,goal_year) VALUES (?,?,?,?,?,?)`).run(req.user.id, country||'US', household_size||1, annual_baseline_kg||10000, reduction_goal_pct||20, goal_year||2026);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/carbon/entries', requireAuth, (req: any, res: any) => {
  const { entry_date, category, subcategory, description, quantity, unit, co2_kg_override, notes } = req.body;
  if (!category) return res.status(400).json({ error: 'category required' });
  const factor = CO2_FACTORS[subcategory] || 0.3;
  const co2_kg = co2_kg_override || (quantity||0) * factor;
  const r = db.prepare(`INSERT INTO carbon_entries (user_id,entry_date,category,subcategory,description,quantity,unit,co2_kg,notes) VALUES (?,?,?,?,?,?,?,?,?)`).run(req.user.id, entry_date||new Date().toISOString().slice(0,10), category, subcategory||'', description||'', quantity||0, unit||'', Math.round(co2_kg * 100) / 100, notes||'');
  res.json({ id: r.lastInsertRowid, co2_kg: Math.round(co2_kg * 100) / 100 });
});
app.get('/api/carbon/dashboard', requireAuth, (req: any, res: any) => {
  const { days = 365 } = req.query as any;
  const entries = db.prepare(`SELECT * FROM carbon_entries WHERE user_id=? AND entry_date >= date('now',?) ORDER BY entry_date DESC`).all(req.user.id, `-${days} days`) as any[];
  const offsets = db.prepare(`SELECT SUM(amount_kg) as total FROM carbon_offsets WHERE user_id=? AND offset_date >= date('now',?)`).get(req.user.id, `-${days} days`) as any;
  const total_co2 = Math.round(entries.reduce((s: number, e: any) => s + e.co2_kg, 0) * 10) / 10;
  const total_offset = Math.round((offsets?.total||0) * 10) / 10;
  const by_category: Record<string, number> = {};
  entries.forEach((e: any) => { by_category[e.category] = (by_category[e.category]||0) + e.co2_kg; });
  res.json({ total_co2_kg: total_co2, total_offset_kg: total_offset, net_co2_kg: Math.round((total_co2 - total_offset) * 10) / 10, by_category, entries_count: entries.length });
});
app.post('/api/carbon/offsets', requireAuth, (req: any, res: any) => {
  const { offset_date, provider, project_name, amount_kg, cost_usd, certificate_url } = req.body;
  if (!amount_kg) return res.status(400).json({ error: 'amount_kg required' });
  const r = db.prepare(`INSERT INTO carbon_offsets (user_id,offset_date,provider,project_name,amount_kg,cost_usd,certificate_url) VALUES (?,?,?,?,?,?,?)`).run(req.user.id, offset_date||new Date().toISOString().slice(0,10), provider||'', project_name||'', amount_kg, cost_usd||0, certificate_url||'');
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/carbon/factors', requireAuth, (_req: any, res: any) => {
  res.json({ factors: CO2_FACTORS, unit_note: 'kg CO2 per unit (miles, kWh, kg food, hour, package)' });
});
// ─── End B320 ────────────────────────────────────────────────────────────────

// ─── B321: Home Automation & Smart Device Hub ─────────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS smart_devices (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, device_name TEXT,
    device_type TEXT DEFAULT 'light', brand TEXT, model TEXT, room TEXT,
    ip_address TEXT, mac_address TEXT, is_online INTEGER DEFAULT 1,
    current_state TEXT DEFAULT '{}', created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS device_automations (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, automation_name TEXT,
    trigger_type TEXT DEFAULT 'schedule', trigger_value TEXT,
    action_device_id INTEGER, action_type TEXT, action_value TEXT DEFAULT '{}',
    is_active INTEGER DEFAULT 1, last_triggered DATETIME,
    run_count INTEGER DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS device_logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT, device_id INTEGER, user_id INTEGER,
    log_time DATETIME DEFAULT CURRENT_TIMESTAMP, event_type TEXT DEFAULT 'state_change',
    old_state TEXT, new_state TEXT, triggered_by TEXT DEFAULT 'manual'
  );
  CREATE TABLE IF NOT EXISTS energy_readings (
    id INTEGER PRIMARY KEY AUTOINCREMENT, device_id INTEGER, user_id INTEGER,
    reading_date DATE, kwh_consumed REAL DEFAULT 0, peak_watts REAL DEFAULT 0,
    cost_usd REAL DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/smarthome/devices', requireAuth, (req: any, res: any) => {
  const { room } = req.query as any;
  let q = `SELECT d.*, (SELECT COUNT(*) FROM device_logs WHERE device_id=d.id AND DATE(log_time)=DATE('now')) as events_today FROM smart_devices d WHERE d.user_id=?`;
  const params: any[] = [req.user.id];
  if (room) { q += ` AND d.room=?`; params.push(room); }
  q += ` ORDER BY d.room, d.device_name ASC`;
  const devices = db.prepare(q).all(...params);
  const rooms = [...new Set((devices as any[]).map((d: any) => d.room))];
  res.json({ devices, rooms });
});
app.post('/api/smarthome/devices', requireAuth, (req: any, res: any) => {
  const { device_name, device_type, brand, model, room, ip_address, mac_address } = req.body;
  if (!device_name) return res.status(400).json({ error: 'device_name required' });
  const r = db.prepare(`INSERT INTO smart_devices (user_id,device_name,device_type,brand,model,room,ip_address,mac_address) VALUES (?,?,?,?,?,?,?,?)`).run(req.user.id, device_name, device_type||'light', brand||'', model||'', room||'Living Room', ip_address||'', mac_address||'');
  res.json({ id: r.lastInsertRowid });
});
app.put('/api/smarthome/devices/:id/state', requireAuth, (req: any, res: any) => {
  const { state, triggered_by } = req.body;
  const device = db.prepare(`SELECT current_state FROM smart_devices WHERE id=? AND user_id=?`).get(req.params.id, req.user.id) as any;
  if (!device) return res.status(404).json({ error: 'not found' });
  const new_state = JSON.stringify({ ...JSON.parse(device.current_state||'{}'), ...state });
  db.prepare(`UPDATE smart_devices SET current_state=?, is_online=1 WHERE id=? AND user_id=?`).run(new_state, req.params.id, req.user.id);
  db.prepare(`INSERT INTO device_logs (device_id,user_id,event_type,old_state,new_state,triggered_by) VALUES (?,?,?,?,?,?)`).run(req.params.id, req.user.id, 'state_change', device.current_state, new_state, triggered_by||'manual');
  res.json({ success: true, new_state: JSON.parse(new_state) });
});
app.post('/api/smarthome/automations', requireAuth, (req: any, res: any) => {
  const { automation_name, trigger_type, trigger_value, action_device_id, action_type, action_value } = req.body;
  if (!automation_name) return res.status(400).json({ error: 'automation_name required' });
  const r = db.prepare(`INSERT INTO device_automations (user_id,automation_name,trigger_type,trigger_value,action_device_id,action_type,action_value) VALUES (?,?,?,?,?,?,?)`).run(req.user.id, automation_name, trigger_type||'schedule', trigger_value||'', action_device_id||null, action_type||'set_state', JSON.stringify(action_value||{}));
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/smarthome/automations', requireAuth, (req: any, res: any) => {
  res.json({ automations: db.prepare(`SELECT a.*, d.device_name FROM device_automations a LEFT JOIN smart_devices d ON d.id=a.action_device_id WHERE a.user_id=? ORDER BY a.automation_name ASC`).all(req.user.id) });
});
app.post('/api/smarthome/energy', requireAuth, (req: any, res: any) => {
  const { device_id, reading_date, kwh_consumed, peak_watts, cost_usd } = req.body;
  const r = db.prepare(`INSERT INTO energy_readings (device_id,user_id,reading_date,kwh_consumed,peak_watts,cost_usd) VALUES (?,?,?,?,?,?)`).run(device_id, req.user.id, reading_date||new Date().toISOString().slice(0,10), kwh_consumed||0, peak_watts||0, cost_usd||0);
  const totals = db.prepare(`SELECT SUM(kwh_consumed) as total_kwh, SUM(cost_usd) as total_cost FROM energy_readings WHERE user_id=? AND reading_date >= date('now','-30 days')`).get(req.user.id) as any;
  res.json({ id: r.lastInsertRowid, monthly_kwh: totals?.total_kwh||0, monthly_cost: totals?.total_cost||0 });
});
// ─── End B321 ────────────────────────────────────────────────────────────────

// ─── B322: Volunteer & Community Service Tracker ──────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS volunteer_orgs (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, org_name TEXT,
    org_type TEXT DEFAULT 'nonprofit', website TEXT, contact_name TEXT,
    contact_email TEXT, cause TEXT DEFAULT 'community', status TEXT DEFAULT 'active',
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS volunteer_activities (
    id INTEGER PRIMARY KEY AUTOINCREMENT, org_id INTEGER, user_id INTEGER,
    activity_date DATE, activity_name TEXT, hours REAL DEFAULT 0,
    location TEXT, role TEXT, mileage REAL DEFAULT 0, impact_notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS volunteer_skills (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, skill_name TEXT,
    category TEXT DEFAULT 'technical', proficiency INTEGER DEFAULT 3,
    willing_to_volunteer INTEGER DEFAULT 1, notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS volunteer_awards (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, award_name TEXT,
    org_id INTEGER, awarded_date DATE, description TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/volunteer/orgs', requireAuth, (req: any, res: any) => {
  const orgs = db.prepare(`SELECT o.*, COUNT(a.id) as session_count, COALESCE(SUM(a.hours),0) as total_hours FROM volunteer_orgs o LEFT JOIN volunteer_activities a ON a.org_id=o.id AND a.user_id=o.user_id WHERE o.user_id=? GROUP BY o.id ORDER BY total_hours DESC`).all(req.user.id);
  const ytd = db.prepare(`SELECT SUM(hours) as total FROM volunteer_activities WHERE user_id=? AND activity_date >= date('now','start of year')`).get(req.user.id) as any;
  res.json({ orgs, ytd_hours: ytd?.total||0 });
});
app.post('/api/volunteer/orgs', requireAuth, (req: any, res: any) => {
  const { org_name, org_type, website, contact_name, contact_email, cause } = req.body;
  if (!org_name) return res.status(400).json({ error: 'org_name required' });
  const r = db.prepare(`INSERT INTO volunteer_orgs (user_id,org_name,org_type,website,contact_name,contact_email,cause) VALUES (?,?,?,?,?,?,?)`).run(req.user.id, org_name, org_type||'nonprofit', website||'', contact_name||'', contact_email||'', cause||'community');
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/volunteer/log', requireAuth, (req: any, res: any) => {
  const { org_id, activity_date, activity_name, hours, location, role, mileage, impact_notes } = req.body;
  if (!org_id || !hours) return res.status(400).json({ error: 'org_id and hours required' });
  const r = db.prepare(`INSERT INTO volunteer_activities (org_id,user_id,activity_date,activity_name,hours,location,role,mileage,impact_notes) VALUES (?,?,?,?,?,?,?,?,?)`).run(org_id, req.user.id, activity_date||new Date().toISOString().slice(0,10), activity_name||'Volunteer Session', hours, location||'', role||'', mileage||0, impact_notes||'');
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/volunteer/stats', requireAuth, (req: any, res: any) => {
  const { year = new Date().getFullYear() } = req.query as any;
  const activities = db.prepare(`SELECT a.*, o.org_name, o.cause FROM volunteer_activities a JOIN volunteer_orgs o ON o.id=a.org_id WHERE a.user_id=? AND strftime('%Y',a.activity_date)=? ORDER BY a.activity_date DESC`).all(req.user.id, String(year)) as any[];
  const total_hours = activities.reduce((s: number, a: any) => s + a.hours, 0);
  const total_miles = activities.reduce((s: number, a: any) => s + a.mileage, 0);
  const by_cause: Record<string, number> = {};
  activities.forEach((a: any) => { by_cause[a.cause] = (by_cause[a.cause]||0) + a.hours; });
  res.json({ year, total_hours: Math.round(total_hours * 10) / 10, total_miles, sessions: activities.length, by_cause, activities });
});
app.post('/api/volunteer/skills', requireAuth, (req: any, res: any) => {
  const { skill_name, category, proficiency, willing_to_volunteer } = req.body;
  if (!skill_name) return res.status(400).json({ error: 'skill_name required' });
  const r = db.prepare(`INSERT INTO volunteer_skills (user_id,skill_name,category,proficiency,willing_to_volunteer) VALUES (?,?,?,?,?)`).run(req.user.id, skill_name, category||'technical', proficiency||3, willing_to_volunteer?1:1);
  res.json({ id: r.lastInsertRowid });
});
