// ─── B323: Board Game & Tabletop RPG Tracker ─────────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS board_games (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, game_name TEXT,
    publisher TEXT, year_published INTEGER DEFAULT 2020,
    min_players INTEGER DEFAULT 2, max_players INTEGER DEFAULT 4,
    play_time_minutes INTEGER DEFAULT 60, complexity REAL DEFAULT 2.5,
    category TEXT DEFAULT 'strategy', bgg_id TEXT, bgg_rating REAL DEFAULT 0,
    own INTEGER DEFAULT 1, wishlist INTEGER DEFAULT 0,
    times_played INTEGER DEFAULT 0, last_played DATE,
    personal_rating INTEGER DEFAULT 0, notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS game_plays (
    id INTEGER PRIMARY KEY AUTOINCREMENT, game_id INTEGER, user_id INTEGER,
    play_date DATE, player_count INTEGER DEFAULT 2, duration_minutes INTEGER DEFAULT 0,
    winner TEXT, scores TEXT DEFAULT '{}', location TEXT DEFAULT 'home',
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS ttrpg_campaigns (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, campaign_name TEXT,
    system TEXT DEFAULT 'D&D 5e', gm_name TEXT, status TEXT DEFAULT 'active',
    start_date DATE, setting TEXT, session_count INTEGER DEFAULT 0,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS ttrpg_sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT, campaign_id INTEGER, user_id INTEGER,
    session_date DATE, session_number INTEGER DEFAULT 1, duration_hours REAL DEFAULT 3,
    summary TEXT, player_count INTEGER DEFAULT 4, highlights TEXT, notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/boardgames', requireAuth, (req: any, res: any) => {
  const { own, wishlist } = req.query as any;
  let q = `SELECT g.*, (SELECT COUNT(*) FROM game_plays WHERE game_id=g.id) as play_count FROM board_games g WHERE g.user_id=?`;
  const params: any[] = [req.user.id];
  if (own !== undefined) { q += ` AND g.own=?`; params.push(own==='true'?1:0); }
  if (wishlist !== undefined) { q += ` AND g.wishlist=?`; params.push(wishlist==='true'?1:0); }
  q += ` ORDER BY g.game_name ASC`;
  const games = db.prepare(q).all(...params);
  res.json({ games, count: games.length });
});
app.post('/api/boardgames', requireAuth, (req: any, res: any) => {
  const { game_name, publisher, year_published, min_players, max_players, play_time_minutes, complexity, category, bgg_id, bgg_rating, own, wishlist } = req.body;
  if (!game_name) return res.status(400).json({ error: 'game_name required' });
  const r = db.prepare(`INSERT INTO board_games (user_id,game_name,publisher,year_published,min_players,max_players,play_time_minutes,complexity,category,bgg_id,bgg_rating,own,wishlist) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, game_name, publisher||'', year_published||2020, min_players||2, max_players||4, play_time_minutes||60, complexity||2.5, category||'strategy', bgg_id||'', bgg_rating||0, own!==false?1:0, wishlist?1:0);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/boardgames/:id/plays', requireAuth, (req: any, res: any) => {
  const { play_date, player_count, duration_minutes, winner, scores, location, notes } = req.body;
  const r = db.prepare(`INSERT INTO game_plays (game_id,user_id,play_date,player_count,duration_minutes,winner,scores,location,notes) VALUES (?,?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, play_date||new Date().toISOString().slice(0,10), player_count||2, duration_minutes||0, winner||'', JSON.stringify(scores||{}), location||'home', notes||'');
  db.prepare(`UPDATE board_games SET times_played=times_played+1, last_played=? WHERE id=?`).run(play_date||new Date().toISOString().slice(0,10), req.params.id);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/ttrpg/campaigns', requireAuth, (req: any, res: any) => {
  const { campaign_name, system, gm_name, start_date, setting } = req.body;
  if (!campaign_name) return res.status(400).json({ error: 'campaign_name required' });
  const r = db.prepare(`INSERT INTO ttrpg_campaigns (user_id,campaign_name,system,gm_name,start_date,setting) VALUES (?,?,?,?,?,?)`).run(req.user.id, campaign_name, system||'D&D 5e', gm_name||'', start_date||new Date().toISOString().slice(0,10), setting||'');
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/ttrpg/campaigns/:id/sessions', requireAuth, (req: any, res: any) => {
  const { session_date, duration_hours, summary, player_count, highlights } = req.body;
  const camp = db.prepare(`SELECT session_count FROM ttrpg_campaigns WHERE id=? AND user_id=?`).get(req.params.id, req.user.id) as any;
  if (!camp) return res.status(404).json({ error: 'campaign not found' });
  const session_num = camp.session_count + 1;
  const r = db.prepare(`INSERT INTO ttrpg_sessions (campaign_id,user_id,session_date,session_number,duration_hours,summary,player_count,highlights) VALUES (?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, session_date||new Date().toISOString().slice(0,10), session_num, duration_hours||3, summary||'', player_count||4, highlights||'');
  db.prepare(`UPDATE ttrpg_campaigns SET session_count=session_count+1 WHERE id=?`).run(req.params.id);
  res.json({ id: r.lastInsertRowid, session_number: session_num });
});
app.get('/api/boardgames/stats', requireAuth, (req: any, res: any) => {
  const games = db.prepare(`SELECT * FROM board_games WHERE user_id=? AND own=1`).all(req.user.id) as any[];
  const plays = db.prepare(`SELECT p.*, g.game_name FROM game_plays p JOIN board_games g ON g.id=p.game_id WHERE p.user_id=? AND p.play_date >= date('now','-365 days') ORDER BY p.play_date DESC`).all(req.user.id) as any[];
  const top = db.prepare(`SELECT g.game_name, COUNT(p.id) as plays FROM game_plays p JOIN board_games g ON g.id=p.game_id WHERE p.user_id=? GROUP BY g.id ORDER BY plays DESC LIMIT 5`).all(req.user.id);
  res.json({ collection_size: games.length, plays_ytd: plays.length, top_games: top, recent_plays: plays.slice(0,10) });
});
// ─── End B323 ────────────────────────────────────────────────────────────────

