try { db.exec(`
  CREATE TABLE IF NOT EXISTS photo_sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, session_name TEXT,
    session_date DATE, session_type TEXT DEFAULT 'portrait',
    location TEXT, client_name TEXT, client_email TEXT,
    shoot_duration_hours REAL DEFAULT 2, photos_taken INTEGER DEFAULT 0,
    photos_delivered INTEGER DEFAULT 0, editing_hours REAL DEFAULT 0,
    session_fee REAL DEFAULT 0, status TEXT DEFAULT 'completed',
    delivery_url TEXT, contract_signed INTEGER DEFAULT 0,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS camera_gear_v2 (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, item_name TEXT,
    item_type TEXT DEFAULT 'camera', brand TEXT, model TEXT,
    serial_number TEXT, purchase_date DATE, purchase_price REAL DEFAULT 0,
    current_value REAL DEFAULT 0, condition TEXT DEFAULT 'excellent',
    shutter_count INTEGER DEFAULT 0, notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS portfolio_images (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, title TEXT,
    session_id INTEGER, url TEXT, thumbnail_url TEXT, category TEXT DEFAULT 'portrait',
    tags TEXT DEFAULT '[]', is_featured INTEGER DEFAULT 0, is_public INTEGER DEFAULT 0,
    width_px INTEGER DEFAULT 0, height_px INTEGER DEFAULT 0,
    camera TEXT, lens TEXT, aperture TEXT, shutter_speed TEXT, iso INTEGER DEFAULT 100,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS photo_clients (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, client_name TEXT,
    email TEXT, phone TEXT, address TEXT, referral_source TEXT,
    total_sessions INTEGER DEFAULT 0, total_revenue REAL DEFAULT 0,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/photo/sessions', requireAuth, (req: any, res: any) => {
  const { status, session_type } = req.query as any;
  let q = `SELECT * FROM photo_sessions WHERE user_id=?`;
  const params: any[] = [req.user.id];
  if (status) { q += ` AND status=?`; params.push(status); }
  if (session_type) { q += ` AND session_type=?`; params.push(session_type); }
  q += ` ORDER BY session_date DESC`;
  const sessions = db.prepare(q).all(...params) as any[];
  const revenue_ytd = sessions.filter((s: any) => s.session_date >= new Date().getFullYear().toString()).reduce((sum: number, s: any) => sum + s.session_fee, 0);
  res.json({ sessions, revenue_ytd: Math.round(revenue_ytd) });
});
app.post('/api/photo/sessions', requireAuth, (req: any, res: any) => {
  const { session_name, session_date, session_type, location, client_name, client_email, shoot_duration_hours, session_fee } = req.body;
  if (!session_name) return res.status(400).json({ error: 'session_name required' });
  const r = db.prepare(`INSERT INTO photo_sessions (user_id,session_name,session_date,session_type,location,client_name,client_email,shoot_duration_hours,session_fee) VALUES (?,?,?,?,?,?,?,?,?)`).run(req.user.id, session_name, session_date||new Date().toISOString().slice(0,10), session_type||'portrait', location||'', client_name||'', client_email||'', shoot_duration_hours||2, session_fee||0);
  if (client_email) {
    const cl = db.prepare(`SELECT id FROM photo_clients WHERE user_id=? AND email=?`).get(req.user.id, client_email) as any;
    if (!cl) db.prepare(`INSERT INTO photo_clients (user_id,client_name,email) VALUES (?,?,?)`).run(req.user.id, client_name||'', client_email);
    else db.prepare(`UPDATE photo_clients SET total_sessions=total_sessions+1, total_revenue=total_revenue+? WHERE id=?`).run(session_fee||0, cl.id);
  }
  res.json({ id: r.lastInsertRowid });
});
app.put('/api/photo/sessions/:id', requireAuth, (req: any, res: any) => {
  const { status, photos_taken, photos_delivered, editing_hours, delivery_url } = req.body;
  db.prepare(`UPDATE photo_sessions SET status=COALESCE(?,status), photos_taken=COALESCE(?,photos_taken), photos_delivered=COALESCE(?,photos_delivered), editing_hours=COALESCE(?,editing_hours), delivery_url=COALESCE(?,delivery_url) WHERE id=? AND user_id=?`).run(status, photos_taken, photos_delivered, editing_hours, delivery_url, req.params.id, req.user.id);
  res.json({ success: true });
});
