app.post('/api/therapy/sessions', requireAuth, (req: any, res: any) => {
  const { session_date, therapist_name, session_type, duration_minutes, format, topics_discussed, homework_assigned, overall_mood_before, overall_mood_after, breakthrough, cost, copay } = req.body;
  if (!session_date) return res.status(400).json({ error: 'session_date required' });
  const r = db.prepare(`INSERT INTO therapy_sessions_v2 (user_id,session_date,therapist_name,session_type,duration_minutes,format,topics_discussed,homework_assigned,overall_mood_before,overall_mood_after,breakthrough,cost,copay) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, session_date, therapist_name||'', session_type||'individual', duration_minutes||50, format||'in-person', JSON.stringify(topics_discussed||[]), homework_assigned||'', overall_mood_before||5, overall_mood_after||5, breakthrough?1:0, cost||0, copay||0);
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/therapy/progress', requireAuth, (req: any, res: any) => {
  const sessions = db.prepare(`SELECT * FROM therapy_sessions_v2 WHERE user_id=? ORDER BY session_date DESC LIMIT 20`).all(req.user.id) as any[];
  const checkins = db.prepare(`SELECT * FROM mental_health_checkins WHERE user_id=? AND checkin_date >= date('now','-30 days') ORDER BY checkin_date DESC`).all(req.user.id) as any[];
  const avg_mood = checkins.length ? Math.round(checkins.reduce((s: number, c: any) => s + c.mood_score, 0) / checkins.length * 10) / 10 : null;
  const avg_anxiety = checkins.length ? Math.round(checkins.reduce((s: number, c: any) => s + c.anxiety_score, 0) / checkins.length * 10) / 10 : null;
  const total_spent = sessions.reduce((s: number, t: any) => s + t.copay, 0);
  res.json({ sessions, checkins, avg_mood_30d: avg_mood, avg_anxiety_30d: avg_anxiety, total_sessions: sessions.length, total_copay_ytd: total_spent });
});
