  const r = db.prepare(`INSERT INTO livestock_health (animal_id,user_id,event_date,event_type,description,medication,dosage,administered_by,next_due_date,cost) VALUES (?,?,?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, event_date||new Date().toISOString().slice(0,10), event_type||'vaccination', description, medication||'', dosage||'', administered_by||'self', next_due_date||null, cost||0);
  res.json({ id: r.lastInsertRowid });
