app.get('/api/3dprint/printers', requireAuth, (req: any, res: any) => {
  const printers = db.prepare(`SELECT p.*, COUNT(j.id) as total_jobs, COALESCE(SUM(CASE WHEN j.success=1 THEN 1 ELSE 0 END),0) as successful_jobs FROM printers_3d p LEFT JOIN print_jobs j ON j.printer_id=p.id AND j.user_id=p.user_id WHERE p.user_id=? GROUP BY p.id`).all(req.user.id);
  res.json({ printers });
});
app.post('/api/3dprint/printers', requireAuth, (req: any, res: any) => {
  const { printer_name, brand, model, build_volume, bed_type, extruder_type, purchase_date, purchase_price } = req.body;
  if (!printer_name) return res.status(400).json({ error: 'printer_name required' });
  const r = db.prepare(`INSERT INTO printers_3d (user_id,printer_name,brand,model,build_volume,bed_type,extruder_type,purchase_date,purchase_price) VALUES (?,?,?,?,?,?,?,?,?)`).run(req.user.id, printer_name, brand||'', model||'', build_volume||'', bed_type||'PEI', extruder_type||'bowden', purchase_date||null, purchase_price||0);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/3dprint/jobs', requireAuth, (req: any, res: any) => {
  const { printer_id, job_name, model_file, slicer, filament_type, filament_color, filament_grams, layer_height_mm, infill_pct, print_time_hours, actual_time_hours, success, failure_reason, notes } = req.body;
  if (!job_name) return res.status(400).json({ error: 'job_name required' });
  const r = db.prepare(`INSERT INTO print_jobs (printer_id,user_id,job_name,model_file,slicer,filament_type,filament_color,filament_grams,layer_height_mm,infill_pct,print_time_hours,actual_time_hours,success,failure_reason,notes) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(printer_id||null, req.user.id, job_name, model_file||'', slicer||'Cura', filament_type||'PLA', filament_color||'', filament_grams||0, layer_height_mm||0.2, infill_pct||20, print_time_hours||0, actual_time_hours||print_time_hours||0, success!==false?1:0, failure_reason||'', notes||'');
  if (printer_id && actual_time_hours) db.prepare(`UPDATE printers_3d SET total_print_hours=total_print_hours+? WHERE id=?`).run(actual_time_hours, printer_id);
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/3dprint/jobs', requireAuth, (req: any, res: any) => {
  const jobs = db.prepare(`SELECT j.*, p.printer_name FROM print_jobs j LEFT JOIN printers_3d p ON p.id=j.printer_id WHERE j.user_id=? ORDER BY j.created_at DESC LIMIT 50`).all(req.user.id) as any[];
  const success_rate = jobs.length ? Math.round(jobs.filter((j: any) => j.success).length / jobs.length * 100) : 0;
  const total_filament = jobs.reduce((s: number, j: any) => s + j.filament_grams, 0);
  res.json({ jobs, success_rate, total_filament_grams: Math.round(total_filament) });
});
app.get('/api/3dprint/filament', requireAuth, (req: any, res: any) => {
  const fil = db.prepare(`SELECT * FROM filament_inventory WHERE user_id=? ORDER BY material, color`).all(req.user.id) as any[];
  const by_material: Record<string, number> = {};
  fil.forEach((f: any) => { by_material[f.material] = (by_material[f.material]||0) + f.remaining_grams; });
  res.json({ filament: fil, by_material });
});
app.post('/api/3dprint/filament', requireAuth, (req: any, res: any) => {
  const { brand, material, color, weight_grams, purchase_price, purchase_date, print_temp_c, bed_temp_c } = req.body;
  if (!material || !color) return res.status(400).json({ error: 'material and color required' });
  const r = db.prepare(`INSERT INTO filament_inventory (user_id,brand,material,color,weight_grams,remaining_grams,purchase_price,purchase_date,print_temp_c,bed_temp_c) VALUES (?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, brand||'', material, color, weight_grams||1000, weight_grams||1000, purchase_price||0, purchase_date||null, print_temp_c||210, bed_temp_c||60);
  res.json({ id: r.lastInsertRowid });
});
