app.post('/api/cards/collections/:id/cards', requireAuth, (req: any, res: any) => {
  const { card_name, set_name, set_code, card_number, rarity, condition, is_foil, is_first_edition, quantity, purchase_price, current_value, for_trade, for_sale, notes } = req.body;
  if (!card_name) return res.status(400).json({ error: 'card_name required' });
  const r = db.prepare(`INSERT INTO trading_cards (collection_id,user_id,card_name,set_name,set_code,card_number,rarity,condition,is_foil,is_first_edition,quantity,purchase_price,current_value,for_trade,for_sale,notes) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, card_name, set_name||'', set_code||'', card_number||'', rarity||'common', condition||'near_mint', is_foil?1:0, is_first_edition?1:0, quantity||1, purchase_price||0, current_value||purchase_price||0, for_trade?1:0, for_sale?1:0, notes||'');
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/cards/collections/:id', requireAuth, (req: any, res: any) => {
  const { rarity, for_trade, for_sale } = req.query as any;
  let q = `SELECT * FROM trading_cards WHERE collection_id=? AND user_id=?`;
  const params: any[] = [req.params.id, req.user.id];
  if (rarity) { q += ` AND rarity=?`; params.push(rarity); }
  if (for_trade === 'true') { q += ` AND for_trade=1`; }
  if (for_sale === 'true') { q += ` AND for_sale=1`; }
  q += ` ORDER BY card_name ASC`;
  const cards = db.prepare(q).all(...params) as any[];
  const total_value = cards.reduce((s: number, c: any) => s + c.current_value * c.quantity, 0);
  const total_cost = cards.reduce((s: number, c: any) => s + c.purchase_price * c.quantity, 0);
  res.json({ cards, total_cards: cards.length, total_value: Math.round(total_value*100)/100, total_cost: Math.round(total_cost*100)/100, gain_loss: Math.round((total_value-total_cost)*100)/100 });
});
