app.get('/api/realestate/properties', requireAuth, (req: any, res: any) => {
  const props = db.prepare(`SELECT p.*, (p.current_value - p.mortgage_balance - p.down_payment) as equity, (p.current_value - p.purchase_price) as appreciation FROM investment_properties p WHERE p.user_id=? ORDER BY p.purchase_date DESC`).all(req.user.id) as any[];
  const portfolio_value = props.reduce((s: number, p: any) => s + p.current_value, 0);
  const total_equity = props.reduce((s: number, p: any) => s + Math.max(0, p.current_value - p.mortgage_balance), 0);
  res.json({ properties: props, portfolio_value: Math.round(portfolio_value), total_equity: Math.round(total_equity) });
});
