app.post('/api/podcast/shows/:id/episodes', requireAuth, (req: any, res: any) => {
  const { title, description, guests, record_date, publish_date, status } = req.body;
  if (!title) return res.status(400).json({ error: 'title required' });
  const last = db.prepare(`SELECT MAX(episode_number) as max_ep FROM podcast_episodes WHERE show_id=?`).get(req.params.id) as any;
  const ep_num = (last?.max_ep||0) + 1;
  const r = db.prepare(`INSERT INTO podcast_episodes (show_id,user_id,episode_number,title,description,guests,record_date,publish_date,status) VALUES (?,?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, ep_num, title, description||'', JSON.stringify(guests||[]), record_date||null, publish_date||null, status||'idea');
  db.prepare(`UPDATE podcast_shows SET total_episodes=total_episodes+1 WHERE id=?`).run(req.params.id);
  const default_tasks = ['Write outline','Record episode','Edit audio','Write show notes','Upload and schedule'];
  default_tasks.forEach(task => db.prepare(`INSERT INTO podcast_tasks (episode_id,user_id,task_name) VALUES (?,?,?)`).run(r.lastInsertRowid, req.user.id, task));
  res.json({ id: r.lastInsertRowid, episode_number: ep_num });
});
