// ─── B342: Vintage & Thrift Store Resale Tracker ──────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS resale_items (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, item_name TEXT,
    category TEXT DEFAULT 'clothing', brand TEXT, size TEXT, color TEXT,
    condition_grade TEXT DEFAULT 'good', purchase_date DATE, purchase_price REAL DEFAULT 0,
    source TEXT DEFAULT 'thrift_store', listing_date DATE, list_price REAL DEFAULT 0,
    sale_date DATE, sale_price REAL DEFAULT 0, platform TEXT DEFAULT 'ebay',
    shipping_cost REAL DEFAULT 0, platform_fee_pct REAL DEFAULT 10,
    status TEXT DEFAULT 'sourced', photo_urls TEXT DEFAULT '[]', notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS resale_expenses (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, expense_date DATE,
    category TEXT DEFAULT 'supplies', description TEXT, amount REAL DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS resale_platforms (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, platform_name TEXT,
    fee_pct REAL DEFAULT 10, shipping_avg REAL DEFAULT 5, notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/resale/items', requireAuth, (req: any, res: any) => {
  const { status, category } = req.query as any;
  let q = `SELECT *, ROUND((sale_price - purchase_price - shipping_cost - (sale_price*platform_fee_pct/100)),2) as profit FROM resale_items WHERE user_id=?`;
  const params: any[] = [req.user.id];
  if (status) { q += ` AND status=?`; params.push(status); }
  if (category) { q += ` AND category=?`; params.push(category); }
  q += ` ORDER BY created_at DESC`;
  const items = db.prepare(q).all(...params) as any[];
  const sold = items.filter((i: any) => i.status === 'sold');
  const total_profit = sold.reduce((s: number, i: any) => s + (i.profit||0), 0);
  const roi = sold.length ? Math.round(total_profit / sold.reduce((s: number, i: any) => s + i.purchase_price, 0) * 100) : 0;
  res.json({ items, sold_count: sold.length, total_profit: Math.round(total_profit*100)/100, roi_pct: roi });
});
app.post('/api/resale/items', requireAuth, (req: any, res: any) => {
  const { item_name, category, brand, size, color, condition_grade, purchase_date, purchase_price, source, notes } = req.body;
  if (!item_name) return res.status(400).json({ error: 'item_name required' });
  const r = db.prepare(`INSERT INTO resale_items (user_id,item_name,category,brand,size,color,condition_grade,purchase_date,purchase_price,source,notes) VALUES (?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, item_name, category||'clothing', brand||'', size||'', color||'', condition_grade||'good', purchase_date||new Date().toISOString().slice(0,10), purchase_price||0, source||'thrift_store', notes||'');
  res.json({ id: r.lastInsertRowid });
});
app.put('/api/resale/items/:id/list', requireAuth, (req: any, res: any) => {
  const { list_price, platform, listing_date } = req.body;
  if (!list_price) return res.status(400).json({ error: 'list_price required' });
  db.prepare(`UPDATE resale_items SET list_price=?, platform=?, listing_date=?, status='listed' WHERE id=? AND user_id=?`).run(list_price, platform||'ebay', listing_date||new Date().toISOString().slice(0,10), req.params.id, req.user.id);
  res.json({ success: true });
});
app.put('/api/resale/items/:id/sell', requireAuth, (req: any, res: any) => {
  const { sale_price, sale_date, shipping_cost, platform_fee_pct } = req.body;
  if (!sale_price) return res.status(400).json({ error: 'sale_price required' });
  db.prepare(`UPDATE resale_items SET sale_price=?, sale_date=?, shipping_cost=?, platform_fee_pct=?, status='sold' WHERE id=? AND user_id=?`).run(sale_price, sale_date||new Date().toISOString().slice(0,10), shipping_cost||0, platform_fee_pct||10, req.params.id, req.user.id);
  const item = db.prepare(`SELECT purchase_price FROM resale_items WHERE id=?`).get(req.params.id) as any;
  const profit = sale_price - (item?.purchase_price||0) - (shipping_cost||0) - (sale_price * (platform_fee_pct||10) / 100);
  res.json({ success: true, profit: Math.round(profit*100)/100 });
});
app.get('/api/resale/dashboard', requireAuth, (req: any, res: any) => {
  const all = db.prepare(`SELECT * FROM resale_items WHERE user_id=?`).all(req.user.id) as any[];
  const sold = all.filter((i: any) => i.status === 'sold');
  const listed = all.filter((i: any) => i.status === 'listed');
  const total_invested = all.reduce((s: number, i: any) => s + i.purchase_price, 0);
  const total_revenue = sold.reduce((s: number, i: any) => s + i.sale_price, 0);
  const expenses_data = db.prepare(`SELECT SUM(amount) as total FROM resale_expenses WHERE user_id=?`).get(req.user.id) as any;
  const total_profit = total_revenue - total_invested - (expenses_data?.total||0);
  res.json({ total_items: all.length, listed_count: listed.length, sold_count: sold.length, total_invested: Math.round(total_invested*100)/100, total_revenue: Math.round(total_revenue*100)/100, total_profit: Math.round(total_profit*100)/100 });
});
// ─── End B342 ────────────────────────────────────────────────────────────────

