app.get('/api/climbing/stats', requireAuth, (req: any, res: any) => {
  const { period = '90' } = req.query as any;
  const sessions = db.prepare(`SELECT * FROM climbing_sessions WHERE user_id=? AND session_date>=date('now','-${period} days')`).all(req.user.id) as any[];
  const routes = db.prepare(`SELECT r.*, s.session_date FROM climbing_routes r JOIN climbing_sessions s ON s.id=r.session_id WHERE r.user_id=? AND s.session_date>=date('now','-${period} days')`).all(req.user.id) as any[];
  const sends = routes.filter((r: any) => r.sent);
  const grades_sent = sends.map((r: any) => r.grade);
  const flash_count = routes.filter((r: any) => r.flash).length;
  res.json({ sessions_count: sessions.length, total_routes: routes.length, sends_count: sends.length, flash_count, grades_sent: [...new Set(grades_sent)].sort() });
});
app.get('/api/climbing/sessions', requireAuth, (req: any, res: any) => {
  const sessions = db.prepare(`SELECT s.*, (SELECT COUNT(*) FROM climbing_routes WHERE session_id=s.id) as routes_tried, (SELECT COUNT(*) FROM climbing_routes WHERE session_id=s.id AND sent=1) as routes_sent FROM climbing_sessions s WHERE s.user_id=? ORDER BY s.session_date DESC LIMIT 50`).all(req.user.id);
  res.json({ sessions });
});
