  const r = db.prepare(`INSERT INTO coffee_brews (bean_id,user_id,brew_date,brew_method,grinder,grind_size,dose_grams,water_grams,water_temp_f,brew_time_seconds,ratio,aroma,flavor,body,acidity,finish,overall,tasting_notes,would_brew_again) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(bean_id, req.user.id, new Date().toISOString().slice(0,10), brew_method||'pour_over', grinder||'', grind_size||20, dose_grams||15, water_grams||250, water_temp_f||200, brew_time_seconds||180, ratio, aroma||4, flavor||4, body||3, acidity||3, finish||3, overall||4, tasting_notes||'', would_brew_again!==false?1:0);
