app.get('/api/music/pieces', requireAuth, (req: any, res: any) => {
  const { status, instrument } = req.query as any;
  let q = `SELECT p.*, (SELECT SUM(duration_minutes) FROM practice_sessions_music WHERE piece_id=p.id) as total_practice_min FROM music_pieces p WHERE p.user_id=?`;
  const params: any[] = [req.user.id];
  if (status) { q += ` AND p.status=?`; params.push(status); }
  if (instrument) { q += ` AND p.instrument=?`; params.push(instrument); }
  q += ` ORDER BY p.title ASC`;
  res.json({ pieces: db.prepare(q).all(...params) });
});
