  const sessions = db.prepare(`SELECT s.*, p.title FROM practice_sessions_music s JOIN music_pieces p ON p.id=s.piece_id WHERE s.user_id=? AND s.practice_date>=date('now','-${days} days') ORDER BY s.practice_date DESC`).all(req.user.id) as any[];
  const total_min = sessions.reduce((s: number, ps: any) => s + ps.duration_minutes, 0);
