app.get('/api/escape/rooms', requireAuth, (req: any, res: any) => {
  const rooms = db.prepare(`SELECT * FROM escape_rooms WHERE user_id=? ORDER BY play_date DESC`).all(req.user.id) as any[];
  const escaped = rooms.filter((r: any) => r.escaped).length;
  const avg_rating = rooms.length ? Math.round(rooms.reduce((s: number, r: any) => s + r.overall_rating, 0) / rooms.length * 10) / 10 : 0;
  res.json({ rooms, total: rooms.length, escaped_count: escaped, escape_rate: rooms.length ? Math.round(escaped / rooms.length * 100) : 0, avg_rating });
});
