  const r = db.prepare(`INSERT INTO box_deliveries (box_id,user_id,delivery_date,box_theme,total_items,retail_value_est,overall_rating,value_rating,curation_rating,notes,photo_url) VALUES (?,?,?,?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, delivery_date, box_theme||'', total_items||0, retail_value_est||0, overall_rating||4, value_rating||4, curation_rating||4, notes||'', photo_url||'');
