// ─── B361: Fantasy Sports & Draft League Manager ──────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS fantasy_leagues (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, league_name TEXT,
    sport TEXT DEFAULT 'football', platform TEXT DEFAULT 'espn',
    season INTEGER DEFAULT 2025, num_teams INTEGER DEFAULT 10,
    scoring_type TEXT DEFAULT 'ppr', draft_date DATE, draft_type TEXT DEFAULT 'snake',
    commissioner TEXT DEFAULT 'me', status TEXT DEFAULT 'active',
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS fantasy_teams (
    id INTEGER PRIMARY KEY AUTOINCREMENT, league_id INTEGER, user_id INTEGER,
    team_name TEXT, wins INTEGER DEFAULT 0, losses INTEGER DEFAULT 0,
    ties INTEGER DEFAULT 0, points_for REAL DEFAULT 0, points_against REAL DEFAULT 0,
    waiver_priority INTEGER DEFAULT 1, playoff_seed INTEGER DEFAULT 0,
    made_playoffs INTEGER DEFAULT 0, won_championship INTEGER DEFAULT 0,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS fantasy_players (
    id INTEGER PRIMARY KEY AUTOINCREMENT, team_id INTEGER, user_id INTEGER,
    player_name TEXT, position TEXT DEFAULT 'QB', nfl_team TEXT,
    acquisition_type TEXT DEFAULT 'draft', draft_round INTEGER DEFAULT 0,
    draft_pick INTEGER DEFAULT 0, waiver_cost INTEGER DEFAULT 0,
    total_points REAL DEFAULT 0, avg_points REAL DEFAULT 0,
    is_active INTEGER DEFAULT 1, notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS fantasy_matchups (
    id INTEGER PRIMARY KEY AUTOINCREMENT, team_id INTEGER, user_id INTEGER,
    week INTEGER DEFAULT 1, opponent_name TEXT, team_score REAL DEFAULT 0,
    opponent_score REAL DEFAULT 0, result TEXT DEFAULT 'pending',
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/fantasy/leagues', requireAuth, (req: any, res: any) => {
  const leagues = db.prepare(`SELECT l.*, (SELECT wins FROM fantasy_teams WHERE league_id=l.id AND user_id=l.user_id LIMIT 1) as team_wins, (SELECT losses FROM fantasy_teams WHERE league_id=l.id AND user_id=l.user_id LIMIT 1) as team_losses FROM fantasy_leagues l WHERE l.user_id=? ORDER BY l.season DESC, l.league_name ASC`).all(req.user.id);
  res.json({ leagues });
});
app.post('/api/fantasy/leagues', requireAuth, (req: any, res: any) => {
  const { league_name, sport, platform, season, num_teams, scoring_type, draft_date, draft_type } = req.body;
  if (!league_name) return res.status(400).json({ error: 'league_name required' });
  const r = db.prepare(`INSERT INTO fantasy_leagues (user_id,league_name,sport,platform,season,num_teams,scoring_type,draft_date,draft_type) VALUES (?,?,?,?,?,?,?,?,?)`).run(req.user.id, league_name, sport||'football', platform||'espn', season||new Date().getFullYear(), num_teams||10, scoring_type||'ppr', draft_date||null, draft_type||'snake');
  const team = db.prepare(`INSERT INTO fantasy_teams (league_id,user_id,team_name) VALUES (?,?,?)`).run(r.lastInsertRowid, req.user.id, 'My Team');
  res.json({ league_id: r.lastInsertRowid, team_id: team.lastInsertRowid });
});
app.post('/api/fantasy/leagues/:id/players', requireAuth, (req: any, res: any) => {
  const team = db.prepare(`SELECT id FROM fantasy_teams WHERE league_id=? AND user_id=?`).get(req.params.id, req.user.id) as any;
  if (!team) return res.status(404).json({ error: 'team not found' });
  const { player_name, position, nfl_team, acquisition_type, draft_round, draft_pick } = req.body;
  if (!player_name) return res.status(400).json({ error: 'player_name required' });
  const r = db.prepare(`INSERT INTO fantasy_players (team_id,user_id,player_name,position,nfl_team,acquisition_type,draft_round,draft_pick) VALUES (?,?,?,?,?,?,?,?)`).run(team.id, req.user.id, player_name, position||'QB', nfl_team||'', acquisition_type||'draft', draft_round||0, draft_pick||0);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/fantasy/leagues/:id/matchups', requireAuth, (req: any, res: any) => {
  const team = db.prepare(`SELECT id FROM fantasy_teams WHERE league_id=? AND user_id=?`).get(req.params.id, req.user.id) as any;
  if (!team) return res.status(404).json({ error: 'team not found' });
  const { week, opponent_name, team_score, opponent_score } = req.body;
  if (!week) return res.status(400).json({ error: 'week required' });
  const result = team_score > opponent_score ? 'win' : team_score < opponent_score ? 'loss' : 'tie';
  const r = db.prepare(`INSERT INTO fantasy_matchups (team_id,user_id,week,opponent_name,team_score,opponent_score,result) VALUES (?,?,?,?,?,?,?)`).run(team.id, req.user.id, week, opponent_name||'TBD', team_score||0, opponent_score||0, result);
  if (team_score > 0 || opponent_score > 0) {
    const col = result === 'win' ? 'wins' : result === 'loss' ? 'losses' : 'ties';
    db.prepare(`UPDATE fantasy_teams SET ${col}=${col}+1, points_for=points_for+?, points_against=points_against+? WHERE id=?`).run(team_score||0, opponent_score||0, team.id);
  }
  res.json({ id: r.lastInsertRowid, result });
});
app.get('/api/fantasy/leagues/:id/summary', requireAuth, (req: any, res: any) => {
  const league = db.prepare(`SELECT * FROM fantasy_leagues WHERE id=? AND user_id=?`).get(req.params.id, req.user.id);
  const team = db.prepare(`SELECT * FROM fantasy_teams WHERE league_id=? AND user_id=?`).get(req.params.id, req.user.id) as any;
  const players = db.prepare(`SELECT * FROM fantasy_players WHERE team_id=? ORDER BY position ASC`).all(team?.id||0);
  const matchups = db.prepare(`SELECT * FROM fantasy_matchups WHERE team_id=? ORDER BY week ASC`).all(team?.id||0);
  res.json({ league, team, players, matchups });
});
// ─── End B361 ────────────────────────────────────────────────────────────────

