app.post('/api/hydro/systems/:id/crops', requireAuth, (req: any, res: any) => {
  const { crop_name, variety, site_number, planted_date, expected_harvest, nutrient_ppm_target } = req.body;
  if (!crop_name) return res.status(400).json({ error: 'crop_name required' });
  const r = db.prepare(`INSERT INTO growing_crops (system_id,user_id,crop_name,variety,site_number,planted_date,expected_harvest,nutrient_ppm_target) VALUES (?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, crop_name, variety||'', site_number||1, planted_date||new Date().toISOString().slice(0,10), expected_harvest||null, nutrient_ppm_target||800);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/hydro/systems/:id/readings', requireAuth, (req: any, res: any) => {
  const { ph, ec_ms, ppm, water_temp_f, reservoir_level_pct, nutrients_added, notes } = req.body;
  const alerts: string[] = [];
  if (ph && (ph < 5.5 || ph > 7.0)) alerts.push(`pH ${ph} out of range (5.5-7.0)`);
  if (ppm && ppm < 400) alerts.push(`PPM ${ppm} too low`);
  const r = db.prepare(`INSERT INTO water_readings_hydro (system_id,user_id,reading_date,ph,ec_ms,ppm,water_temp_f,reservoir_level_pct,nutrients_added,notes) VALUES (?,?,?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, new Date().toISOString().slice(0,10), ph||6.0, ec_ms||1.5, ppm||750, water_temp_f||68, reservoir_level_pct||80, JSON.stringify(nutrients_added||{}), notes||'');
  res.json({ id: r.lastInsertRowid, alerts });
});
app.get('/api/hydro/systems/:id/history', requireAuth, (req: any, res: any) => {
  const readings = db.prepare(`SELECT * FROM water_readings_hydro WHERE system_id=? AND user_id=? ORDER BY reading_date DESC LIMIT 30`).all(req.params.id, req.user.id);
  const crops = db.prepare(`SELECT * FROM growing_crops WHERE system_id=? AND user_id=? ORDER BY planted_date DESC`).all(req.params.id, req.user.id);
  res.json({ readings, crops });
});
// ─── End B362 ────────────────────────────────────────────────────────────────

// ─── B363: Freelance Writing & Content Portfolio ──────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS writing_clients (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, client_name TEXT,
    company TEXT, niche TEXT DEFAULT 'general', contact_email TEXT,
    per_word_rate REAL DEFAULT 0, per_article_rate REAL DEFAULT 0,
    payment_terms TEXT DEFAULT 'net30', style_guide_url TEXT,
    status TEXT DEFAULT 'active', total_earned REAL DEFAULT 0,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS writing_assignments (
    id INTEGER PRIMARY KEY AUTOINCREMENT, client_id INTEGER, user_id INTEGER,
    title TEXT, content_type TEXT DEFAULT 'blog_post', topic TEXT,
    target_word_count INTEGER DEFAULT 1000, actual_word_count INTEGER DEFAULT 0,
    deadline DATE, submitted_date DATE, published_date DATE, published_url TEXT,
    agreed_rate REAL DEFAULT 0, invoiced INTEGER DEFAULT 0, paid INTEGER DEFAULT 0,
    status TEXT DEFAULT 'assigned', notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS writing_portfolio (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, title TEXT,
    content_type TEXT DEFAULT 'blog_post', client_name TEXT,
    published_date DATE, published_url TEXT, word_count INTEGER DEFAULT 0,
    excerpt TEXT, niche TEXT DEFAULT 'general', is_featured INTEGER DEFAULT 0,
    performance_notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS writing_pitches (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, publication TEXT,
    topic TEXT, pitch_date DATE, response_date DATE,
    status TEXT DEFAULT 'pending', agreed_rate REAL DEFAULT 0, notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/writing/clients', requireAuth, (req: any, res: any) => {
  const clients = db.prepare(`SELECT c.*, (SELECT COUNT(*) FROM writing_assignments WHERE client_id=c.id AND status NOT IN ('completed','cancelled')) as active_assignments FROM writing_clients c WHERE c.user_id=? ORDER BY c.status ASC, c.client_name ASC`).all(req.user.id);
  const total_earned = db.prepare(`SELECT SUM(total_earned) as total FROM writing_clients WHERE user_id=?`).get(req.user.id) as any;
  res.json({ clients, total_earned: total_earned?.total||0 });
});
app.post('/api/writing/clients', requireAuth, (req: any, res: any) => {
  const { client_name, company, niche, contact_email, per_word_rate, per_article_rate, payment_terms } = req.body;
  if (!client_name) return res.status(400).json({ error: 'client_name required' });
  const r = db.prepare(`INSERT INTO writing_clients (user_id,client_name,company,niche,contact_email,per_word_rate,per_article_rate,payment_terms) VALUES (?,?,?,?,?,?,?,?)`).run(req.user.id, client_name, company||'', niche||'general', contact_email||'', per_word_rate||0, per_article_rate||0, payment_terms||'net30');
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/writing/clients/:id/assignments', requireAuth, (req: any, res: any) => {
  const { title, content_type, topic, target_word_count, deadline, agreed_rate } = req.body;
  if (!title) return res.status(400).json({ error: 'title required' });
  const r = db.prepare(`INSERT INTO writing_assignments (client_id,user_id,title,content_type,topic,target_word_count,deadline,agreed_rate) VALUES (?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, title, content_type||'blog_post', topic||'', target_word_count||1000, deadline||null, agreed_rate||0);
  res.json({ id: r.lastInsertRowid });
});
app.put('/api/writing/assignments/:id/submit', requireAuth, (req: any, res: any) => {
  const { actual_word_count, submitted_date, published_url } = req.body;
  const asgn = db.prepare(`SELECT * FROM writing_assignments WHERE id=? AND user_id=?`).get(req.params.id, req.user.id) as any;
  if (!asgn) return res.status(404).json({ error: 'not found' });
  db.prepare(`UPDATE writing_assignments SET actual_word_count=?,submitted_date=?,status='submitted',published_url=COALESCE(?,published_url) WHERE id=?`).run(actual_word_count||0, submitted_date||new Date().toISOString().slice(0,10), published_url, req.params.id);
  const earned = asgn.agreed_rate || (asgn.per_word_rate||0) * (actual_word_count||asgn.target_word_count);
  if (earned) db.prepare(`UPDATE writing_clients SET total_earned=total_earned+? WHERE id=?`).run(earned, asgn.client_id);
  res.json({ success: true, earned: Math.round(earned*100)/100 });
});
app.get('/api/writing/pipeline', requireAuth, (req: any, res: any) => {
  const assignments = db.prepare(`SELECT a.*, c.client_name, c.niche FROM writing_assignments a JOIN writing_clients c ON c.id=a.client_id WHERE a.user_id=? AND a.status NOT IN ('completed','cancelled') ORDER BY a.deadline ASC`).all(req.user.id);
  const overdue = (assignments as any[]).filter((a: any) => a.deadline && a.deadline < new Date().toISOString().slice(0,10));
  res.json({ assignments, overdue_count: overdue.length });
});
// ─── End B363 ────────────────────────────────────────────────────────────────

// ─── B364: Motorcycle & Powersport Tracker ────────────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS motorcycles (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, nickname TEXT,
    make TEXT, model TEXT, year INTEGER DEFAULT 2020, color TEXT,
    engine_cc INTEGER DEFAULT 650, purchase_date DATE, purchase_price REAL DEFAULT 0,
    current_value REAL DEFAULT 0, odometer_miles INTEGER DEFAULT 0,
    vin TEXT, license_plate TEXT, insurance_policy TEXT,
    status TEXT DEFAULT 'active', notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS moto_rides (
    id INTEGER PRIMARY KEY AUTOINCREMENT, moto_id INTEGER, user_id INTEGER,
    ride_date DATE, start_odometer INTEGER DEFAULT 0, end_odometer INTEGER DEFAULT 0,
    distance_miles REAL DEFAULT 0, duration_minutes INTEGER DEFAULT 60,
    route_description TEXT, ride_type TEXT DEFAULT 'leisure',
    weather TEXT DEFAULT 'clear', temp_f INTEGER DEFAULT 70,
    avg_speed_mph REAL DEFAULT 0, fuel_used_gal REAL DEFAULT 0,
    mpg REAL DEFAULT 0, notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS moto_maintenance (
    id INTEGER PRIMARY KEY AUTOINCREMENT, moto_id INTEGER, user_id INTEGER,
    service_date DATE, service_type TEXT DEFAULT 'oil_change',
    mileage_at_service INTEGER DEFAULT 0, next_service_miles INTEGER DEFAULT 0,
    cost REAL DEFAULT 0, shop TEXT DEFAULT 'diy', parts_used TEXT DEFAULT '[]',
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS moto_mods (
    id INTEGER PRIMARY KEY AUTOINCREMENT, moto_id INTEGER, user_id INTEGER,
    mod_name TEXT, category TEXT DEFAULT 'performance', brand TEXT,
    part_number TEXT, install_date DATE, cost REAL DEFAULT 0,
    reversible INTEGER DEFAULT 1, notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/moto/bikes', requireAuth, (req: any, res: any) => {
  const bikes = db.prepare(`SELECT m.*, (SELECT SUM(distance_miles) FROM moto_rides WHERE moto_id=m.id) as total_miles_ridden, (SELECT ride_date FROM moto_rides WHERE moto_id=m.id ORDER BY ride_date DESC LIMIT 1) as last_ride FROM motorcycles m WHERE m.user_id=? ORDER BY m.status ASC, m.year DESC`).all(req.user.id);
  res.json({ bikes });
});
app.post('/api/moto/bikes', requireAuth, (req: any, res: any) => {
  const { nickname, make, model, year, color, engine_cc, purchase_date, purchase_price, odometer_miles } = req.body;
  if (!make || !model) return res.status(400).json({ error: 'make and model required' });
  const r = db.prepare(`INSERT INTO motorcycles (user_id,nickname,make,model,year,color,engine_cc,purchase_date,purchase_price,current_value,odometer_miles) VALUES (?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, nickname||`${year} ${make} ${model}`, make, model, year||2020, color||'', engine_cc||650, purchase_date||null, purchase_price||0, purchase_price||0, odometer_miles||0);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/moto/bikes/:id/rides', requireAuth, (req: any, res: any) => {
  const { ride_date, start_odometer, end_odometer, duration_minutes, route_description, ride_type, weather, temp_f, fuel_used_gal } = req.body;
  if (!ride_date) return res.status(400).json({ error: 'ride_date required' });
  const distance = end_odometer && start_odometer ? end_odometer - start_odometer : 0;
  const mpg = fuel_used_gal && distance ? Math.round(distance / fuel_used_gal * 10) / 10 : 0;
  const r = db.prepare(`INSERT INTO moto_rides (moto_id,user_id,ride_date,start_odometer,end_odometer,distance_miles,duration_minutes,route_description,ride_type,weather,temp_f,fuel_used_gal,mpg) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, ride_date, start_odometer||0, end_odometer||0, distance, duration_minutes||60, route_description||'', ride_type||'leisure', weather||'clear', temp_f||70, fuel_used_gal||0, mpg);
  if (end_odometer) db.prepare(`UPDATE motorcycles SET odometer_miles=? WHERE id=? AND user_id=?`).run(end_odometer, req.params.id, req.user.id);
  res.json({ id: r.lastInsertRowid, distance_miles: distance, mpg });
});
app.post('/api/moto/bikes/:id/maintenance', requireAuth, (req: any, res: any) => {
  const { service_date, service_type, mileage_at_service, next_service_miles, cost, shop, parts_used } = req.body;
  if (!service_type) return res.status(400).json({ error: 'service_type required' });
  const r = db.prepare(`INSERT INTO moto_maintenance (moto_id,user_id,service_date,service_type,mileage_at_service,next_service_miles,cost,shop,parts_used) VALUES (?,?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, service_date||new Date().toISOString().slice(0,10), service_type, mileage_at_service||0, next_service_miles||0, cost||0, shop||'diy', JSON.stringify(parts_used||[]));
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/moto/bikes/:id/stats', requireAuth, (req: any, res: any) => {
  const bike = db.prepare(`SELECT * FROM motorcycles WHERE id=? AND user_id=?`).get(req.params.id, req.user.id) as any;
  if (!bike) return res.status(404).json({ error: 'not found' });
  const ride_stats = db.prepare(`SELECT COUNT(*) as ride_count, SUM(distance_miles) as total_miles, AVG(mpg) as avg_mpg FROM moto_rides WHERE moto_id=? AND user_id=?`).get(req.params.id, req.user.id) as any;
  const maintenance_cost = db.prepare(`SELECT SUM(cost) as total FROM moto_maintenance WHERE moto_id=? AND user_id=?`).get(req.params.id, req.user.id) as any;
  res.json({ bike, ride_count: ride_stats?.ride_count||0, total_miles: ride_stats?.total_miles||0, avg_mpg: Math.round((ride_stats?.avg_mpg||0)*10)/10, maintenance_total: maintenance_cost?.total||0 });
});
// ─── End B364 ────────────────────────────────────────────────────────────────

