app.get('/api/gratitude/entries', requireAuth, (req: any, res: any) => {
  const entries = db.prepare(`SELECT * FROM gratitude_entries WHERE user_id=? ORDER BY entry_date DESC LIMIT 30`).all(req.user.id);
  res.json({ entries });
});
app.post('/api/gratitude/entries', requireAuth, (req: any, res: any) => {
  const { entry_date, gratitudes, savoring_moment, acts_of_kindness, positive_emotions, strengths_used, flow_activities, overall_wellbeing, notes } = req.body;
  if (!gratitudes?.length) return res.status(400).json({ error: 'at least one gratitude required' });
  const r = db.prepare(`INSERT INTO gratitude_entries (user_id,entry_date,gratitudes,savoring_moment,acts_of_kindness,positive_emotions,strengths_used,flow_activities,overall_wellbeing,notes) VALUES (?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, entry_date||new Date().toISOString().slice(0,10), JSON.stringify(gratitudes), savoring_moment||'', JSON.stringify(acts_of_kindness||[]), JSON.stringify(positive_emotions||[]), JSON.stringify(strengths_used||[]), JSON.stringify(flow_activities||[]), overall_wellbeing||3, notes||'');
  if (strengths_used?.length) {
    (strengths_used as string[]).forEach((s: string) => {
      const ex = db.prepare(`SELECT id FROM character_strengths WHERE user_id=? AND strength_name=?`).get(req.user.id, s);
      if (ex) { db.prepare(`UPDATE character_strengths SET usage_count=usage_count+1, peak_date=? WHERE user_id=? AND strength_name=?`).run(entry_date||new Date().toISOString().slice(0,10), req.user.id, s); }
      else { db.prepare(`INSERT INTO character_strengths (user_id,strength_name,usage_count,peak_date) VALUES (?,?,1,?)`).run(req.user.id, s, entry_date||new Date().toISOString().slice(0,10)); }
    });
  }
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/gratitude/stats', requireAuth, (req: any, res: any) => {
  const streak = db.prepare(`SELECT COUNT(*) as c FROM gratitude_entries WHERE user_id=? AND entry_date>=date('now','-7 days')`).get(req.user.id) as any;
  const avg_wellbeing = db.prepare(`SELECT AVG(overall_wellbeing) as avg FROM gratitude_entries WHERE user_id=? AND entry_date>=date('now','-30 days')`).get(req.user.id) as any;
  const top_strengths = db.prepare(`SELECT strength_name, usage_count FROM character_strengths WHERE user_id=? ORDER BY usage_count DESC LIMIT 5`).all(req.user.id);
  const total = db.prepare(`SELECT COUNT(*) as c FROM gratitude_entries WHERE user_id=?`).get(req.user.id) as any;
  res.json({ total_entries: total?.c||0, streak_7d: streak?.c||0, avg_wellbeing_30d: Math.round((avg_wellbeing?.avg||0)*10)/10, top_strengths });
});
