// ─── B380: Digital Nomad & Remote Work Tracker ────────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS nomad_locations (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, city TEXT, country TEXT,
    arrival_date DATE, departure_date DATE, accommodation_type TEXT DEFAULT 'apartment',
    accommodation_name TEXT, monthly_cost REAL DEFAULT 0, currency TEXT DEFAULT 'USD',
    internet_speed_mbps INTEGER DEFAULT 0, timezone TEXT DEFAULT 'UTC',
    visa_type TEXT DEFAULT 'tourist', visa_expiry DATE,
    coworking_spaces TEXT DEFAULT '[]', overall_rating INTEGER DEFAULT 4,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS nomad_expenses (
    id INTEGER PRIMARY KEY AUTOINCREMENT, location_id INTEGER, user_id INTEGER,
    expense_date DATE, category TEXT DEFAULT 'accommodation',
    description TEXT, amount REAL DEFAULT 0, currency TEXT DEFAULT 'USD',
    usd_amount REAL DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS remote_work_sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT, location_id INTEGER, user_id INTEGER,
    work_date DATE, hours_worked REAL DEFAULT 8,
    productivity_rating INTEGER DEFAULT 3, tools_used TEXT DEFAULT '[]',
    meeting_count INTEGER DEFAULT 0, notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/nomad/locations', requireAuth, (req: any, res: any) => {
  const locations = db.prepare(`SELECT l.*, CAST((julianday(COALESCE(l.departure_date,date('now'))) - julianday(l.arrival_date)) AS INTEGER) as days_stayed FROM nomad_locations l WHERE l.user_id=? ORDER BY l.arrival_date DESC`).all(req.user.id) as any[];
  const countries = new Set((locations as any[]).map((l: any) => l.country)).size;
  const cities = locations.length;
  res.json({ locations, countries_visited: countries, cities_visited: cities });
});
app.post('/api/nomad/locations', requireAuth, (req: any, res: any) => {
  const { city, country, arrival_date, departure_date, accommodation_type, accommodation_name, monthly_cost, currency, internet_speed_mbps, timezone, visa_type, visa_expiry, overall_rating } = req.body;
  if (!city || !country || !arrival_date) return res.status(400).json({ error: 'city, country, arrival_date required' });
  const r = db.prepare(`INSERT INTO nomad_locations (user_id,city,country,arrival_date,departure_date,accommodation_type,accommodation_name,monthly_cost,currency,internet_speed_mbps,timezone,visa_type,visa_expiry,overall_rating) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, city, country, arrival_date, departure_date||null, accommodation_type||'apartment', accommodation_name||'', monthly_cost||0, currency||'USD', internet_speed_mbps||0, timezone||'UTC', visa_type||'tourist', visa_expiry||null, overall_rating||4);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/nomad/locations/:id/expenses', requireAuth, (req: any, res: any) => {
  const { expense_date, category, description, amount, currency, usd_amount } = req.body;
  if (!amount) return res.status(400).json({ error: 'amount required' });
  const r = db.prepare(`INSERT INTO nomad_expenses (location_id,user_id,expense_date,category,description,amount,currency,usd_amount) VALUES (?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, expense_date||new Date().toISOString().slice(0,10), category||'accommodation', description||'', amount, currency||'USD', usd_amount||amount);
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/nomad/stats', requireAuth, (req: any, res: any) => {
  const expenses = db.prepare(`SELECT category, SUM(usd_amount) as total FROM nomad_expenses WHERE user_id=? GROUP BY category ORDER BY total DESC`).all(req.user.id);
  const total_spent = db.prepare(`SELECT SUM(usd_amount) as total FROM nomad_expenses WHERE user_id=?`).get(req.user.id) as any;
  const avg_productivity = db.prepare(`SELECT AVG(productivity_rating) as avg FROM remote_work_sessions WHERE user_id=?`).get(req.user.id) as any;
  const top_cities = db.prepare(`SELECT city, country, overall_rating FROM nomad_locations WHERE user_id=? ORDER BY overall_rating DESC LIMIT 5`).all(req.user.id);
  res.json({ total_spent_usd: Math.round((total_spent?.total||0)*100)/100, expenses_by_category: expenses, avg_productivity: Math.round((avg_productivity?.avg||0)*10)/10, top_cities });
});
app.post('/api/nomad/locations/:id/work', requireAuth, (req: any, res: any) => {
  const { work_date, hours_worked, productivity_rating, tools_used, meeting_count } = req.body;
  const r = db.prepare(`INSERT INTO remote_work_sessions (location_id,user_id,work_date,hours_worked,productivity_rating,tools_used,meeting_count) VALUES (?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, work_date||new Date().toISOString().slice(0,10), hours_worked||8, productivity_rating||3, JSON.stringify(tools_used||[]), meeting_count||0);
  res.json({ id: r.lastInsertRowid });
});
