// ─── B381: Tabletop RPG Campaign Manager ──────────────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS rpg_campaigns (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, campaign_name TEXT,
    system TEXT DEFAULT 'DnD5e', setting TEXT, synopsis TEXT,
    gm_name TEXT, player_count INTEGER DEFAULT 4, status TEXT DEFAULT 'active',
    session_count INTEGER DEFAULT 0, total_hours REAL DEFAULT 0,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS rpg_characters (
    id INTEGER PRIMARY KEY AUTOINCREMENT, campaign_id INTEGER, user_id INTEGER,
    character_name TEXT, player_name TEXT, race TEXT, char_class TEXT,
    level INTEGER DEFAULT 1, background TEXT, alignment TEXT DEFAULT 'neutral',
    hp_current INTEGER DEFAULT 10, hp_max INTEGER DEFAULT 10,
    stats TEXT DEFAULT '{}', traits TEXT DEFAULT '[]',
    is_npc INTEGER DEFAULT 0, is_alive INTEGER DEFAULT 1,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS rpg_sessions_log (
    id INTEGER PRIMARY KEY AUTOINCREMENT, campaign_id INTEGER, user_id INTEGER,
    session_number INTEGER, session_date DATE, duration_hours REAL DEFAULT 3,
    title TEXT, summary TEXT, xp_awarded INTEGER DEFAULT 0,
    loot TEXT DEFAULT '[]', key_events TEXT DEFAULT '[]', cliffhanger TEXT,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS rpg_locations (
    id INTEGER PRIMARY KEY AUTOINCREMENT, campaign_id INTEGER, user_id INTEGER,
    location_name TEXT, location_type TEXT DEFAULT 'city', description TEXT,
    notable_npcs TEXT DEFAULT '[]', is_discovered INTEGER DEFAULT 0,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/rpg/campaigns', requireAuth, (req: any, res: any) => {
  const campaigns = db.prepare(`SELECT c.*, (SELECT COUNT(*) FROM rpg_characters WHERE campaign_id=c.id AND is_npc=0) as player_chars, (SELECT session_date FROM rpg_sessions_log WHERE campaign_id=c.id ORDER BY session_date DESC LIMIT 1) as last_session FROM rpg_campaigns c WHERE c.user_id=? ORDER BY c.status ASC, c.created_at DESC`).all(req.user.id);
  res.json({ campaigns });
});
app.post('/api/rpg/campaigns', requireAuth, (req: any, res: any) => {
  const { campaign_name, system, setting, synopsis, gm_name, player_count } = req.body;
  if (!campaign_name) return res.status(400).json({ error: 'campaign_name required' });
  const r = db.prepare(`INSERT INTO rpg_campaigns (user_id,campaign_name,system,setting,synopsis,gm_name,player_count) VALUES (?,?,?,?,?,?,?)`).run(req.user.id, campaign_name, system||'DnD5e', setting||'', synopsis||'', gm_name||'', player_count||4);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/rpg/campaigns/:id/characters', requireAuth, (req: any, res: any) => {
  const { character_name, player_name, race, char_class, level, background, alignment, hp_max, stats, is_npc } = req.body;
  if (!character_name) return res.status(400).json({ error: 'character_name required' });
  const r = db.prepare(`INSERT INTO rpg_characters (campaign_id,user_id,character_name,player_name,race,char_class,level,background,alignment,hp_current,hp_max,stats,is_npc) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, character_name, player_name||'', race||'human', char_class||'fighter', level||1, background||'', alignment||'neutral', hp_max||10, hp_max||10, JSON.stringify(stats||{}), is_npc?1:0);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/rpg/campaigns/:id/sessions', requireAuth, (req: any, res: any) => {
  const { session_date, duration_hours, title, summary, xp_awarded, loot, key_events, cliffhanger } = req.body;
  if (!session_date) return res.status(400).json({ error: 'session_date required' });
  const num = db.prepare(`SELECT COUNT(*) as c FROM rpg_sessions_log WHERE campaign_id=?`).get(req.params.id) as any;
  const r = db.prepare(`INSERT INTO rpg_sessions_log (campaign_id,user_id,session_number,session_date,duration_hours,title,summary,xp_awarded,loot,key_events,cliffhanger) VALUES (?,?,?,?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, (num?.c||0)+1, session_date, duration_hours||3, title||`Session ${(num?.c||0)+1}`, summary||'', xp_awarded||0, JSON.stringify(loot||[]), JSON.stringify(key_events||[]), cliffhanger||'');
  db.prepare(`UPDATE rpg_campaigns SET session_count=session_count+1, total_hours=total_hours+? WHERE id=?`).run(duration_hours||3, req.params.id);
  if (xp_awarded) db.prepare(`UPDATE rpg_characters SET level=MIN(20,level+CASE WHEN level<5 THEN ? ELSE 0 END) WHERE campaign_id=? AND is_npc=0`).run(xp_awarded>300?1:0, req.params.id);
  res.json({ id: r.lastInsertRowid, session_number: (num?.c||0)+1 });
});
app.get('/api/rpg/campaigns/:id', requireAuth, (req: any, res: any) => {
  const campaign = db.prepare(`SELECT * FROM rpg_campaigns WHERE id=? AND user_id=?`).get(req.params.id, req.user.id);
  if (!campaign) return res.status(404).json({ error: 'not found' });
  const characters = db.prepare(`SELECT * FROM rpg_characters WHERE campaign_id=? AND user_id=? ORDER BY is_npc ASC, character_name ASC`).all(req.params.id, req.user.id);
  const sessions = db.prepare(`SELECT * FROM rpg_sessions_log WHERE campaign_id=? AND user_id=? ORDER BY session_number DESC`).all(req.params.id, req.user.id);
  const locations = db.prepare(`SELECT * FROM rpg_locations WHERE campaign_id=? AND user_id=? ORDER BY location_name ASC`).all(req.params.id, req.user.id);
  res.json({ campaign, characters, sessions, locations });
});
