// ─── B384: Home Energy & Utilities Tracker ────────────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS utility_accounts (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, utility_type TEXT DEFAULT 'electricity',
    provider_name TEXT, account_number TEXT, monthly_budget REAL DEFAULT 0,
    billing_cycle_day INTEGER DEFAULT 1, notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS utility_bills (
    id INTEGER PRIMARY KEY AUTOINCREMENT, account_id INTEGER, user_id INTEGER,
    bill_date DATE, period_start DATE, period_end DATE, amount REAL DEFAULT 0,
    usage_amount REAL DEFAULT 0, usage_unit TEXT DEFAULT 'kWh',
    rate_per_unit REAL DEFAULT 0, is_paid INTEGER DEFAULT 0, notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS energy_improvements (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, improvement_name TEXT,
    category TEXT DEFAULT 'insulation', cost REAL DEFAULT 0, installation_date DATE,
    estimated_annual_savings REAL DEFAULT 0, payback_years REAL DEFAULT 0,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/utilities/accounts', requireAuth, (req: any, res: any) => {
  const accounts = db.prepare(`SELECT a.*, (SELECT SUM(amount) FROM utility_bills WHERE account_id=a.id AND bill_date>=date('now','start of year')) as ytd_spend, (SELECT AVG(amount) FROM utility_bills WHERE account_id=a.id AND bill_date>=date('now','-12 months')) as avg_monthly FROM utility_accounts a WHERE a.user_id=? ORDER BY a.utility_type ASC`).all(req.user.id);
  res.json({ accounts });
});
app.post('/api/utilities/accounts', requireAuth, (req: any, res: any) => {
  const { utility_type, provider_name, account_number, monthly_budget, billing_cycle_day } = req.body;
  if (!utility_type || !provider_name) return res.status(400).json({ error: 'utility_type and provider_name required' });
  const r = db.prepare(`INSERT INTO utility_accounts (user_id,utility_type,provider_name,account_number,monthly_budget,billing_cycle_day) VALUES (?,?,?,?,?,?)`).run(req.user.id, utility_type, provider_name, account_number||'', monthly_budget||0, billing_cycle_day||1);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/utilities/accounts/:id/bills', requireAuth, (req: any, res: any) => {
  const { bill_date, period_start, period_end, amount, usage_amount, usage_unit, rate_per_unit } = req.body;
  if (!bill_date || !amount) return res.status(400).json({ error: 'bill_date and amount required' });
  const acct = db.prepare(`SELECT * FROM utility_accounts WHERE id=? AND user_id=?`).get(req.params.id, req.user.id) as any;
  if (!acct) return res.status(404).json({ error: 'not found' });
  const r = db.prepare(`INSERT INTO utility_bills (account_id,user_id,bill_date,period_start,period_end,amount,usage_amount,usage_unit,rate_per_unit) VALUES (?,?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, bill_date, period_start||bill_date, period_end||bill_date, amount, usage_amount||0, usage_unit||'kWh', rate_per_unit||0);
  const over_budget = acct.monthly_budget > 0 && amount > acct.monthly_budget;
  res.json({ id: r.lastInsertRowid, over_budget, budget_diff: acct.monthly_budget > 0 ? Math.round((amount - acct.monthly_budget)*100)/100 : null });
});
app.get('/api/utilities/summary', requireAuth, (req: any, res: any) => {
  const by_type = db.prepare(`SELECT a.utility_type, SUM(b.amount) as ytd_total, AVG(b.amount) as avg_monthly FROM utility_bills b JOIN utility_accounts a ON b.account_id=a.id WHERE b.user_id=? AND b.bill_date>=date('now','start of year') GROUP BY a.utility_type`).all(req.user.id);
  const total_ytd = db.prepare(`SELECT SUM(amount) as t FROM utility_bills WHERE user_id=? AND bill_date>=date('now','start of year')`).get(req.user.id) as any;
  const unpaid = db.prepare(`SELECT COUNT(*) as c, SUM(amount) as total FROM utility_bills WHERE user_id=? AND is_paid=0`).get(req.user.id) as any;
  res.json({ by_type, total_ytd: total_ytd?.t||0, unpaid_count: unpaid?.c||0, unpaid_total: unpaid?.total||0 });
});
