// ─── B385: Vintage Clothing & Thrift Fashion Archive ──────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS wardrobe_items (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, item_name TEXT,
    category TEXT DEFAULT 'top', decade TEXT DEFAULT '1990s',
    brand TEXT, size TEXT, color TEXT DEFAULT 'black',
    material TEXT DEFAULT 'cotton', condition TEXT DEFAULT 'good',
    source TEXT DEFAULT 'thrift', purchase_date DATE, purchase_price REAL DEFAULT 0,
    est_value REAL DEFAULT 0, worn_count INTEGER DEFAULT 0,
    last_worn DATE, is_for_sale INTEGER DEFAULT 0, asking_price REAL DEFAULT 0,
    photo_url TEXT, notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS outfit_logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, outfit_name TEXT,
    wear_date DATE, item_ids TEXT DEFAULT '[]', occasion TEXT DEFAULT 'casual',
    weather TEXT DEFAULT 'mild', rating INTEGER DEFAULT 4,
    photo_url TEXT, notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS style_boards (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, board_name TEXT,
    aesthetic TEXT DEFAULT 'cottagecore', item_ids TEXT DEFAULT '[]',
    inspiration_links TEXT DEFAULT '[]', notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/wardrobe/items', requireAuth, (req: any, res: any) => {
  const { category, decade, is_for_sale } = req.query as any;
  let q = `SELECT * FROM wardrobe_items WHERE user_id=?`;
  const params: any[] = [req.user.id];
  if (category) { q += ` AND category=?`; params.push(category); }
  if (decade) { q += ` AND decade=?`; params.push(decade); }
  if (is_for_sale !== undefined) { q += ` AND is_for_sale=?`; params.push(is_for_sale==='true'?1:0); }
  q += ` ORDER BY category ASC, decade ASC`;
  const items = db.prepare(q).all(...params) as any[];
  const total_value = items.reduce((s: number, i: any) => s + i.est_value, 0);
  const total_cost = items.reduce((s: number, i: any) => s + i.purchase_price, 0);
  res.json({ items, total_value, total_cost, count: items.length });
});
app.post('/api/wardrobe/items', requireAuth, (req: any, res: any) => {
  const { item_name, category, decade, brand, size, color, material, condition, source, purchase_date, purchase_price, est_value, photo_url } = req.body;
  if (!item_name) return res.status(400).json({ error: 'item_name required' });
  const r = db.prepare(`INSERT INTO wardrobe_items (user_id,item_name,category,decade,brand,size,color,material,condition,source,purchase_date,purchase_price,est_value,photo_url) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, item_name, category||'top', decade||'1990s', brand||'', size||'', color||'black', material||'cotton', condition||'good', source||'thrift', purchase_date||null, purchase_price||0, est_value||purchase_price||0, photo_url||'');
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/wardrobe/outfits', requireAuth, (req: any, res: any) => {
  const { outfit_name, wear_date, item_ids, occasion, weather, rating, photo_url } = req.body;
  if (!item_ids?.length) return res.status(400).json({ error: 'item_ids required' });
  const r = db.prepare(`INSERT INTO outfit_logs (user_id,outfit_name,wear_date,item_ids,occasion,weather,rating,photo_url) VALUES (?,?,?,?,?,?,?,?)`).run(req.user.id, outfit_name||'Outfit', wear_date||new Date().toISOString().slice(0,10), JSON.stringify(item_ids), occasion||'casual', weather||'mild', rating||4, photo_url||'');
  (item_ids as number[]).forEach((id: number) => {
    db.prepare(`UPDATE wardrobe_items SET worn_count=worn_count+1, last_worn=? WHERE id=? AND user_id=?`).run(wear_date||new Date().toISOString().slice(0,10), id, req.user.id);
  });
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/wardrobe/stats', requireAuth, (req: any, res: any) => {
  const by_decade = db.prepare(`SELECT decade, COUNT(*) as count FROM wardrobe_items WHERE user_id=? GROUP BY decade ORDER BY count DESC`).all(req.user.id);
  const by_category = db.prepare(`SELECT category, COUNT(*) as count FROM wardrobe_items WHERE user_id=? GROUP BY category ORDER BY count DESC`).all(req.user.id);
  const never_worn = db.prepare(`SELECT COUNT(*) as c FROM wardrobe_items WHERE user_id=? AND worn_count=0`).get(req.user.id) as any;
  const total = db.prepare(`SELECT COUNT(*) as c, SUM(est_value) as val, SUM(purchase_price) as cost FROM wardrobe_items WHERE user_id=?`).get(req.user.id) as any;
  res.json({ by_decade, by_category, never_worn_count: never_worn?.c||0, total_items: total?.c||0, total_value: total?.val||0, total_cost: total?.cost||0, gain_loss: (total?.val||0)-(total?.cost||0) });
});
// ─── End B385 ────────────────────────────────────────────────────────────────

// ─── B386: Mushroom Cultivation & Growing Log ─────────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS mushroom_grows (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, species TEXT,
    substrate TEXT DEFAULT 'straw', container_type TEXT DEFAULT 'bag',
    inoculation_date DATE, colonization_complete DATE, fruiting_start DATE,
    status TEXT DEFAULT 'colonizing', spawn_source TEXT DEFAULT 'purchased',
    spawn_weight_g REAL DEFAULT 100, substrate_weight_g REAL DEFAULT 1000,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS mushroom_flushes (
    id INTEGER PRIMARY KEY AUTOINCREMENT, grow_id INTEGER, user_id INTEGER,
    flush_number INTEGER, harvest_date DATE, yield_grams REAL DEFAULT 0,
    quality TEXT DEFAULT 'good', pin_count INTEGER DEFAULT 0,
    photo_url TEXT, notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS mushroom_recipes_grow (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, recipe_name TEXT,
    species TEXT, substrate_recipe TEXT, notes TEXT,
    success_rate INTEGER DEFAULT 80, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/mushroom/grows', requireAuth, (req: any, res: any) => {
  const grows = db.prepare(`SELECT g.*, (SELECT COUNT(*) FROM mushroom_flushes WHERE grow_id=g.id) as flush_count, (SELECT SUM(yield_grams) FROM mushroom_flushes WHERE grow_id=g.id) as total_yield FROM mushroom_grows g WHERE g.user_id=? ORDER BY g.inoculation_date DESC`).all(req.user.id);
  res.json({ grows });
});
app.post('/api/mushroom/grows', requireAuth, (req: any, res: any) => {
  const { species, substrate, container_type, inoculation_date, spawn_source, spawn_weight_g, substrate_weight_g } = req.body;
  if (!species) return res.status(400).json({ error: 'species required' });
  const r = db.prepare(`INSERT INTO mushroom_grows (user_id,species,substrate,container_type,inoculation_date,spawn_source,spawn_weight_g,substrate_weight_g) VALUES (?,?,?,?,?,?,?,?)`).run(req.user.id, species, substrate||'straw', container_type||'bag', inoculation_date||new Date().toISOString().slice(0,10), spawn_source||'purchased', spawn_weight_g||100, substrate_weight_g||1000);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/mushroom/grows/:id/flush', requireAuth, (req: any, res: any) => {
  const { harvest_date, yield_grams, quality, pin_count, photo_url, notes } = req.body;
  if (!harvest_date || !yield_grams) return res.status(400).json({ error: 'harvest_date and yield_grams required' });
  const fn = db.prepare(`SELECT COUNT(*) as c FROM mushroom_flushes WHERE grow_id=?`).get(req.params.id) as any;
  const r = db.prepare(`INSERT INTO mushroom_flushes (grow_id,user_id,flush_number,harvest_date,yield_grams,quality,pin_count,photo_url,notes) VALUES (?,?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, (fn?.c||0)+1, harvest_date, yield_grams, quality||'good', pin_count||0, photo_url||'', notes||'');
  db.prepare(`UPDATE mushroom_grows SET status='fruiting' WHERE id=? AND user_id=?`).run(req.params.id, req.user.id);
  res.json({ id: r.lastInsertRowid, flush_number: (fn?.c||0)+1 });
});
app.get('/api/mushroom/stats', requireAuth, (req: any, res: any) => {
  const by_species = db.prepare(`SELECT g.species, COUNT(*) as grow_count, SUM(f.yield_grams) as total_yield FROM mushroom_grows g LEFT JOIN mushroom_flushes f ON f.grow_id=g.id WHERE g.user_id=? GROUP BY g.species ORDER BY total_yield DESC`).all(req.user.id);
  const total = db.prepare(`SELECT SUM(f.yield_grams) as total FROM mushroom_flushes f JOIN mushroom_grows g ON f.grow_id=g.id WHERE f.user_id=?`).get(req.user.id) as any;
  res.json({ by_species, total_yield_grams: total?.total||0 });
});
