// ─── B387: Chess & Board Game Rating Tracker ──────────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS game_profiles (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, game_name TEXT,
    platform TEXT DEFAULT 'otb', username TEXT, current_rating INTEGER DEFAULT 1200,
    peak_rating INTEGER DEFAULT 1200, started_date DATE,
    preferred_time_control TEXT DEFAULT 'rapid', notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS game_results (
    id INTEGER PRIMARY KEY AUTOINCREMENT, profile_id INTEGER, user_id INTEGER,
    game_date DATE, opponent_name TEXT, opponent_rating INTEGER DEFAULT 1200,
    result TEXT DEFAULT 'draw', color TEXT DEFAULT 'white',
    opening TEXT DEFAULT 'unknown', time_control TEXT DEFAULT 'rapid',
    rating_before INTEGER DEFAULT 0, rating_after INTEGER DEFAULT 0,
    rating_change INTEGER DEFAULT 0, duration_min INTEGER DEFAULT 10,
    pgn TEXT, analysis TEXT, mistakes INTEGER DEFAULT 0, blunders INTEGER DEFAULT 0,
    accuracy REAL DEFAULT 0, notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS study_sessions_game (
    id INTEGER PRIMARY KEY AUTOINCREMENT, profile_id INTEGER, user_id INTEGER,
    session_date DATE, duration_min INTEGER DEFAULT 30, study_type TEXT DEFAULT 'tactics',
    topics TEXT DEFAULT '[]', puzzles_solved INTEGER DEFAULT 0,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/chess/profiles', requireAuth, (req: any, res: any) => {
  const profiles = db.prepare(`SELECT p.*, (SELECT COUNT(*) FROM game_results WHERE profile_id=p.id) as games_played FROM game_profiles p WHERE p.user_id=? ORDER BY p.game_name ASC`).all(req.user.id);
  res.json({ profiles });
});
app.post('/api/chess/profiles', requireAuth, (req: any, res: any) => {
  const { game_name, platform, username, current_rating, started_date, preferred_time_control } = req.body;
  if (!game_name) return res.status(400).json({ error: 'game_name required' });
  const r = db.prepare(`INSERT INTO game_profiles (user_id,game_name,platform,username,current_rating,peak_rating,started_date,preferred_time_control) VALUES (?,?,?,?,?,?,?,?)`).run(req.user.id, game_name, platform||'otb', username||'', current_rating||1200, current_rating||1200, started_date||null, preferred_time_control||'rapid');
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/chess/profiles/:id/games', requireAuth, (req: any, res: any) => {
  const { game_date, opponent_name, opponent_rating, result, color, opening, time_control, rating_before, rating_after, duration_min, mistakes, blunders, accuracy } = req.body;
  if (!game_date || !result) return res.status(400).json({ error: 'game_date and result required' });
  const rc = result==='win'?10:result==='loss'?-10:0;
  const ra = rating_after || (rating_before||0) + rc;
  const r = db.prepare(`INSERT INTO game_results (profile_id,user_id,game_date,opponent_name,opponent_rating,result,color,opening,time_control,rating_before,rating_after,rating_change,duration_min,mistakes,blunders,accuracy) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, game_date, opponent_name||'Anonymous', opponent_rating||1200, result, color||'white', opening||'unknown', time_control||'rapid', rating_before||0, ra, rc, duration_min||10, mistakes||0, blunders||0, accuracy||0);
  if (rating_after) { db.prepare(`UPDATE game_profiles SET current_rating=?, peak_rating=MAX(peak_rating,?) WHERE id=?`).run(rating_after, rating_after, req.params.id); }
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/chess/profiles/:id/stats', requireAuth, (req: any, res: any) => {
  const wins = db.prepare(`SELECT COUNT(*) as c FROM game_results WHERE profile_id=? AND user_id=? AND result='win'`).get(req.params.id, req.user.id) as any;
  const losses = db.prepare(`SELECT COUNT(*) as c FROM game_results WHERE profile_id=? AND user_id=? AND result='loss'`).get(req.params.id, req.user.id) as any;
  const draws = db.prepare(`SELECT COUNT(*) as c FROM game_results WHERE profile_id=? AND user_id=? AND result='draw'`).get(req.params.id, req.user.id) as any;
  const avg_acc = db.prepare(`SELECT AVG(accuracy) as a FROM game_results WHERE profile_id=? AND user_id=? AND accuracy>0`).get(req.params.id, req.user.id) as any;
  const by_opening = db.prepare(`SELECT opening, COUNT(*) as c, SUM(CASE WHEN result='win' THEN 1 ELSE 0 END) as wins FROM game_results WHERE profile_id=? AND user_id=? GROUP BY opening ORDER BY c DESC LIMIT 5`).all(req.params.id, req.user.id);
  const total = (wins?.c||0)+(losses?.c||0)+(draws?.c||0);
  res.json({ wins: wins?.c||0, losses: losses?.c||0, draws: draws?.c||0, total, win_rate: total?Math.round(wins?.c/total*100):0, avg_accuracy: Math.round((avg_acc?.a||0)*10)/10, by_opening });
});
// ─── End B387 ────────────────────────────────────────────────────────────────

