app.get('/api/library/books', requireAuth, (req: any, res: any) => {
  const { status, genre } = req.query as any;
  let q = `SELECT * FROM book_library WHERE user_id=?`;
  const params: any[] = [req.user.id];
  if (status) { q += ` AND status=?`; params.push(status); }
  if (genre) { q += ` AND genre=?`; params.push(genre); }
  q += ` ORDER BY author ASC, title ASC`;
  const books = db.prepare(q).all(...params) as any[];
  res.json({ books, count: books.length });
});
app.post('/api/library/books', requireAuth, (req: any, res: any) => {
  const { title, author, isbn, genre, publication_year, edition, condition, source, purchase_price, shelf_location } = req.body;
  if (!title || !author) return res.status(400).json({ error: 'title and author required' });
  const r = db.prepare(`INSERT INTO book_library (user_id,title,author,isbn,genre,publication_year,edition,condition,source,purchase_price,shelf_location,date_added) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, title, author, isbn||'', genre||'fiction', publication_year||2000, edition||'', condition||'good', source||'purchased', purchase_price||0, shelf_location||'', new Date().toISOString().slice(0,10));
  res.json({ id: r.lastInsertRowid });
});
app.put('/api/library/books/:id/status', requireAuth, (req: any, res: any) => {
  const { status, rating, review } = req.body;
  if (!status) return res.status(400).json({ error: 'status required' });
  const updates: any = { status };
  if (status==='reading') updates.date_started = new Date().toISOString().slice(0,10);
  if (status==='finished') { updates.date_finished = new Date().toISOString().slice(0,10); if (rating) updates.rating = rating; if (review) updates.review = review; }
  const setClauses = Object.keys(updates).map((k: string) => `${k}=?`).join(',');
  db.prepare(`UPDATE book_library SET ${setClauses} WHERE id=? AND user_id=?`).run(...Object.values(updates) as any[], req.params.id, req.user.id);
  res.json({ success: true });
});
app.get('/api/library/stats', requireAuth, (req: any, res: any) => {
  const by_status = db.prepare(`SELECT status, COUNT(*) as c FROM book_library WHERE user_id=? GROUP BY status`).all(req.user.id);
  const total_spent = db.prepare(`SELECT SUM(purchase_price) as t FROM book_library WHERE user_id=?`).get(req.user.id) as any;
  const by_genre = db.prepare(`SELECT genre, COUNT(*) as c FROM book_library WHERE user_id=? GROUP BY genre ORDER BY c DESC LIMIT 10`).all(req.user.id);
  const this_year = db.prepare(`SELECT COUNT(*) as c FROM book_library WHERE user_id=? AND date_finished>=date('now','start of year')`).get(req.user.id) as any;
  res.json({ by_status, total_spent: total_spent?.t||0, by_genre, read_this_year: this_year?.c||0 });
});
