app.get('/api/community/stats', requireAuth, (req: any, res: any) => {
  const members = db.prepare(`SELECT COUNT(*) as c FROM community_members WHERE user_id=?`).get(req.user.id) as any;
  const aid = db.prepare(`SELECT aid_type, COUNT(*) as c, SUM(value_est) as val FROM mutual_aid_log WHERE user_id=? GROUP BY aid_type`).all(req.user.id);
  const skills_pool = db.prepare(`SELECT skills_offered FROM community_members WHERE user_id=?`).all(req.user.id) as any[];
  const all_skills = skills_pool.flatMap((m: any) => { try { return JSON.parse(m.skills_offered||'[]'); } catch { return []; } });
  const skill_counts: Record<string, number> = {};
  all_skills.forEach((s: string) => { skill_counts[s] = (skill_counts[s]||0)+1; });
  const top_skills = Object.entries(skill_counts).sort((a,b) => b[1]-a[1]).slice(0,10);
  res.json({ member_count: members?.c||0, aid_summary: aid, top_skills });
});
