  const r = db.prepare(`INSERT INTO garden_care_log (container_id,plant_id,user_id,care_date,care_type,notes) VALUES (?,?,?,?,?,?)`).run(container_id||null, plant_id||null, req.user.id, care_date||new Date().toISOString().slice(0,10), care_type, notes||'');
