// ─── B397: Crypto & NFT Portfolio Journal ─────────────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS crypto_holdings (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, symbol TEXT,
    name TEXT, blockchain TEXT DEFAULT 'ethereum', quantity REAL DEFAULT 0,
    avg_buy_price REAL DEFAULT 0, current_price REAL DEFAULT 0,
    wallet_address TEXT, exchange TEXT DEFAULT 'coinbase',
    is_staking INTEGER DEFAULT 0, staking_apy REAL DEFAULT 0,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS crypto_transactions (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, symbol TEXT,
    tx_type TEXT DEFAULT 'buy', quantity REAL DEFAULT 0, price_per_unit REAL DEFAULT 0,
    total_value REAL DEFAULT 0, fee REAL DEFAULT 0, tx_date DATE,
    exchange TEXT, tx_hash TEXT, notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS nft_holdings (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, nft_name TEXT,
    collection TEXT, token_id TEXT, blockchain TEXT DEFAULT 'ethereum',
    purchase_price_eth REAL DEFAULT 0, purchase_date DATE,
    current_floor_eth REAL DEFAULT 0, wallet TEXT, marketplace TEXT DEFAULT 'opensea',
    is_listed INTEGER DEFAULT 0, list_price_eth REAL DEFAULT 0,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/crypto/holdings', requireAuth, (req: any, res: any) => {
  const holdings = db.prepare(`SELECT * FROM crypto_holdings WHERE user_id=? ORDER BY symbol ASC`).all(req.user.id) as any[];
  const portfolio_value = holdings.reduce((s: number, h: any) => s + h.quantity * h.current_price, 0);
  const cost_basis = holdings.reduce((s: number, h: any) => s + h.quantity * h.avg_buy_price, 0);
  res.json({ holdings: holdings.map((h: any) => ({ ...h, current_value: h.quantity*h.current_price, pnl: (h.current_price-h.avg_buy_price)*h.quantity })), portfolio_value: Math.round(portfolio_value*100)/100, cost_basis: Math.round(cost_basis*100)/100, total_pnl: Math.round((portfolio_value-cost_basis)*100)/100 });
});
app.post('/api/crypto/holdings', requireAuth, (req: any, res: any) => {
  const { symbol, name, blockchain, quantity, avg_buy_price, current_price, exchange, is_staking, staking_apy } = req.body;
  if (!symbol || !quantity) return res.status(400).json({ error: 'symbol and quantity required' });
  const existing = db.prepare(`SELECT id FROM crypto_holdings WHERE user_id=? AND symbol=? AND exchange=?`).get(req.user.id, symbol.toUpperCase(), exchange||'coinbase') as any;
  if (existing) {
    db.prepare(`UPDATE crypto_holdings SET quantity=quantity+?, current_price=? WHERE id=?`).run(quantity, current_price||0, existing.id);
    res.json({ id: existing.id, updated: true });
  } else {
    const r = db.prepare(`INSERT INTO crypto_holdings (user_id,symbol,name,blockchain,quantity,avg_buy_price,current_price,exchange,is_staking,staking_apy) VALUES (?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, symbol.toUpperCase(), name||symbol, blockchain||'ethereum', quantity, avg_buy_price||0, current_price||0, exchange||'coinbase', is_staking?1:0, staking_apy||0);
    res.json({ id: r.lastInsertRowid });
  }
});
app.post('/api/crypto/transactions', requireAuth, (req: any, res: any) => {
  const { symbol, tx_type, quantity, price_per_unit, fee, tx_date, exchange, tx_hash } = req.body;
  if (!symbol || !quantity) return res.status(400).json({ error: 'symbol and quantity required' });
  const total = quantity * (price_per_unit||0);
  const r = db.prepare(`INSERT INTO crypto_transactions (user_id,symbol,tx_type,quantity,price_per_unit,total_value,fee,tx_date,exchange,tx_hash) VALUES (?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, symbol.toUpperCase(), tx_type||'buy', quantity, price_per_unit||0, total, fee||0, tx_date||new Date().toISOString().slice(0,10), exchange||'', tx_hash||'');
  res.json({ id: r.lastInsertRowid, total_value: total });
});
app.get('/api/crypto/summary', requireAuth, (req: any, res: any) => {
  const realized = db.prepare(`SELECT SUM(CASE WHEN tx_type='sell' THEN total_value ELSE -total_value END) as pnl FROM crypto_transactions WHERE user_id=? AND tx_type IN ('buy','sell')`).get(req.user.id) as any;
  const total_fees = db.prepare(`SELECT SUM(fee) as f FROM crypto_transactions WHERE user_id=?`).get(req.user.id) as any;
  const nft_count = db.prepare(`SELECT COUNT(*) as c FROM nft_holdings WHERE user_id=?`).get(req.user.id) as any;
  res.json({ realized_pnl: realized?.pnl||0, total_fees: total_fees?.f||0, nft_count: nft_count?.c||0 });
});
// ─── End B397 ────────────────────────────────────────────────────────────────

// ─── B398: Food Waste & Sustainability Tracker ────────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS waste_log (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, log_date DATE,
    item_name TEXT, food_category TEXT DEFAULT 'vegetables',
    quantity_grams REAL DEFAULT 100, reason TEXT DEFAULT 'expired',
    money_wasted REAL DEFAULT 0, preventable INTEGER DEFAULT 1,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS sustainability_goals_food (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, goal_name TEXT,
    goal_type TEXT DEFAULT 'reduce_waste', target_value REAL DEFAULT 0,
    target_unit TEXT DEFAULT 'grams_per_week', current_value REAL DEFAULT 0,
    start_date DATE, end_date DATE, achieved INTEGER DEFAULT 0,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS eco_actions (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, action_date DATE,
    action_type TEXT DEFAULT 'composting', description TEXT,
    impact_score INTEGER DEFAULT 3, co2_saved_kg REAL DEFAULT 0,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.post('/api/foodwaste/log', requireAuth, (req: any, res: any) => {
  const { log_date, item_name, food_category, quantity_grams, reason, money_wasted, preventable } = req.body;
  if (!item_name || !quantity_grams) return res.status(400).json({ error: 'item_name and quantity_grams required' });
  const r = db.prepare(`INSERT INTO waste_log (user_id,log_date,item_name,food_category,quantity_grams,reason,money_wasted,preventable) VALUES (?,?,?,?,?,?,?,?)`).run(req.user.id, log_date||new Date().toISOString().slice(0,10), item_name, food_category||'vegetables', quantity_grams, reason||'expired', money_wasted||0, preventable?1:1);
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/foodwaste/summary', requireAuth, (req: any, res: any) => {
  const period = 30;
  const total = db.prepare(`SELECT COUNT(*) as c, SUM(quantity_grams) as grams, SUM(money_wasted) as money, SUM(preventable) as prev FROM waste_log WHERE user_id=? AND log_date>=date('now','-${period} days')`).get(req.user.id) as any;
  const by_category = db.prepare(`SELECT food_category, COUNT(*) as c, SUM(quantity_grams) as grams FROM waste_log WHERE user_id=? AND log_date>=date('now','-${period} days') GROUP BY food_category ORDER BY grams DESC`).all(req.user.id);
  const by_reason = db.prepare(`SELECT reason, COUNT(*) as c FROM waste_log WHERE user_id=? AND log_date>=date('now','-${period} days') GROUP BY reason ORDER BY c DESC`).all(req.user.id);
  res.json({ period_days: period, total_items: total?.c||0, total_grams: total?.grams||0, money_wasted: total?.money||0, preventable_count: total?.prev||0, by_category, by_reason });
});
app.post('/api/foodwaste/eco-actions', requireAuth, (req: any, res: any) => {
  const { action_date, action_type, description, impact_score, co2_saved_kg } = req.body;
  if (!action_type) return res.status(400).json({ error: 'action_type required' });
  const r = db.prepare(`INSERT INTO eco_actions (user_id,action_date,action_type,description,impact_score,co2_saved_kg) VALUES (?,?,?,?,?,?)`).run(req.user.id, action_date||new Date().toISOString().slice(0,10), action_type, description||'', impact_score||3, co2_saved_kg||0);
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/foodwaste/eco-stats', requireAuth, (req: any, res: any) => {
  const eco = db.prepare(`SELECT COUNT(*) as c, SUM(co2_saved_kg) as co2, AVG(impact_score) as avg_impact FROM eco_actions WHERE user_id=?`).get(req.user.id) as any;
  const by_type = db.prepare(`SELECT action_type, COUNT(*) as c, SUM(co2_saved_kg) as co2 FROM eco_actions WHERE user_id=? GROUP BY action_type ORDER BY co2 DESC`).all(req.user.id);
  res.json({ total_actions: eco?.c||0, total_co2_saved_kg: eco?.co2||0, avg_impact: Math.round((eco?.avg_impact||0)*10)/10, by_type });
});
