app.post('/api/fermentation/batches', requireAuth, (req: any, res: any) => {
  const { batch_name, ferment_type, start_date, vessel_liters, tea_type, sugar_grams, starter_ml, scoby_weight_grams } = req.body;
  if (!batch_name) return res.status(400).json({ error: 'batch_name required' });
  const r = db.prepare(`INSERT INTO fermentation_batches (user_id,batch_name,ferment_type,start_date,vessel_liters,tea_type,sugar_grams,starter_ml,scoby_weight_grams) VALUES (?,?,?,?,?,?,?,?,?)`).run(req.user.id, batch_name, ferment_type||'kombucha', start_date||new Date().toISOString().slice(0,10), vessel_liters||4, tea_type||'black', sugar_grams||100, starter_ml||400, scoby_weight_grams||150);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/fermentation/batches/:id/readings', requireAuth, (req: any, res: any) => {
  const { reading_date, ph, temp_celsius, taste_notes, sweetness, sourness } = req.body;
  const batch = db.prepare(`SELECT start_date FROM fermentation_batches WHERE id=?`).get(req.params.id) as any;
  const day = batch ? Math.floor((new Date(reading_date||new Date()).getTime() - new Date(batch.start_date).getTime())/86400000) : 0;
  const r = db.prepare(`INSERT INTO ferment_readings (batch_id,user_id,reading_date,ph,temp_celsius,taste_notes,sweetness,sourness,day_number) VALUES (?,?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, reading_date||new Date().toISOString().slice(0,10), ph||3.2, temp_celsius||24, taste_notes||'', sweetness||3, sourness||3, day);
  const is_ready = (ph||3.2) <= 3.5 && (sourness||3) >= 3;
  res.json({ id: r.lastInsertRowid, day_number: day, is_ready_for_f2: is_ready });
});
app.post('/api/fermentation/batches/:id/bottle', requireAuth, (req: any, res: any) => {
  const { bottle_date, flavor, bottles_count, sugar_added_grams, fruit_grams, f2_days } = req.body;
  if (!bottle_date) return res.status(400).json({ error: 'bottle_date required' });
  const r = db.prepare(`INSERT INTO ferment_bottles (batch_id,user_id,bottle_date,flavor,bottles_count,sugar_added_grams,fruit_grams,f2_days) VALUES (?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, bottle_date, flavor||'plain', bottles_count||6, sugar_added_grams||0, fruit_grams||0, f2_days||3);
  db.prepare(`UPDATE fermentation_batches SET status='bottled', phase='F2' WHERE id=? AND user_id=?`).run(req.params.id, req.user.id);
  res.json({ id: r.lastInsertRowid, ready_date: new Date(new Date(bottle_date).getTime()+(f2_days||3)*86400000).toISOString().slice(0,10) });
});
