app.get('/api/affirmations', requireAuth, (req: any, res: any) => {
  const { category, is_favorite } = req.query as any;
  let q = `SELECT * FROM affirmations WHERE user_id=? AND is_active=1`;
  const params: any[] = [req.user.id];
  if (category) { q += ` AND category=?`; params.push(category); }
  if (is_favorite === '1') { q += ` AND is_favorite=1`; }
  q += ` ORDER BY resonance_score DESC, times_used DESC`;
  const affirmations = db.prepare(q).all(...params);
  res.json({ affirmations });
});
app.post('/api/affirmations', requireAuth, (req: any, res: any) => {
  const { text, category, source } = req.body;
  if (!text) return res.status(400).json({ error: 'text required' });
  const r = db.prepare(`INSERT INTO affirmations (user_id,text,category,source) VALUES (?,?,?,?)`).run(req.user.id, text, category||'self-worth', source||'personal');
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/affirmations/daily', requireAuth, (req: any, res: any) => {
  const pool = db.prepare(`SELECT * FROM affirmations WHERE user_id=? AND is_active=1 ORDER BY RANDOM() LIMIT 5`).all(req.user.id) as any[];
  const favorites = db.prepare(`SELECT * FROM affirmations WHERE user_id=? AND is_favorite=1 AND is_active=1 ORDER BY RANDOM() LIMIT 2`).all(req.user.id) as any[];
  const daily = [...favorites, ...pool].slice(0, 5);
  res.json({ daily, count: daily.length, date: new Date().toISOString().slice(0,10) });
});
app.post('/api/affirmations/sessions', requireAuth, (req: any, res: any) => {
  const { session_date, session_type, affirmations_used, mood_before, mood_after, duration_mins } = req.body;
  const r = db.prepare(`INSERT INTO affirmation_sessions (user_id,session_date,session_type,affirmations_used,mood_before,mood_after,duration_mins) VALUES (?,?,?,?,?,?,?)`).run(req.user.id, session_date||new Date().toISOString().slice(0,10), session_type||'morning', JSON.stringify(affirmations_used||[]), mood_before||3, mood_after||4, duration_mins||5);
  const mood_lift = (mood_after||4) - (mood_before||3);
  if (affirmations_used?.length) {
    const stmt = db.prepare(`UPDATE affirmations SET times_used=times_used+1, resonance_score=ROUND((resonance_score*times_used+?)/(times_used+1),2) WHERE id=? AND user_id=?`);
    (affirmations_used as number[]).forEach((aid: number) => stmt.run(mood_lift > 0 ? mood_after : 3, aid, req.user.id));
  }
  res.json({ id: r.lastInsertRowid, mood_lift });
});
