  db.prepare(`UPDATE antiques SET current_value=?, last_appraised=?, appraiser_name=? WHERE id=? AND user_id=?`).run(appraised_value, appraisal_date||new Date().toISOString().slice(0,10), appraiser_name||'', req.params.id, req.user.id);
