try { db.exec(`
  CREATE TABLE IF NOT EXISTS bucket_items (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, title TEXT,
    description TEXT, category TEXT DEFAULT 'travel', priority INTEGER DEFAULT 2,
    target_date DATE, completed_date DATE, is_completed INTEGER DEFAULT 0,
    difficulty TEXT DEFAULT 'medium', estimated_cost REAL DEFAULT 0,
    actual_cost REAL DEFAULT 0, location TEXT, with_whom TEXT DEFAULT '[]',
    photo_urls TEXT DEFAULT '[]', story TEXT, tags TEXT DEFAULT '[]',
    is_public INTEGER DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS bucket_milestones (
    id INTEGER PRIMARY KEY AUTOINCREMENT, bucket_item_id INTEGER, user_id INTEGER,
    milestone_text TEXT, target_date DATE, completed_date DATE,
    is_completed INTEGER DEFAULT 0, notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/bucket', requireAuth, (req: any, res: any) => {
  const { category, is_completed } = req.query as any;
  let q = `SELECT b.*, (SELECT COUNT(*) FROM bucket_milestones WHERE bucket_item_id=b.id AND is_completed=1) as milestones_done, (SELECT COUNT(*) FROM bucket_milestones WHERE bucket_item_id=b.id) as milestones_total FROM bucket_items b WHERE b.user_id=?`;
  const params: any[] = [req.user.id];
  if (category) { q += ` AND b.category=?`; params.push(category); }
  if (is_completed !== undefined) { q += ` AND b.is_completed=?`; params.push(is_completed === '1' ? 1 : 0); }
  q += ` ORDER BY b.priority DESC, b.target_date ASC NULLS LAST`;
  const items = db.prepare(q).all(...params) as any[];
  const stats = { total: items.length, completed: items.filter((i: any) => i.is_completed).length, total_cost: items.reduce((s: number, i: any) => s + i.actual_cost, 0) };
  res.json({ items, stats, completion_pct: stats.total ? Math.round(stats.completed/stats.total*100) : 0 });
});
app.post('/api/bucket', requireAuth, (req: any, res: any) => {
  const { title, description, category, priority, target_date, difficulty, estimated_cost, location, tags } = req.body;
  if (!title) return res.status(400).json({ error: 'title required' });
  const r = db.prepare(`INSERT INTO bucket_items (user_id,title,description,category,priority,target_date,difficulty,estimated_cost,location,tags) VALUES (?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, title, description||'', category||'travel', priority||2, target_date||null, difficulty||'medium', estimated_cost||0, location||'', JSON.stringify(tags||[]));
  res.json({ id: r.lastInsertRowid });
});
app.put('/api/bucket/:id/complete', requireAuth, (req: any, res: any) => {
  const { completed_date, actual_cost, story } = req.body;
  db.prepare(`UPDATE bucket_items SET is_completed=1, completed_date=?, actual_cost=?, story=? WHERE id=? AND user_id=?`).run(completed_date||new Date().toISOString().slice(0,10), actual_cost||0, story||'', req.params.id, req.user.id);
  const total = (db.prepare(`SELECT COUNT(*) as c FROM bucket_items WHERE user_id=?`).get(req.user.id) as any)?.c||1;
  const done = (db.prepare(`SELECT COUNT(*) as c FROM bucket_items WHERE user_id=? AND is_completed=1`).get(req.user.id) as any)?.c||0;
  res.json({ success: true, total_completed: done, completion_pct: Math.round(done/total*100) });
});
