// ─── B425: Personal Energy Audit & Flow State Tracker ────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS energy_logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, log_date DATE,
    log_time TEXT, energy_level INTEGER DEFAULT 5, mental_clarity INTEGER DEFAULT 5,
    physical_energy INTEGER DEFAULT 5, emotional_energy INTEGER DEFAULT 5,
    activity TEXT DEFAULT 'working', location TEXT DEFAULT 'home',
    sleep_hours REAL DEFAULT 7, caffeine_mg INTEGER DEFAULT 100,
    meal_timing TEXT DEFAULT 'recent', stress_level INTEGER DEFAULT 3,
    flow_state_mins INTEGER DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS flow_activities (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, activity_name TEXT,
    category TEXT DEFAULT 'work', avg_flow_mins REAL DEFAULT 0,
    total_sessions INTEGER DEFAULT 0, peak_time_of_day TEXT DEFAULT 'morning',
    optimal_conditions TEXT DEFAULT '[]', flow_triggers TEXT DEFAULT '[]',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS energy_patterns (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, pattern_name TEXT,
    hour_of_day INTEGER DEFAULT 9, day_of_week TEXT DEFAULT 'Monday',
    avg_energy REAL DEFAULT 7, avg_clarity REAL DEFAULT 7,
    sample_count INTEGER DEFAULT 0, last_updated DATE,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.post('/api/energy/logs', requireAuth, (req: any, res: any) => {
  const { log_date, log_time, energy_level, mental_clarity, physical_energy, emotional_energy, activity, location, sleep_hours, caffeine_mg, flow_state_mins } = req.body;
  const r = db.prepare(`INSERT INTO energy_logs (user_id,log_date,log_time,energy_level,mental_clarity,physical_energy,emotional_energy,activity,location,sleep_hours,caffeine_mg,flow_state_mins) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, log_date||new Date().toISOString().slice(0,10), log_time||new Date().toTimeString().slice(0,5), energy_level||5, mental_clarity||5, physical_energy||5, emotional_energy||5, activity||'working', location||'home', sleep_hours||7, caffeine_mg||100, flow_state_mins||0);
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/energy/patterns', requireAuth, (req: any, res: any) => {
  const hourly = db.prepare(`SELECT CAST(substr(log_time,1,2) AS INTEGER) as hour, AVG(energy_level) as avg_e, AVG(mental_clarity) as avg_c, COUNT(*) as n FROM energy_logs WHERE user_id=? GROUP BY hour ORDER BY hour ASC`).all(req.user.id) as any[];
  const best_hour = hourly.reduce((best: any, h: any) => h.avg_e > (best?.avg_e||0) ? h : best, null);
  const by_activity = db.prepare(`SELECT activity, AVG(energy_level) as avg_e, AVG(flow_state_mins) as avg_flow FROM energy_logs WHERE user_id=? GROUP BY activity ORDER BY avg_e DESC LIMIT 10`).all(req.user.id);
  const sleep_correlation = db.prepare(`SELECT ROUND(sleep_hours) as sleep_h, AVG(energy_level) as avg_e FROM energy_logs WHERE user_id=? GROUP BY sleep_h ORDER BY sleep_h ASC`).all(req.user.id);
  res.json({ hourly_energy: hourly, peak_hour: best_hour?.hour, by_activity, sleep_correlation });
});
app.get('/api/energy/weekly', requireAuth, (req: any, res: any) => {
  const logs = db.prepare(`SELECT log_date, AVG(energy_level) as avg_e, AVG(mental_clarity) as avg_c, SUM(flow_state_mins) as flow_mins FROM energy_logs WHERE user_id=? AND log_date>=date('now','-7 days') GROUP BY log_date ORDER BY log_date ASC`).all(req.user.id);
  const total_flow = (logs as any[]).reduce((s: number, l: any) => s + l.flow_mins, 0);
  res.json({ daily: logs, total_flow_hours_7d: Math.round(total_flow/60*10)/10 });
});
// ─── End B425 ────────────────────────────────────────────────────────────────

// ─── B426: Personal Letter Writing & Correspondence Archive ───────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS letters (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, letter_title TEXT,
    letter_type TEXT DEFAULT 'personal', recipient_name TEXT,
    recipient_relation TEXT DEFAULT 'friend', written_date DATE,
    sent_date DATE, is_sent INTEGER DEFAULT 0, occasion TEXT DEFAULT 'general',
    tone TEXT DEFAULT 'warm', draft_text TEXT,
    word_count INTEGER DEFAULT 0, is_handwritten INTEGER DEFAULT 0,
    response_received INTEGER DEFAULT 0, response_date DATE,
    tags TEXT DEFAULT '[]', notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS letter_templates (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, template_name TEXT,
    occasion TEXT DEFAULT 'birthday', template_text TEXT,
    times_used INTEGER DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS correspondents (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, name TEXT,
    relation TEXT DEFAULT 'friend', address TEXT,
    birthday DATE, last_contacted DATE, letters_sent INTEGER DEFAULT 0,
    letters_received INTEGER DEFAULT 0, notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/letters', requireAuth, (req: any, res: any) => {
  const { letter_type, recipient_name } = req.query as any;
  let q = `SELECT * FROM letters WHERE user_id=?`;
  const params: any[] = [req.user.id];
  if (letter_type) { q += ` AND letter_type=?`; params.push(letter_type); }
  if (recipient_name) { q += ` AND recipient_name LIKE ?`; params.push(`%${recipient_name}%`); }
  q += ` ORDER BY written_date DESC`;
  const letters = db.prepare(q).all(...params);
  res.json({ letters });
});
app.post('/api/letters', requireAuth, (req: any, res: any) => {
  const { letter_title, letter_type, recipient_name, recipient_relation, written_date, occasion, tone, draft_text, is_handwritten } = req.body;
  if (!recipient_name || !draft_text) return res.status(400).json({ error: 'recipient_name and draft_text required' });
  const wc = (draft_text||'').split(/\s+/).filter(Boolean).length;
  const r = db.prepare(`INSERT INTO letters (user_id,letter_title,letter_type,recipient_name,recipient_relation,written_date,occasion,tone,draft_text,word_count,is_handwritten) VALUES (?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, letter_title||`Letter to ${recipient_name}`, letter_type||'personal', recipient_name, recipient_relation||'friend', written_date||new Date().toISOString().slice(0,10), occasion||'general', tone||'warm', draft_text, wc, is_handwritten?1:0);
  res.json({ id: r.lastInsertRowid, word_count: wc });
});
app.put('/api/letters/:id/send', requireAuth, (req: any, res: any) => {
  const { sent_date } = req.body;
  db.prepare(`UPDATE letters SET is_sent=1, sent_date=? WHERE id=? AND user_id=?`).run(sent_date||new Date().toISOString().slice(0,10), req.params.id, req.user.id);
  const letter = db.prepare(`SELECT recipient_name FROM letters WHERE id=?`).get(req.params.id) as any;
  db.prepare(`UPDATE correspondents SET letters_sent=letters_sent+1, last_contacted=? WHERE user_id=? AND name=?`).run(sent_date||new Date().toISOString().slice(0,10), req.user.id, letter?.recipient_name||'');
  res.json({ success: true });
});
// ─── End B426 ────────────────────────────────────────────────────────────────

// ─── B427: Personal Conspiracy Theory Debunker Journal ────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS claims (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, claim_text TEXT,
    claim_source TEXT DEFAULT 'social_media', category TEXT DEFAULT 'health',
    date_encountered DATE, verdict TEXT DEFAULT 'investigating',
    truth_rating INTEGER DEFAULT 3, evidence_for TEXT DEFAULT '[]',
    evidence_against TEXT DEFAULT '[]', logical_fallacies TEXT DEFAULT '[]',
    credible_sources TEXT DEFAULT '[]', rebuttal_summary TEXT,
    is_debunked INTEGER DEFAULT 0, confidence_pct INTEGER DEFAULT 50,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS source_reliability (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, source_name TEXT,
    source_type TEXT DEFAULT 'website', reliability_score INTEGER DEFAULT 3,
    bias TEXT DEFAULT 'center', fact_check_url TEXT,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/claims', requireAuth, (req: any, res: any) => {
  const { category, verdict } = req.query as any;
  let q = `SELECT * FROM claims WHERE user_id=?`;
  const params: any[] = [req.user.id];
  if (category) { q += ` AND category=?`; params.push(category); }
  if (verdict) { q += ` AND verdict=?`; params.push(verdict); }
  q += ` ORDER BY date_encountered DESC`;
  const claims = db.prepare(q).all(...params) as any[];
  const debunked = claims.filter((c: any) => c.is_debunked).length;
  res.json({ claims, debunked_count: debunked, debunk_rate: claims.length ? Math.round(debunked/claims.length*100) : 0 });
});
app.post('/api/claims', requireAuth, (req: any, res: any) => {
  const { claim_text, claim_source, category, date_encountered, evidence_for, evidence_against, logical_fallacies, credible_sources, rebuttal_summary, verdict, confidence_pct } = req.body;
  if (!claim_text) return res.status(400).json({ error: 'claim_text required' });
  const is_debunked = verdict === 'false' ? 1 : 0;
  const r = db.prepare(`INSERT INTO claims (user_id,claim_text,claim_source,category,date_encountered,evidence_for,evidence_against,logical_fallacies,credible_sources,rebuttal_summary,verdict,confidence_pct,is_debunked) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, claim_text, claim_source||'social_media', category||'health', date_encountered||new Date().toISOString().slice(0,10), JSON.stringify(evidence_for||[]), JSON.stringify(evidence_against||[]), JSON.stringify(logical_fallacies||[]), JSON.stringify(credible_sources||[]), rebuttal_summary||'', verdict||'investigating', confidence_pct||50, is_debunked);
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/claims/stats', requireAuth, (req: any, res: any) => {
  const by_category = db.prepare(`SELECT category, COUNT(*) as c, SUM(is_debunked) as debunked FROM claims WHERE user_id=? GROUP BY category ORDER BY c DESC`).all(req.user.id);
  const common_fallacies = db.prepare(`SELECT logical_fallacies FROM claims WHERE user_id=? AND logical_fallacies != '[]'`).all(req.user.id);
  res.json({ by_category, total_claims: (db.prepare(`SELECT COUNT(*) as c FROM claims WHERE user_id=?`).get(req.user.id) as any)?.c||0 });
});
// ─── End B427 ────────────────────────────────────────────────────────────────

