app.get('/api/negotiations', requireAuth, (req: any, res: any) => {
  const negs = db.prepare(`SELECT * FROM negotiations WHERE user_id=? ORDER BY date DESC`).all(req.user.id) as any[];
  const total_value = negs.reduce((s: number, n: any) => s + n.total_value_gained, 0);
  const win_rate = negs.length ? Math.round(negs.filter((n: any) => n.outcome_type === 'win').length/negs.length*100) : 0;
  res.json({ negotiations: negs, total_value_gained: total_value, win_rate, count: negs.length });
});
app.post('/api/negotiations', requireAuth, (req: any, res: any) => {
  const { negotiation_title, negotiation_type, counterparty, date, opening_position, target_position, walkaway_position, final_outcome, outcome_type, tactics_used, lessons_learned, confidence_before, confidence_after } = req.body;
  if (!negotiation_title) return res.status(400).json({ error: 'negotiation_title required' });
  const value_gained = outcome_type === 'win' && final_outcome && opening_position ? final_outcome - opening_position : 0;
  const r = db.prepare(`INSERT INTO negotiations (user_id,negotiation_title,negotiation_type,counterparty,date,opening_position,target_position,walkaway_position,final_outcome,outcome_type,tactics_used,lessons_learned,confidence_before,confidence_after,total_value_gained) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, negotiation_title, negotiation_type||'salary', counterparty||'', date||new Date().toISOString().slice(0,10), opening_position||0, target_position||0, walkaway_position||0, final_outcome||0, outcome_type||'win', JSON.stringify(tactics_used||[]), lessons_learned||'', confidence_before||3, confidence_after||3, Math.abs(value_gained));
  res.json({ id: r.lastInsertRowid, value_gained: Math.abs(value_gained) });
});
