app.get('/api/ebooks', requireAuth, (req: any, res: any) => {
  const { genre, read_status, language } = req.query as any;
  let q = `SELECT * FROM ebooks WHERE user_id=?`;
  const params: any[] = [req.user.id];
  if (genre) { q += ` AND genre=?`; params.push(genre); }
  if (read_status) { q += ` AND read_status=?`; params.push(read_status); }
  if (language) { q += ` AND language=?`; params.push(language); }
  q += ` ORDER BY acquisition_date DESC`;
  const books = db.prepare(q).all(...params) as any[];
  const stats = { total: books.length, read: books.filter((b: any) => b.read_status === 'finished').length, reading: books.filter((b: any) => b.read_status === 'reading').length };
  res.json({ books, stats });
});
app.post('/api/ebooks', requireAuth, (req: any, res: any) => {
  const { title, author, format, pages, genre, language, publisher, year, isbn, acquisition_source, location } = req.body;
  if (!title || !author) return res.status(400).json({ error: 'title and author required' });
  const r = db.prepare(`INSERT INTO ebooks (user_id,title,author,format,pages,genre,language,publisher,year,isbn,acquisition_date,acquisition_source,location) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, title, author, format||'epub', pages||200, genre||'non-fiction', language||'en', publisher||'', year||2020, isbn||'', new Date().toISOString().slice(0,10), acquisition_source||'purchased', location||'kindle');
  res.json({ id: r.lastInsertRowid });
});
app.put('/api/ebooks/:id/progress', requireAuth, (req: any, res: any) => {
  const { read_pct, read_status } = req.body;
  const status = read_pct >= 100 ? 'finished' : read_pct > 0 ? 'reading' : read_status||'unread';
  const updates: any = { read_pct: read_pct||0, read_status: status };
  if (status === 'reading' && read_pct > 0) updates.date_started = new Date().toISOString().slice(0,10);
  if (status === 'finished') updates.date_finished = new Date().toISOString().slice(0,10);
  db.prepare(`UPDATE ebooks SET read_pct=?, read_status=? WHERE id=? AND user_id=?`).run(read_pct||0, status, req.params.id, req.user.id);
  res.json({ success: true, read_status: status });
});
