app.post('/api/kindness/acts', requireAuth, (req: any, res: any) => {
  const { act_date, recipient, recipient_relation, act_description, act_type, effort_level, cost_dollars, time_mins, how_i_felt, is_anonymous } = req.body;
  if (!act_description) return res.status(400).json({ error: 'act_description required' });
  const r = db.prepare(`INSERT INTO kindness_acts (user_id,act_date,recipient,recipient_relation,act_description,act_type,effort_level,cost_dollars,time_mins,how_i_felt,is_anonymous) VALUES (?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, act_date||new Date().toISOString().slice(0,10), recipient||'stranger', recipient_relation||'stranger', act_description, act_type||'spontaneous', effort_level||2, cost_dollars||0, time_mins||5, how_i_felt||4, is_anonymous?1:0);
  const today = act_date||new Date().toISOString().slice(0,10);
  const yesterday = new Date(Date.now()-86400000).toISOString().slice(0,10);
  const g = db.prepare(`SELECT * FROM kindness_goals WHERE user_id=?`).get(req.user.id) as any;
  const new_streak = g?.last_act_date === yesterday ? (g.current_streak||0)+1 : 1;
  db.prepare(`INSERT INTO kindness_goals (user_id,total_acts,current_streak,longest_streak,last_act_date,current_week_count) VALUES (?,1,?,?,?,1) ON CONFLICT(user_id) DO UPDATE SET total_acts=total_acts+1,current_streak=?,longest_streak=MAX(longest_streak,?),last_act_date=?,current_week_count=current_week_count+1`).run(req.user.id, new_streak, new_streak, today, new_streak, new_streak, today);
  res.json({ id: r.lastInsertRowid, streak: new_streak });
});
app.get('/api/kindness/stats', requireAuth, (req: any, res: any) => {
  const goal = db.prepare(`SELECT * FROM kindness_goals WHERE user_id=?`).get(req.user.id);
  const this_month = db.prepare(`SELECT COUNT(*) as c, AVG(how_i_felt) as avg_feel, SUM(cost_dollars) as cost FROM kindness_acts WHERE user_id=? AND act_date>=date('now','start of month')`).get(req.user.id) as any;
  const by_type = db.prepare(`SELECT act_type, COUNT(*) as c FROM kindness_acts WHERE user_id=? GROUP BY act_type ORDER BY c DESC`).all(req.user.id);
  res.json({ goal, this_month_count: this_month?.c||0, avg_feeling: Math.round((this_month?.avg_feel||0)*10)/10, cost_this_month: this_month?.cost||0, by_type });
});
