app.post('/api/lucid/attempts', requireAuth, (req: any, res: any) => {
  const { attempt_date, technique, was_lucid, lucid_duration_mins, clarity_level, dream_content, intentions_set, intentions_achieved, sleep_quality } = req.body;
  const r = db.prepare(`INSERT INTO lucid_attempts (user_id,attempt_date,technique,was_lucid,lucid_duration_mins,clarity_level,dream_content,intentions_set,intentions_achieved,sleep_quality) VALUES (?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, attempt_date||new Date().toISOString().slice(0,10), technique||'WILD', was_lucid?1:0, lucid_duration_mins||0, clarity_level||0, dream_content||'', JSON.stringify(intentions_set||[]), JSON.stringify(intentions_achieved||[]), sleep_quality||3);
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/lucid/stats', requireAuth, (req: any, res: any) => {
  const total = db.prepare(`SELECT COUNT(*) as attempts, SUM(was_lucid) as lucid, AVG(CASE WHEN was_lucid=1 THEN lucid_duration_mins END) as avg_dur FROM lucid_attempts WHERE user_id=?`).get(req.user.id) as any;
  const by_technique = db.prepare(`SELECT technique, COUNT(*) as c, SUM(was_lucid) as lucid FROM lucid_attempts WHERE user_id=? GROUP BY technique ORDER BY lucid DESC`).all(req.user.id) as any[];
  const success_rate = total?.attempts ? Math.round((total.lucid||0)/total.attempts*100) : 0;
  const best_technique = (by_technique as any[]).reduce((best: any, t: any) => (t.lucid/t.c) > ((best?.lucid||0)/(best?.c||1)) ? t : best, null);
  res.json({ total_attempts: total?.attempts||0, total_lucid: total?.lucid||0, success_rate, avg_duration_mins: Math.round(total?.avg_dur||0), by_technique, best_technique: best_technique?.technique });
});
