app.get('/api/hustles', requireAuth, (req: any, res: any) => {
  const hustles = db.prepare(`SELECT h.*, (SELECT SUM(amount) FROM hustle_income WHERE hustle_id=h.id AND income_date>=date('now','start of month')) as this_month_revenue, (SELECT COUNT(DISTINCT client) FROM hustle_income WHERE hustle_id=h.id) as client_count FROM side_hustles h WHERE h.user_id=? ORDER BY h.total_revenue DESC`).all(req.user.id) as any[];
  const total = hustles.reduce((acc: any, h: any) => ({ rev: acc.rev + h.total_revenue, exp: acc.exp + h.total_expenses }), { rev: 0, exp: 0 });
  res.json({ hustles, total_revenue: total.rev, total_expenses: total.exp, net_profit: total.rev - total.exp });
});
app.post('/api/hustles', requireAuth, (req: any, res: any) => {
  const { hustle_name, category, platform, start_date, hourly_rate, monthly_goal } = req.body;
  if (!hustle_name) return res.status(400).json({ error: 'hustle_name required' });
  const r = db.prepare(`INSERT INTO side_hustles (user_id,hustle_name,category,platform,start_date,hourly_rate,monthly_goal) VALUES (?,?,?,?,?,?,?)`).run(req.user.id, hustle_name, category||'freelance', platform||'', start_date||new Date().toISOString().slice(0,10), hourly_rate||0, monthly_goal||0);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/hustles/:id/income', requireAuth, (req: any, res: any) => {
  const { income_date, amount, client, description, is_recurring, category } = req.body;
  if (!amount) return res.status(400).json({ error: 'amount required' });
  const r = db.prepare(`INSERT INTO hustle_income (hustle_id,user_id,income_date,amount,client,description,is_recurring,category) VALUES (?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, income_date||new Date().toISOString().slice(0,10), amount, client||'', description||'', is_recurring?1:0, category||'service');
  db.prepare(`UPDATE side_hustles SET total_revenue=total_revenue+? WHERE id=? AND user_id=?`).run(amount, req.params.id, req.user.id);
  const h = db.prepare(`SELECT total_revenue, monthly_goal FROM side_hustles WHERE id=?`).get(req.params.id) as any;
  const this_month = (db.prepare(`SELECT SUM(amount) as s FROM hustle_income WHERE hustle_id=? AND income_date>=date('now','start of month')`).get(req.params.id) as any)?.s||0;
  res.json({ id: r.lastInsertRowid, this_month_revenue: this_month, goal_pct: h?.monthly_goal ? Math.round(this_month/h.monthly_goal*100) : null });
});
