// ─── B445: Personal Oral History & Family Story Archive ───────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS oral_stories (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, story_title TEXT,
    storyteller TEXT, storyteller_relation TEXT DEFAULT 'grandparent',
    story_date DATE, era TEXT DEFAULT '1950s', location TEXT,
    story_text TEXT, audio_url TEXT, video_url TEXT,
    themes TEXT DEFAULT '[]', people_mentioned TEXT DEFAULT '[]',
    is_verified INTEGER DEFAULT 0, verification_source TEXT,
    emotional_tone TEXT DEFAULT 'nostalgic', significance INTEGER DEFAULT 3,
    tags TEXT DEFAULT '[]', notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS interview_sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, interviewee TEXT,
    interview_date DATE, duration_mins INTEGER DEFAULT 60,
    location TEXT, questions_asked TEXT DEFAULT '[]',
    stories_captured INTEGER DEFAULT 0, audio_recorded INTEGER DEFAULT 0,
    transcribed INTEGER DEFAULT 0, notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS family_timeline (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, event_title TEXT,
    event_date TEXT, event_era TEXT DEFAULT '1960s',
    family_branch TEXT DEFAULT 'paternal', location TEXT,
    people_involved TEXT DEFAULT '[]', description TEXT,
    story_ids TEXT DEFAULT '[]', significance INTEGER DEFAULT 3,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/oral-history/stories', requireAuth, (req: any, res: any) => {
  const { storyteller, era, themes } = req.query as any;
  let q = `SELECT * FROM oral_stories WHERE user_id=?`;
  const params: any[] = [req.user.id];
  if (storyteller) { q += ` AND storyteller LIKE ?`; params.push(`%${storyteller}%`); }
  if (era) { q += ` AND era=?`; params.push(era); }
  q += ` ORDER BY story_date DESC`;
  const stories = db.prepare(q).all(...params);
  res.json({ stories });
});
app.post('/api/oral-history/stories', requireAuth, (req: any, res: any) => {
  const { story_title, storyteller, storyteller_relation, story_date, era, location, story_text, themes, people_mentioned, emotional_tone, significance } = req.body;
  if (!story_title || !story_text) return res.status(400).json({ error: 'story_title and story_text required' });
  const r = db.prepare(`INSERT INTO oral_stories (user_id,story_title,storyteller,storyteller_relation,story_date,era,location,story_text,themes,people_mentioned,emotional_tone,significance) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, story_title, storyteller||'', storyteller_relation||'grandparent', story_date||null, era||'', location||'', story_text, JSON.stringify(themes||[]), JSON.stringify(people_mentioned||[]), emotional_tone||'nostalgic', significance||3);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/oral-history/interviews', requireAuth, (req: any, res: any) => {
  const { interviewee, interview_date, duration_mins, location, questions_asked, audio_recorded } = req.body;
  if (!interviewee) return res.status(400).json({ error: 'interviewee required' });
  const r = db.prepare(`INSERT INTO interview_sessions (user_id,interviewee,interview_date,duration_mins,location,questions_asked,audio_recorded) VALUES (?,?,?,?,?,?,?)`).run(req.user.id, interviewee, interview_date||new Date().toISOString().slice(0,10), duration_mins||60, location||'', JSON.stringify(questions_asked||[]), audio_recorded?1:0);
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/oral-history/timeline', requireAuth, (req: any, res: any) => {
  const events = db.prepare(`SELECT * FROM family_timeline WHERE user_id=? ORDER BY event_date ASC`).all(req.user.id);
  const stats = db.prepare(`SELECT storyteller, COUNT(*) as stories FROM oral_stories WHERE user_id=? GROUP BY storyteller ORDER BY stories DESC`).all(req.user.id);
  res.json({ timeline: events, stories_by_storyteller: stats, total_stories: (db.prepare(`SELECT COUNT(*) as c FROM oral_stories WHERE user_id=?`).get(req.user.id) as any)?.c||0 });
});
// ─── End B445 ────────────────────────────────────────────────────────────────

// ─── B446: Personal Board Game Collection & Play Log ─────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS board_games (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, game_name TEXT,
    publisher TEXT, year INTEGER DEFAULT 2020, bgg_id INTEGER,
    min_players INTEGER DEFAULT 2, max_players INTEGER DEFAULT 4,
    avg_playtime_mins INTEGER DEFAULT 60, weight_rating REAL DEFAULT 2.5,
    category TEXT DEFAULT 'strategy', mechanisms TEXT DEFAULT '[]',
    acquisition_date DATE, acquisition_price REAL DEFAULT 0,
    condition TEXT DEFAULT 'good', is_sleeved INTEGER DEFAULT 0,
    shelf_location TEXT DEFAULT 'main', times_played INTEGER DEFAULT 0,
    personal_rating REAL DEFAULT 0, notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS board_game_plays (
    id INTEGER PRIMARY KEY AUTOINCREMENT, game_id INTEGER, user_id INTEGER,
    play_date DATE, duration_mins INTEGER DEFAULT 60, players TEXT DEFAULT '[]',
    player_count INTEGER DEFAULT 2, winner TEXT, score_data TEXT DEFAULT '{}',
    location TEXT DEFAULT 'home', notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/boardgames', requireAuth, (req: any, res: any) => {
  const games = db.prepare(`SELECT g.*, (SELECT MAX(play_date) FROM board_game_plays WHERE game_id=g.id) as last_played FROM board_games g WHERE g.user_id=? ORDER BY g.times_played DESC`).all(req.user.id) as any[];
  const by_cat = db.prepare(`SELECT category, COUNT(*) as c FROM board_games WHERE user_id=? GROUP BY category ORDER BY c DESC`).all(req.user.id);
  const total_val = games.reduce((s: number, g: any) => s + g.acquisition_price, 0);
  res.json({ games, count: games.length, total_value: total_val, by_category: by_cat, never_played: games.filter((g: any) => g.times_played === 0).length });
});
app.post('/api/boardgames', requireAuth, (req: any, res: any) => {
  const { game_name, publisher, year, min_players, max_players, avg_playtime_mins, weight_rating, category, acquisition_price } = req.body;
  if (!game_name) return res.status(400).json({ error: 'game_name required' });
  const r = db.prepare(`INSERT INTO board_games (user_id,game_name,publisher,year,min_players,max_players,avg_playtime_mins,weight_rating,category,acquisition_date,acquisition_price) VALUES (?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, game_name, publisher||'', year||2020, min_players||2, max_players||4, avg_playtime_mins||60, weight_rating||2.5, category||'strategy', new Date().toISOString().slice(0,10), acquisition_price||0);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/boardgames/:id/play', requireAuth, (req: any, res: any) => {
  const { play_date, duration_mins, players, winner, score_data } = req.body;
  const player_count = Array.isArray(players) ? players.length : (req.body.player_count || 2);
  const r = db.prepare(`INSERT INTO board_game_plays (game_id,user_id,play_date,duration_mins,players,player_count,winner,score_data) VALUES (?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, play_date||new Date().toISOString().slice(0,10), duration_mins||60, JSON.stringify(players||[]), player_count, winner||'', JSON.stringify(score_data||{}));
  db.prepare(`UPDATE board_games SET times_played=times_played+1 WHERE id=? AND user_id=?`).run(req.params.id, req.user.id);
  const total = (db.prepare(`SELECT times_played FROM board_games WHERE id=?`).get(req.params.id) as any)?.times_played || 1;
  res.json({ id: r.lastInsertRowid, total_plays: total });
});
// ─── End B446 ────────────────────────────────────────────────────────────────

