// ─── B451: Personal Typewriter Collection & Repair Log ───────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS typewriters (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, brand TEXT,
    model TEXT, serial_number TEXT, year INTEGER DEFAULT 1960,
    country TEXT DEFAULT 'US', type TEXT DEFAULT 'portable',
    color TEXT DEFAULT 'black', key_layout TEXT DEFAULT 'QWERTY',
    condition TEXT DEFAULT 'good', acquisition_date DATE,
    acquisition_price REAL DEFAULT 0, current_value REAL DEFAULT 0,
    is_functional INTEGER DEFAULT 1, needs_repair INTEGER DEFAULT 0,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS typewriter_repairs (
    id INTEGER PRIMARY KEY AUTOINCREMENT, typewriter_id INTEGER, user_id INTEGER,
    repair_date DATE, issue TEXT, repair_action TEXT,
    parts_replaced TEXT DEFAULT '[]', cost REAL DEFAULT 0,
    repaired_by TEXT DEFAULT 'self', is_resolved INTEGER DEFAULT 1,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/typewriters', requireAuth, (req: any, res: any) => {
  const tws = db.prepare(`SELECT t.*, (SELECT COUNT(*) FROM typewriter_repairs WHERE typewriter_id=t.id) as repair_count FROM typewriters t WHERE t.user_id=? ORDER BY t.year ASC`).all(req.user.id) as any[];
  const total_val = tws.reduce((s: number, t: any) => s + t.current_value, 0);
  const total_cost = tws.reduce((s: number, t: any) => s + t.acquisition_price, 0);
  res.json({ typewriters: tws, count: tws.length, total_value: total_val, total_cost, pnl: total_val - total_cost, needs_repair: tws.filter((t: any) => t.needs_repair).length });
});
