try { db.exec(`
  CREATE TABLE IF NOT EXISTS language_goals (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, language TEXT,
    target_level TEXT DEFAULT 'B2', current_level TEXT DEFAULT 'A1',
    daily_goal_mins INTEGER DEFAULT 30, streak_days INTEGER DEFAULT 0,
    last_practice_date DATE, total_hours REAL DEFAULT 0,
    start_date DATE, target_date DATE,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS language_sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, language TEXT,
    session_date DATE, duration_mins INTEGER DEFAULT 30,
    activity_type TEXT DEFAULT 'app', activity_name TEXT,
    words_learned INTEGER DEFAULT 0, sentences_practiced INTEGER DEFAULT 0,
    new_grammar_points TEXT DEFAULT '[]', comprehension_pct INTEGER DEFAULT 70,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS language_vocab (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, language TEXT,
    word TEXT, translation TEXT, phonetic TEXT, example_sentence TEXT,
    category TEXT DEFAULT 'general', difficulty TEXT DEFAULT 'medium',
    is_mastered INTEGER DEFAULT 0, times_reviewed INTEGER DEFAULT 0,
    next_review DATE, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/language/goals', requireAuth, (req: any, res: any) => {
  const goals = db.prepare(`SELECT g.*, (SELECT COUNT(*) FROM language_sessions WHERE user_id=? AND language=g.language) as total_sessions, (SELECT SUM(words_learned) FROM language_sessions WHERE user_id=? AND language=g.language) as total_words FROM language_goals g WHERE g.user_id=?`).all(req.user.id, req.user.id, req.user.id);
  res.json({ goals });
});
app.post('/api/language/sessions', requireAuth, (req: any, res: any) => {
  const { language, session_date, duration_mins, activity_type, words_learned, sentences_practiced, comprehension_pct } = req.body;
  if (!language) return res.status(400).json({ error: 'language required' });
  const today = new Date().toISOString().slice(0,10);
  const r = db.prepare(`INSERT INTO language_sessions (user_id,language,session_date,duration_mins,activity_type,words_learned,sentences_practiced,comprehension_pct) VALUES (?,?,?,?,?,?,?,?)`).run(req.user.id, language, session_date||today, duration_mins||30, activity_type||'app', words_learned||0, sentences_practiced||0, comprehension_pct||70);
  const goal = db.prepare(`SELECT * FROM language_goals WHERE user_id=? AND language=?`).get(req.user.id, language) as any;
  if (goal) {
    const last = goal.last_practice_date;
    const yesterday = new Date(Date.now()-86400000).toISOString().slice(0,10);
    const new_streak = (last===yesterday||last===today) ? goal.streak_days+1 : 1;
    db.prepare(`UPDATE language_goals SET streak_days=?, last_practice_date=?, total_hours=total_hours+? WHERE user_id=? AND language=?`).run(last===today?goal.streak_days:new_streak, today, (duration_mins||30)/60, req.user.id, language);
  }
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/language/:lang/vocab', requireAuth, (req: any, res: any) => {
  const vocab = db.prepare(`SELECT * FROM language_vocab WHERE user_id=? AND language=? ORDER BY next_review ASC NULLS FIRST LIMIT 20`).all(req.user.id, req.params.lang);
  res.json({ vocab, due_for_review: (db.prepare(`SELECT COUNT(*) as c FROM language_vocab WHERE user_id=? AND language=? AND (next_review<=date('now') OR next_review IS NULL) AND is_mastered=0`).get(req.user.id, req.params.lang) as any)?.c||0 });
});
