app.get('/api/sleep/stats', requireAuth, (req: any, res: any) => {
  const avg = db.prepare(`SELECT AVG(total_hours) as avg_hrs, AVG(sleep_quality) as avg_qual, AVG(restedness_on_wake) as avg_rest, AVG(time_to_fall_asleep_mins) as avg_latency, AVG(awakenings) as avg_wake FROM sleep_logs WHERE user_id=? AND sleep_date>=date('now','-30 days')`).get(req.user.id) as any;
  const by_day = db.prepare(`SELECT strftime('%w',sleep_date) as dow, AVG(total_hours) as avg_hrs, AVG(sleep_quality) as avg_qual FROM sleep_logs WHERE user_id=? AND sleep_date>=date('now','-90 days') GROUP BY dow ORDER BY dow`).all(req.user.id);
  const alcohol_effect = db.prepare(`SELECT AVG(sleep_quality) as avg_q FROM sleep_logs WHERE user_id=? AND alcohol_units>0 AND sleep_date>=date('now','-60 days')`).get(req.user.id) as any;
  const no_alcohol = db.prepare(`SELECT AVG(sleep_quality) as avg_q FROM sleep_logs WHERE user_id=? AND alcohol_units=0 AND sleep_date>=date('now','-60 days')`).get(req.user.id) as any;
  const streak = (db.prepare(`SELECT COUNT(*) as c FROM sleep_logs WHERE user_id=? AND sleep_date>=date('now','-7 days')`).get(req.user.id) as any)?.c||0;
  res.json({ avg_hours: Math.round((avg?.avg_hrs||0)*10)/10, avg_quality: Math.round((avg?.avg_qual||0)*10)/10, avg_restedness: Math.round((avg?.avg_rest||0)*10)/10, avg_sleep_latency: Math.round(avg?.avg_latency||15), by_day_of_week: by_day, alcohol_vs_no_alcohol: { with_alcohol: Math.round((alcohol_effect?.avg_q||0)*10)/10, without_alcohol: Math.round((no_alcohol?.avg_q||0)*10)/10 }, logged_this_week: streak });
});
app.get('/api/sleep/recent', requireAuth, (req: any, res: any) => {
  const logs = db.prepare(`SELECT * FROM sleep_logs WHERE user_id=? ORDER BY sleep_date DESC LIMIT 14`).all(req.user.id);
  res.json({ logs });
});
