// ─── B459: Personal Breath Work & Pranayama Practice Log ─────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS breathwork_sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER,
    session_date DATE, session_time TEXT,
    technique TEXT DEFAULT 'box_breathing',
    duration_mins INTEGER DEFAULT 10, rounds INTEGER DEFAULT 0,
    inhale_secs INTEGER DEFAULT 4, hold_in_secs INTEGER DEFAULT 4,
    exhale_secs INTEGER DEFAULT 4, hold_out_secs INTEGER DEFAULT 0,
    stress_before INTEGER DEFAULT 5, stress_after INTEGER DEFAULT 5,
    clarity_before INTEGER DEFAULT 5, clarity_after INTEGER DEFAULT 5,
    energy_before INTEGER DEFAULT 5, energy_after INTEGER DEFAULT 5,
    max_breath_hold_secs INTEGER DEFAULT 0, notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS breathwork_goals (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER,
    goal_type TEXT DEFAULT 'daily_practice',
    target_mins_daily INTEGER DEFAULT 10,
    target_technique TEXT DEFAULT 'wim_hof',
    streak_days INTEGER DEFAULT 0, last_practice_date DATE,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.post('/api/breathwork/log', requireAuth, (req: any, res: any) => {
  const { session_date, technique, duration_mins, rounds, inhale_secs, hold_in_secs, exhale_secs, stress_before, stress_after, clarity_before, clarity_after, energy_before, energy_after, max_breath_hold_secs } = req.body;
  const today = new Date().toISOString().slice(0,10);
  const r = db.prepare(`INSERT INTO breathwork_sessions (user_id,session_date,technique,duration_mins,rounds,inhale_secs,hold_in_secs,exhale_secs,stress_before,stress_after,clarity_before,clarity_after,energy_before,energy_after,max_breath_hold_secs) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, session_date||today, technique||'box_breathing', duration_mins||10, rounds||0, inhale_secs||4, hold_in_secs||4, exhale_secs||4, stress_before||5, stress_after||5, clarity_before||5, clarity_after||5, energy_before||5, energy_after||5, max_breath_hold_secs||0);
  const stress_delta = (stress_before||5)-(stress_after||5);
  const clarity_delta = (clarity_after||5)-(clarity_before||5);
  const goal = db.prepare(`SELECT * FROM breathwork_goals WHERE user_id=? LIMIT 1`).get(req.user.id) as any;
  if (goal) {
    const last = goal.last_practice_date;
    const yesterday = new Date(Date.now()-86400000).toISOString().slice(0,10);
    const new_streak = (last===yesterday||last===today) ? goal.streak_days+1 : 1;
    db.prepare(`UPDATE breathwork_goals SET streak_days=?, last_practice_date=? WHERE user_id=?`).run(last===today?goal.streak_days:new_streak, today, req.user.id);
  }
  res.json({ id: r.lastInsertRowid, stress_reduction: stress_delta, clarity_gain: clarity_delta });
});
app.get('/api/breathwork/stats', requireAuth, (req: any, res: any) => {
  const avg = db.prepare(`SELECT AVG(stress_before-stress_after) as stress_red, AVG(clarity_after-clarity_before) as clarity_gain, AVG(max_breath_hold_secs) as avg_hold, AVG(duration_mins) as avg_mins FROM breathwork_sessions WHERE user_id=? AND session_date>=date('now','-30 days')`).get(req.user.id) as any;
  const by_technique = db.prepare(`SELECT technique, COUNT(*) as sessions, AVG(stress_before-stress_after) as avg_stress_red FROM breathwork_sessions WHERE user_id=? GROUP BY technique ORDER BY sessions DESC`).all(req.user.id);
  const goal = db.prepare(`SELECT streak_days FROM breathwork_goals WHERE user_id=? LIMIT 1`).get(req.user.id) as any;
  res.json({ avg_stress_reduction: Math.round((avg?.stress_red||0)*10)/10, avg_clarity_gain: Math.round((avg?.clarity_gain||0)*10)/10, avg_hold_secs: Math.round(avg?.avg_hold||0), by_technique, streak_days: goal?.streak_days||0 });
});
// ─── End B459 ────────────────────────────────────────────────────────────────

// ─── B460: Personal Rare Book & First Edition Tracker ────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS rare_books (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, title TEXT,
    author TEXT, publisher TEXT, publication_year INTEGER DEFAULT 1950,
    edition TEXT DEFAULT 'first', printing TEXT DEFAULT 'first',
    isbn TEXT, language TEXT DEFAULT 'English',
    binding TEXT DEFAULT 'hardcover', condition TEXT DEFAULT 'fine',
    has_dust_jacket INTEGER DEFAULT 0, dj_condition TEXT DEFAULT 'none',
    is_signed INTEGER DEFAULT 0, signed_by TEXT,
    inscription TEXT, provenance TEXT, acquisition_date DATE,
    acquisition_price REAL DEFAULT 0, current_value REAL DEFAULT 0,
    acquisition_source TEXT DEFAULT 'dealer',
    category TEXT DEFAULT 'literature', notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS book_appraisals (
    id INTEGER PRIMARY KEY AUTOINCREMENT, book_id INTEGER, user_id INTEGER,
    appraisal_date DATE, appraised_value REAL DEFAULT 0,
    appraiser TEXT, appraisal_source TEXT DEFAULT 'dealer',
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/rare-books', requireAuth, (req: any, res: any) => {
  const { author, category, signed } = req.query as any;
  let q = `SELECT * FROM rare_books WHERE user_id=?`;
  const params: any[] = [req.user.id];
  if (author) { q += ` AND author LIKE ?`; params.push(`%${author}%`); }
  if (category) { q += ` AND category=?`; params.push(category); }
  if (signed === 'true') { q += ` AND is_signed=1`; }
  q += ` ORDER BY current_value DESC`;
  const books = db.prepare(q).all(...params) as any[];
  const total_val = books.reduce((s: number, b: any) => s + b.current_value, 0);
  const total_cost = books.reduce((s: number, b: any) => s + b.acquisition_price, 0);
  const by_cat = db.prepare(`SELECT category, COUNT(*) as c, SUM(current_value) as val FROM rare_books WHERE user_id=? GROUP BY category ORDER BY val DESC`).all(req.user.id);
  res.json({ books, count: books.length, total_value: total_val, total_cost, pnl: total_val-total_cost, signed: books.filter((b: any) => b.is_signed).length, by_category: by_cat });
});
app.post('/api/rare-books', requireAuth, (req: any, res: any) => {
  const { title, author, publisher, publication_year, edition, printing, condition, has_dust_jacket, is_signed, signed_by, acquisition_date, acquisition_price, category } = req.body;
  if (!title || !author) return res.status(400).json({ error: 'title and author required' });
  const r = db.prepare(`INSERT INTO rare_books (user_id,title,author,publisher,publication_year,edition,printing,condition,has_dust_jacket,is_signed,signed_by,acquisition_date,acquisition_price,current_value,category) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, title, author, publisher||'', publication_year||1950, edition||'first', printing||'first', condition||'fine', has_dust_jacket?1:0, is_signed?1:0, signed_by||'', acquisition_date||null, acquisition_price||0, acquisition_price||0, category||'literature');
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/rare-books/:id/appraise', requireAuth, (req: any, res: any) => {
  const { appraisal_date, appraised_value, appraiser } = req.body;
  if (!appraised_value) return res.status(400).json({ error: 'appraised_value required' });
  const r = db.prepare(`INSERT INTO book_appraisals (book_id,user_id,appraisal_date,appraised_value,appraiser) VALUES (?,?,?,?,?)`).run(req.params.id, req.user.id, appraisal_date||new Date().toISOString().slice(0,10), appraised_value, appraiser||'');
  db.prepare(`UPDATE rare_books SET current_value=? WHERE id=? AND user_id=?`).run(appraised_value, req.params.id, req.user.id);
  res.json({ id: r.lastInsertRowid });
});
// ─── End B460 ────────────────────────────────────────────────────────────────

