  db.prepare(`UPDATE mushroom_grows SET total_yield_grams=total_yield_grams+?, flush_count=MAX(flush_count,?), status='fruiting' WHERE id=? AND user_id=?`).run(weight_grams, flush_number||1, req.params.id, req.user.id);
