// ─── B471: Personal Motorsport Lap Time Tracker ───────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS track_sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER,
    session_date DATE, track_name TEXT, track_config TEXT DEFAULT 'full',
    vehicle TEXT, vehicle_class TEXT DEFAULT 'street',
    tire_compound TEXT DEFAULT 'street', tire_temp_f INTEGER DEFAULT 180,
    fuel_level TEXT DEFAULT 'half', track_temp_f INTEGER DEFAULT 90,
    air_temp_f INTEGER DEFAULT 72, session_type TEXT DEFAULT 'open_laps',
    total_laps INTEGER DEFAULT 0, best_lap_secs REAL DEFAULT 0,
    avg_lap_secs REAL DEFAULT 0, session_notes TEXT,
    incident TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS lap_times (
    id INTEGER PRIMARY KEY AUTOINCREMENT, session_id INTEGER, user_id INTEGER,
    lap_number INTEGER DEFAULT 1, lap_time_secs REAL DEFAULT 0,
    sector_1_secs REAL DEFAULT 0, sector_2_secs REAL DEFAULT 0,
    sector_3_secs REAL DEFAULT 0, is_personal_best INTEGER DEFAULT 0,
    is_clean_lap INTEGER DEFAULT 1, notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.post('/api/motorsport/sessions', requireAuth, (req: any, res: any) => {
  const { session_date, track_name, track_config, vehicle, vehicle_class, tire_compound, track_temp_f, air_temp_f, session_type } = req.body;
  if (!track_name || !vehicle) return res.status(400).json({ error: 'track_name and vehicle required' });
  const r = db.prepare(`INSERT INTO track_sessions (user_id,session_date,track_name,track_config,vehicle,vehicle_class,tire_compound,track_temp_f,air_temp_f,session_type) VALUES (?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, session_date||new Date().toISOString().slice(0,10), track_name, track_config||'full', vehicle, vehicle_class||'street', tire_compound||'street', track_temp_f||90, air_temp_f||72, session_type||'open_laps');
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/motorsport/sessions/:id/laps', requireAuth, (req: any, res: any) => {
  const { lap_number, lap_time_secs, sector_1_secs, sector_2_secs, sector_3_secs, is_clean_lap } = req.body;
  if (!lap_time_secs) return res.status(400).json({ error: 'lap_time_secs required' });
  const session = db.prepare(`SELECT track_name, vehicle FROM track_sessions WHERE id=? AND user_id=?`).get(req.params.id, req.user.id) as any;
  if (!session) return res.status(404).json({ error: 'session not found' });
  const pb = db.prepare(`SELECT MIN(lap_time_secs) as pb FROM lap_times lt JOIN track_sessions ts ON lt.session_id=ts.id WHERE ts.user_id=? AND ts.track_name=? AND ts.vehicle=?`).get(req.user.id, session.track_name, session.vehicle) as any;
  const is_pb = !pb?.pb || lap_time_secs < pb.pb ? 1 : 0;
  const r = db.prepare(`INSERT INTO lap_times (session_id,user_id,lap_number,lap_time_secs,sector_1_secs,sector_2_secs,sector_3_secs,is_personal_best,is_clean_lap) VALUES (?,?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, lap_number||1, lap_time_secs, sector_1_secs||0, sector_2_secs||0, sector_3_secs||0, is_pb, is_clean_lap===false?0:1);
  const laps = db.prepare(`SELECT COUNT(*) as c, MIN(lap_time_secs) as best, AVG(lap_time_secs) as avg FROM lap_times WHERE session_id=?`).get(req.params.id) as any;
  db.prepare(`UPDATE track_sessions SET total_laps=?, best_lap_secs=?, avg_lap_secs=? WHERE id=? AND user_id=?`).run(laps?.c||1, laps?.best||lap_time_secs, Math.round((laps?.avg||lap_time_secs)*1000)/1000, req.params.id, req.user.id);
  res.json({ id: r.lastInsertRowid, is_personal_best: is_pb===1 });
});
app.get('/api/motorsport/pb', requireAuth, (req: any, res: any) => {
  const pbs = db.prepare(`SELECT ts.track_name, ts.track_config, ts.vehicle, MIN(lt.lap_time_secs) as pb_secs FROM lap_times lt JOIN track_sessions ts ON lt.session_id=ts.id WHERE ts.user_id=? AND lt.is_clean_lap=1 GROUP BY ts.track_name, ts.track_config, ts.vehicle ORDER BY ts.track_name`).all(req.user.id);
  res.json({ personal_bests: pbs });
});
