app.post('/api/biorhythm/log', requireAuth, (req: any, res: any) => {
  const { log_date, physical_energy, emotional_energy, mental_energy, intuitive_energy, overall_energy, motivation, focus_quality, creativity, social_energy } = req.body;
  const existing = db.prepare(`SELECT id FROM biorhythm_logs WHERE user_id=? AND log_date=?`).get(req.user.id, log_date||new Date().toISOString().slice(0,10));
  if (existing) {
    db.prepare(`UPDATE biorhythm_logs SET physical_energy=?,emotional_energy=?,mental_energy=?,intuitive_energy=?,overall_energy=?,motivation=?,focus_quality=?,creativity=?,social_energy=? WHERE id=?`).run(physical_energy||5, emotional_energy||5, mental_energy||5, intuitive_energy||5, overall_energy||5, motivation||5, focus_quality||5, creativity||5, social_energy||5, (existing as any).id);
    return res.json({ id: (existing as any).id, updated: true });
  }
  const r = db.prepare(`INSERT INTO biorhythm_logs (user_id,log_date,physical_energy,emotional_energy,mental_energy,intuitive_energy,overall_energy,motivation,focus_quality,creativity,social_energy) VALUES (?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, log_date||new Date().toISOString().slice(0,10), physical_energy||5, emotional_energy||5, mental_energy||5, intuitive_energy||5, overall_energy||5, motivation||5, focus_quality||5, creativity||5, social_energy||5);
  res.json({ id: r.lastInsertRowid });
});
app.get('/api/biorhythm/patterns', requireAuth, (req: any, res: any) => {
  const by_dow = db.prepare(`SELECT strftime('%w',log_date) as dow, AVG(overall_energy) as avg_energy, AVG(focus_quality) as avg_focus, AVG(creativity) as avg_creativity FROM biorhythm_logs WHERE user_id=? AND log_date>=date('now','-90 days') GROUP BY dow ORDER BY dow`).all(req.user.id);
  const recent = db.prepare(`SELECT * FROM biorhythm_logs WHERE user_id=? ORDER BY log_date DESC LIMIT 30`).all(req.user.id);
  const avg_all = db.prepare(`SELECT AVG(overall_energy) as e, AVG(focus_quality) as f, AVG(creativity) as c FROM biorhythm_logs WHERE user_id=? AND log_date>=date('now','-30 days')`).get(req.user.id) as any;
  res.json({ by_day_of_week: by_dow, recent_30_days: recent, monthly_averages: { energy: Math.round((avg_all?.e||5)*10)/10, focus: Math.round((avg_all?.f||5)*10)/10, creativity: Math.round((avg_all?.c||5)*10)/10 } });
});
