// ─── B474: Personal Grant Writing & Funding Application Tracker ───────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS grant_applications (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, grant_name TEXT,
    funder TEXT, grant_type TEXT DEFAULT 'public', amount_requested REAL DEFAULT 0,
    amount_awarded REAL DEFAULT 0, deadline DATE, submission_date DATE,
    status TEXT DEFAULT 'researching', project_description TEXT,
    eligibility_confirmed INTEGER DEFAULT 0, letter_of_inquiry_sent DATE,
    full_app_submitted DATE, decision_date DATE, decision TEXT DEFAULT 'pending',
    contact_name TEXT, contact_email TEXT, next_cycle_date DATE,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS grant_tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT, application_id INTEGER, user_id INTEGER,
    task_name TEXT, due_date DATE, is_complete INTEGER DEFAULT 0,
    priority TEXT DEFAULT 'medium', notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/grants', requireAuth, (req: any, res: any) => {
  const grants = db.prepare(`SELECT g.*, (SELECT COUNT(*) FROM grant_tasks WHERE application_id=g.id AND is_complete=0) as open_tasks FROM grant_applications g WHERE g.user_id=? ORDER BY g.deadline ASC NULLS LAST`).all(req.user.id) as any[];
  const stats = db.prepare(`SELECT SUM(CASE WHEN decision='awarded' THEN amount_awarded ELSE 0 END) as total_awarded, COUNT(CASE WHEN decision='awarded' THEN 1 END) as awarded_count, COUNT(*) as total_apps FROM grant_applications WHERE user_id=?`).get(req.user.id) as any;
  res.json({ grants, total_applied: stats?.total_apps||0, total_awarded: stats?.awarded_count||0, total_funding: stats?.total_awarded||0, success_rate: stats?.total_apps ? Math.round((stats.awarded_count||0)/stats.total_apps*100) : 0 });
});
app.post('/api/grants', requireAuth, (req: any, res: any) => {
  const { grant_name, funder, grant_type, amount_requested, deadline, project_description } = req.body;
  if (!grant_name) return res.status(400).json({ error: 'grant_name required' });
  const r = db.prepare(`INSERT INTO grant_applications (user_id,grant_name,funder,grant_type,amount_requested,deadline,project_description) VALUES (?,?,?,?,?,?,?)`).run(req.user.id, grant_name, funder||'', grant_type||'public', amount_requested||0, deadline||null, project_description||'');
  res.json({ id: r.lastInsertRowid });
});
app.patch('/api/grants/:id', requireAuth, (req: any, res: any) => {
  const { status, amount_awarded, decision, decision_date, submission_date } = req.body;
  const updates: string[] = [];
  const vals: any[] = [];
  if (status) { updates.push(`status=?`); vals.push(status); }
  if (amount_awarded !== undefined) { updates.push(`amount_awarded=?`); vals.push(amount_awarded); }
  if (decision) { updates.push(`decision=?`); vals.push(decision); }
  if (decision_date) { updates.push(`decision_date=?`); vals.push(decision_date); }
  if (submission_date) { updates.push(`submission_date=?`); vals.push(submission_date); }
  if (!updates.length) return res.status(400).json({ error: 'nothing to update' });
  db.prepare(`UPDATE grant_applications SET ${updates.join(',')} WHERE id=? AND user_id=?`).run(...vals, req.params.id, req.user.id);
  res.json({ success: true });
});
// ─── End B474 ────────────────────────────────────────────────────────────────

