app.post('/api/habit-stacks/:id/log', requireAuth, (req: any, res: any) => {
  const { log_date, completed_habits, duration_actual_mins } = req.body;
  const stack = db.prepare(`SELECT habits FROM habit_stacks WHERE id=? AND user_id=?`).get(req.params.id, req.user.id) as any;
  if (!stack) return res.status(404).json({ error: 'stack not found' });
  let total_in_stack: number; try { total_in_stack = JSON.parse(stack.habits).length; } catch(e) { total_in_stack = 1; }
  const completed: string[] = Array.isArray(completed_habits) ? completed_habits : [];
  const pct = total_in_stack ? Math.round(completed.length/total_in_stack*100) : 100;
  const r = db.prepare(`INSERT INTO habit_stack_logs (stack_id,user_id,log_date,completed_habits,total_completed,total_in_stack,completion_pct,duration_actual_mins) VALUES (?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, log_date||new Date().toISOString().slice(0,10), JSON.stringify(completed), completed.length, total_in_stack, pct, duration_actual_mins||0);
  res.json({ id: r.lastInsertRowid, completion_pct: pct });
});
