app.post('/api/tea/:id/session', requireAuth, (req: any, res: any) => {
  const { session_date, session_type, water_temp_f, vessel, infusions, grams_used, rating, flavor_profile, mood } = req.body;
  const r = db.prepare(`INSERT INTO tea_sessions (tea_id,user_id,session_date,session_type,water_temp_f,vessel,infusions,grams_used,rating,flavor_profile,mood) VALUES (?,?,?,?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, session_date||new Date().toISOString().slice(0,10), session_type||'gongfu', water_temp_f||185, vessel||'gaiwan', infusions||3, grams_used||5, rating||4, JSON.stringify(flavor_profile||[]), mood||'calm');
  if (grams_used) db.prepare(`UPDATE tea_collection SET quantity_grams=MAX(0,quantity_grams-?) WHERE id=? AND user_id=?`).run(grams_used, req.params.id, req.user.id);
  const avg_r = (db.prepare(`SELECT AVG(rating) as a FROM tea_sessions WHERE tea_id=?`).get(req.params.id) as any)?.a||rating;
  db.prepare(`UPDATE tea_collection SET personal_rating=? WHERE id=? AND user_id=?`).run(Math.round(avg_r*10)/10, req.params.id, req.user.id);
  res.json({ id: r.lastInsertRowid });
});
