// ─── B485: Personal Digital Minimalism & Screen Time Journal ─────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS screen_time_logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, log_date DATE,
    total_screen_mins INTEGER DEFAULT 0, phone_mins INTEGER DEFAULT 0,
    computer_mins INTEGER DEFAULT 0, tv_mins INTEGER DEFAULT 0,
    social_media_mins INTEGER DEFAULT 0, news_mins INTEGER DEFAULT 0,
    productive_mins INTEGER DEFAULT 0, entertainment_mins INTEGER DEFAULT 0,
    doom_scroll_sessions INTEGER DEFAULT 0, checked_phone_times INTEGER DEFAULT 0,
    first_phone_check TEXT, last_phone_check TEXT,
    no_phone_hours TEXT DEFAULT '[]', offline_activities TEXT DEFAULT '[]',
    satisfaction_with_usage INTEGER DEFAULT 3, notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS digital_detox_goals (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER,
    daily_screen_limit_mins INTEGER DEFAULT 120,
    social_media_limit_mins INTEGER DEFAULT 30,
    no_phone_morning_hours INTEGER DEFAULT 1,
    no_phone_evening_hours INTEGER DEFAULT 1,
    weekly_detox_day TEXT DEFAULT 'Sunday',
    streak_days INTEGER DEFAULT 0, last_under_limit DATE,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.post('/api/screen-time/log', requireAuth, (req: any, res: any) => {
  const { log_date, total_screen_mins, phone_mins, computer_mins, tv_mins, social_media_mins, productive_mins, doom_scroll_sessions, checked_phone_times, offline_activities, satisfaction_with_usage } = req.body;
  const r = db.prepare(`INSERT INTO screen_time_logs (user_id,log_date,total_screen_mins,phone_mins,computer_mins,tv_mins,social_media_mins,productive_mins,doom_scroll_sessions,checked_phone_times,offline_activities,satisfaction_with_usage) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, log_date||new Date().toISOString().slice(0,10), total_screen_mins||0, phone_mins||0, computer_mins||0, tv_mins||0, social_media_mins||0, productive_mins||0, doom_scroll_sessions||0, checked_phone_times||0, JSON.stringify(offline_activities||[]), satisfaction_with_usage||3);
  const goal = db.prepare(`SELECT * FROM digital_detox_goals WHERE user_id=? LIMIT 1`).get(req.user.id) as any;
  const under_limit = goal && total_screen_mins <= goal.daily_screen_limit_mins;
  if (goal && under_limit) {
    const yesterday = new Date(Date.now()-86400000).toISOString().slice(0,10);
    const today = log_date||new Date().toISOString().slice(0,10);
    const new_streak = goal.last_under_limit===yesterday ? goal.streak_days+1 : 1;
    db.prepare(`UPDATE digital_detox_goals SET streak_days=?, last_under_limit=? WHERE user_id=?`).run(new_streak, today, req.user.id);
  }
  res.json({ id: r.lastInsertRowid, under_limit, streak: under_limit && goal ? goal.streak_days+1 : 0 });
});
app.get('/api/screen-time/trends', requireAuth, (req: any, res: any) => {
  const avg = db.prepare(`SELECT AVG(total_screen_mins) as avg_total, AVG(social_media_mins) as avg_social, AVG(productive_mins) as avg_productive, AVG(doom_scroll_sessions) as avg_doom FROM screen_time_logs WHERE user_id=? AND log_date>=date('now','-30 days')`).get(req.user.id) as any;
  const by_dow = db.prepare(`SELECT strftime('%w',log_date) as dow, AVG(total_screen_mins) as avg_mins FROM screen_time_logs WHERE user_id=? AND log_date>=date('now','-90 days') GROUP BY dow ORDER BY dow`).all(req.user.id);
  const goal = db.prepare(`SELECT * FROM digital_detox_goals WHERE user_id=? LIMIT 1`).get(req.user.id);
  res.json({ avg_daily_mins: Math.round(avg?.avg_total||0), avg_social_mins: Math.round(avg?.avg_social||0), avg_productive_mins: Math.round(avg?.avg_productive||0), avg_doom_scrolls: Math.round((avg?.avg_doom||0)*10)/10, by_day_of_week: by_dow, goals: goal });
});
// ─── End B485 ────────────────────────────────────────────────────────────────

