// ─── B503: Personal Cigar Collection & Humidor Manager ───────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS humidors (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, humidor_name TEXT,
    capacity INTEGER DEFAULT 25, current_count INTEGER DEFAULT 0,
    target_rh INTEGER DEFAULT 70, current_rh REAL DEFAULT 70,
    current_temp_f REAL DEFAULT 70, wood_type TEXT DEFAULT 'spanish_cedar',
    last_humidified_date DATE, notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS cigars (
    id INTEGER PRIMARY KEY AUTOINCREMENT, humidor_id INTEGER, user_id INTEGER,
    brand TEXT, blend TEXT, vitola TEXT DEFAULT 'robusto',
    size_inches TEXT DEFAULT '5x50', origin TEXT DEFAULT 'Nicaragua',
    wrapper TEXT DEFAULT 'colorado', filler TEXT DEFAULT 'mixed',
    quantity INTEGER DEFAULT 1, purchase_date DATE,
    purchase_price_each REAL DEFAULT 10, best_after DATE,
    personal_rating REAL DEFAULT 0, notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS cigar_smokes (
    id INTEGER PRIMARY KEY AUTOINCREMENT, cigar_id INTEGER, user_id INTEGER,
    smoke_date DATE, smoke_duration_mins INTEGER DEFAULT 45,
    pairing TEXT DEFAULT 'bourbon', setting TEXT DEFAULT 'patio',
    draw INTEGER DEFAULT 4, burn INTEGER DEFAULT 4, flavor INTEGER DEFAULT 4,
    strength TEXT DEFAULT 'medium', retrohale INTEGER DEFAULT 3,
    overall_rating INTEGER DEFAULT 4, notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/cigars', requireAuth, (req: any, res: any) => {
  const humidors = db.prepare(`SELECT * FROM humidors WHERE user_id=? ORDER BY humidor_name`).all(req.user.id);
  const collection = db.prepare(`SELECT c.*, h.humidor_name FROM cigars c LEFT JOIN humidors h ON c.humidor_id=h.id WHERE c.user_id=? AND c.quantity>0 ORDER BY c.brand`).all(req.user.id) as any[];
  const total_val = collection.reduce((s: number, c: any) => s + c.quantity * c.purchase_price_each, 0);
  const by_origin = db.prepare(`SELECT origin, COUNT(*) as blends, SUM(quantity) as sticks FROM cigars WHERE user_id=? AND quantity>0 GROUP BY origin ORDER BY sticks DESC`).all(req.user.id);
  res.json({ humidors, collection, total_sticks: collection.reduce((s: number, c: any) => s + c.quantity, 0), total_value: total_val, by_origin });
});
app.post('/api/cigars/humidors', requireAuth, (req: any, res: any) => {
  const { humidor_name, capacity, wood_type } = req.body;
  if (!humidor_name) return res.status(400).json({ error: 'humidor_name required' });
  const r = db.prepare(`INSERT INTO humidors (user_id,humidor_name,capacity,wood_type) VALUES (?,?,?,?)`).run(req.user.id, humidor_name, capacity||25, wood_type||'spanish_cedar');
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/cigars', requireAuth, (req: any, res: any) => {
  const { humidor_id, brand, blend, vitola, origin, wrapper, quantity, purchase_price_each } = req.body;
  if (!brand) return res.status(400).json({ error: 'brand required' });
  const r = db.prepare(`INSERT INTO cigars (humidor_id,user_id,brand,blend,vitola,origin,wrapper,quantity,purchase_date,purchase_price_each) VALUES (?,?,?,?,?,?,?,?,?,?)`).run(humidor_id||null, req.user.id, brand, blend||'', vitola||'robusto', origin||'Nicaragua', wrapper||'colorado', quantity||1, new Date().toISOString().slice(0,10), purchase_price_each||10);
  if (humidor_id) db.prepare(`UPDATE humidors SET current_count=current_count+? WHERE id=? AND user_id=?`).run(quantity||1, humidor_id, req.user.id);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/cigars/:id/smoke', requireAuth, (req: any, res: any) => {
  const { smoke_date, smoke_duration_mins, pairing, setting, overall_rating, notes } = req.body;
  const cigar = db.prepare(`SELECT * FROM cigars WHERE id=? AND user_id=?`).get(req.params.id, req.user.id) as any;
  if (!cigar || cigar.quantity < 1) return res.status(400).json({ error: 'no sticks remaining' });
  const r = db.prepare(`INSERT INTO cigar_smokes (cigar_id,user_id,smoke_date,smoke_duration_mins,pairing,setting,overall_rating,notes) VALUES (?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, smoke_date||new Date().toISOString().slice(0,10), smoke_duration_mins||45, pairing||'bourbon', setting||'patio', overall_rating||4, notes||'');
  db.prepare(`UPDATE cigars SET quantity=quantity-1 WHERE id=? AND user_id=?`).run(req.params.id, req.user.id);
  if (cigar.humidor_id) db.prepare(`UPDATE humidors SET current_count=MAX(0,current_count-1) WHERE id=?`).run(cigar.humidor_id);
  const avg = (db.prepare(`SELECT AVG(overall_rating) as a FROM cigar_smokes WHERE cigar_id=?`).get(req.params.id) as any)?.a||overall_rating;
  db.prepare(`UPDATE cigars SET personal_rating=? WHERE id=?`).run(Math.round(avg*10)/10, req.params.id);
  res.json({ id: r.lastInsertRowid, remaining: cigar.quantity-1 });
});
// ─── End B503 ────────────────────────────────────────────────────────────────

