// ─── B505: Personal Cold Plunge & Heat Therapy Tracker ───────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS thermal_sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, session_date DATE,
    session_time TEXT, therapy_type TEXT DEFAULT 'cold_plunge',
    duration_mins REAL DEFAULT 3, water_temp_f REAL DEFAULT 50,
    air_temp_f REAL DEFAULT 70, pre_mood INTEGER DEFAULT 3,
    post_mood INTEGER DEFAULT 4, energy_before INTEGER DEFAULT 3,
    energy_after INTEGER DEFAULT 4, focus_after INTEGER DEFAULT 4,
    hrv_before INTEGER DEFAULT 0, hrv_after INTEGER DEFAULT 0,
    shiver_intensity TEXT DEFAULT 'mild', breathing_method TEXT DEFAULT 'wim_hof',
    followed_by_sauna INTEGER DEFAULT 0, rounds INTEGER DEFAULT 1,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS thermal_goals (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER,
    weekly_target_sessions INTEGER DEFAULT 5,
    target_temp_f REAL DEFAULT 40, target_duration_mins REAL DEFAULT 5,
    streak_days INTEGER DEFAULT 0, last_session_date DATE,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.post('/api/thermal/log', requireAuth, (req: any, res: any) => {
  const { session_date, therapy_type, duration_mins, water_temp_f, pre_mood, post_mood, energy_after, rounds } = req.body;
  const r = db.prepare(`INSERT INTO thermal_sessions (user_id,session_date,therapy_type,duration_mins,water_temp_f,pre_mood,post_mood,energy_after,rounds) VALUES (?,?,?,?,?,?,?,?,?)`).run(req.user.id, session_date||new Date().toISOString().slice(0,10), therapy_type||'cold_plunge', duration_mins||3, water_temp_f||50, pre_mood||3, post_mood||4, energy_after||4, rounds||1);
  const mood_lift = (post_mood||4)-(pre_mood||3);
  const goal = db.prepare(`SELECT * FROM thermal_goals WHERE user_id=? LIMIT 1`).get(req.user.id) as any;
  let streak = 1;
  if (goal) {
    const yesterday = new Date(Date.now()-86400000).toISOString().slice(0,10);
    streak = goal.last_session_date===yesterday ? goal.streak_days+1 : 1;
    db.prepare(`UPDATE thermal_goals SET streak_days=?, last_session_date=? WHERE user_id=?`).run(streak, session_date||new Date().toISOString().slice(0,10), req.user.id);
  }
  res.json({ id: r.lastInsertRowid, mood_lift, streak });
});
app.get('/api/thermal/stats', requireAuth, (req: any, res: any) => {
  const avg = db.prepare(`SELECT AVG(duration_mins) as avg_dur, AVG(water_temp_f) as avg_temp, AVG(post_mood-pre_mood) as avg_mood_lift, AVG(energy_after-energy_before) as avg_energy_lift, COUNT(*) as sessions FROM thermal_sessions WHERE user_id=? AND session_date>=date('now','-30 days')`).get(req.user.id) as any;
  const by_type = db.prepare(`SELECT therapy_type, COUNT(*) as c, AVG(post_mood-pre_mood) as mood_lift FROM thermal_sessions WHERE user_id=? GROUP BY therapy_type ORDER BY c DESC`).all(req.user.id);
  const goal = db.prepare(`SELECT * FROM thermal_goals WHERE user_id=? LIMIT 1`).get(req.user.id);
  res.json({ ...avg, by_type, goals: goal });
});
// ─── End B505 ────────────────────────────────────────────────────────────────

// ─── B506: Personal Bonsai Collection & Care Journal ─────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS bonsai_trees (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, tree_name TEXT,
    species TEXT DEFAULT 'Juniper', style TEXT DEFAULT 'informal_upright',
    age_years INTEGER DEFAULT 5, trunk_diameter_in REAL DEFAULT 1,
    height_in REAL DEFAULT 12, pot_type TEXT DEFAULT 'ceramic',
    soil_mix TEXT DEFAULT 'akadama_pumice', acquisition_date DATE,
    acquisition_price REAL DEFAULT 0, current_value REAL DEFAULT 0,
    health_status TEXT DEFAULT 'healthy', last_repotted DATE,
    last_pruned DATE, last_wired DATE, wire_on INTEGER DEFAULT 0,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS bonsai_care_logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT, tree_id INTEGER, user_id INTEGER,
    care_date DATE, activity TEXT DEFAULT 'watered',
    fertilizer_used TEXT, notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/bonsai', requireAuth, (req: any, res: any) => {
  const trees = db.prepare(`SELECT t.*, (SELECT MAX(care_date) FROM bonsai_care_logs WHERE tree_id=t.id) as last_care FROM bonsai_trees t WHERE t.user_id=? ORDER BY t.current_value DESC`).all(req.user.id) as any[];
  const by_species = db.prepare(`SELECT species, COUNT(*) as c FROM bonsai_trees WHERE user_id=? GROUP BY species ORDER BY c DESC`).all(req.user.id);
  const needs_wire_removal = trees.filter((t: any) => t.wire_on);
  res.json({ trees, count: trees.length, by_species, needs_wire_removal: needs_wire_removal.length, total_value: trees.reduce((s: number, t: any) => s + t.current_value, 0) });
});
app.post('/api/bonsai', requireAuth, (req: any, res: any) => {
  const { tree_name, species, style, age_years, trunk_diameter_in, height_in, pot_type, acquisition_date, acquisition_price } = req.body;
  if (!tree_name) return res.status(400).json({ error: 'tree_name required' });
  const r = db.prepare(`INSERT INTO bonsai_trees (user_id,tree_name,species,style,age_years,trunk_diameter_in,height_in,pot_type,acquisition_date,acquisition_price,current_value) VALUES (?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, tree_name, species||'Juniper', style||'informal_upright', age_years||5, trunk_diameter_in||1, height_in||12, pot_type||'ceramic', acquisition_date||null, acquisition_price||0, acquisition_price||0);
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/bonsai/:id/care', requireAuth, (req: any, res: any) => {
  const { care_date, activity, fertilizer_used, notes } = req.body;
  const r = db.prepare(`INSERT INTO bonsai_care_logs (tree_id,user_id,care_date,activity,fertilizer_used,notes) VALUES (?,?,?,?,?,?)`).run(req.params.id, req.user.id, care_date||new Date().toISOString().slice(0,10), activity||'watered', fertilizer_used||null, notes||'');
  if (activity==='wired') db.prepare(`UPDATE bonsai_trees SET wire_on=1, last_wired=? WHERE id=? AND user_id=?`).run(care_date||new Date().toISOString().slice(0,10), req.params.id, req.user.id);
  if (activity==='wire_removed') db.prepare(`UPDATE bonsai_trees SET wire_on=0 WHERE id=? AND user_id=?`).run(req.params.id, req.user.id);
  if (activity==='repotted') db.prepare(`UPDATE bonsai_trees SET last_repotted=? WHERE id=? AND user_id=?`).run(care_date||new Date().toISOString().slice(0,10), req.params.id, req.user.id);
  if (activity==='pruned') db.prepare(`UPDATE bonsai_trees SET last_pruned=? WHERE id=? AND user_id=?`).run(care_date||new Date().toISOString().slice(0,10), req.params.id, req.user.id);
  res.json({ id: r.lastInsertRowid });
});
