// ─── B507: Personal Freediving & Breath-Hold Training ────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS freediving_sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, session_date DATE,
    location TEXT DEFAULT 'pool', water_temp_f INTEGER DEFAULT 75,
    session_type TEXT DEFAULT 'static_apnea', dives INTEGER DEFAULT 5,
    max_depth_ft REAL DEFAULT 10, max_hold_secs INTEGER DEFAULT 90,
    avg_hold_secs INTEGER DEFAULT 60, total_dive_mins INTEGER DEFAULT 30,
    surface_interval_secs INTEGER DEFAULT 120, samba_events INTEGER DEFAULT 0,
    blackout_events INTEGER DEFAULT 0, buddy_name TEXT,
    warmup_mins INTEGER DEFAULT 10, notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS pb_records (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER,
    discipline TEXT DEFAULT 'STA', pb_value REAL DEFAULT 0,
    pb_unit TEXT DEFAULT 'seconds', pb_date DATE,
    location TEXT, verified INTEGER DEFAULT 0,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.post('/api/freediving/sessions', requireAuth, (req: any, res: any) => {
  const { session_date, location, session_type, dives, max_depth_ft, max_hold_secs, avg_hold_secs, buddy_name } = req.body;
  const r = db.prepare(`INSERT INTO freediving_sessions (user_id,session_date,location,session_type,dives,max_depth_ft,max_hold_secs,avg_hold_secs,buddy_name) VALUES (?,?,?,?,?,?,?,?,?)`).run(req.user.id, session_date||new Date().toISOString().slice(0,10), location||'pool', session_type||'static_apnea', dives||5, max_depth_ft||10, max_hold_secs||90, avg_hold_secs||60, buddy_name||'solo');
  const pb = db.prepare(`SELECT pb_value FROM pb_records WHERE user_id=? AND discipline=?`).get(req.user.id, session_type||'static_apnea') as any;
  const is_pb = (max_hold_secs||90) > (pb?.pb_value||0);
  if (is_pb) {
    const existing = db.prepare(`SELECT id FROM pb_records WHERE user_id=? AND discipline=?`).get(req.user.id, session_type||'static_apnea');
    if (existing) db.prepare(`UPDATE pb_records SET pb_value=?, pb_date=? WHERE user_id=? AND discipline=?`).run(max_hold_secs||90, session_date||new Date().toISOString().slice(0,10), req.user.id, session_type||'static_apnea');
    else db.prepare(`INSERT INTO pb_records (user_id,discipline,pb_value,pb_unit,pb_date) VALUES (?,?,?,'seconds',?)`).run(req.user.id, session_type||'static_apnea', max_hold_secs||90, session_date||new Date().toISOString().slice(0,10));
  }
  res.json({ id: r.lastInsertRowid, personal_best: is_pb });
});
app.get('/api/freediving/stats', requireAuth, (req: any, res: any) => {
  const pbs = db.prepare(`SELECT * FROM pb_records WHERE user_id=? ORDER BY discipline`).all(req.user.id);
  const recent = db.prepare(`SELECT * FROM freediving_sessions WHERE user_id=? ORDER BY session_date DESC LIMIT 10`).all(req.user.id);
  const avg = db.prepare(`SELECT AVG(max_hold_secs) as avg_max, AVG(dives) as avg_dives, COUNT(*) as sessions FROM freediving_sessions WHERE user_id=? AND session_date>=date('now','-90 days')`).get(req.user.id);
  res.json({ personal_bests: pbs, recent_sessions: recent, ...avg });
});
// ─── End B507 ────────────────────────────────────────────────────────────────

// ─── B508: Personal Urban Photography Walk Planner ───────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS photo_walks (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, walk_name TEXT,
    walk_date DATE, city TEXT DEFAULT 'home_city',
    neighborhoods TEXT DEFAULT '[]', route_description TEXT,
    distance_miles REAL DEFAULT 2, duration_mins INTEGER DEFAULT 90,
    weather TEXT DEFAULT 'sunny', time_of_day TEXT DEFAULT 'golden_hour',
    camera_used TEXT DEFAULT 'mirrorless', lens_used TEXT DEFAULT '35mm',
    shots_taken INTEGER DEFAULT 0, keepers INTEGER DEFAULT 0,
    best_shot_desc TEXT, themes TEXT DEFAULT '[]',
    mood TEXT DEFAULT 'focused', notes TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/photo-walks', requireAuth, (req: any, res: any) => {
  const walks = db.prepare(`SELECT * FROM photo_walks WHERE user_id=? ORDER BY walk_date DESC`).all(req.user.id) as any[];
  const total_shots = walks.reduce((s: number, w: any) => s + w.shots_taken, 0);
  const total_keepers = walks.reduce((s: number, w: any) => s + w.keepers, 0);
  const hit_rate = total_shots > 0 ? Math.round(total_keepers/total_shots*1000)/10 : 0;
  const by_city = db.prepare(`SELECT city, COUNT(*) as walks, SUM(shots_taken) as shots FROM photo_walks WHERE user_id=? GROUP BY city ORDER BY walks DESC`).all(req.user.id);
  res.json({ walks, count: walks.length, total_shots, total_keepers, hit_rate_pct: hit_rate, by_city });
});
app.post('/api/photo-walks', requireAuth, (req: any, res: any) => {
  const { walk_name, walk_date, city, neighborhoods, distance_miles, duration_mins, weather, time_of_day, camera_used, lens_used, shots_taken, keepers, best_shot_desc, themes } = req.body;
  if (!walk_name) return res.status(400).json({ error: 'walk_name required' });
  const r = db.prepare(`INSERT INTO photo_walks (user_id,walk_name,walk_date,city,neighborhoods,distance_miles,duration_mins,weather,time_of_day,camera_used,lens_used,shots_taken,keepers,best_shot_desc,themes) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, walk_name, walk_date||new Date().toISOString().slice(0,10), city||'home_city', JSON.stringify(neighborhoods||[]), distance_miles||2, duration_mins||90, weather||'sunny', time_of_day||'golden_hour', camera_used||'mirrorless', lens_used||'35mm', shots_taken||0, keepers||0, best_shot_desc||'', JSON.stringify(themes||[]));
  res.json({ id: r.lastInsertRowid });
});
