  const r = db.prepare(`INSERT INTO detecting_sessions (user_id,session_date,location,location_type,detector_model,duration_mins,best_find,best_find_value) VALUES (?,?,?,?,?,?,?,?)`).run(req.user.id, session_date||new Date().toISOString().slice(0,10), location||'park', location_type||'park', detector_model||'Minelab Equinox 800', duration_mins||120, best_find||'', best_find_value||0);
