// ─── B510: Personal Tabletop RPG Campaign Manager ─────────────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS rpg_campaigns (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, campaign_name TEXT,
    system TEXT DEFAULT 'DnD 5e', setting TEXT DEFAULT 'Forgotten Realms',
    role TEXT DEFAULT 'player', dm_name TEXT, session_count INTEGER DEFAULT 0,
    is_active INTEGER DEFAULT 1, start_date DATE,
    player_character TEXT, character_class TEXT, character_level INTEGER DEFAULT 1,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS rpg_sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT, campaign_id INTEGER, user_id INTEGER,
    session_date DATE, session_number INTEGER DEFAULT 1,
    duration_hours REAL DEFAULT 3, players_count INTEGER DEFAULT 4,
    summary TEXT, highlights TEXT DEFAULT '[]',
    xp_gained INTEGER DEFAULT 0, loot TEXT DEFAULT '[]',
    npc_met TEXT DEFAULT '[]', cliffhanger TEXT,
    dm_rating INTEGER DEFAULT 4, fun_rating INTEGER DEFAULT 4,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.get('/api/rpg/campaigns', requireAuth, (req: any, res: any) => {
  const campaigns = db.prepare(`SELECT c.*, (SELECT MAX(session_date) FROM rpg_sessions WHERE campaign_id=c.id) as last_session FROM rpg_campaigns c WHERE c.user_id=? ORDER BY c.is_active DESC, c.session_count DESC`).all(req.user.id);
  const total_hours = (db.prepare(`SELECT SUM(duration_hours) as h FROM rpg_sessions WHERE user_id=?`).get(req.user.id) as any)?.h||0;
  res.json({ campaigns, total_campaigns: (campaigns as any[]).length, total_hours_played: Math.round(total_hours) });
});
app.post('/api/rpg/campaigns', requireAuth, (req: any, res: any) => {
  const { campaign_name, system, setting, role, dm_name, player_character, character_class } = req.body;
  if (!campaign_name) return res.status(400).json({ error: 'campaign_name required' });
  const r = db.prepare(`INSERT INTO rpg_campaigns (user_id,campaign_name,system,setting,role,dm_name,player_character,character_class,start_date) VALUES (?,?,?,?,?,?,?,?,?)`).run(req.user.id, campaign_name, system||'DnD 5e', setting||'Forgotten Realms', role||'player', dm_name||'', player_character||'', character_class||'', new Date().toISOString().slice(0,10));
  res.json({ id: r.lastInsertRowid });
});
app.post('/api/rpg/campaigns/:id/sessions', requireAuth, (req: any, res: any) => {
  const { session_date, duration_hours, players_count, summary, xp_gained, highlights, cliffhanger, fun_rating } = req.body;
  const campaign = db.prepare(`SELECT session_count FROM rpg_campaigns WHERE id=? AND user_id=?`).get(req.params.id, req.user.id) as any;
  const session_number = (campaign?.session_count||0)+1;
  const r = db.prepare(`INSERT INTO rpg_sessions (campaign_id,user_id,session_date,session_number,duration_hours,players_count,summary,xp_gained,highlights,cliffhanger,fun_rating) VALUES (?,?,?,?,?,?,?,?,?,?,?)`).run(req.params.id, req.user.id, session_date||new Date().toISOString().slice(0,10), session_number, duration_hours||3, players_count||4, summary||'', xp_gained||0, JSON.stringify(highlights||[]), cliffhanger||'', fun_rating||4);
  db.prepare(`UPDATE rpg_campaigns SET session_count=session_count+1 WHERE id=? AND user_id=?`).run(req.params.id, req.user.id);
  if (xp_gained) {
    const xp_thresholds = [300,900,2700,6500,14000,23000,34000,48000,64000,85000,100000,120000,140000,165000,195000,225000,265000,305000,355000];
    const cam = db.prepare(`SELECT character_level FROM rpg_campaigns WHERE id=?`).get(req.params.id) as any;
    const total_xp_approx = ((cam?.character_level||1)-1)*10000 + (xp_gained||0);
    const new_level = Math.min(20, xp_thresholds.findIndex((t: number) => total_xp_approx < t)+1||20);
    if (new_level > (cam?.character_level||1)) db.prepare(`UPDATE rpg_campaigns SET character_level=? WHERE id=? AND user_id=?`).run(new_level, req.params.id, req.user.id);
  }
  res.json({ id: r.lastInsertRowid, session_number });
});
// ─── End B510 ────────────────────────────────────────────────────────────────

