app.post('/api/shooting/matches', requireAuth, (req: any, res: any) => {
  const { match_date, match_name, discipline, division, location, stage_count, total_points, total_time_secs, finish_position, total_competitors, mikes } = req.body;
  const hit_factor = total_time_secs > 0 ? Math.round((total_points||0)/total_time_secs*100)/100 : 0;
  const percentage = total_competitors > 0 ? Math.round(((total_competitors-((finish_position||1)-1))/total_competitors)*100*10)/10 : 0;
  const r = db.prepare(`INSERT INTO shooting_matches (user_id,match_date,match_name,discipline,division,location,stage_count,total_points,total_time_secs,hit_factor,finish_position,total_competitors,percentage,mikes) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, match_date||new Date().toISOString().slice(0,10), match_name||'local match', discipline||'USPSA', division||'Production', location||'', stage_count||4, total_points||0, total_time_secs||60, hit_factor, finish_position||1, total_competitors||10, percentage, mikes||0);
  res.json({ id: r.lastInsertRowid, hit_factor, percentage });
});
