// ─── B525: Personal Financial Independence (FIRE) Tracker ─────────────────────
try { db.exec(`
  CREATE TABLE IF NOT EXISTS fire_snapshots (
    id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, snapshot_date DATE,
    total_investments REAL DEFAULT 0, total_cash REAL DEFAULT 0,
    total_real_estate REAL DEFAULT 0, total_debt REAL DEFAULT 0,
    monthly_expenses REAL DEFAULT 3000, annual_expenses REAL DEFAULT 0,
    monthly_savings REAL DEFAULT 1000, annual_income REAL DEFAULT 0,
    target_number REAL DEFAULT 0, fire_type TEXT DEFAULT 'lean_fire',
    swr_pct REAL DEFAULT 4.0, coast_fire_number REAL DEFAULT 0,
    notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
`); } catch(e) {}

app.post('/api/fire/snapshot', requireAuth, (req: any, res: any) => {
  const { snapshot_date, total_investments, total_cash, total_real_estate, total_debt, monthly_expenses, monthly_savings, annual_income, fire_type, swr_pct } = req.body;
  const annual_exp = (monthly_expenses||3000)*12;
  const swr = (swr_pct||4.0)/100;
  const target = annual_exp / swr;
  const net_worth = (total_investments||0)+(total_cash||0)+(total_real_estate||0)-(total_debt||0);
  const fire_pct = target > 0 ? Math.round(net_worth/target*1000)/10 : 0;
  const months_to_fire = monthly_savings > 0 && target > net_worth ? Math.ceil((target-net_worth)/monthly_savings) : 0;
  const r = db.prepare(`INSERT INTO fire_snapshots (user_id,snapshot_date,total_investments,total_cash,total_real_estate,total_debt,monthly_expenses,annual_expenses,monthly_savings,annual_income,target_number,fire_type,swr_pct) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(req.user.id, snapshot_date||new Date().toISOString().slice(0,10), total_investments||0, total_cash||0, total_real_estate||0, total_debt||0, monthly_expenses||3000, annual_exp, monthly_savings||1000, annual_income||0, target, fire_type||'lean_fire', swr_pct||4.0);
  res.json({ id: r.lastInsertRowid, net_worth, fire_number: target, fire_pct, months_to_fire, years_to_fire: Math.round(months_to_fire/12*10)/10 });
});
app.get('/api/fire/progress', requireAuth, (req: any, res: any) => {
  const snapshots = db.prepare(`SELECT * FROM fire_snapshots WHERE user_id=? ORDER BY snapshot_date DESC LIMIT 24`).all(req.user.id) as any[];
  if (snapshots.length === 0) return res.json({ snapshots: [] });
  const latest = snapshots[0] as any;
  const net_worth = latest.total_investments+latest.total_cash+latest.total_real_estate-latest.total_debt;
  const fire_pct = latest.target_number > 0 ? Math.round(net_worth/latest.target_number*1000)/10 : 0;
  const oldest = snapshots[snapshots.length-1] as any;
  const old_nw = oldest.total_investments+oldest.total_cash+oldest.total_real_estate-oldest.total_debt;
  const nw_growth = net_worth-old_nw;
  res.json({ snapshots, current_net_worth: net_worth, fire_number: latest.target_number, fire_pct, net_worth_growth: nw_growth });
});
// ─── End B525 ────────────────────────────────────────────────────────────────

