app.post('/api/birding/sightings', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { feeder_id, species, count=1, sighting_date, behavior, photo_taken=0, notes } = req.body;
    if (!species) return res.status(400).json({ success: false, error: 'species required' });
    const existing = db.prepare(`SELECT id FROM bird_sightings WHERE user_id=? AND species=?`).get(uid, species);
    const life_bird = existing ? 0 : 1;
    const r = db.prepare(`INSERT INTO bird_sightings (user_id,feeder_id,species,count,sighting_date,behavior,photo_taken,life_bird) VALUES (?,?,?,?,?,?,?,?)`).run(uid,feeder_id,species,count,sighting_date||new Date().toISOString().slice(0,10),behavior,photo_taken,life_bird);
    res.json({ success: true, id: r.lastInsertRowid, life_bird: !!life_bird, message: life_bird ? `New life bird: ${species}!` : `${species} sighted again` });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

