    const uid = req.user.id;
    const { name, wall_type='woody', height_ft, width_ft, angle_deg=0, t_nuts=0, budget_usd=0, actual_cost_usd=0, notes } = req.body;
    if (!name) return res.status(400).json({ success: false, error: 'name required' });
    const sqft = height_ft && width_ft ? Math.round(height_ft * width_ft) : null;
