try {
  db.exec(`CREATE TABLE IF NOT EXISTS mushroom_grows (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    species TEXT NOT NULL,
    substrate TEXT DEFAULT 'masters_mix',
    inoculation_date TEXT,
    colonization_days INTEGER,
    fruiting_start TEXT,
    flush_number INTEGER DEFAULT 1,
    yield_grams REAL DEFAULT 0,
    contaminated INTEGER DEFAULT 0,
    notes TEXT,
    created_at TEXT DEFAULT (datetime('now'))
  )`);
  db.exec(`CREATE TABLE IF NOT EXISTS mushroom_spawn (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    culture_name TEXT NOT NULL,
    source TEXT,
    date_created TEXT DEFAULT (date('now')),
    transfers_made INTEGER DEFAULT 0,
    viable INTEGER DEFAULT 1,
    notes TEXT,
    created_at TEXT DEFAULT (datetime('now'))
  )`);
} catch(e) {}

app.get('/api/mycultivation/grows', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const grows = db.prepare(`SELECT * FROM mushroom_grows WHERE user_id=? ORDER BY created_at DESC`).all(uid);
    const stats = db.prepare(`SELECT COUNT(*) as total_grows, SUM(yield_grams) as total_yield_g, AVG(yield_grams) as avg_yield_g, AVG(colonization_days) as avg_colonization, SUM(CASE WHEN contaminated=1 THEN 1 ELSE 0 END) as contaminations FROM mushroom_grows WHERE user_id=?`).get(uid) as any;
    const by_species = db.prepare(`SELECT species, COUNT(*) as grows, AVG(yield_grams) as avg_yield, SUM(yield_grams) as total_yield FROM mushroom_grows WHERE user_id=? AND contaminated=0 GROUP BY species ORDER BY total_yield DESC`).all(uid);
    const spawn = db.prepare(`SELECT * FROM mushroom_spawn WHERE user_id=? ORDER BY date_created DESC`).all(uid);
    res.json({ success: true, grows, stats: { ...stats, success_rate: stats?.total_grows > 0 ? Math.round((1-stats.contaminations/stats.total_grows)*100) : 100 }, by_species, spawn });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

app.post('/api/mycultivation/grows', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { species, substrate='masters_mix', inoculation_date, notes } = req.body;
    if (!species) return res.status(400).json({ success: false, error: 'species required' });
    const r = db.prepare(`INSERT INTO mushroom_grows (user_id,species,substrate,inoculation_date,notes) VALUES (?,?,?,?,?)`).run(uid,species,substrate,inoculation_date||new Date().toISOString().slice(0,10),notes);
    res.json({ success: true, id: r.lastInsertRowid });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

app.post('/api/mycultivation/grows/:id/harvest', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { yield_grams=0, flush_number=1, contaminated=0, colonization_days, notes } = req.body;
    db.prepare(`UPDATE mushroom_grows SET yield_grams=yield_grams+?,flush_number=?,contaminated=?,colonization_days=COALESCE(colonization_days,?),notes=COALESCE(?,notes) WHERE id=? AND user_id=?`).run(yield_grams,flush_number,contaminated,colonization_days,notes,req.params.id,uid);
    res.json({ success: true, message: contaminated ? 'Contamination logged' : `Harvest recorded: ${yield_grams}g flush #${flush_number}` });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

// ─── B548: Speed Cubing & Puzzle Collection ───────────────────────────────────
try {
  db.exec(`CREATE TABLE IF NOT EXISTS cubing_solves (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    puzzle_type TEXT DEFAULT '3x3',
    solve_time_ms INTEGER NOT NULL,
    scramble TEXT,
    dnf INTEGER DEFAULT 0,
    plus_two INTEGER DEFAULT 0,
    notes TEXT,
    created_at TEXT DEFAULT (datetime('now'))
  )`);
  db.exec(`CREATE TABLE IF NOT EXISTS cube_collection (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    name TEXT NOT NULL,
    puzzle_type TEXT DEFAULT '3x3',
    brand TEXT,
    cost_usd REAL DEFAULT 0,
    lubed INTEGER DEFAULT 0,
    tensioned INTEGER DEFAULT 0,
    rating INTEGER,
    notes TEXT,
    created_at TEXT DEFAULT (datetime('now'))
  )`);
} catch(e) {}

app.get('/api/cubing/stats', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const by_puzzle = db.prepare(`SELECT puzzle_type, COUNT(*) as solves, MIN(CASE WHEN dnf=0 THEN solve_time_ms END) as pb_ms, AVG(CASE WHEN dnf=0 THEN solve_time_ms END) as avg_ms FROM cubing_solves WHERE user_id=? GROUP BY puzzle_type ORDER BY solves DESC`).all(uid);
    // ao5 and ao12 for most recent 3x3
    const recent = db.prepare(`SELECT solve_time_ms, dnf, plus_two FROM cubing_solves WHERE user_id=? AND puzzle_type='3x3' ORDER BY created_at DESC LIMIT 12`).all(uid) as any[];
    const valid5 = recent.slice(0,5).filter((s: any)=>!s.dnf).map((s: any)=>s.solve_time_ms+(s.plus_two?2000:0));
    const ao5 = valid5.length >= 3 ? Math.round(valid5.reduce((a: number,b: number)=>a+b,0)/valid5.length) : null;
    const collection = db.prepare(`SELECT * FROM cube_collection WHERE user_id=? ORDER BY created_at DESC`).all(uid);
    res.json({ success: true, by_puzzle, ao5_ms: ao5, recent_3x3: recent.slice(0,5), collection });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

app.post('/api/cubing/solves', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { puzzle_type='3x3', solve_time_ms, scramble, dnf=0, plus_two=0, notes } = req.body;
    if (!solve_time_ms) return res.status(400).json({ success: false, error: 'solve_time_ms required' });
    const r = db.prepare(`INSERT INTO cubing_solves (user_id,puzzle_type,solve_time_ms,scramble,dnf,plus_two,notes) VALUES (?,?,?,?,?,?,?)`).run(uid,puzzle_type,solve_time_ms,scramble,dnf,plus_two,notes);
    const pb = db.prepare(`SELECT MIN(solve_time_ms) as pb FROM cubing_solves WHERE user_id=? AND puzzle_type=? AND dnf=0`).get(uid,puzzle_type) as any;
    res.json({ success: true, id: r.lastInsertRowid, is_pb: !dnf && solve_time_ms <= (pb?.pb||Infinity), pb_ms: pb?.pb });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

app.post('/api/cubing/collection', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { name, puzzle_type='3x3', brand, cost_usd=0, rating, notes } = req.body;
    if (!name) return res.status(400).json({ success: false, error: 'name required' });
    const r = db.prepare(`INSERT INTO cube_collection (user_id,name,puzzle_type,brand,cost_usd,rating,notes) VALUES (?,?,?,?,?,?,?)`).run(uid,name,puzzle_type,brand,cost_usd,rating,notes);
    res.json({ success: true, id: r.lastInsertRowid });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

