app.get('/api/swim/stats', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const sessions = db.prepare(`SELECT * FROM swim_sessions WHERE user_id=? ORDER BY session_date DESC LIMIT 30`).all(uid);
    const totals = db.prepare(`SELECT COUNT(*) as sessions, SUM(total_distance_m) as total_meters, SUM(duration_minutes) as total_minutes FROM swim_sessions WHERE user_id=?`).get(uid) as any;
    const pbs = db.prepare(`SELECT * FROM swim_pbs WHERE user_id=? ORDER BY event`).all(uid);
    const by_stroke = db.prepare(`SELECT stroke, COUNT(*) as sessions, SUM(total_distance_m) as meters FROM swim_sessions WHERE user_id=? GROUP BY stroke ORDER BY sessions DESC`).all(uid);
    res.json({ success: true, sessions, totals: { ...totals, total_km: Math.round((totals?.total_meters||0)/1000*10)/10 }, pbs, by_stroke });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

app.post('/api/swim/sessions', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { session_date, pool_length_m=25, total_distance_m=0, duration_minutes=0, stroke='freestyle', main_set, notes } = req.body;
    const avg_pace = duration_minutes > 0 && total_distance_m > 0 ? Math.round(duration_minutes*60/(total_distance_m/100)) : null;
    const r = db.prepare(`INSERT INTO swim_sessions (user_id,session_date,pool_length_m,total_distance_m,duration_minutes,stroke,main_set,avg_pace_per_100m,notes) VALUES (?,?,?,?,?,?,?,?,?)`).run(uid,session_date||new Date().toISOString().slice(0,10),pool_length_m,total_distance_m,duration_minutes,stroke,main_set,avg_pace,notes);
    res.json({ success: true, id: r.lastInsertRowid, avg_pace_per_100m_seconds: avg_pace });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

app.post('/api/swim/pb', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { event, time_seconds, course='SCY', set_date } = req.body;
    if (!event || !time_seconds) return res.status(400).json({ success: false, error: 'event and time_seconds required' });
    const existing = db.prepare(`SELECT id, time_seconds FROM swim_pbs WHERE user_id=? AND event=? AND course=?`).get(uid,event,course) as any;
    if (existing) {
      if (time_seconds < existing.time_seconds) {
        db.prepare(`UPDATE swim_pbs SET time_seconds=?, set_date=? WHERE id=?`).run(time_seconds,set_date||new Date().toISOString().slice(0,10),existing.id);
        return res.json({ success: true, new_pb: true, improvement_seconds: Math.round((existing.time_seconds-time_seconds)*100)/100 });
      }
      return res.json({ success: true, new_pb: false, current_pb: existing.time_seconds });
    }
    const r = db.prepare(`INSERT INTO swim_pbs (user_id,event,time_seconds,course,set_date) VALUES (?,?,?,?,?)`).run(uid,event,time_seconds,course,set_date||new Date().toISOString().slice(0,10));
    res.json({ success: true, id: r.lastInsertRowid, new_pb: true });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

// ─── B558: Personal Sauna & Recovery Protocol ────────────────────────────────
try {
  db.exec(`CREATE TABLE IF NOT EXISTS sauna_sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    session_date TEXT DEFAULT (date('now')),
    sauna_type TEXT DEFAULT 'traditional',
    temp_f INTEGER DEFAULT 180,
    duration_minutes INTEGER DEFAULT 20,
    rounds INTEGER DEFAULT 1,
    cold_plunge INTEGER DEFAULT 0,
    cold_duration_seconds INTEGER DEFAULT 0,
    heart_rate_after INTEGER,
    sweat_liters REAL,
    mood_before INTEGER,
    mood_after INTEGER,
    notes TEXT,
    created_at TEXT DEFAULT (datetime('now'))
  )`);
} catch(e) {}

app.get('/api/sauna/stats', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const sessions = db.prepare(`SELECT * FROM sauna_sessions WHERE user_id=? ORDER BY session_date DESC LIMIT 30`).all(uid);
    const stats = db.prepare(`SELECT COUNT(*) as total_sessions, SUM(duration_minutes) as total_minutes, AVG(duration_minutes) as avg_duration, AVG(temp_f) as avg_temp, SUM(CASE WHEN cold_plunge=1 THEN 1 ELSE 0 END) as cold_plunge_count, AVG(mood_after - mood_before) as avg_mood_lift FROM sauna_sessions WHERE user_id=?`).get(uid) as any;
    const streak = (() => {
      const dates = (sessions as any[]).map((s: any) => s.session_date).sort().reverse();
      let s = 0; let d = new Date(); d.setHours(0,0,0,0);
      for (const dt of dates) {
        const sd = new Date(dt); sd.setHours(0,0,0,0);
        if (Math.abs(d.getTime()-sd.getTime()) <= 86400000) { s++; d=sd; } else break;
      }
      return s;
    })();
    res.json({ success: true, sessions, stats: { ...stats, current_streak: streak, total_hours: Math.round((stats?.total_minutes||0)/60*10)/10 } });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

app.post('/api/sauna/sessions', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { session_date, sauna_type='traditional', temp_f=180, duration_minutes=20, rounds=1, cold_plunge=0, cold_duration_seconds=0, heart_rate_after, sweat_liters, mood_before, mood_after, notes } = req.body;
    const r = db.prepare(`INSERT INTO sauna_sessions (user_id,session_date,sauna_type,temp_f,duration_minutes,rounds,cold_plunge,cold_duration_seconds,heart_rate_after,sweat_liters,mood_before,mood_after,notes) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(uid,session_date||new Date().toISOString().slice(0,10),sauna_type,temp_f,duration_minutes,rounds,cold_plunge,cold_duration_seconds,heart_rate_after,sweat_liters,mood_before,mood_after,notes);
    const tips = [];
    if (sweat_liters && sweat_liters > 1) tips.push('Rehydrate with electrolytes — significant sweat loss');
    if (!cold_plunge && rounds > 1) tips.push('Consider cold exposure between rounds for contrast therapy');
    res.json({ success: true, id: r.lastInsertRowid, tips });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

