// ─── B560: Personal Hedge Fund Simulator ──────────────────────────────────────
try {
  db.exec(`CREATE TABLE IF NOT EXISTS hedge_fund_portfolio (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    ticker TEXT NOT NULL,
    strategy TEXT DEFAULT 'long',
    shares REAL DEFAULT 0,
    entry_price_usd REAL DEFAULT 0,
    current_price_usd REAL DEFAULT 0,
    stop_loss_usd REAL,
    target_price_usd REAL,
    thesis TEXT,
    opened_date TEXT DEFAULT (date('now')),
    closed_date TEXT,
    closed_price_usd REAL,
    created_at TEXT DEFAULT (datetime('now'))
  )`);
  db.exec(`CREATE TABLE IF NOT EXISTS hedge_fund_trades (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    ticker TEXT NOT NULL,
    action TEXT DEFAULT 'buy',
    shares REAL DEFAULT 0,
    price_usd REAL DEFAULT 0,
    trade_date TEXT DEFAULT (date('now')),
    notes TEXT,
    created_at TEXT DEFAULT (datetime('now'))
  )`);
} catch(e) {}

app.get('/api/hedgefund/portfolio', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const positions = db.prepare(`SELECT *, (current_price_usd - entry_price_usd) * shares as unrealized_pnl, ROUND((current_price_usd - entry_price_usd) / NULLIF(entry_price_usd,0) * 100, 2) as return_pct, shares * current_price_usd as market_value FROM hedge_fund_portfolio WHERE user_id=? AND closed_date IS NULL ORDER BY market_value DESC`).all(uid);
    const total_value = (positions as any[]).reduce((s: number, p: any) => s + p.market_value, 0);
    const total_cost = (positions as any[]).reduce((s: number, p: any) => s + p.shares * p.entry_price_usd, 0);
    const closed = db.prepare(`SELECT *, (closed_price_usd - entry_price_usd) * shares as realized_pnl FROM hedge_fund_portfolio WHERE user_id=? AND closed_date IS NOT NULL ORDER BY closed_date DESC LIMIT 20`).all(uid);
    const realized_pnl = (closed as any[]).reduce((s: number, p: any) => s + (p.realized_pnl||0), 0);
    res.json({ success: true, positions, total_value: Math.round(total_value*100)/100, total_cost: Math.round(total_cost*100)/100, unrealized_pnl: Math.round((total_value-total_cost)*100)/100, realized_pnl: Math.round(realized_pnl*100)/100, closed_positions: closed });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

app.post('/api/hedgefund/positions', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { ticker, strategy='long', shares=0, entry_price_usd=0, current_price_usd, stop_loss_usd, target_price_usd, thesis } = req.body;
    if (!ticker || !shares) return res.status(400).json({ success: false, error: 'ticker and shares required' });
    const r = db.prepare(`INSERT INTO hedge_fund_portfolio (user_id,ticker,strategy,shares,entry_price_usd,current_price_usd,stop_loss_usd,target_price_usd,thesis) VALUES (?,?,?,?,?,?,?,?,?)`).run(uid,ticker.toUpperCase(),strategy,shares,entry_price_usd,current_price_usd||entry_price_usd,stop_loss_usd,target_price_usd,thesis);
    const risk_pct = stop_loss_usd ? Math.round((entry_price_usd-stop_loss_usd)/entry_price_usd*100*10)/10 : null;
    const reward_pct = target_price_usd ? Math.round((target_price_usd-entry_price_usd)/entry_price_usd*100*10)/10 : null;
    res.json({ success: true, id: r.lastInsertRowid, risk_pct, reward_pct, risk_reward: risk_pct && reward_pct ? Math.round(reward_pct/risk_pct*10)/10 : null });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

app.post('/api/hedgefund/positions/:id/close', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { closed_price_usd } = req.body;
    if (!closed_price_usd) return res.status(400).json({ success: false, error: 'closed_price_usd required' });
    const pos = db.prepare(`SELECT * FROM hedge_fund_portfolio WHERE id=? AND user_id=?`).get(req.params.id,uid) as any;
    if (!pos) return res.status(404).json({ success: false, error: 'position not found' });
    db.prepare(`UPDATE hedge_fund_portfolio SET closed_date=?,closed_price_usd=? WHERE id=?`).run(new Date().toISOString().slice(0,10),closed_price_usd,req.params.id);
    const pnl = (closed_price_usd - pos.entry_price_usd) * pos.shares;
    const return_pct = Math.round((closed_price_usd-pos.entry_price_usd)/pos.entry_price_usd*100*100)/100;
    res.json({ success: true, realized_pnl: Math.round(pnl*100)/100, return_pct });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

