try {
  db.exec(`CREATE TABLE IF NOT EXISTS print_jobs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    name TEXT NOT NULL,
    printer TEXT,
    material TEXT DEFAULT 'PLA',
    material_grams REAL DEFAULT 0,
    print_hours REAL DEFAULT 0,
    layer_height_mm REAL DEFAULT 0.2,
    infill_pct INTEGER DEFAULT 20,
    success INTEGER DEFAULT 1,
    failure_reason TEXT,
    cost_usd REAL DEFAULT 0,
    sold INTEGER DEFAULT 0,
    sale_price_usd REAL DEFAULT 0,
    notes TEXT,
    created_at TEXT DEFAULT (datetime('now'))
  )`);
} catch(e) {}

app.get('/api/3dprint/jobs', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const jobs = db.prepare(`SELECT * FROM print_jobs WHERE user_id=? ORDER BY created_at DESC`).all(uid);
    const stats = db.prepare(`SELECT COUNT(*) as total, SUM(CASE WHEN success=1 THEN 1 ELSE 0 END) as successes, SUM(material_grams) as total_grams, SUM(print_hours) as total_hours, SUM(cost_usd) as total_cost, SUM(CASE WHEN sold=1 THEN sale_price_usd ELSE 0 END) as revenue FROM print_jobs WHERE user_id=?`).get(uid) as any;
    const by_material = db.prepare(`SELECT material, COUNT(*) as jobs, SUM(material_grams) as grams FROM print_jobs WHERE user_id=? GROUP BY material ORDER BY grams DESC`).all(uid);
    const fail_reasons = db.prepare(`SELECT failure_reason, COUNT(*) as count FROM print_jobs WHERE user_id=? AND success=0 AND failure_reason IS NOT NULL GROUP BY failure_reason ORDER BY count DESC`).all(uid);
    res.json({ success: true, jobs, stats: { ...stats, success_rate: stats?.total > 0 ? Math.round(stats.successes/stats.total*100) : 100, total_kg: Math.round((stats?.total_grams||0)/1000*100)/100 }, by_material, fail_reasons });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

app.post('/api/3dprint/jobs', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { name, printer, material='PLA', material_grams=0, print_hours=0, layer_height_mm=0.2, infill_pct=20, success=1, failure_reason, notes } = req.body;
    if (!name) return res.status(400).json({ success: false, error: 'name required' });
    const filament_cost_per_gram = material === 'TPU' ? 0.05 : material === 'PETG' ? 0.03 : 0.02;
    const cost_usd = Math.round(material_grams * filament_cost_per_gram * 100)/100;
    const r = db.prepare(`INSERT INTO print_jobs (user_id,name,printer,material,material_grams,print_hours,layer_height_mm,infill_pct,success,failure_reason,cost_usd,notes) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)`).run(uid,name,printer,material,material_grams,print_hours,layer_height_mm,infill_pct,success,failure_reason,cost_usd,notes);
    res.json({ success: true, id: r.lastInsertRowid, estimated_material_cost_usd: cost_usd });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

