app.get('/api/energy/overview', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const bills = db.prepare(`SELECT * FROM energy_bills WHERE user_id=? ORDER BY bill_month DESC LIMIT 24`).all(uid);
    const yearly = db.prepare(`SELECT strftime('%Y',bill_month) as year, SUM(kwh_used) as kwh, SUM(amount_usd) as cost FROM energy_bills WHERE user_id=? GROUP BY year ORDER BY year DESC LIMIT 3`).all(uid);
    const improvements = db.prepare(`SELECT * FROM energy_improvements WHERE user_id=? ORDER BY created_at DESC`).all(uid);
    const total_savings = (improvements as any[]).reduce((s: number, i: any) => s + (i.annual_savings_usd||0), 0);
    const total_improvement_cost = (improvements as any[]).reduce((s: number, i: any) => s + (i.cost_usd||0), 0);
    res.json({ success: true, bills, yearly_trends: yearly, improvements, total_annual_savings: Math.round(total_savings*100)/100, total_improvement_cost: Math.round(total_improvement_cost*100)/100, payback_years: total_savings > 0 ? Math.round(total_improvement_cost/total_savings*10)/10 : null });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

app.post('/api/energy/bills', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { bill_month, utility_type='electric', kwh_used=0, therms_used=0, amount_usd=0, notes } = req.body;
    if (!bill_month) return res.status(400).json({ success: false, error: 'bill_month required (YYYY-MM)' });
    const rate_per_kwh = kwh_used > 0 ? Math.round(amount_usd/kwh_used*1000)/1000 : null;
    const r = db.prepare(`INSERT INTO energy_bills (user_id,bill_month,utility_type,kwh_used,therms_used,amount_usd,rate_per_kwh,notes) VALUES (?,?,?,?,?,?,?,?)`).run(uid,bill_month,utility_type,kwh_used,therms_used,amount_usd,rate_per_kwh,notes);
    const prev = db.prepare(`SELECT kwh_used, amount_usd FROM energy_bills WHERE user_id=? AND utility_type=? AND bill_month < ? ORDER BY bill_month DESC LIMIT 1`).get(uid,utility_type,bill_month) as any;
    const yoy_change = prev?.kwh_used > 0 ? Math.round((kwh_used-prev.kwh_used)/prev.kwh_used*1000)/10 : null;
    res.json({ success: true, id: r.lastInsertRowid, rate_per_kwh, yoy_change_pct: yoy_change });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

