// ─── B571: Competitive Crossword Solving ──────────────────────────────────────
try {
  db.exec(`CREATE TABLE IF NOT EXISTS crossword_solves (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    puzzle_date TEXT DEFAULT (date('now')),
    publication TEXT DEFAULT 'NYT',
    day_of_week TEXT,
    solve_time_seconds INTEGER,
    completed INTEGER DEFAULT 1,
    errors INTEGER DEFAULT 0,
    hints_used INTEGER DEFAULT 0,
    notes TEXT,
    created_at TEXT DEFAULT (datetime('now'))
  )`);
} catch(e) {}

app.get('/api/crossword/stats', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const solves = db.prepare(`SELECT * FROM crossword_solves WHERE user_id=? ORDER BY puzzle_date DESC LIMIT 30`).all(uid);
    const by_day = db.prepare(`SELECT day_of_week, COUNT(*) as count, AVG(solve_time_seconds) as avg_secs, MIN(solve_time_seconds) as pb FROM crossword_solves WHERE user_id=? AND completed=1 AND solve_time_seconds IS NOT NULL GROUP BY day_of_week ORDER BY CASE day_of_week WHEN 'Monday' THEN 1 WHEN 'Tuesday' THEN 2 WHEN 'Wednesday' THEN 3 WHEN 'Thursday' THEN 4 WHEN 'Friday' THEN 5 WHEN 'Saturday' THEN 6 WHEN 'Sunday' THEN 7 END`).all(uid);
    const overall = db.prepare(`SELECT COUNT(*) as total, SUM(completed) as completed, AVG(solve_time_seconds) as avg_secs, MIN(solve_time_seconds) as fastest FROM crossword_solves WHERE user_id=?`).get(uid);
    res.json({ success: true, recent: solves, by_day, overall });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

app.post('/api/crossword/solves', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { puzzle_date, publication='NYT', day_of_week, solve_time_seconds, completed=1, errors=0, hints_used=0, notes } = req.body;
    const r = db.prepare(`INSERT INTO crossword_solves (user_id,puzzle_date,publication,day_of_week,solve_time_seconds,completed,errors,hints_used,notes) VALUES (?,?,?,?,?,?,?,?,?)`).run(uid,puzzle_date||new Date().toISOString().slice(0,10),publication,day_of_week,solve_time_seconds,completed,errors,hints_used,notes);
    const pb = db.prepare(`SELECT MIN(solve_time_seconds) as pb FROM crossword_solves WHERE user_id=? AND day_of_week=? AND completed=1`).get(uid,day_of_week) as any;
    const is_pb = pb && solve_time_seconds && solve_time_seconds <= pb.pb;
    res.json({ success: true, id: r.lastInsertRowid, personal_best: is_pb });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

