try {
  db.exec(`CREATE TABLE IF NOT EXISTS wine_batches (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    batch_name TEXT NOT NULL,
    wine_type TEXT DEFAULT 'red',
    grape_variety TEXT,
    start_date TEXT DEFAULT (date('now')),
    gallons REAL DEFAULT 1,
    sg_start REAL,
    sg_current REAL,
    sg_final REAL,
    status TEXT DEFAULT 'fermenting',
    bottles_produced INTEGER DEFAULT 0,
    cost_usd REAL DEFAULT 0,
    tasting_notes TEXT,
    notes TEXT,
    created_at TEXT DEFAULT (datetime('now'))
  )`);
} catch(e) {}

app.get('/api/winemaking/batches', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const batches = db.prepare(`SELECT * FROM wine_batches WHERE user_id=? ORDER BY start_date DESC`).all(uid);
    const stats = db.prepare(`SELECT COUNT(*) as total, SUM(CASE WHEN status='bottled' THEN bottles_produced ELSE 0 END) as total_bottles, AVG(CASE WHEN sg_start IS NOT NULL AND sg_final IS NOT NULL THEN ROUND((sg_start - sg_final)*131.25,1) END) as avg_abv FROM wine_batches WHERE user_id=?`).get(uid);
    res.json({ success: true, batches, stats });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

app.post('/api/winemaking/batches', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { batch_name, wine_type='red', grape_variety, start_date, gallons=1, sg_start, cost_usd=0, notes } = req.body;
    if (!batch_name) return res.status(400).json({ success: false, error: 'batch_name required' });
    const r = db.prepare(`INSERT INTO wine_batches (user_id,batch_name,wine_type,grape_variety,start_date,gallons,sg_start,sg_current,cost_usd,notes) VALUES (?,?,?,?,?,?,?,?,?,?)`).run(uid,batch_name,wine_type,grape_variety,start_date||new Date().toISOString().slice(0,10),gallons,sg_start,sg_start,cost_usd,notes);
    res.json({ success: true, id: r.lastInsertRowid });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

app.post('/api/winemaking/batches/:id/reading', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { sg_current, status, bottles_produced, tasting_notes } = req.body;
    const batch = db.prepare(`SELECT * FROM wine_batches WHERE id=? AND user_id=?`).get(req.params.id,uid) as any;
    if (!batch) return res.status(404).json({ success: false, error: 'not found' });
    db.prepare(`UPDATE wine_batches SET sg_current=COALESCE(?,sg_current), status=COALESCE(?,status), bottles_produced=COALESCE(?,bottles_produced), tasting_notes=COALESCE(?,tasting_notes), sg_final=CASE WHEN ?='bottled' THEN ? ELSE sg_final END WHERE id=? AND user_id=?`).run(sg_current,status,bottles_produced,tasting_notes,status,sg_current,req.params.id,uid);
    const abv = (batch.sg_start && sg_current) ? Math.round((batch.sg_start - sg_current)*131.25*10)/10 : null;
    res.json({ success: true, estimated_abv: abv });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

