app.get('/api/espresso/log', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const shots = db.prepare(`SELECT * FROM espresso_shots WHERE user_id=? ORDER BY shot_date DESC LIMIT 30`).all(uid);
    const best = db.prepare(`SELECT * FROM espresso_shots WHERE user_id=? AND rating IS NOT NULL ORDER BY rating DESC LIMIT 5`).all(uid);
    const stats = db.prepare(`SELECT COUNT(*) as shots, AVG(rating) as avg_rating, AVG(brew_ratio) as avg_ratio, AVG(extraction_seconds) as avg_time FROM espresso_shots WHERE user_id=?`).get(uid);
    res.json({ success: true, shots, best_shots: best, stats });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

app.post('/api/espresso/shots', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { shot_date, coffee_origin, roaster, roast_date, grind_size, dose_grams=18, yield_grams, extraction_seconds, machine, grinder, tasting_notes, rating, notes } = req.body;
    const brew_ratio = dose_grams > 0 && yield_grams ? Math.round(yield_grams/dose_grams*100)/100 : null;
    const r = db.prepare(`INSERT INTO espresso_shots (user_id,shot_date,coffee_origin,roaster,roast_date,grind_size,dose_grams,yield_grams,extraction_seconds,machine,grinder,brew_ratio,tasting_notes,rating,notes) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(uid,shot_date||new Date().toISOString().slice(0,10),coffee_origin,roaster,roast_date,grind_size,dose_grams,yield_grams,extraction_seconds,machine,grinder,brew_ratio,tasting_notes,rating,notes);
    const tips = [];
    if (extraction_seconds && extraction_seconds < 20) tips.push('Under-extracted — try finer grind');
    if (extraction_seconds && extraction_seconds > 35) tips.push('Over-extracted — try coarser grind');
    if (brew_ratio && brew_ratio < 1.5) tips.push('Low yield — try longer extraction');
    if (brew_ratio && brew_ratio > 3) tips.push('High yield — may be watery, reduce yield');
    res.json({ success: true, id: r.lastInsertRowid, brew_ratio, extraction_tips: tips });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

