try {
  db.exec(`CREATE TABLE IF NOT EXISTS thrift_items (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    item_name TEXT NOT NULL,
    brand TEXT,
    size TEXT,
    era TEXT,
    condition TEXT DEFAULT 'good',
    purchase_price_usd REAL DEFAULT 0,
    purchase_source TEXT,
    listed_price_usd REAL DEFAULT 0,
    sold_price_usd REAL DEFAULT 0,
    platform TEXT,
    status TEXT DEFAULT 'in_inventory',
    days_to_sell INTEGER,
    notes TEXT,
    created_at TEXT DEFAULT (datetime('now'))
  )`);
} catch(e) {}

app.get('/api/thrift/inventory', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const items = db.prepare(`SELECT * FROM thrift_items WHERE user_id=? ORDER BY created_at DESC`).all(uid);
    const in_inv = (items as any[]).filter((i:any)=>i.status==='in_inventory');
    const sold = (items as any[]).filter((i:any)=>i.status==='sold');
    const total_revenue = sold.reduce((s:number,i:any)=>s+(i.sold_price_usd||0),0);
    const total_cost = sold.reduce((s:number,i:any)=>s+(i.purchase_price_usd||0),0);
    const inv_cost = in_inv.reduce((s:number,i:any)=>s+(i.purchase_price_usd||0),0);
    const avg_days = sold.length ? Math.round(sold.reduce((s:number,i:any)=>s+(i.days_to_sell||0),0)/sold.length) : null;
    res.json({ success: true, inventory: in_inv, sold_items: sold, stats: { total_revenue: Math.round(total_revenue*100)/100, total_cogs: Math.round(total_cost*100)/100, gross_profit: Math.round((total_revenue-total_cost)*100)/100, inventory_cost: Math.round(inv_cost*100)/100, avg_days_to_sell: avg_days } });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

app.post('/api/thrift/items', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { item_name, brand, size, era, condition='good', purchase_price_usd=0, purchase_source, listed_price_usd=0, notes } = req.body;
    if (!item_name) return res.status(400).json({ success: false, error: 'item_name required' });
    const r = db.prepare(`INSERT INTO thrift_items (user_id,item_name,brand,size,era,condition,purchase_price_usd,purchase_source,listed_price_usd,notes) VALUES (?,?,?,?,?,?,?,?,?,?)`).run(uid,item_name,brand,size,era,condition,purchase_price_usd,purchase_source,listed_price_usd,notes);
    const potential_margin = listed_price_usd > 0 ? Math.round((listed_price_usd-purchase_price_usd)/listed_price_usd*1000)/10 : null;
    res.json({ success: true, id: r.lastInsertRowid, potential_margin_pct: potential_margin });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

app.post('/api/thrift/items/:id/sell', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { sold_price_usd, platform } = req.body;
    if (!sold_price_usd) return res.status(400).json({ success: false, error: 'sold_price_usd required' });
    const item = db.prepare(`SELECT * FROM thrift_items WHERE id=? AND user_id=?`).get(req.params.id,uid) as any;
    if (!item) return res.status(404).json({ success: false, error: 'not found' });
    const days = Math.floor((Date.now() - new Date(item.created_at).getTime())/86400000);
    db.prepare(`UPDATE thrift_items SET sold_price_usd=?, platform=?, status='sold', days_to_sell=? WHERE id=? AND user_id=?`).run(sold_price_usd,platform,days,req.params.id,uid);
    const profit = sold_price_usd - item.purchase_price_usd;
    res.json({ success: true, profit: Math.round(profit*100)/100, margin_pct: Math.round(profit/sold_price_usd*1000)/10, days_held: days });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

