try {
  db.exec(`CREATE TABLE IF NOT EXISTS networth_accounts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    account_name TEXT NOT NULL,
    account_type TEXT DEFAULT 'checking',
    institution TEXT,
    current_balance_usd REAL DEFAULT 0,
    is_liability INTEGER DEFAULT 0,
    notes TEXT,
    created_at TEXT DEFAULT (datetime('now'))
  )`);
  db.exec(`CREATE TABLE IF NOT EXISTS networth_snapshots (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    snapshot_date TEXT DEFAULT (date('now')),
    total_assets_usd REAL DEFAULT 0,
    total_liabilities_usd REAL DEFAULT 0,
    net_worth_usd REAL DEFAULT 0,
    created_at TEXT DEFAULT (datetime('now'))
  )`);
} catch(e) {}

app.get('/api/networth/overview', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const accounts = db.prepare(`SELECT * FROM networth_accounts WHERE user_id=? ORDER BY account_type, account_name`).all(uid);
    const assets = (accounts as any[]).filter((a:any)=>!a.is_liability).reduce((s:number,a:any)=>s+(a.current_balance_usd||0),0);
    const liabilities = (accounts as any[]).filter((a:any)=>a.is_liability).reduce((s:number,a:any)=>s+(a.current_balance_usd||0),0);
    const net_worth = assets - liabilities;
    const history = db.prepare(`SELECT * FROM networth_snapshots WHERE user_id=? ORDER BY snapshot_date DESC LIMIT 12`).all(uid);
    const prev = history[1] as any;
    const change = prev ? net_worth - prev.net_worth_usd : null;
    res.json({ success: true, accounts, assets: Math.round(assets*100)/100, liabilities: Math.round(liabilities*100)/100, net_worth: Math.round(net_worth*100)/100, history, change_from_last: change ? Math.round(change*100)/100 : null });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

