// ─── B592: AI Content Calendar & Ideation ─────────────────────────────────────
try {
  db.exec(`CREATE TABLE IF NOT EXISTS content_ideas (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    title TEXT NOT NULL,
    platform TEXT DEFAULT 'instagram',
    content_type TEXT DEFAULT 'post',
    topic TEXT,
    hook TEXT,
    body TEXT,
    cta TEXT,
    scheduled_date TEXT,
    status TEXT DEFAULT 'idea',
    priority INTEGER DEFAULT 2,
    tags TEXT,
    notes TEXT,
    created_at TEXT DEFAULT (datetime('now'))
  )`);
} catch(e) {}

app.get('/api/contentcal/ideas', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { status, platform } = req.query;
    let q = `SELECT * FROM content_ideas WHERE user_id=?`;
    const params: any[] = [uid];
    if (status) { q += ` AND status=?`; params.push(status); }
    if (platform) { q += ` AND platform=?`; params.push(platform); }
    q += ` ORDER BY scheduled_date, priority DESC`;
    const ideas = db.prepare(q).all(...params);
    const by_platform = db.prepare(`SELECT platform, COUNT(*) as count, SUM(CASE WHEN status='published' THEN 1 ELSE 0 END) as published FROM content_ideas WHERE user_id=? GROUP BY platform ORDER BY count DESC`).all(uid);
    const upcoming = db.prepare(`SELECT * FROM content_ideas WHERE user_id=? AND scheduled_date IS NOT NULL AND scheduled_date >= date('now') AND status!='published' ORDER BY scheduled_date LIMIT 10`).all(uid);
    res.json({ success: true, ideas, by_platform, upcoming });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

