// ─── B594: Personal Cold Plunge & Recovery Log ────────────────────────────────
try {
  db.exec(`CREATE TABLE IF NOT EXISTS cold_plunge_sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    session_date TEXT DEFAULT (date('now')),
    water_temp_f REAL,
    duration_seconds INTEGER DEFAULT 120,
    pre_hr INTEGER,
    post_hr INTEGER,
    mood_before INTEGER DEFAULT 3,
    mood_after INTEGER DEFAULT 5,
    alertness_after INTEGER DEFAULT 5,
    streak_day INTEGER DEFAULT 1,
    notes TEXT,
    created_at TEXT DEFAULT (datetime('now'))
  )`);
} catch(e) {}

app.get('/api/coldplunge/stats', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const sessions = db.prepare(`SELECT * FROM cold_plunge_sessions WHERE user_id=? ORDER BY session_date DESC LIMIT 30`).all(uid);
    const stats = db.prepare(`SELECT COUNT(*) as total, AVG(duration_seconds) as avg_duration, MIN(water_temp_f) as coldest, AVG(mood_after-mood_before) as avg_mood_lift, MAX(streak_day) as longest_streak FROM cold_plunge_sessions WHERE user_id=?`).get(uid);
    const current_streak = db.prepare(`SELECT streak_day FROM cold_plunge_sessions WHERE user_id=? ORDER BY session_date DESC LIMIT 1`).get(uid) as any;
    res.json({ success: true, sessions, stats, current_streak: current_streak?.streak_day||0 });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

app.post('/api/coldplunge/sessions', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { session_date, water_temp_f, duration_seconds=120, pre_hr, post_hr, mood_before=3, mood_after=5, alertness_after=5, notes } = req.body;
    const yesterday = new Date(); yesterday.setDate(yesterday.getDate()-1);
    const prev = db.prepare(`SELECT streak_day, session_date FROM cold_plunge_sessions WHERE user_id=? ORDER BY session_date DESC LIMIT 1`).get(uid) as any;
    const prev_date = prev?.session_date ? new Date(prev.session_date) : null;
    const is_consecutive = prev_date && Math.abs(new Date(session_date||new Date().toISOString().slice(0,10)).getTime() - prev_date.getTime()) <= 86400000*1.5;
    const streak_day = is_consecutive ? (prev?.streak_day||0)+1 : 1;
    const r = db.prepare(`INSERT INTO cold_plunge_sessions (user_id,session_date,water_temp_f,duration_seconds,pre_hr,post_hr,mood_before,mood_after,alertness_after,streak_day,notes) VALUES (?,?,?,?,?,?,?,?,?,?,?)`).run(uid,session_date||new Date().toISOString().slice(0,10),water_temp_f,duration_seconds,pre_hr,post_hr,mood_before,mood_after,alertness_after,streak_day,notes);
    res.json({ success: true, id: r.lastInsertRowid, streak_day, mood_lift: mood_after - mood_before });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

// ─── B595: Vintage Watch Collection ───────────────────────────────────────────
try {
  db.exec(`CREATE TABLE IF NOT EXISTS watch_collection (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    brand TEXT NOT NULL,
    model TEXT NOT NULL,
    reference TEXT,
    year INTEGER,
    movement TEXT DEFAULT 'automatic',
    case_material TEXT DEFAULT 'stainless',
    dial_color TEXT,
    condition TEXT DEFAULT 'good',
    purchase_price_usd REAL DEFAULT 0,
    estimated_value_usd REAL DEFAULT 0,
    purchase_date TEXT,
    service_date TEXT,
    next_service_due TEXT,
    notes TEXT,
    created_at TEXT DEFAULT (datetime('now'))
  )`);
} catch(e) {}

app.get('/api/watches/collection', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const watches = db.prepare(`SELECT * FROM watch_collection WHERE user_id=? ORDER BY estimated_value_usd DESC`).all(uid);
    const total_cost = (watches as any[]).reduce((s:number,w:any)=>s+(w.purchase_price_usd||0),0);
    const total_value = (watches as any[]).reduce((s:number,w:any)=>s+(w.estimated_value_usd||0),0);
    const service_due = db.prepare(`SELECT * FROM watch_collection WHERE user_id=? AND next_service_due IS NOT NULL AND next_service_due <= date('now','+6 months') ORDER BY next_service_due`).all(uid);
    const by_brand = db.prepare(`SELECT brand, COUNT(*) as count, SUM(estimated_value_usd) as value FROM watch_collection WHERE user_id=? GROUP BY brand ORDER BY value DESC`).all(uid);
    res.json({ success: true, watches, by_brand, service_due_soon: service_due, portfolio: { cost: Math.round(total_cost*100)/100, value: Math.round(total_value*100)/100, unrealized_gain: Math.round((total_value-total_cost)*100)/100 } });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

app.post('/api/watches/collection', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { brand, model, reference, year, movement='automatic', case_material='stainless', dial_color, condition='good', purchase_price_usd=0, estimated_value_usd=0, purchase_date, notes } = req.body;
    if (!brand || !model) return res.status(400).json({ success: false, error: 'brand and model required' });
    const service_years = movement === 'mechanical' || movement === 'automatic' ? 5 : 10;
    const next_service = new Date(); next_service.setFullYear(next_service.getFullYear()+service_years);
    const r = db.prepare(`INSERT INTO watch_collection (user_id,brand,model,reference,year,movement,case_material,dial_color,condition,purchase_price_usd,estimated_value_usd,purchase_date,next_service_due,notes) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(uid,brand,model,reference,year,movement,case_material,dial_color,condition,purchase_price_usd,estimated_value_usd,purchase_date||new Date().toISOString().slice(0,10),next_service.toISOString().slice(0,10),notes);
    res.json({ success: true, id: r.lastInsertRowid, next_service_due: next_service.toISOString().slice(0,10) });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

