// ─── B609: Personal Subscription Manager ──────────────────────────────────────
try {
  db.exec(`CREATE TABLE IF NOT EXISTS subscriptions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    service_name TEXT NOT NULL,
    category TEXT DEFAULT 'entertainment',
    monthly_cost_usd REAL DEFAULT 0,
    billing_cycle TEXT DEFAULT 'monthly',
    next_billing_date TEXT,
    status TEXT DEFAULT 'active',
    payment_method TEXT,
    auto_renew INTEGER DEFAULT 1,
    notes TEXT,
    created_at TEXT DEFAULT (datetime('now'))
  )`);
} catch(e) {}

app.get('/api/subscriptions/overview', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const subs = db.prepare(`SELECT * FROM subscriptions WHERE user_id=? ORDER BY monthly_cost_usd DESC`).all(uid);
    const active = (subs as any[]).filter((s:any)=>s.status==='active');
    const monthly_total = active.reduce((sum:number,s:any)=>sum+(s.monthly_cost_usd||0),0);
    const by_category = db.prepare(`SELECT category, COUNT(*) as count, SUM(monthly_cost_usd) as monthly FROM subscriptions WHERE user_id=? AND status='active' GROUP BY category ORDER BY monthly DESC`).all(uid);
    const renewing_soon = db.prepare(`SELECT * FROM subscriptions WHERE user_id=? AND status='active' AND next_billing_date IS NOT NULL AND next_billing_date <= date('now','+7 days') ORDER BY next_billing_date`).all(uid);
    res.json({ success: true, subscriptions: subs, monthly_total: Math.round(monthly_total*100)/100, annual_total: Math.round(monthly_total*12*100)/100, by_category, renewing_soon });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

app.post('/api/subscriptions/add', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { service_name, category='entertainment', monthly_cost_usd=0, billing_cycle='monthly', next_billing_date, payment_method, auto_renew=1, notes } = req.body;
    if (!service_name) return res.status(400).json({ success: false, error: 'service_name required' });
    const r = db.prepare(`INSERT INTO subscriptions (user_id,service_name,category,monthly_cost_usd,billing_cycle,next_billing_date,payment_method,auto_renew,notes) VALUES (?,?,?,?,?,?,?,?,?)`).run(uid,service_name,category,monthly_cost_usd,billing_cycle,next_billing_date,payment_method,auto_renew,notes);
    const total = (db.prepare(`SELECT SUM(monthly_cost_usd) as t FROM subscriptions WHERE user_id=? AND status='active'`).get(uid) as any)?.t||0;
    res.json({ success: true, id: r.lastInsertRowid, new_monthly_total: Math.round(total*100)/100 });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

app.patch('/api/subscriptions/:id/cancel', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    db.prepare(`UPDATE subscriptions SET status='cancelled' WHERE id=? AND user_id=?`).run(req.params.id,uid);
    const saved = (db.prepare(`SELECT monthly_cost_usd FROM subscriptions WHERE id=? AND user_id=?`).get(req.params.id,uid) as any)?.monthly_cost_usd||0;
    res.json({ success: true, monthly_savings: Math.round(saved*100)/100, annual_savings: Math.round(saved*12*100)/100 });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

