    const sessions = language
      ? db.prepare(`SELECT * FROM language_sessions WHERE user_id=? AND language=? ORDER BY session_date DESC LIMIT 20`).all(uid,language)
      : db.prepare(`SELECT * FROM language_sessions WHERE user_id=? ORDER BY session_date DESC LIMIT 20`).all(uid);
