// ─── B628: Personal Investing & Stock Tracker ────────────────────────────────
try {
  db.exec(`CREATE TABLE IF NOT EXISTS stock_holdings (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    ticker TEXT NOT NULL,
    company_name TEXT,
    shares REAL DEFAULT 0,
    avg_cost_basis REAL DEFAULT 0,
    current_price REAL DEFAULT 0,
    account TEXT DEFAULT 'brokerage',
    sector TEXT,
    notes TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT DEFAULT (datetime('now'))
  )`);
  db.exec(`CREATE TABLE IF NOT EXISTS stock_trades (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    trade_date TEXT DEFAULT (date('now')),
    ticker TEXT NOT NULL,
    action TEXT DEFAULT 'buy',
    shares REAL DEFAULT 0,
    price_usd REAL DEFAULT 0,
    fees_usd REAL DEFAULT 0,
    notes TEXT,
    created_at TEXT DEFAULT (datetime('now'))
  )`);
} catch(e) {}

app.get('/api/stocks/portfolio', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const holdings = db.prepare(`SELECT * FROM stock_holdings WHERE user_id=? AND shares > 0 ORDER BY shares*current_price DESC`).all(uid);
    const enriched = (holdings as any[]).map((h: any) => ({
      ...h,
      market_value: Math.round(h.shares * h.current_price * 100) / 100,
      cost_basis_total: Math.round(h.shares * h.avg_cost_basis * 100) / 100,
      gain_loss: Math.round((h.current_price - h.avg_cost_basis) * h.shares * 100) / 100,
      gain_pct: h.avg_cost_basis ? Math.round(((h.current_price - h.avg_cost_basis) / h.avg_cost_basis) * 10000) / 100 : 0
    }));
    const total_value = enriched.reduce((s, h) => s + h.market_value, 0);
    const total_cost = enriched.reduce((s, h) => s + h.cost_basis_total, 0);
    const recent_trades = db.prepare(`SELECT * FROM stock_trades WHERE user_id=? ORDER BY trade_date DESC LIMIT 10`).all(uid);
    res.json({ success: true, holdings: enriched, portfolio: { total_value: Math.round(total_value*100)/100, total_cost: Math.round(total_cost*100)/100, total_gain: Math.round((total_value-total_cost)*100)/100, total_gain_pct: total_cost ? Math.round((total_value-total_cost)/total_cost*10000)/100 : 0 }, recent_trades });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

app.post('/api/stocks/trades', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { trade_date, ticker, action='buy', shares=0, price_usd=0, fees_usd=0, notes } = req.body;
    if (!ticker || !shares) return res.status(400).json({ success: false, error: 'ticker and shares required' });
    db.prepare(`INSERT INTO stock_trades (user_id,trade_date,ticker,action,shares,price_usd,fees_usd,notes) VALUES (?,?,?,?,?,?,?,?)`).run(uid,trade_date||new Date().toISOString().slice(0,10),ticker.toUpperCase(),action,shares,price_usd,fees_usd,notes);
    const existing = db.prepare(`SELECT * FROM stock_holdings WHERE user_id=? AND ticker=?`).get(uid,ticker.toUpperCase()) as any;
    if (action === 'buy') {
      if (existing) {
        const new_shares = existing.shares + shares;
        const new_basis = ((existing.shares * existing.avg_cost_basis) + (shares * price_usd)) / new_shares;
        db.prepare(`UPDATE stock_holdings SET shares=?, avg_cost_basis=?, updated_at=datetime('now') WHERE id=?`).run(new_shares,new_basis,existing.id);
      } else {
        db.prepare(`INSERT INTO stock_holdings (user_id,ticker,shares,avg_cost_basis,current_price) VALUES (?,?,?,?,?)`).run(uid,ticker.toUpperCase(),shares,price_usd,price_usd);
      }
    } else if (action === 'sell' && existing) {
      db.prepare(`UPDATE stock_holdings SET shares=MAX(0,shares-?), updated_at=datetime('now') WHERE id=?`).run(shares,existing.id);
    }
    res.json({ success: true });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

