    const stats = db.prepare(`SELECT COUNT(*) as batches, SUM(candles_made) as candles, SUM(cost_usd) as total_cost, AVG(hot_throw_rating) as avg_hot_throw FROM candle_batches WHERE user_id=?`).get(uid) as any;
