// ─── B643: Personal Cryptocurrency DCA Tracker ───────────────────────────────
try {
  db.exec(`CREATE TABLE IF NOT EXISTS crypto_dca (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    buy_date TEXT DEFAULT (date('now')),
    coin TEXT NOT NULL,
    amount_usd REAL DEFAULT 100,
    coin_amount REAL DEFAULT 0,
    price_at_purchase REAL DEFAULT 0,
    exchange TEXT DEFAULT 'coinbase',
    notes TEXT,
    created_at TEXT DEFAULT (datetime('now'))
  )`);
  db.exec(`CREATE TABLE IF NOT EXISTS crypto_prices (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    coin TEXT NOT NULL,
    current_price REAL DEFAULT 0,
    updated_at TEXT DEFAULT (datetime('now'))
  )`);
} catch(e) {}

app.get('/api/cryptodca/portfolio', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const buys = db.prepare(`SELECT coin, SUM(amount_usd) as invested, SUM(coin_amount) as coins, COUNT(*) as purchases, AVG(price_at_purchase) as avg_cost FROM crypto_dca WHERE user_id=? GROUP BY coin`).all(uid);
    const prices = db.prepare(`SELECT * FROM crypto_prices WHERE user_id=?`).all(uid);
    const price_map: any = {};
    (prices as any[]).forEach((p:any) => { price_map[p.coin] = p.current_price; });
    const portfolio = (buys as any[]).map((b: any) => {
      const current = price_map[b.coin] || b.avg_cost;
      const current_value = b.coins * current;
      return { ...b, current_price: current, current_value_usd: Math.round(current_value*100)/100, gain_loss: Math.round((current_value-b.invested)*100)/100, gain_pct: Math.round((current_value-b.invested)/b.invested*10000)/100 };
    });
    const recent = db.prepare(`SELECT * FROM crypto_dca WHERE user_id=? ORDER BY buy_date DESC LIMIT 10`).all(uid);
    res.json({ success: true, portfolio, recent_buys: recent });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

app.post('/api/cryptodca/buy', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { buy_date, coin, amount_usd=100, coin_amount=0, price_at_purchase=0, exchange='coinbase', notes } = req.body;
    if (!coin) return res.status(400).json({ success: false, error: 'coin required' });
    const r = db.prepare(`INSERT INTO crypto_dca (user_id,buy_date,coin,amount_usd,coin_amount,price_at_purchase,exchange,notes) VALUES (?,?,?,?,?,?,?,?)`).run(uid,buy_date||new Date().toISOString().slice(0,10),coin.toUpperCase(),amount_usd,coin_amount,price_at_purchase,exchange,notes);
    res.json({ success: true, id: r.lastInsertRowid });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

