app.get('/api/freelance/overview', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const clients = db.prepare(`SELECT * FROM freelance_clients WHERE user_id=? AND status='active' ORDER BY client_name`).all(uid);
    const invoices = db.prepare(`SELECT i.*, c.client_name FROM freelance_invoices i LEFT JOIN freelance_clients c ON c.id=i.client_id WHERE i.user_id=? ORDER BY i.issue_date DESC LIMIT 20`).all(uid);
    const stats = db.prepare(`SELECT SUM(CASE WHEN status='paid' THEN amount_usd ELSE 0 END) as collected, SUM(CASE WHEN status IN ('sent','overdue') THEN amount_usd ELSE 0 END) as outstanding, COUNT(DISTINCT client_id) as active_clients FROM freelance_invoices WHERE user_id=?`).get(uid);
    const overdue = db.prepare(`SELECT i.*, c.client_name FROM freelance_invoices i LEFT JOIN freelance_clients c ON c.id=i.client_id WHERE i.user_id=? AND i.status='sent' AND i.due_date < date('now') ORDER BY i.due_date`).all(uid);
    res.json({ success: true, clients, recent_invoices: invoices, stats, overdue_invoices: overdue });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

