app.get('/api/ebike/log', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const rides = db.prepare(`SELECT * FROM ebike_rides WHERE user_id=? ORDER BY ride_date DESC LIMIT 20`).all(uid);
    const stats = db.prepare(`SELECT COUNT(*) as rides, SUM(distance_miles) as miles, SUM(duration_minutes) as minutes, AVG(battery_start_pct-battery_end_pct) as avg_battery_used FROM ebike_rides WHERE user_id=?`).get(uid) as any;
    const by_purpose = db.prepare(`SELECT purpose, COUNT(*) as count, SUM(distance_miles) as miles FROM ebike_rides WHERE user_id=? GROUP BY purpose ORDER BY count DESC`).all(uid);
    const ytd = db.prepare(`SELECT SUM(distance_miles) as miles, COUNT(*) as rides FROM ebike_rides WHERE user_id=? AND strftime('%Y',ride_date)=strftime('%Y','now')`).get(uid);
    res.json({ success: true, rides, stats: { ...stats, range_per_pct: stats?.avg_battery_used ? Math.round((stats.miles/(stats.avg_battery_used*stats.rides||1)*100)*10)/10 : 0 }, by_purpose, ytd });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

