try {
  db.exec(`CREATE TABLE IF NOT EXISTS fasting_logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    fast_date TEXT DEFAULT (date('now')),
    protocol TEXT DEFAULT '16:8',
    fast_start TEXT,
    fast_end TEXT,
    target_hours INTEGER DEFAULT 16,
    actual_hours REAL DEFAULT 0,
    completed INTEGER DEFAULT 1,
    break_reason TEXT,
    energy_level INTEGER DEFAULT 7,
    hunger_level INTEGER DEFAULT 5,
    weight_lbs REAL,
    notes TEXT,
    created_at TEXT DEFAULT (datetime('now'))
  )`);
} catch(e) {}

app.get('/api/fasting/log', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const logs = db.prepare(`SELECT * FROM fasting_logs WHERE user_id=? ORDER BY fast_date DESC LIMIT 30`).all(uid);
    const stats = db.prepare(`SELECT COUNT(*) as fasts, AVG(actual_hours) as avg_hours, SUM(completed) as completed, MAX(actual_hours) as longest FROM fasting_logs WHERE user_id=?`).get(uid) as any;
    const streak = db.prepare(`SELECT COUNT(DISTINCT fast_date) as days FROM fasting_logs WHERE user_id=? AND completed=1 AND fast_date >= date('now','-30 days')`).get(uid);
    const by_protocol = db.prepare(`SELECT protocol, COUNT(*) as count, AVG(actual_hours) as avg_hours, SUM(completed) as completed FROM fasting_logs WHERE user_id=? GROUP BY protocol`).all(uid);
    res.json({ success: true, logs, stats: { ...stats, completion_rate: stats?.fasts ? Math.round((stats.completed/stats.fasts)*100) : 0 }, monthly_days: (streak as any)?.days, by_protocol });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

