try {
  db.exec(`CREATE TABLE IF NOT EXISTS mushroom_grows (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    grow_name TEXT NOT NULL,
    species TEXT NOT NULL,
    substrate TEXT DEFAULT 'masters_mix',
    inoculation_date TEXT DEFAULT (date('now')),
    grain_spawn_oz REAL DEFAULT 16,
    substrate_lb REAL DEFAULT 5,
    colonization_days INTEGER DEFAULT 21,
    first_pin_date TEXT,
    first_harvest_date TEXT,
    total_yield_oz REAL DEFAULT 0,
    flush_count INTEGER DEFAULT 0,
    contamination INTEGER DEFAULT 0,
    be_pct REAL,
    notes TEXT,
    created_at TEXT DEFAULT (datetime('now'))
  )`);
} catch(e) {}

app.get('/api/mushrooms/grows', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const grows = db.prepare(`SELECT * FROM mushroom_grows WHERE user_id=? ORDER BY inoculation_date DESC`).all(uid);
    const stats = db.prepare(`SELECT COUNT(*) as grows, SUM(total_yield_oz) as yield_oz, AVG(be_pct) as avg_be, SUM(contamination) as contaminations FROM mushroom_grows WHERE user_id=?`).get(uid) as any;
    const by_species = db.prepare(`SELECT species, COUNT(*) as grows, AVG(be_pct) as avg_be, SUM(total_yield_oz) as yield FROM mushroom_grows WHERE user_id=? GROUP BY species ORDER BY yield DESC`).all(uid);
    res.json({ success: true, grows, stats: { ...stats, success_rate: stats?.grows ? Math.round(((stats.grows-stats.contaminations)/stats.grows)*100) : 0 }, by_species });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

app.post('/api/mushrooms/grows', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { grow_name, species, substrate='masters_mix', inoculation_date, grain_spawn_oz=16, substrate_lb=5, notes } = req.body;
    if (!grow_name || !species) return res.status(400).json({ success: false, error: 'grow_name and species required' });
    const r = db.prepare(`INSERT INTO mushroom_grows (user_id,grow_name,species,substrate,inoculation_date,grain_spawn_oz,substrate_lb,notes) VALUES (?,?,?,?,?,?,?,?)`).run(uid,grow_name,species,substrate,inoculation_date||new Date().toISOString().slice(0,10),grain_spawn_oz,substrate_lb,notes);
    res.json({ success: true, id: r.lastInsertRowid });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

app.patch('/api/mushrooms/:id/harvest', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { yield_oz=0, flush=1 } = req.body;
    const grow = db.prepare(`SELECT * FROM mushroom_grows WHERE id=? AND user_id=?`).get(req.params.id,uid) as any;
    if (!grow) return res.status(404).json({ success: false, error: 'grow not found' });
    const new_yield = (grow.total_yield_oz||0)+yield_oz;
    const be = grow.substrate_lb > 0 ? Math.round((new_yield/16/grow.substrate_lb)*10000)/100 : null;
    db.prepare(`UPDATE mushroom_grows SET total_yield_oz=?, flush_count=?, be_pct=?, first_harvest_date=COALESCE(first_harvest_date,date('now')) WHERE id=? AND user_id=?`).run(new_yield,flush,be,req.params.id,uid);
    res.json({ success: true, total_yield_oz: new_yield, be_pct: be });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

