app.post('/api/beekeeping/inspections', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { inspection_date, hive_name, queen_seen=0, eggs_seen=0, brood_pattern='solid', honey_frames=0, empty_frames=0, bee_temperament='calm', mite_wash_pct, disease_signs, action_taken, weight_lbs, notes } = req.body;
    if (!hive_name) return res.status(400).json({ success: false, error: 'hive_name required' });
    const r = db.prepare(`INSERT INTO hive_inspections (user_id,inspection_date,hive_name,queen_seen,eggs_seen,brood_pattern,honey_frames,empty_frames,bee_temperament,mite_wash_pct,disease_signs,action_taken,weight_lbs,notes) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(uid,inspection_date||new Date().toISOString().slice(0,10),hive_name,queen_seen,eggs_seen,brood_pattern,honey_frames,empty_frames,bee_temperament,mite_wash_pct,disease_signs,action_taken,weight_lbs,notes);
    const alerts = [];
    if (mite_wash_pct && mite_wash_pct > 2) alerts.push('mite_threshold_exceeded');
    if (!queen_seen && !eggs_seen) alerts.push('queen_not_confirmed');
    res.json({ success: true, id: r.lastInsertRowid, alerts });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

