app.post('/api/coffeeroasting/roasts', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { roast_date, green_origin, green_weight_g=250, roast_level='medium', first_crack_time_s=480, drop_temp_f=410, roasted_weight_g=210, development_time_s=90, rest_days_planned=10, notes } = req.body;
    if (!green_origin) return res.status(400).json({ success: false, error: 'green_origin required' });
    const weight_loss_pct = Math.round((1 - roasted_weight_g/green_weight_g)*1000)/10;
    const r = db.prepare(`INSERT INTO coffee_roasts (user_id,roast_date,green_origin,green_weight_g,roast_level,first_crack_time_s,drop_temp_f,roasted_weight_g,weight_loss_pct,development_time_s,rest_days_planned,notes) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)`).run(uid,roast_date||new Date().toISOString().slice(0,10),green_origin,green_weight_g,roast_level,first_crack_time_s,drop_temp_f,roasted_weight_g,weight_loss_pct,development_time_s,rest_days_planned,notes);
    res.json({ success: true, id: r.lastInsertRowid, weight_loss_pct });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

app.post('/api/coffeeroasting/pulls', requireAuth, (req: any, res: any) => {
  try {
    const uid = req.user.id;
    const { roast_id, pull_date, dose_g=18, yield_g=36, time_s=28, water_temp_f=201, grind_setting, extraction_rating=7, taste_notes, notes } = req.body;
    const ratio = Math.round(yield_g/dose_g*10)/10;
    const r = db.prepare(`INSERT INTO espresso_pulls (user_id,roast_id,pull_date,dose_g,yield_g,ratio,time_s,water_temp_f,grind_setting,extraction_rating,taste_notes,notes) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)`).run(uid,roast_id,pull_date||new Date().toISOString().slice(0,10),dose_g,yield_g,ratio,time_s,water_temp_f,grind_setting,extraction_rating,taste_notes,notes);
    res.json({ success: true, id: r.lastInsertRowid, ratio });
  } catch(e: any) { res.status(500).json({ success: false, error: e.message }); }
});

