    const uid = req.user.id;
    const projects = db.prepare(`SELECT * FROM stained_glass_projects WHERE user_id=? ORDER BY start_date DESC`).all(uid);
    const stats = db.prepare(`SELECT COUNT(*) as projects, SUM(hours_invested) as hours, SUM(material_cost_usd) as material_cost, SUM(CASE WHEN sold=1 THEN sale_price_usd ELSE 0 END) as revenue, AVG(satisfaction_rating) as avg_rating FROM stained_glass_projects WHERE user_id=?`).get(uid) as any;
    res.json({ success: true, projects, stats: { ...stats, profit: Math.round(((stats?.revenue||0)-(stats?.material_cost||0))*100)/100, avg_rating: Math.round((stats?.avg_rating||0)*10)/10 } });
